INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('antverpia-lied', 'ANTVERPIA LIED', 'ANTVERPIA LIED', 'kringliederen', 'nl', 'antverpia', 33, 33, NULL, '‘In ’t Antwerps a.u.b.’, De Strangers', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('antverpia-lied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('antverpia-lied', 0, 0, 'Antwârpe ... gij zè ga veur mij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('antverpia-lied', 0, 1, 'Toch de stad waar azzek zèn gebore');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('antverpia-lied', 0, 2, 'De Greunpleuts, de Meir ... de Keyserlei');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('antverpia-lied', 0, 3, 'Daar hemme kik m’n hart verlore');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('antverpia-lied', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('antverpia-lied', 1, 0, 'Antwârpe ... waar da’k ik ook ben');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('antverpia-lied', 1, 1, 'Ik kan nievrans mijnen draai ni vinde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('antverpia-lied', 1, 2, '’k Weet het ’t is flaa ... mor ik beken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('antverpia-lied', 1, 3, 'Bij aa zèn ’k thuis ... en onder vrinde');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('antverpia-lied', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('antverpia-lied', 2, 0, 'Cheerio, Cheerio,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('antverpia-lied', 2, 1, 'In Antwerpen daar poepen ze zo');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('antverpia-lied', 2, 2, 'Eerst met de vinger en dan met de fluit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('antverpia-lied', 2, 3, 'Ge steekt hem erin en ge trekt hem eruit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('antverpia-lied', 2, 4, 'En zolang er Sinjoren bestaan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('antverpia-lied', 2, 5, 'Zal Antwerpen nooit niet vergaan.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('antverpia-lied', 2, 6, 'Wij weten wat lol is, als ’t pintje maar vol is');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('antverpia-lied', 2, 7, 'De rest trekken wij ons niet aan!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('bierkultuur-kreet', 'BIERKULTUUR KREET', 'BIERKULTUUR KREET', 'kringliederen', 'nl', 'bierkultuur', 34, 34, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bierkultuur-kreet', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-kreet', 0, 0, 'Zuip je voor het eerst, dan heb je een kater');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-kreet', 0, 1, 'Trek het je niet aan, ga door want later');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-kreet', 0, 2, 'Geniet je des te meer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-kreet', 0, 3, 'Van bier en van BK');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-kreet', 0, 4, 'Van bier en van BK');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-kreet', 0, 5, 'Van BK en bier');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('bierkultuur-lied', 'BIERKULTUUR LIED', 'BIERKULTUUR LIED', 'kringliederen', 'nl', 'bierkultuur', 34, 35, NULL, '‘Mijn vriend Benjamin’, Louis Neefs', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bierkultuur-lied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-lied', 0, 0, 'BierKultuur zijn een bende hechte vrienden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-lied', 0, 1, 'En we zorgen voor vertier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-lied', 0, 2, 'We hebben elkaar hier kunnen vinden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-lied', 0, 3, 'Bij een glaasje lekker bier');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bierkultuur-lied', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-lied', 1, 0, 'Af en toe gaan wij eens op verplaatsing');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-lied', 1, 1, 'Om er ander bier te smaken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-lied', 1, 2, 'Zodat we een paar flesjes kraken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-lied', 1, 3, 'Van trappist, malheur of zeunt');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bierkultuur-lied', 2, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-lied', 2, 0, 'Nooit dronk ik een beter bier dan met BK');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-lied', 2, 1, 'Om te genieten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-lied', 2, 2, 'Proeven kan op elk moment, elke minuut');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-lied', 2, 3, 'Niet om te gieten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-lied', 2, 4, 'Bestelde ik toen trots en fier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-lied', 2, 5, 'Een mij onbekend en nieuw bier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-lied', 2, 6, 'En het feit dat het smaakt op ieder uur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-lied', 2, 7, 'Maakte mij tot deel van BierKultuur');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('bierkultuur-lied', 2, 7, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bierkultuur-lied', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-lied', 3, 0, 'En op café zijn w’altijd te vinden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-lied', 3, 1, 'Aan de toog of op de vloer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-lied', 3, 2, 'We zijn een groep gelijkgezinden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bierkultuur-lied', 3, 3, 'In de liefde voor het bier');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('boves-luci-clublied', 'BOVES LUCI CLUBLIED', 'BOVES LUCI CLUBLIED', 'kringliederen', 'nl', 'boves-luci', 36, 36, NULL, '‘Ergo bibamus’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('boves-luci-clublied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boves-luci-clublied', 0, 0, 'Boves Luci, het is u bekend');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boves-luci-clublied', 0, 1, 'De eerste gilde van ’t L.U.C.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boves-luci-clublied', 0, 2, 'Bij pot en pint,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boves-luci-clublied', 0, 3, 'Ja, zo zijn we ’t gewend');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boves-luci-clublied', 0, 4, 'Is ’t ’s avonds club en ieder doet mee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boves-luci-clublied', 0, 5, 'Voor Bos en voor schacht is ’t enige woord');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boves-luci-clublied', 0, 6, 'Waar hart en ziel aan toe behoort');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boves-luci-clublied', 0, 7, 'Wat immer meer en meer bekoort');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boves-luci-clublied', 0, 8, 'De eeuwige Boves Luci.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('boves-luci-clublied', 0, 8, 8, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('campina-kreet', 'CAMPINA-KREET', 'CAMPINA-KREET', 'kringliederen', 'nl', 'campina', 36, 36, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('campina-kreet', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campina-kreet', 0, 0, 'We zijn van de Kempen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campina-kreet', 0, 1, 'Van de Kempen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campina-kreet', 0, 2, 'Waar ons geboortehuisje staat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campina-kreet', 0, 3, 'We zijn Campianen, Campianen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campina-kreet', 0, 4, 'Campina is weer paraat!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campina-kreet', 0, 5, 'Olé');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('campinalied', 'CAMPINALIED', 'CAMPINALIED', 'kringliederen', 'nl', 'campina', 37, 38, 'Bram Gilles, 2005', '‘Kinderfiets’, Herman van Veen (naar Ralph McTell)', 'Geschreven n.a.v. 25 jaar Campina VUB');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('campinalied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 0, 0, 'Hallo, dag student op de VUB,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 0, 1, 'Je komt, je ziet, overwint');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 0, 2, 'Met je boerenverstand uit het hinterland,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 0, 3, 'Een vrolijk en vrij Kempenkind');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('campinalied', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 1, 0, 'En je studententijd die begint bij Campina,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 1, 1, 'Want daar weten ze van veel plezier, en bier, en bier');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('campinalied', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 2, 0, 'Hallo, lieve schacht in je witte jas,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 2, 1, 'Men zegt, het studeren gaat voor');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 2, 2, 'Maar soms is het tijd voor wat wild vertier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 2, 3, 'Nog een avond, nog een nacht, wij gaan door');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('campinalied', 3, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 3, 0, 'En je studententijd die gaat voort met Campina,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 3, 1, 'Want daar weten ze van veel plezier, en bier, en bier');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('campinalied', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 4, 0, 'Hallo, dag ancien met je grote mond,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 4, 1, 'Je lacht en drinkt nog een pint');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 4, 2, 'Met je klak gekleurd in het groen wit groen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 4, 3, 'En een eekhoorn die prijkt op het lint');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('campinalied', 5, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 5, 0, 'En je studententijd die blijft gaan voor Campina,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 5, 1, 'Want daar weten ze van veel plezier, en bier, en bier');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('campinalied', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 6, 0, 'Hallo, oude zak met je groot verstand,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 6, 1, 'Je studententijd was een feest');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 6, 2, 'En soms keer je terug naar de VUB,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 6, 3, 'Bij Campina ben je nooit weggeweest');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('campinalied', 7, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 7, 0, 'En je studententijd die leeft voort met Campina,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 7, 1, 'Want daar weten ze van veel plezier, en bier, en bier');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('campinalied', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 8, 0, 'Hallo, Campiaan met je grote hart,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 8, 1, 'Door dun en door dik, hand in hand');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 8, 2, 'Uit Mol, uit Lier, uit Geel ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 8, 3, '... zijn we hier beland');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('campinalied', 8, 4, 'En zingen we van ’t Kempenland!');
