INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('chanson-du-cercle-omega', 'CHANSON DU CERCLE OMEGA', 'CHANSON DU CERCLE OMEGA', 'kringliederen', 'fr', 'cercle-omega', 38, 39, NULL, '‘Grand-Papa Nicolas’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chanson-du-cercle-omega', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-du-cercle-omega', 0, 0, 'Arrivé à l’ERM, c’est l’enfer du baptême');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-du-cercle-omega', 0, 1, 'Pas question de couillons, on crève à l’infection');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-du-cercle-omega', 0, 2, 'On est tous étudiant, buveur et guindailleur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-du-cercle-omega', 0, 3, 'Chopes, pintes, demis, crapuleuses, mais ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chanson-du-cercle-omega', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-du-cercle-omega', 1, 0, 'Cercle Oméga, debout tu resteras');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-du-cercle-omega', 1, 1, 'Cercle Oméga, au bar tu t’accrocheras');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-du-cercle-omega', 1, 2, 'Nul ne saura, ni comment, ni pourquoi');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-du-cercle-omega', 1, 3, 'Mais au Cercle Oméga on ne dégueule pas');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-du-cercle-omega', 1, 4, 'Palapalam palam palam, palapalam');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chanson-du-cercle-omega', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-du-cercle-omega', 2, 0, 'On vit entre quat’murs, mais on a la peau dure');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-du-cercle-omega', 2, 1, 'Comme on manque de gonzesses, on s’sert à l’ACS');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-du-cercle-omega', 2, 2, 'Elles trouvent qu’on a bon goût, quant elles nous sucent le');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-du-cercle-omega', 2, 3, 'bout');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-du-cercle-omega', 2, 4, 'Bittes, queues, braquemarts, bistouquettes, mais ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chanson-du-cercle-omega', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-du-cercle-omega', 3, 0, 'Viens à la Renaissance, pour te remplir la panse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-du-cercle-omega', 3, 1, 'Pour boire pour guindailler, pour te rincer le gosier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-du-cercle-omega', 3, 2, 'Amène ta copine, pour nous rincer la pine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-du-cercle-omega', 3, 3, 'Chattes, moules, migeoles et cramouilles, mais ...');
