INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('het-enigmalied', 'HET ENIGMALIED', 'ENIGMALIED, HET', 'kringliederen', 'nl', 'enigma', 41, 42, 'Jasper Stegen', '‘Another Irish drinking song’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-enigmalied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 0, 0, 'Gezeten en getogen op de campus aan ’t kanaal');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 0, 1, 'Studeren op de kaai is het begin van ons verhaal');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 0, 2, 'De ene doet design, en de ander doet IT');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 0, 3, 'Onze hechte band, dat is een echte synergie');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-enigmalied', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 1, 0, 'Ontsproten aan de geesten van een kring reeds lang vergaan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 1, 1, 'Zetten we tradities voort van ons befaamd bestaan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 1, 2, 'Studeren combineren met folkloor’, wat een cumul');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 1, 3, 'En wij evolueren tot studenten 2.0');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-enigmalied', 2, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 2, 0, 'Wij ademen digitaal');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 2, 1, 'Studeren aan’t kanaal');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 2, 2, 'Gelijkgezinde geesten en studentikoze taal');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 2, 3, 'Enigma is wat ons verbindt, de klak, de kiel bemind');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 2, 4, 'En gaan w’er onderdoor, dan komt er wel een volgende release');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-enigmalied', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 3, 0, '’s Morgens steeds de slachthuisgeuren, gaan we tegemoet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 3, 1, 'Niet altijd met volle goesting, wel omdat het moet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 3, 2, 'Maar tegen ’s middags keert de wind en voelen w’ons weer goed');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 3, 3, 'Ons ’s avonds Brussel eigen maken, ’t zit ons in het bloed');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-enigmalied', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 4, 0, 'Enigma is wat ons hier op dag 1 al overviel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 4, 1, 'Sindsdien zijn w’onafscheidelijk van onze klak en kiel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 4, 2, 'Gezamenlijk trotseren w’iedereen bij BSK');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 4, 3, 'Toch wanneer dat we buiten mogen van ons ma en pa');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-enigmalied', 5, 'chorus-ref', 1, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-enigmalied', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 6, 0, 'Brussel ziet ons komen en men zet zich al paraat');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 6, 1, 'In stilte wordt gefluisterd, “’t is Enigma dat daar staat”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 6, 2, 'Ons’ kleuren wapp’ren fier en trots, in groen en zwart en grijs');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 6, 3, 'Enigma maakt het feest compleet, en hier is het bewijs!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-enigmalied', 7, 'direction', 1, 'Laatste refrein:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-enigmalied', 8, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 8, 0, 'Enigma maakt furoor');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 8, 1, 'Dus zing met ons in koor');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 8, 2, 'Al wordt het ons fataal, We feesten door tot ’t ochtendgloor!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 8, 3, 'Dat doen we sinds ’t begin van onze trotse fiere kring');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-enigmalied', 8, 4, 'Dat is sinds ’t jaar 0111 1101 1111');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('apothekerslied', 'APOTHEKERSLIED', 'APOTHEKERSLIED', 'kringliederen', 'nl', 'farmaceutische-kring', 43, 43, NULL, '‘Stars and stripes’, John Philip Souza, 1896', NULL);
