INSERT INTO line (song_id, stanza_position, position, text) VALUES ('apothekerslied', 0, 1, 'En zij maken zo geerne plezier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('apothekerslied', 0, 2, 'Zij doen met de blokkers niet mee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('apothekerslied', 0, 3, 'Want die studeren de farmacopee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('apothekerslied', 0, 4, 'Zij draaien de pillen zo fijn');
