INSERT INTO line (song_id, stanza_position, position, text) VALUES ('apothekerslied', 0, 6, 'Zij drinken een stuk in ulder kraag');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('apothekerslied', 0, 7, 'Maar ’s anderendaags zijn zij weer daar om te studeren.');
