INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('chant-de-medecine', 'CHANT DE MEDECINE', 'CHANT DE MEDECINE', 'kringliederen', 'fr', 'geneeskundige-kring', 44, 46, NULL, NULL, 'Gewoonlijk worden de 1e, 3e en laatste strofe gezongen');
