INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 0, 1, 'Ma maîtresse est une putain');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 0, 2, 'Dont le vagin syphilitique');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 0, 3, 'Infeste le Quartier Latin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 0, 4, 'Mais moi, vieux pilier de l’école');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 0, 5, 'Je l’aime à cause de son mal');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 0, 6, 'Oui de son mal!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 0, 7, 'Nous somm’s unis par la vérole');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 0, 8, 'Mieux que par un lien conjugal');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('chant-de-medecine', 0, 8, 8, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chant-de-medecine', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 1, 0, 'Tous les matins vidant nos verres');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 1, 1, 'Nous y buvons avec entrein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 1, 2, 'Nous partageons comme des frères');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 1, 3, 'Les pilules de Dupuytren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 1, 4, 'Nous vivons et baisons ensemble,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 1, 5, 'Heureux comme des demi-dieux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 1, 6, 'Des demi-dieux!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 1, 7, 'N’est-c’pas la plus belle existence');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 1, 8, 'Pour des amants toujours heureux');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('chant-de-medecine', 1, 8, 8, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chant-de-medecine', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 2, 0, 'Nous transformons en pharmacie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 2, 1, 'Les lieux sacrés de nos amours');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 2, 2, 'La valériane et la charpie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 2, 3, 'S’y manipulent tour tour');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 2, 4, 'Tandis qu’avec de l’iodure');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 2, 5, 'Ma femm’ me fait des injections');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 2, 6, 'Des injections!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 2, 7, 'Avec du chlorur’ de mercure');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 2, 8, 'Moi je lui fais des frictions');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('chant-de-medecine', 2, 8, 8, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chant-de-medecine', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 3, 0, 'Goutte, goutte, de sa matrice');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 3, 1, 'Comme d’un alambic fêlé,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 3, 2, 'Son urine suinte et glisse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 3, 3, 'Le long de son cul tout pelfe');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 3, 4, 'Son con est une casserole');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 3, 5, 'Où fermentent en cumant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 3, 6, 'En cumant!');
