INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chant-de-medecine', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 4, 0, 'Ses cuiss’s ont des reflets verdâtres');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 4, 1, 'Ses seins sont flasques et flétris');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 4, 2, 'Dans son con les morpions jaunâtres');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 4, 3, 'Sur le fumier ont leur logis');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 4, 4, 'Mais moi, j’aime mon amante');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 4, 5, 'Et je voudrais jusqu’à demain');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 4, 6, 'Jusqu’à demain!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 4, 7, 'Lécher de mes lèvres brûlantes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 4, 8, 'Le foutre de son vieux vagin');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('chant-de-medecine', 4, 8, 8, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chant-de-medecine', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 5, 0, 'Délassement de l’innocence');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 5, 1, 'Je regarde chaque matin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 5, 2, 'Si quelque nouvelle excroissance');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 5, 3, 'Ne vient pas orner son vagin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 5, 4, 'Tandis qu’avec un oeuil humide');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 5, 5, 'Elle jette un regard timide');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 5, 6, 'Regard timide!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 5, 7, 'Sur mon corps que les syphilides');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 5, 8, 'Ont zébré comme un léopard');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('chant-de-medecine', 5, 8, 8, 3, '(TER)');
