INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 6, 0, 'Et quand viendra l’heure dernière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 6, 1, 'Quand nous s’rons mangés des morpions');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 6, 2, 'Unis dans un dernier ulcère');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 6, 3, 'Ad patres gaiement nous irons');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 6, 4, 'Nous adress’rons une supplique');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 6, 5, 'Afin qu’nous soyons exposés');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 6, 6, 'Oui exposés!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 6, 7, 'Dans un musée pathologique');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-medecine', 6, 8, 'A la section des vérolés.');
