INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('kbs-kreet', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kbs-kreet', 0, 0, 'K!—K!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kbs-kreet', 0, 1, 'B!—B!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kbs-kreet', 0, 2, 'S!—S!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kbs-kreet', 0, 3, 'KBS!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kbs-kreet', 0, 4, 'Wie maakt er hier het meest plezier?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kbs-kreet', 0, 5, '’t Zijn wij, ’t zijn wij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kbs-kreet', 0, 6, 'Wie drinkt er hier zo’n massa’s bier?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kbs-kreet', 0, 7, '’t Zijn wij, ’t zijn wij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kbs-kreet', 0, 8, 'We zijn nie groot, maar toch zo fijn');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kbs-kreet', 0, 9, 'En de kaloot, die krijgen we klein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kbs-kreet', 0, 10, 'Want we zijn de Kring der Brusselse Studenten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kbs-kreet', 0, 11, 'Brusselse Studenten');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('kbs-kreet', 0, 0, 3, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('lied-van-de-brusselse-geus', 'LIED VAN DE BRUSSELSE GEUS', 'LIED VAN DE BRUSSELSE GEUS', 'kringliederen', 'nl', 'kring-der-brusselse-en-brabantse-studenten', 53, 54, 'Bert Mosselmans, 1988', '‘Lied van Koppelstock de veerman’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-van-de-brusselse-geus', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-de-brusselse-geus', 0, 0, 'In naam van K.B.S. doet open ’t café');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-de-brusselse-geus', 0, 1, 'De Brusselaar sluipt door de stad');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-de-brusselse-geus', 0, 2, 'Hij dorst naar het bier in zijn Brabantse stee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-de-brusselse-geus', 0, 3, 'Doet open of ’t café ligt plat');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-de-brusselse-geus', 0, 4, 'En haast u of ’k leg hier uw deur op den toog');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-van-de-brusselse-geus', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-de-brusselse-geus', 1, 0, 'En Manneke Pis zeikt dan recht in uw oog');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-de-brusselse-geus', 1, 1, 'De Brusselaar heeft dorst, geef hem bier!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('lied-van-de-brusselse-geus', 1, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-van-de-brusselse-geus', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-de-brusselse-geus', 2, 0, 'De vrijzinnigheid is nu troef in dit land');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-de-brusselse-geus', 2, 1, 'Hang de kaloot in een boom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-de-brusselse-geus', 2, 2, 'K.B.S. regeert weer met ijzeren hand');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-de-brusselse-geus', 2, 3, 'Gaat pissen op het papendom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-de-brusselse-geus', 2, 4, 'En gaan we dan ’s morgens bezopen naar kot');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-de-brusselse-geus', 2, 5, 'Dan zingen we luid en harmonisch tot slot');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-de-brusselse-geus', 2, 6, 'Het Lied van de Brusselse Geus!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('lied-van-de-brusselse-geus', 2, 6, 6, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('keps-kreet', 'KEPS-KREET', 'KEPS-KREET', 'kringliederen', 'en', 'kring-voor-economische-politieke-en-sociale-wetenschappen', 54, 54, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('keps-kreet', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('keps-kreet', 0, 0, 'Ai, ai, ai, ai,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('keps-kreet', 0, 1, 'We are the KEPS-bandidos,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('keps-kreet', 0, 2, 'We drink all the day,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('keps-kreet', 0, 3, 'And we fuck all the night,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('keps-kreet', 0, 4, 'We are the KEPS-bandidos.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('keps-lied', 'KEPS-LIED', 'KEPS-LIED', 'kringliederen', 'nl', 'kring-voor-economische-politieke-en-sociale-wetenschappen', 55, 55, 'N. Joschko, 1980', '‘La Marseillaise’, Claude-Joseph Rouget', 'de Lisle, 24 april 1792');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('keps-lied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('keps-lied', 0, 0, 'Wij zijn de geuzen van de KEPS, hoera,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('keps-lied', 0, 1, 'Ja, de geuzen van ’t plezier!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('keps-lied', 0, 2, 'Met de pint in d’ hand zingen wijle,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('keps-lied', 0, 3, 'Van Verhaegen, sex en schuimend bier!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('keps-lied', 0, 4, 'Waar wij zijn daar is ambiance!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('keps-lied', 0, 5, 'Brussel beeft voor onze zeden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('keps-lied', 0, 6, '’t Is hier nu een reuzengroot bordeel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('keps-lied', 0, 7, 'Wij zijn hier om te studeren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('keps-lied', 0, 8, 'Maar wat we doen dat is het bier vereren!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('keps-lied', 0, 9, 'Wat volgt is onze leus,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('keps-lied', 0, 10, 'De leuze van de Geus:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('keps-lied', 0, 11, 'Cantamus, bibamus, alea iacta est,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('keps-lied', 0, 12, 'Dus sluit aan bij de KEPS.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('chant-de-philo', 'CHANT DE PHILO', 'CHANT DE PHILO', 'kringliederen', 'fr', 'letteren-en-wijsbegeerte-kring', 56, 56, NULL, '‘Le Chant du départ’, Etienne Nicolas', 'Mehul, 1794');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chant-de-philo', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-philo', 0, 0, 'C’est le chant de Philo');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-philo', 0, 1, 'Partons à la guindaille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-philo', 0, 2, 'La pine en fleur,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-philo', 0, 3, 'Les roustons en chaleur;');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chant-de-philo', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-philo', 1, 0, 'Comm’ de francs saligauds,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-philo', 1, 1, 'Courons à la ripaille,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-philo', 1, 2, 'Bourreaux des cœurs,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-philo', 1, 3, 'Toujours avec ardeur.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chant-de-philo', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-philo', 2, 0, 'Les petits et les grands');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-philo', 2, 1, 'Cons, nou-ous les baisons');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-philo', 2, 2, 'Et du soir au matin,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-philo', 2, 3, 'Notre pine guerrière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-philo', 2, 4, 'Fera jouir bon nombre de vagins.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chant-de-philo', 3, 'direction', 1, 'Gesproken:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chant-de-philo', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-philo', 4, 0, 'A la Philo, cré nom de nom,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-philo', 4, 1, 'On est peu d’ poils mais on est bons!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('limburg-allein', 'LIMBURG ALLEIN', 'LIMBURG ALLEIN', 'kringliederen', 'nl', 'limburgia', 57, 57, NULL, NULL, 'T & M: Jo Erens, oorspronkelijk ‘Zitterd (Sittard) Allein’
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('limburg-allein', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburg-allein', 0, 0, 'Do, wo ich gebore ben,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburg-allein', 0, 1, 'Wo min ouwers hoesch nog steit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburg-allein', 0, 2, 'De taal die ich toch zo gaod kan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburg-allein', 0, 3, 'Wo ich how min lijef en leed.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('limburg-allein', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburg-allein', 1, 0, 'Limburg, Limburg allein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburg-allein', 1, 1, 'Do geit niks boven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburg-allein', 1, 2, 'Zo is er maor ein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburg-allein', 1, 3, 'As min olt Limburg');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburg-allein', 1, 4, 'Limburg allein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburg-allein', 1, 5, 'Do geit niks boven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburg-allein', 1, 6, 'Zo is ter maor ein.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('limburg-allein', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburg-allein', 2, 0, 'Gaon ich no de vremden her,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburg-allein', 2, 1, 'Of wiet oet Limburg weg,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburg-allein', 2, 2, 'Heur ich immer toch zo ger,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburg-allein', 2, 3, 'Het gaod, het kaod, het slech.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('limburg-allein', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburg-allein', 3, 0, 'Zeuk ich mich e maedje oet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburg-allein', 3, 1, 'Is dat e Limburgs keindj.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburg-allein', 3, 2, 'Dao wo ich zoe op vertrouw,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburg-allein', 3, 3, 'en nörgens e baeter vinj.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('limburgs-volkslied', 'LIMBURGS VOLKSLIED', 'LIMBURGS VOLKSLIED', 'kringliederen', 'nl', 'limburgia', 58, 58, 'G. Krekelberg', 'H. Thyssens', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('limburgs-volkslied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburgs-volkslied', 0, 0, 'Waar in ’t bronsgroen eikenhout,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburgs-volkslied', 0, 1, '’t Nachtegaaltje zingt;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburgs-volkslied', 0, 2, 'Over ’t malse korenveld');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburgs-volkslied', 0, 3, '’t Lied des leeuwriks klinkt:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburgs-volkslied', 0, 4, 'Waar de hoorn des herders schalt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburgs-volkslied', 0, 5, 'Langs des beekjes boord;');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('limburgs-volkslied', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburgs-volkslied', 1, 0, 'Daar is mijn Vaderland,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburgs-volkslied', 1, 1, 'Limburgs dierbaar oord');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('limburgs-volkslied', 1, 0, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('limburgs-volkslied', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburgs-volkslied', 2, 0, 'Waar de brede stroom der Maas');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburgs-volkslied', 2, 1, 'Statig zeewaarts vloeit;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburgs-volkslied', 2, 2, 'Weeld’rig sappig veldgewas');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburgs-volkslied', 2, 3, 'Kostlijk groeit en bloeit;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburgs-volkslied', 2, 4, 'Bloemengaard en beemd en bos');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburgs-volkslied', 2, 5, 'Overheerlijk gloort.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('limburgs-volkslied', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburgs-volkslied', 3, 0, 'Waar der vaadren schone taal');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburgs-volkslied', 3, 1, 'Klinkt met held’re kracht:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburgs-volkslied', 3, 2, 'Waar men kloek en fier van aard');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburgs-volkslied', 3, 3, 'Vreemde praal veracht:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburgs-volkslied', 3, 4, 'Eigen zeden, eigen schoon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('limburgs-volkslied', 3, 5, '’t Hart des volks bekoort.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('manu-juvanta-clublied', 'MANU JUVANTA CLUBLIED', 'MANU JUVANTA CLUBLIED', 'kringliederen', 'nl', 'manu-juvanta', 59, 60, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('manu-juvanta-clublied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 0, 0, 'Ge ziet ze altijd lopen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 0, 1, 'Op TD, cantus of fuif');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 0, 2, 'Met een ferm stuk in hun kloten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 0, 3, 'En een porre rond hun lijf');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('manu-juvanta-clublied', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 1, 0, 'Wij zijn van Manu Juvanta');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 1, 1, 'Wij zuipen gelijk de beesten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 1, 2, 'Wij zijn van Manu Juvanta');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 1, 3, 'Wij houden van boemelen en feesten');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('manu-juvanta-clublied', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 2, 0, 'En zijn we weeral zat');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 2, 1, 'En hebben we morgen stage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 2, 2, 'Dan zal het weer ons feest gaan zijn');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 2, 3, 'Maar zonder bier of wijn.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('manu-juvanta-clublied', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 3, 0, 'De kleuren van onze studentenclub');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 3, 1, 'Die zijn geel en rood');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 3, 2, 'En als je dat niet weet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 3, 3, 'Dan ben j’een dikke kaloot.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('manu-juvanta-clublied', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 4, 0, 'En hebben we dan exams');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 4, 1, 'Dan worden we opeens serieus');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 4, 2, 'Ge gaat het niet geloven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 4, 3, 'Dan drinken we Spa in plaats van gueuze.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('manu-juvanta-clublied', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 5, 0, 'Al die dat nog niet weten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 5, 1, 'Wat zo speciaal aan ons nog is');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 5, 2, 'Dat is ’t gehalte pure alcohol');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('manu-juvanta-clublied', 5, 3, 'In onze ochtendpis.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('mesacosa-kreet', 'MESACOSA-KREET', 'MESACOSA-KREET', 'kringliederen', 'nl', 'mens-sana-in-corpore-sano', 60, 60, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('mesacosa-kreet', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mesacosa-kreet', 0, 0, 'Vinger in je kont, sporten is gezond,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mesacosa-kreet', 0, 1, 'We vallen van zattigheid op de grond.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mesacosa-kreet', 0, 2, 'Zuipen op café, shaken op TD,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mesacosa-kreet', 0, 3, 'De MESACOSA doet altijd mee!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('mesacosa-clublied', 'MESACOSA-CLUBLIED', 'MESACOSA-CLUBLIED', 'kringliederen', 'nl', 'mens-sana-in-corpore-sano', 60, 61, 'Yves Cools', NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('mesacosa-clublied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mesacosa-clublied', 0, 0, 'Mesacosa is de kring der LK-studenten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mesacosa-clublied', 0, 1, 'En daar zitten dan wat wijven en wat venten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mesacosa-clublied', 0, 2, 'En die zuipen en die feesten en die poepen er op los');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mesacosa-clublied', 0, 3, 'En als ’t ’s morgensvroeg dan les is dan zijn zij weeral de klos');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('mesacosa-clublied', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mesacosa-clublied', 1, 0, 'Mesacosa een kring vol toffe mensen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mesacosa-clublied', 1, 1, 'En dat zuipen ja dat zie je aan hun pensen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mesacosa-clublied', 1, 2, 'Maar dan zeg ik: “een buikje ja dat mag,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mesacosa-clublied', 1, 3, 'Want dat is voor mij een vorm van gezag!”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('mesacosa-clublied', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mesacosa-clublied', 2, 0, 'Stoere binken, hete wijven dat zijn wij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mesacosa-clublied', 2, 1, 'En dat sporten en masseren maakt ons o zo blij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mesacosa-clublied', 2, 2, 'Mesacosa op café dan is’t plezant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mesacosa-clublied', 2, 3, 'Want we zijn de beste kring van’t ganse land');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('mesacosa-clublied', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mesacosa-clublied', 3, 0, 'Mesacosa is de kring van de student');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mesacosa-clublied', 3, 1, 'Die LO of Kiné doen voor het verdienen van hun cent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mesacosa-clublied', 3, 2, 'En voor al wie het zo graag heeft gehoord');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mesacosa-clublied', 3, 3, 'Hier een ode aan het oude HILOK woord:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('mesacosa-clublied', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mesacosa-clublied', 4, 0, 'HI, HIL, HILO, HILOK!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('mesacosa-clublied', 4, 0, 0, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('hilok-lied', 'HILOK-LIED', 'HILOK-LIED', 'kringliederen', 'nl', 'mens-sana-in-corpore-sano', 61, 61, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('hilok-lied', 0, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('hilok-lied', 0, 0, 'Ik ben al jaren ne grote HILOK-fan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('hilok-lied', 0, 1, 'Zie maar naar mij wat dat ik allemaal kan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('hilok-lied', 0, 2, 'We zuipen, feesten en amuseren ons rot,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('hilok-lied', 0, 3, 'En we poepen elke avond op een ander kot.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('hilok-lied', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('hilok-lied', 1, 0, 'De prof die vroeg aan mij: “Hoeveel is twee plus drei?”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('hilok-lied', 1, 1, 'Maar ik had godverdoeme mijn telmachien ni bij,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('hilok-lied', 1, 2, 'Die vent die trok ne smoel, hij was precies heel kwaad,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('hilok-lied', 1, 3, 'Ik zei: “ik was met ’t HILOK weg en ’t wier weer veel te laat”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('hilok-lied', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('hilok-lied', 2, 0, 'Sporten valt wel mee, al zit ik op ’t WC,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('hilok-lied', 2, 1, 'Ik was nog aan ’t kotsen van gisteren die TD,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('hilok-lied', 2, 2, 'Maar ’s avonds word ik nuchter, dan voel ik mij weer goed,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('hilok-lied', 2, 3, 'Dan ga ik naar ’t café en zuip ik mij weeral pottoe');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('moeder-gevaar-lied', 'MOEDER GEVAAR-LIED', 'MOEDER GEVAAR-LIED', 'kringliederen', 'nl', 'moeder-gevaar', 62, 62, 'Daevy Dendauw, David Luyssaert en Stefaan Dermout', '‘Le duc de bordeaux’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('moeder-gevaar-lied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('moeder-gevaar-lied', 0, 0, 'Studentencafés, er zijn er zoveel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('moeder-gevaar-lied', 0, 1, 'Voor ons telt er één, ’t is ’t gevaar ons café.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('moeder-gevaar-lied', 0, 2, 'Vanaf ’s avonds laat, tot ’s morgens heel vroeg,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('moeder-gevaar-lied', 0, 3, 'Ge vindt steeds uw vrienden in deze kroeg.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('moeder-gevaar-lied', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('moeder-gevaar-lied', 1, 0, 'We zuipen en zuipen ons recht in de goot.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('moeder-gevaar-lied', 1, 1, 'Het Gevaar dat wordt onze dood!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('moeder-gevaar-lied', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('moeder-gevaar-lied', 2, 0, 'Al zijn we failliet, dan nog geen verdriet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('moeder-gevaar-lied', 2, 1, 'We poefen en zuipen en niet in’t geniep.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('moeder-gevaar-lied', 2, 2, 'Onze ziel die gaat naar de hel.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('moeder-gevaar-lied', 2, 3, 'Het nuchtere verstand, dat komt later wel.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('moeder-gevaar-lied', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('moeder-gevaar-lied', 3, 0, 'We zeiken aan den toog, ons kelen staan droog.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('moeder-gevaar-lied', 3, 1, 'We klagen om bier voor ons dagelijks plezier.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('moeder-gevaar-lied', 3, 2, 'MOEDER GEVAAR, dat is nu een feit,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('moeder-gevaar-lied', 3, 3, 'Het zuipen dat is onze dagelijkse strijd.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('het-blauw-wit-van-normalia', 'HET BLAUW-WIT VAN NORMALIA', 'BLAUW-WIT VAN NORMALIA, HET', 'kringliederen', 'nl', 'normalia', 63, 64, 'Johan Heremans', 'E viva España', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-blauw-wit-van-normalia', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 0, 0, 'Ik ging naar Brussel, om leerkracht te worden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 0, 1, 'Les gaan geven, dat leek een leuk job');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 0, 2, 'Maar toen liet ik me dopen bij Normalia');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 0, 3, 'Het studeren dat liep wat achterop');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 0, 4, 'Mijn studies die zijn nu weer naar de maan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 0, 5, 'Want ik ben weer met mijn vrienden op de baan');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-blauw-wit-van-normalia', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 1, 0, 'Het blauw-wit van Normalia');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 1, 1, 'Tot in de vroege uren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 1, 2, 'Het blauw-wit van Normalia');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 1, 3, 'Jette davert op zijn muren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 1, 4, 'Het blauw-wit van Normalia');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 1, 5, 'Plezier en alcohol');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 1, 6, 'Het blauw-wit van Normalia');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 1, 7, 'Doet ze nog eens vol!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-blauw-wit-van-normalia', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 2, 0, 'Wilt ge iets weten over wiskunde of sporten?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 2, 1, 'Of over kleuters, pubers of kadees?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 2, 2, 'Gij moet dringend uw schoonheid eens verzorgen!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 2, 3, 'Gaat naar ons lessen, daar zien ze ’t allemaal.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 2, 4, 'En pakt direct notities voor ons mee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 2, 5, 'Want wijle zitte weeral op TD');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-blauw-wit-van-normalia', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 3, 0, 'Maar uiteindelijk na veel zwoegen en veel zweten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 3, 1, 'Zullen we krijgen, en dan zijn we zeer fier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 3, 2, 'Een diploma waarmee ge kunt gaan werken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 3, 3, 'En een toekomst, met een huisje en een dier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 3, 4, 'Maar dan denken we steeds vol heimwee terug');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-blauw-wit-van-normalia', 3, 5, 'Aan die kleuren, die dorsten naar het bier.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('perskreet', 'PERSKREET', 'PERSKREET', 'kringliederen', 'nl', 'perskring', 64, 64, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('perskreet', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('perskreet', 0, 0, 'Bier en poepen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('perskreet', 0, 1, 'Poepen en bier.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('perskreet', 0, 2, 'Hier is de PERSkring, de PERSkring is hier.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('perskreet', 0, 3, 'Ja ja bij PERS, bij PERS, daar zijn ze zo pervers.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('perskreet', 0, 4, 'Eerst alco’ol en dan veel seks,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('perskreet', 0, 5, 'veel seks, veel seks, veel seks, alco’ol, alco’ol,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('perskreet', 0, 6, 'wij leven op alco’ol.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('perskreet', 0, 7, 'Van ’s morgens vroeg tot ’s avonds laat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('perskreet', 0, 8, 'alco’ol, alco’ol en dan weer seks.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('pers-lied', 'PERS-LIED', 'PERS-LIED', 'kringliederen', 'nl', 'perskring', 65, 65, 'Bert Fierens & Sven Fiers, 1995', '‘Ruiterslied’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('pers-lied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pers-lied', 0, 0, 'De Pers is hier en neemt het woord,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pers-lied', 0, 1, 'Geen ruis dat ons signaal verstoort.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pers-lied', 0, 2, 'De veer dicteert wat schrijven.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pers-lied', 0, 3, '’t Gebiedt te drinken het gerstenat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pers-lied', 0, 4, 'Van ’s avonds laat tot ’s morgens zat.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pers-lied', 0, 5, 'Van ’t zuipen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('pers-lied', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pers-lied', 1, 0, 'Studentikoos gaat ’t grijs op zwier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pers-lied', 1, 1, 'Met klinkende potten vol schuimend bier.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pers-lied', 1, 2, 'Als rolders zullen we blijven.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pers-lied', 1, 3, 'De geus leeft in het herte voort,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pers-lied', 1, 4, 'Van al die tot de loge hoort,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pers-lied', 1, 5, 'Van Perskring.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('pers-lied', 1, 5, 5, 2, '(BIS)');
