INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ppk-lied', 'PPK-LIED', 'PPK-LIED', 'kringliederen', 'nl', 'psychopedagogische-kring', 69, 69, NULL, '‘Rosamunde’, Franz Peter Schubert', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ppk-lied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ppk-lied', 0, 0, 'Dag Brussel, dag Geuzen, hier volgt onze leuze,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ppk-lied', 0, 1, 'Geeft ons een lief naar keuze, dat maakt dan klein geuze,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ppk-lied', 0, 2, 'Dag porren, dag binken, wij laten de glazen klinken.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ppk-lied', 0, 3, 'Het worden drukke dagen, met leutige zaken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ppk-lied', 0, 4, 'En als dat lukt dan is de Geus content,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ppk-lied', 0, 5, 'En geef hij aan ’t bier een dikke cent,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ppk-lied', 0, 6, 'Want zonder nat minder plezier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ppk-lied', 0, 7, 'En voor ’t plezier zijn wij toch hier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ppk-lied', 0, 8, 'Een dagske brossen, ja dat ziet geen mens,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ppk-lied', 0, 9, 'En na de twaalven wordt men pas echt mens.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ppk-lied', 0, 10, 'Zo moet het op ons unief zijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ppk-lied', 0, 11, 'Omdat wij toch studenten zijn.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ppk-lied', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ppk-lied', 1, 0, 'PPK-ers');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ppk-lied', 1, 1, 'Zet al je zorgen opzij,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ppk-lied', 1, 2, 'Al wat wij willen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ppk-lied', 1, 3, 'Is leute, kontent zijn en blij,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ppk-lied', 1, 4, 'Reik elkaar de handen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ppk-lied', 1, 5, 'Wees vrienden voor elkaar,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ppk-lied', 1, 6, 'Smeed nu de hechte banden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ppk-lied', 1, 7, '’t Wordt een heerlijk groots jaar.');
