INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('the-mad-gamer', 'THE MAD GAMER', 'MAD GAMER, THE', 'kringliederen', 'en', 'society-of-weird-and-mad-people', 71, 71, 'Jorgo Stavroudis, 1998', '‘The Wild Rover’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-mad-gamer', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-mad-gamer', 0, 0, 'I’ve been a mad gamer for many’s a year');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-mad-gamer', 0, 1, 'I’ve spent all my money on Magic and beer.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-mad-gamer', 0, 2, 'My parents deny me, they think I’m obsessed');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-mad-gamer', 0, 3, 'But I know much better and say “Fuck” to the rest.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-mad-gamer', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-mad-gamer', 1, 0, 'And it’s always forever, forever and more,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-mad-gamer', 1, 1, 'Will I be the Mad Gamer, forever and more.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-mad-gamer', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-mad-gamer', 2, 0, 'Where winners reign mighty, and losers die fast');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-mad-gamer', 2, 1, 'Where the cardboard is holy, and the rulebooks are vast.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-mad-gamer', 2, 2, 'It’s there where my heart is, and I say to the rest:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-mad-gamer', 2, 3, 'I don’t care what you think, I like gaming the best.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('solvay-c-est-du-champagne', 'SOLVAY, C’EST DU CHAMPAGNE', 'SOLVAY, C’EST DU CHAMPAGNE', 'kringliederen', 'fr', 'solvay-kring', 72, 72, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('solvay-c-est-du-champagne', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('solvay-c-est-du-champagne', 0, 0, 'Solvay, c’est du champagne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('solvay-c-est-du-champagne', 0, 1, 'Solvay, c’est de l’humour');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('solvay-c-est-du-champagne', 0, 2, 'C’est l’école de la Guindaille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('solvay-c-est-du-champagne', 0, 3, 'Où le Temps parait trop court;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('solvay-c-est-du-champagne', 0, 4, 'L’esprit que l’on y gagne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('solvay-c-est-du-champagne', 0, 5, 'Au coeur chante toujours,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('solvay-c-est-du-champagne', 0, 6, 'Car Solvay c’est du champagne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('solvay-c-est-du-champagne', 0, 7, 'Du champagne et de l’humour.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('chant-de-solvay', 'CHANT DE SOLVAY', 'CHANT DE SOLVAY', 'kringliederen', 'fr', 'solvay-kring', 72, 73, NULL, '‘Les Housards de la garde’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chant-de-solvay', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 0, 0, 'C’est durant toutes nos folles ivresses');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 0, 1, 'Que nous nous livrons à bien des méfaits');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 0, 2, 'Car nous voulons dissiper la tristesse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 0, 3, 'De l’Avenir que la vie nous promet.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chant-de-solvay', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 1, 0, 'Verre à la main, chantons notre jeunesse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 1, 1, 'Ecoute bourgeois,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 1, 2, 'Qui nous prend pour des fous.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 1, 3, 'C’est à Solvay qu’on fête la Vadrouille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 1, 4, 'Jusqu’à l’aube');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 1, 5, 'Nous buvons comme des trous.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chant-de-solvay', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 2, 0, 'Nous adorons nos charmantes amies');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 2, 1, 'Et restons près d’elles jusqu’au matin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 2, 2, 'Mais malgré tout cet amour qui nous lie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 2, 3, 'Nous ne laisserons pas tomber les copains.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chant-de-solvay', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 3, 0, 'Et si parfois des esprits pas trop sages');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 3, 1, 'Disaient: “Bientôt vous le regretterez');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 3, 2, 'Vous abusez trop de votre jeune âge');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 3, 3, 'Ce n’est pas ainsi qu’il faut s’amuser”.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chant-de-solvay', 4, 'direction', 1, 'Laatste refrein:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chant-de-solvay', 5, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 5, 0, 'Verre à la main nous leur rétorquerons:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 5, 1, '“C’est à Solvay qu’on fête les orgies');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 5, 2, 'Ne craignant pas la suite de nos folies');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 5, 3, 'Il nous faut la femme,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 5, 4, 'La bière, la chanson,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 5, 5, 'Verre à la main nous passons par la vie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 5, 6, 'Verre à la main,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-de-solvay', 5, 7, 'Gaiement nous la quitterons.”');
