INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wk-lied', 2, 2, 'Of ook wel informatica,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wk-lied', 2, 3, 'Misschien biologie,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wk-lied', 2, 4, 'Er zijn er ook van de landbouw,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wk-lied', 2, 5, 'En ook die van geologie.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wk-lied', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wk-lied', 3, 0, 'En als we weer gaan rollen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wk-lied', 3, 1, 'Zet het gerstenat maar klaar,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wk-lied', 3, 2, 'Wij zullen het niet laten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wk-lied', 3, 3, 'Gelooft U dat maar,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wk-lied', 3, 4, 'Zolang men het café niet sluit,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wk-lied', 3, 5, 'Krijgt men de WK er niet uit.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('sprekt-a-moojertoel', 'SPREKT A MOOJERTOÊL', 'SPREKT A MOOJERTOÊL', 'kringliederen', 'nl', 'woltje', 84, 85, 'Michaël Heiremans, 2006', '‘La Chanson du Roi Albert’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sprekt-a-moojertoel', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 0, 0, 'Da was nen oevend in ne staminei te Jet’');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 0, 1, 'dacht ik veneir, le Bruxellois es duud.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 0, 2, 'Den iene Woel, daa wilt gien Vloms meir leire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 0, 3, 'en den andere daan kent gien waurd Frans.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 0, 4, 'Waddesmeda, waddes da veu geziever?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 0, 5, 'Le Bruxellois dad’es toch zu’n schuun toêl!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 0, 6, 'De Brusseleir moot da toch kunne spreike');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 0, 7, 'En aaft a vast, en sprekt a moojertoêl!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 0, 8, 'En aaf a recht, en sprekt a moojertoêl!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 0, 9, 'LE BRUXELLOIS!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sprekt-a-moojertoel', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 1, 0, 'Mo ik em chance, ça est pas tout a fait perdu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 1, 1, 'Woltje es doe, le Bruxellois REVIT');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 1, 2, 'Ce dialect est le plus beau que je connais');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 1, 3, 'Un mengeling de Français en van Vloms');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 1, 4, 'Aussi avec, les chansons que l’on connait tous');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 1, 5, '“En doebaa nen dikke cervola”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 1, 6, 'Woltje es fier de pouvoir vous l’apprendre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 1, 7, 'En aaft a vast, en sprekt a moojertoêl!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 1, 8, 'En aaft a recht, en sprekt a moojertoêl!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 1, 9, 'LE BRUXELLOIS!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sprekt-a-moojertoel', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 2, 0, 'Bij Woltje kundet allemoêl gon leire,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 2, 1, 'alles van Toone, Tishken en Lambic');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 2, 2, 'De chansonettekes en poezeekes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 2, 3, 'et les histoires van onze Jef Kazak!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 2, 4, 'Lange Jojo en gans zaainen discografee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 2, 5, 'En uuk de Vlomse versies van Jacques Brel.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 2, 6, 'Dans un cantus in d’èt van de Marolle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 2, 7, 'En aaft a vast, en sprekt a moojertoêl!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 2, 8, 'En aaft a recht, en sprekt a moojertoêl!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sprekt-a-moojertoel', 2, 9, 'LE BRUXELLOIS!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('zwk-kreet', 'ZWK-KREET', 'ZWK-KREET', 'kringliederen', 'nl', 'zatte-wijvenkring', 85, 85, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('zwk-kreet', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zwk-kreet', 0, 0, 'Wie wil een vat? — Z!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zwk-kreet', 0, 1, 'Wie krijgt een vat? — W!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zwk-kreet', 0, 2, 'Wie drinkt een vat? — K!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zwk-kreet', 0, 3, 'Wie is het vat? — ZWK!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('zwk-lied', 'ZWK-LIED', 'ZWK-LIED', 'kringliederen', 'nl', 'zatte-wijvenkring', 85, 86, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('zwk-lied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zwk-lied', 0, 0, 'ZWK, ZWK');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zwk-lied', 0, 1, 'We hebben allemaal tetten');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('zwk-lied', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zwk-lied', 1, 0, 'ZWK, ZWK');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zwk-lied', 1, 1, 'Doe ons dat toch maar eens na');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('zwk-lied', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zwk-lied', 2, 0, 'Buvons ensemble');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zwk-lied', 2, 1, 'Buvons sans les garçons');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('zwk-lied', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zwk-lied', 3, 0, 'Eins, Zwei, Saufen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zwk-lied', 3, 1, 'Wir saufen un à fond');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('zwk-lied', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zwk-lied', 4, 0, 'Blote blote-te blote tetten tette!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('zennevallei-lied', 'ZENNEVALLEI LIED', 'ZENNEVALLEI LIED', 'kringliederen', 'nl', 'zennevallei', 86, 87, 'Peter Villé', '‘Het Vendel’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('zennevallei-lied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 0, 0, 'Studenten moeten bewegen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 0, 1, 'Want de ZENNEVALLEI leeft voort.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 0, 2, 'Halle geeft ons zijn kleuren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 0, 3, 'En bier tot aan de dood.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 0, 4, 'Waarom zouden wij dorst lijden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 0, 5, 'Als ’t gele vocht daar staat;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 0, 6, 'We zullen niemand mijden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 0, 7, 'Zolang de club bestaat.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 0, 8, 'Santé, student, santé.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('zennevallei-lied', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 1, 0, 'Studenten van heel Vlaand’ren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 1, 1, 'Komen hier bij elkaar.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 1, 2, 'Ze drinken dan tezamen.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 1, 3, 'Het vat is al tapklaar.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 1, 4, 'Als ’t tijd is om te drinken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 1, 5, 'Dan pakken wij naar ’t glas.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 1, 6, 'Al moeten we eerst eens klinken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 1, 7, 'Maar dan ’s ’t volle gas.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 1, 8, 'Santé, student, santé.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('zennevallei-lied', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 2, 0, 'Vergeten wij de dagen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 2, 1, 'Die wij reeds hebben verspild.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 2, 2, 'Met studeren en met klagen.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 2, 3, 'Er is niemand die dat wilt.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 2, 4, 'Maar wat wij niet vergeten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 2, 5, 'Is de naam van ons clublokaal.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 2, 6, 'De Blue Note moet je weten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 2, 7, 'Anders wordt het je fataal.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 2, 8, 'Santé, student, santé.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('zennevallei-lied', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 3, 0, 'Wij hebben eerbare kleuren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 3, 1, 'Blauw-wit is dat niet schoon?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 3, 2, 'We zullen ze niet besmeuren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 3, 3, 'We doen toch heel gewoon.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 3, 4, 'Wij blijven hier niet zingen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 3, 5, 'Want ’t is bijna gedaan.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 3, 6, 'Straks gaan z’ons hier nog dwingen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 3, 7, 'Om al naar huis te gaan.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zennevallei-lied', 3, 8, 'Santé, student, santé.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('lied-van-geen-taal', 'LIED VAN GEEN TAAL', 'LIED VAN GEEN TAAL', 'officiele-liederen', 'nl', 'brussels-studentengenootschap', 91, 91, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-van-geen-taal', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-geen-taal', 0, 0, 'Brusselse studenten van de “Klauwaert ende Geus”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-geen-taal', 0, 1, 'Strijden wij voor vrijheid, steeds getrouw aan onze leus');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-geen-taal', 0, 2, 'Roemberuchte rolders blijven wij tot in de dood');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-geen-taal', 0, 3, 'De schrik van de kaloot.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-van-geen-taal', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-geen-taal', 1, 0, 'Glorie, glorie, alleluja');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-geen-taal', 1, 1, 'Brusselse studenten van de “Klauwaert ende Geus”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-geen-taal', 1, 2, 'Glorie, glorie, alleluja');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-geen-taal', 1, 3, 'Getrouw aan onze leus.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-van-geen-taal', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-geen-taal', 2, 0, 'Hij die ’t licht niet kan verdragen der “Geen Taalse zon”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-geen-taal', 2, 1, 'Hij weze een kaloot of een bekrompen franskiljon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-geen-taal', 2, 2, 'Moet maar zien dat hij in onze weg niet komt te staan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-geen-taal', 2, 3, 'Of ’t zal hem slecht vergaan.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-van-geen-taal', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-geen-taal', 3, 0, 'Fiere dragers van de fakkels van de VUB');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-geen-taal', 3, 1, 'Dragen w’in de wereld en doorheen heel Vlaanderen mee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-geen-taal', 3, 2, 'Onze wil tot leven vrij van dwang en levensblij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-geen-taal', 3, 3, '“Geen Talers” blijven wij.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('bsk-lied', 'BSK-LIED', 'BSK-LIED', 'officiele-liederen', 'nl', 'brussels-seniorenkonvent', 92, 92, NULL, '‘O, Toreador’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bsk-lied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bsk-lied', 0, 0, 'Wij zijn student,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bsk-lied', 0, 1, 'Het is u bekend');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bsk-lied', 0, 2, 'Van d’Hogeschool, bij ’t BSK');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bsk-lied', 0, 3, 'Wij dragen vrijzinnigheid in ’t hart,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bsk-lied', 0, 4, 'En geen kaloot die ons tart,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bsk-lied', 0, 5, 'Wij zuipen altijd voort');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bsk-lied', 0, 6, 'Tot in den dood');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bsk-lied', 0, 7, 'Den BSK-student');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('gaudeamus-igitur', 'GAUDEAMUS IGITUR', 'GAUDEAMUS IGITUR', 'officiele-liederen', 'la', 'brussels-seniorenkonvent', 92, 93, 'Nieuwe versie door Christian Wilhelm Kindleben.', 'In huidige vorm uit 1781.', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gaudeamus-igitur', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 0, 0, 'Gaudeamus igitur, iuvenes dum sumus,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 0, 1, 'Post iucundam iuventutem,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 0, 2, 'Post molestam senectutem');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 0, 3, 'Nos habebit humus!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('gaudeamus-igitur', 0, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('gaudeamus-igitur', 0, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gaudeamus-igitur', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 1, 0, 'Ubi sunt qui ante nos in mundo fuere?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 1, 1, 'Vadite ad superos,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 1, 2, 'Transite ad inferos,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 1, 3, 'Ubi? Iam fuere.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('gaudeamus-igitur', 1, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('gaudeamus-igitur', 1, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gaudeamus-igitur', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 2, 0, 'Vita nostra brevis est, brevi finietur,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 2, 1, 'Venit mors velociter,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 2, 2, 'Rapit nos atrociter,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 2, 3, 'Nemini parcetur.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('gaudeamus-igitur', 2, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('gaudeamus-igitur', 2, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gaudeamus-igitur', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 3, 0, 'Vivat academia, vivant professores,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 3, 1, 'Vivat membrum quodlibet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 3, 2, 'Vivant membra quaelibet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 3, 3, 'Semper sint in flore!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('gaudeamus-igitur', 3, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('gaudeamus-igitur', 3, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gaudeamus-igitur', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 4, 0, 'Vivant omnes virgines graciles formosae!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 4, 1, 'Vivant et mulieres,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 4, 2, 'Tenerae, amabiles.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 4, 3, 'Bonae, Laboriosae!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('gaudeamus-igitur', 4, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('gaudeamus-igitur', 4, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gaudeamus-igitur', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 5, 0, 'Vivat et res publica et qui illam regit!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 5, 1, 'Vivat nostra civitas,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 5, 2, 'Maecenatum caritas,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 5, 3, 'Quae nos hic protegit!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('gaudeamus-igitur', 5, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('gaudeamus-igitur', 5, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gaudeamus-igitur', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 6, 0, 'Pereat tristitia, pereant osores,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 6, 1, 'Pereat diabolus,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 6, 2, 'Quivis antiburchius,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gaudeamus-igitur', 6, 3, 'Atque irrisores!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('gaudeamus-igitur', 6, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('gaudeamus-igitur', 6, 3, 3, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ave-confrater', 'AVE CONFRATER', 'AVE CONFRATER', 'officiele-liederen', 'nl', 'brussels-seniorenkonvent', 94, 94, NULL, NULL, 'Dit lied wordt gezongen bij de overdracht van het praesesschap. Na de overhandiging van het praeseslint en de eedaflegging, gaan de oude en de nieuwe senior over tot de Ave Confrater.
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ave-confrater', 0, 'direction', 1, 'Legende: 1 = aftredende senior 2 = nieuwe senior');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ave-confrater', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ave-confrater', 1, 0, '1 Ave confrater');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ave-confrater', 1, 1, '2 ’k Drink liever bier dan water');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ave-confrater', 2, 'direction', 1, 'Nummer 2 begint te drinken bij 1, bij 7 heeft hij zijn glas ad fundum gedronken en zet het omgekeerd op zijn hoofd.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ave-confrater', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ave-confrater', 3, 0, '1 Drink dan op het kommando van 1, 2, 3, 4, 5, 6, 7');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ave-confrater', 3, 1, '2 Er is niets meer in mijn glas gebleven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ave-confrater', 3, 2, '2 Ave confrater');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ave-confrater', 3, 3, '1 ’k Drink liever bier dan water');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ave-confrater', 4, 'direction', 1, 'Nummer 1 drinkt op dezelfde manier.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ave-confrater', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ave-confrater', 5, 0, '2 Drink dan op het kommando van 1, 2, 3, 4, 5, 6, 7');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ave-confrater', 5, 1, '1 Er is niets meer in mijn glas gebleven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ave-confrater', 5, 2, '2 Flexamus genua');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ave-confrater', 6, 'direction', 1, 'Beide commilitones maken een knieval.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ave-confrater', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ave-confrater', 7, 0, '1 Levate');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ave-confrater', 8, 'direction', 1, 'Beide commilitones staan terug recht.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ave-confrater', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ave-confrater', 9, 0, '1+2Ave confrater');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('io-vivat', 'IO VIVAT', 'IO VIVAT', 'officiele-liederen', 'la', 'brussels-seniorenkonvent', 95, 95, NULL, NULL, '18e eeuws; traditioneel worden enkel het refrein, de eerste strofe en dan nog eens het refrein gezongen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('io-vivat', 0, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('io-vivat', 0, 0, 'Io vivat! Io vivat!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('io-vivat', 0, 1, 'Nostrorum sanitas!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('io-vivat', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('io-vivat', 1, 0, 'Hoc est amoris poculum!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('io-vivat', 1, 1, 'Doloris est antidotum!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('io-vivat', 1, 2, 'Dum nihil est in poculo.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('io-vivat', 1, 3, 'Jam repleatur denuo!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('io-vivat', 1, 4, 'Nos jungit amicitia,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('io-vivat', 1, 5, 'Et vinum praebet gaudia.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('io-vivat', 1, 6, 'Est vita nostra brevior,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('io-vivat', 1, 7, 'Et mors amara longior.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('io-vivat', 1, 8, 'Osores nostri pereant!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('io-vivat', 1, 9, 'Amici semper floreant!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('io-vivat', 1, 10, 'Jam tota Academia,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('io-vivat', 1, 11, 'Nobiscum amet gaudia.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('tsjechisch-drinklied', 'TSJECHISCH DRINKLIED', 'TSJECHISCH DRINKLIED', 'officiele-liederen', 'nl', 'brussels-seniorenkonvent', 96, 96, NULL, NULL, 'Dr. D. Devos');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('tsjechisch-drinklied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tsjechisch-drinklied', 0, 0, 'Drink uit dan, broeder, drink!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tsjechisch-drinklied', 0, 1, 'Drink uit tot op den grond');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tsjechisch-drinklied', 0, 2, 'Want nooit zien w’ons weerom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tsjechisch-drinklied', 0, 3, 'Voor ’t volle jaar is rond.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('tsjechisch-drinklied', 0, 0, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('tsjechisch-drinklied', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tsjechisch-drinklied', 1, 0, 'En daarom drink maar, drink maar, drink maar,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tsjechisch-drinklied', 1, 1, 'Zolang de beker ons nog wenkt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tsjechisch-drinklied', 1, 2, 'En daarom drink maar, drink maar, drink maar,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tsjechisch-drinklied', 1, 3, 'Zolang een druppel wijn nog blinkt:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tsjechisch-drinklied', 1, 4, 'En daarom drink maar, drink maar, drink maar,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tsjechisch-drinklied', 1, 5, 'Eer we malkander ’t afscheid bi’en,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tsjechisch-drinklied', 1, 6, 'En daarom drink maar, drink maar, drink maar,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tsjechisch-drinklied', 1, 7, 'Drink op het vrolijk wederzien!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('oude-roldersklacht', 'OUDE ROLDERSKLACHT', 'OUDE ROLDERSKLACHT', 'officiele-liederen', 'nl', 'brussels-seniorenkonvent', 96, 98, 'vertaald door K. D. W.', '‘O alte Burschenherrlichkeit’, Eugen Höfling, 1825', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 0, 'direction', 1, 'De lichten worden gedoofd en de eerste vier strofen worden heel plechtig en ingetogen gezongen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 1, 0, 'O vrij-studentenheerlijkheid');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 1, 1, 'Waar zijt gij thans verzwonden?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 1, 2, 'O keer nog eenmaal, schone tijd,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 1, 3, 'Zo vrij, zo ongebonden!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 1, 4, 'Ik zoek U langs mijn wegen weer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 1, 5, 'En vind uw sporen nimmer meer!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 2, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 2, 0, 'O jerum, jerum, jerum');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 2, 1, 'O quae mutatio rerum?');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('oude-roldersklacht', 2, 0, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 3, 'direction', 1, 'De oudstudenten staan recht');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 4, 0, 'Waar zijn zij die voor ’t Brussels* bier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 4, 1, 'Hun laatste cent verdronken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 4, 2, 'Als wereldbazen, op de zwier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 4, 3, 'Met volle potten klonken?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 4, 4, 'Zij gingen, ’t hart gebroken, voort');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 4, 5, 'Van hier naar ’t stil geboorteoord.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 5, 'chorus-ref', 1, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 6, 'direction', 1, 'Studenten toegepaste, exacte, industriële, farmaceutische, politieke, economische en sociale wetenschappen, evenals de handelsingenieurs, architecten en studenten horteco, hotel en toerisme staan recht.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 7, 0, 'Daar ligt er een als man van plicht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 7, 1, 'Op een bureau gebogen;');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 8, 'direction', 1, 'Studenten letteren en wijsbegeerte, pedagogie, psychologie, agogiek, toegepaste taalkunde, sociaal-agogisch werk en lerarenopleiding staan recht.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 9, 0, 'Een ander ontplooit met koud gezicht');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 9, 1, 'Zijn schoolmeestersvermogen.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 9, 2, 'Wie dacht ooit dat een schurk zo fijn');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 9, 3, 'Zou zo pedant geworden zijn?');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 10, 'chorus-ref', 1, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 11, 'direction', 1, 'Studenten genees- en tandheelkunde, verpleegkunde, sport en kine staan recht.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 12, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 12, 0, 'Een dokter preekt de matigheid,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 12, 1, 'En was een grote rolder;');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 13, 'direction', 1, 'Bestuursleden staan recht.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 14, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 14, 0, 'Ministers gaan met statigheid,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 14, 1, 'En woonden hier op zolder;');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 15, 'direction', 1, 'Studenten rechten en criminologie staan recht.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 16, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 16, 0, 'De rechter straft nu drankmisbruik');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 16, 1, 'En vroeger sliep hij met de kruik!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 17, 'chorus-ref', 1, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 18, 'direction', 1, 'Het licht gaat aan. Gans de corona staat recht en men reikt elkaar met gekruiste armen de handen, terwijl men nu met vol enthousiasme verderzingt.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 19, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 19, 0, 'Sa vrienden reikt elkaar de hand,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 19, 1, 'Opdat hij zich vernauwe:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 19, 2, 'Der trouwe vriendschap heil’ge band.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 19, 3, 'De heil’ge band der trouwe.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 20, 'direction', 1, 'De glazen worden geheven en geklonken.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 21, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 21, 0, 'Klinkt aan en heft omhoog het glas.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 21, 1, 'Nog leeft het oud studentenras!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oude-roldersklacht', 22, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 22, 0, 'Laatste Refrein:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 22, 1, 'Bibamus laeti merum;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oude-roldersklacht', 22, 2, 'Non est mutatio rerum!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('oude-roldersklacht', 22, 1, 2, 2, '(BIS)');
INSERT INTO footnote (song_id, position, text) VALUES ('oude-roldersklacht', 0, '* In de originele vertaling gaat het hier om het “Werchters” bier, met name Jack-Op, dat in het begin van de vorige eeuw heel populair was bij de Leuvense studenten. Het wordt sinds 1869 gebrouwen door brouwerij Felix van Roost te Werchter in de stoombrouwerij ’De Palmboom’. Tegenwoordig wordt het gebrouwen in de brouwerij ’Belle-Vue’.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('le-semeur', 'LE SEMEUR', 'SEMEUR, LE', 'officiele-liederen', 'fr', 'brussels-seniorenkonvent', 99, 100, 'Georges Garnir, 1890', 'Charles Mélant', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-semeur', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 0, 0, 'Semeurs vaillants du rêve,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 0, 1, 'Du travail, du plaisir,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 0, 2, 'C’est pour nous que se lève');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 0, 3, 'La moisson d’avenir');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 0, 4, 'Ami de la science,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 0, 5, 'Léger, insouciant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 0, 6, 'Et fou d’indépendance');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 0, 7, 'Tel est l’étudiant!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-semeur', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 1, 0, 'Frère, chante ton verre,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 1, 1, 'Et chante ta gaîté,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 1, 2, 'La femme qui t’est chère');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 1, 3, 'Et la fraternité');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 1, 4, 'À d’autres la sagesse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 1, 5, 'Nous t’aimons Vérité');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 1, 6, 'Mais la seule maîtresse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 1, 7, 'Ah, c’est toi, Liberté!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-semeur', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 2, 0, 'Aux rêves de notre âge');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 2, 1, 'Larges, ambitieux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 2, 2, 'S’il était fait outrage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 2, 3, 'Gare à l’audacieux!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 2, 4, 'Si l’on osait prétendre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 2, 5, 'À mettre le Holà');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 2, 6, 'Liberté, pour défendre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 2, 7, 'Tes droits nous serions là!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-semeur', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 3, 0, 'Une aurore nouvelle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 3, 1, 'Grandit à l’horizon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 3, 2, 'La Science immortelle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 3, 3, 'Eclaire la Raison');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 3, 4, 'Rome tremble et chancelle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 3, 5, 'Devant la Vérité');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 3, 6, 'Serrons-nous autour d’elle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-semeur', 3, 7, 'Contre la papauté!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('aan-de-oevers-van-de-zenne', 'AAN DE OEVERS VAN DE ZENNE', 'AAN DE OEVERS VAN DE ZENNE', 'nederlandstalige-liederen', 'nl', NULL, 103, 103, NULL, 'Van oorsprong een Russisch kozakkenlied ter nagedachtenis van Stenka Razin, de leider van een boerenopstand in 1667.', 'De originele titel luidt ‘Aan de oevers van de Rotte’. De Rotte is de rivier in Nederland aan wie Rotterdam haar naam dankt. Vele regio’s hebben hun eigen versie van dit lied, waar de naam van de rivier aangepast wordt.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('aan-de-oevers-van-de-zenne', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aan-de-oevers-van-de-zenne', 0, 0, 'Aan de oevers van de Zenne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aan-de-oevers-van-de-zenne', 0, 1, 'Daar verscholen in het riet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aan-de-oevers-van-de-zenne', 0, 2, 'Zat een kleine, jonge kikker,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aan-de-oevers-van-de-zenne', 0, 3, 'Bij zijn moeder op de knie.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('aan-de-oevers-van-de-zenne', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aan-de-oevers-van-de-zenne', 1, 0, '“Ziet gij daar”, zo sprak die moeder,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aan-de-oevers-van-de-zenne', 1, 1, '“Ziet gij daar, dien ooievaar?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aan-de-oevers-van-de-zenne', 1, 2, '’t Is de moord’naar van uw vader,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aan-de-oevers-van-de-zenne', 1, 3, 'Hij vrat hem op met huid en haar.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('aan-de-oevers-van-de-zenne', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aan-de-oevers-van-de-zenne', 2, 0, '“Godverdomme”, zo sprak die kleine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aan-de-oevers-van-de-zenne', 2, 1, '“Heeft die smeerlap dat gedaan?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aan-de-oevers-van-de-zenne', 2, 2, 'Als ik groot en sterk zal wezen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aan-de-oevers-van-de-zenne', 2, 3, 'Zal ’k hem op zijn kloten slaan!”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('aan-de-oevers-van-de-zenne', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aan-de-oevers-van-de-zenne', 3, 0, 'Vele jaren zijn verstreken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aan-de-oevers-van-de-zenne', 3, 1, 'En de kikker is niet meer,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aan-de-oevers-van-de-zenne', 3, 2, 'Maar de ooievaar zijn kloten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aan-de-oevers-van-de-zenne', 3, 3, 'Doen verdomme nog altijd zeer!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('aan-de-oevers-van-de-zenne', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aan-de-oevers-van-de-zenne', 4, 0, '’k Heb zoveel U nog te zeggen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aan-de-oevers-van-de-zenne', 4, 1, 'Maar ge zoudt het niet verstaan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aan-de-oevers-van-de-zenne', 4, 2, '’k Zal U in uw bedje leggen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aan-de-oevers-van-de-zenne', 4, 3, 'En daarmee is het lied gedaan!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ach-lieflijke-meisjes', 'ACH LIEFLIJKE MEISJES', 'ACH LIEFLIJKE MEISJES', 'nederlandstalige-liederen', 'nl', NULL, 104, 105, 'L. Dolhain', '‘Etoile des neiges’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ach-lieflijke-meisjes', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 0, 0, 'Er liep eens een schachtje door Brussel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 0, 1, 'Hij was vol ijver en vlijt.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 0, 2, 'Toen zag hij de schoonste');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 0, 3, 'Schachtin van het jaar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 0, 4, 'En droomde van vrijen gaan met haar.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ach-lieflijke-meisjes', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 1, 0, 'Ach lieflijke meisjes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 1, 1, 'Wij hebben geen tijd,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 1, 2, 'Er valt te blokken:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 1, 3, 'De FACULTEIT ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 1, 4, 'Ach lieflijke meisjes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 1, 5, 'Wij hebben geen tijd,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 1, 6, 'Alleen studeren telt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 1, 7, 'Aan de universiteit.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ach-lieflijke-meisjes', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 2, 0, 'Toen kwam er de dag dat hij groot werd,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 2, 1, 'Hij ging voor ’t eerst naar de club.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 2, 2, 'Hij werd er gedoopt en hij dronk er lambik');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 2, 3, 'En gaf voor het bier het meisje op.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ach-lieflijke-meisjes', 3, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 3, 0, 'Ach lieflijke meisjes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 3, 1, 'Wij hebben geen tijd,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 3, 2, 'Er valt te drinken:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 3, 3, 'SPECIALITEIT ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 3, 4, 'Ach lieflijke meisjes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 3, 5, 'Wij hebben geen tijd,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 3, 6, 'Alleen de club die telt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 3, 7, 'Aan de universiteit.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ach-lieflijke-meisjes', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 4, 0, 'Maar eens komt er een eind aan ’t studeren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 4, 1, 'Dan werkt hij zelf voor zijn brood.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 4, 2, 'Dan denkt hij aan trouwen, aan kinderen en huis');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 4, 3, 'En zoekt zich een maagdje rein en kuis.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ach-lieflijke-meisjes', 5, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 5, 0, 'Ach lieflijk jong meisje,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 5, 1, 'Nu heb ik wel tijd!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 5, 2, 'Er valt te trouwen:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 5, 3, 'MATERNITEIT ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 5, 4, 'Ach lieflijk jong meisje,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 5, 5, 'Nu heb ik wel tijd!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 5, 6, 'Alleen nog trouwen telt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ach-lieflijke-meisjes', 5, 7, 'Aan de universiteit.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ad-fundum-per-jaar', 'AD FUNDUM PER JAAR', 'AD FUNDUM PER JAAR', 'nederlandstalige-liederen', 'nl', NULL, 105, 106, NULL, NULL, '‘per jaar’ heeft hier betrekking op het aantal jaren studie.
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ad-fundum-per-jaar', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ad-fundum-per-jaar', 0, 0, 'En al wie voor ’t eerste jaar,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ad-fundum-per-jaar', 0, 1, 'Te Brussel is; sta recht!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ad-fundum-per-jaar', 0, 2, 'Breng het glaasje aan de lippen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ad-fundum-per-jaar', 0, 3, 'Laat het zachtjes binnenglippen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ad-fundum-per-jaar', 0, 4, 'Breng het glaasje aan de mond,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ad-fundum-per-jaar', 0, 5, 'En drink het uit tot op de grond!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ad-fundum-per-jaar', 0, 0, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ad-fundum-per-jaar', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ad-fundum-per-jaar', 1, 0, 'Ja, dat voelen zij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ad-fundum-per-jaar', 1, 1, 'Aan hun hartje');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ad-fundum-per-jaar', 1, 2, 'Ja, dat voelen zij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ad-fundum-per-jaar', 1, 3, 'Aan hun jeugdig hartje.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ad-fundum-per-jaar', 1, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ad-fundum-per-jaar', 1, 1, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ad-fundum-per-jaar', 1, 2, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ad-fundum-per-jaar', 2, 'direction', 1, 'De rechtstaande commilitones zingen vervolgens deze laatste regels maar vervangen ‘zij’ en ‘hun’ respectievelijk door ‘wij’ en ‘ons’. ‘Eerste’ wordt nu vervangen door ‘tweede’ (enzovoort) tot alle jaren geweest zijn. Voor eventuele oud-studenten wordt de ganse eerste zin vervangen door de volgende:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ad-fundum-per-jaar', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ad-fundum-per-jaar', 3, 0, 'En al wie niet meer te Brussel is');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ad-fundum-per-jaar', 4, 'direction', 1, 'Indien er niemand recht staat zingt de corona:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ad-fundum-per-jaar', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ad-fundum-per-jaar', 5, 0, '’t Is mis! ’t Is mis! ’t Is mis!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ad-fundum-per-jaar', 5, 0, 0, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('adhemar', 'ADHEMAR', 'ADHEMAR', 'nederlandstalige-liederen', 'nl', NULL, 106, 107, NULL, '‘Gaudeamus igitur’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('adhemar', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 0, 0, 'Adhemar heeft syfilis');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 0, 1, 'Wat verdomd vervelend is');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 0, 2, 'In een bed met zeven teven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 0, 3, 'Heeft hij al zijn zaad gegeven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 0, 4, 'En zijn pietje is afgezet.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('adhemar', 0, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('adhemar', 0, 4, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('adhemar', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 1, 0, 'Honoree heeft gonoree');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 1, 1, 'Maar hij poept nog altijd mee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 1, 2, 'Als hij op zijn wijf wil kruipen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 1, 3, 'Blijft zijn pietje steeds maar druipen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 1, 4, 'En hij laat haar met een vuile snee.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('adhemar', 1, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('adhemar', 1, 4, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('adhemar', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 2, 0, 'Mie katoen komt morgennoen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 2, 1, 'Om ne ferme poep te doen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 2, 2, 'Als haar preut begint te lekken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 2, 3, 'Is ’t tapijt vol vuile vlekken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 2, 4, 'En dan poept ze tot de noen.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('adhemar', 2, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('adhemar', 2, 4, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('adhemar', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 3, 0, 'Er hangt visgeur in de lucht');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 3, 1, 'Want Mie Pis zit met de bucht');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 3, 2, 'Iedere keer dat ze moet zeken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 3, 3, 'Moet ze een andere vod opsteken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 3, 4, 'En dat maakt een hels gerucht.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('adhemar', 3, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('adhemar', 3, 4, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('adhemar', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 4, 0, 'De moraal is zeer devoot:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 4, 1, 'Gebruik steeds een kapoot');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 4, 2, 'Voor tien frank bij den apotheker');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 4, 3, 'Hebt gij nooit een vuile steker');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('adhemar', 4, 4, 'En uw pietje is nooit meer bloot!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('adhemar', 4, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('adhemar', 4, 4, 4, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('age-quod-agis', 'AGE QUOD AGIS', 'AGE QUOD AGIS', 'nederlandstalige-liederen', 'nl', NULL, 107, 108, NULL, '‘De lichtjes van de Schelde’, Bobbejaan Schoepen', 'AVSG, 30e Vrijzinnig Zangfeest van Vlaanderen, 2015');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('age-quod-agis', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 0, 0, 'Ik was nog een kind toen ik vaders klak zag,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 0, 1, 'ze lag tussen zijn oude kleren.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 0, 2, 'Ik ging naar hem toe en hij schoot in de lach.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 0, 3, 'Zeg jongen, ik zal jou iets leren...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 0, 4, 'Hij vertelde mij toen over zijn ouwe tijd,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 0, 5, 'over klak, labojas, pot en pint.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 0, 6, 'Hij zei wacht maar af tot ge ouder zijt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 0, 7, 'en ge ’t al’maal zelf ondervindt.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('age-quod-agis', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 1, 0, 'Zolang de student nog vrij kan denken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 1, 1, 'zal de folklore nooit vergaan.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 1, 2, 'Ik kan me niets zo moois bedenken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 1, 3, 'dan met men club op zwier te gaan.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 1, 4, 'Oude verhalen lijken beter,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 1, 5, 'maar dat is lang vervlogen tijd.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 1, 6, 'Dus hef nu allemaal de beker');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 1, 7, 'en drink op de vrijzinnigheid.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('age-quod-agis', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 2, 0, 'Ik weet het nog goed al mijn jaren als schacht.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 2, 1, 'Mijn vaders verhaal leek verloren.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 2, 2, 'Niets gebeurt hier zoals ik ’t had verwacht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 2, 3, 'een nieuw tijdperk is aangebroken.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 2, 4, 'De tijden zijn anders maar ’t lied klinkt nog fel!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 2, 5, 'Hier schrijven w’ons eigen verhaal.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 2, 6, 'Klinken en drinken dat doen we nog wel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 2, 7, 'dus zing nu maar mee allemaal!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('age-quod-agis', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 3, 0, 'De zon komt al op en ik wankel naar huis,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 3, 1, 'de cantus is weer afgelopen.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 3, 2, '’k geraak niet in mijn les, dus dat wordt weer een buis.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 3, 3, 'Zal straks met een kater rondlopen.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 3, 4, 'Weeral een avond die ’k nooit meer vergeet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 3, 5, 'de vriendschap, ’t gezang en ’t jolijt.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 3, 6, 'één ding dat ik wel zeker weet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('age-quod-agis', 3, 7, 'folklore gaat mee met zen tijd!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('al-die-willen-te-kaap-ren-varen', 'AL DIE WILLEN TE KAAP’REN VAREN', 'AL DIE WILLEN TE KAAP’REN VAREN', 'nederlandstalige-liederen', 'nl', NULL, 109, 109, NULL, NULL, 'Opgetekend door De Coussemaker, 1856
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('al-die-willen-te-kaap-ren-varen', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-die-willen-te-kaap-ren-varen', 0, 0, 'Al die willen te Kaap’ren varen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-die-willen-te-kaap-ren-varen', 0, 1, 'Moeten mannen met baarden zijn:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-die-willen-te-kaap-ren-varen', 0, 2, 'Jan, Pier, Tjores en Korneel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-die-willen-te-kaap-ren-varen', 0, 3, 'Die hebben baarden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-die-willen-te-kaap-ren-varen', 0, 4, 'Jan, Pier, Tjores en Korneel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-die-willen-te-kaap-ren-varen', 0, 5, 'Die hebben baarden zij varen mee!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('al-die-willen-te-kaap-ren-varen', 0, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('al-die-willen-te-kaap-ren-varen', 1, 'direction', 1, 'Voor de volgende strofen vervangt men de eerste regel door:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('al-die-willen-te-kaap-ren-varen', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-die-willen-te-kaap-ren-varen', 2, 0, 'Al die ranzige tweebak lusten');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('al-die-willen-te-kaap-ren-varen', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-die-willen-te-kaap-ren-varen', 3, 0, 'Al die deftige pijpkens smoren');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('al-die-willen-te-kaap-ren-varen', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-die-willen-te-kaap-ren-varen', 4, 0, 'Allen die met ons de walvis killen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('al-die-willen-te-kaap-ren-varen', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-die-willen-te-kaap-ren-varen', 5, 0, 'Allen die dood en duivel niet duchten');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('al-van-den-drogen-haring', 'AL VAN DEN DROGEN HARING', 'AL VAN DEN DROGEN HARING', 'nederlandstalige-liederen', 'nl', NULL, 109, 110, NULL, NULL, 'Lied uit de streek van Duinkerken');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('al-van-den-drogen-haring', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-van-den-drogen-haring', 0, 0, 'Al van den drogen haring willen wij zingen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-van-den-drogen-haring', 0, 1, 'Ter ere van zijn kopke zullen wij springen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-van-den-drogen-haring', 0, 2, '’t Is van zijn kop, springt er maar op:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-van-den-drogen-haring', 0, 3, '’t Is van den drogen haring!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('al-van-den-drogen-haring', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-van-den-drogen-haring', 1, 0, 'Al van den drogen haring willen wij zingen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-van-den-drogen-haring', 1, 1, 'Ter ere van zijn oogske zullen wij springen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-van-den-drogen-haring', 1, 2, '’t Is van zijn oog, springt er maar hoog:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-van-den-drogen-haring', 1, 3, '’t Is van den drogen haring!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('al-van-den-drogen-haring', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-van-den-drogen-haring', 2, 0, 'Al van den drogen haring willen wij zingen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-van-den-drogen-haring', 2, 1, 'Ter ere van zijn balgske zullen wij springen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-van-den-drogen-haring', 2, 2, '’t Is van zijn balg, springt er maar half:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-van-den-drogen-haring', 2, 3, '’t Is van den drogen haring!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('al-van-den-drogen-haring', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-van-den-drogen-haring', 3, 0, 'Al van den drogen haring willen wij zingen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-van-den-drogen-haring', 3, 1, 'Ter ere van zijn stertje willen wij springen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-van-den-drogen-haring', 3, 2, '’t Is van zijn stert, springt er met hert:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('al-van-den-drogen-haring', 3, 3, '’t Is van den drogen haring!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('allen-die-willen-naar-island-gaan', 'ALLEN DIE WILLEN NAAR ISLAND GAAN', 'ALLEN DIE WILLEN NAAR ISLAND GAAN', 'nederlandstalige-liederen', 'nl', NULL, 111, 112, NULL, NULL, 'Opgetekend door De Coussemaker, 1856
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('allen-die-willen-naar-island-gaan', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 0, 0, 'Allen die willen naer Island gaen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 0, 1, 'Om kabeljauw te vangen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 0, 2, 'En te visschen met verlange');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 0, 3, 'Naer Iseland, naer Iseland, naer Island toe:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 0, 4, 'Tot drie-en-dertig reyzen zyn zy nog niet moe.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('allen-die-willen-naar-island-gaan', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 1, 0, 'Komt ons den tyd van de fooie aen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 1, 1, 'Wy danse met behaegen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 1, 2, 'En wy weten van geen klaegen:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 1, 3, 'Maer komt de tyd, maer komt de tyd naer zee te gaen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 1, 4, 'Dan is er wel ons hoofd van zorgen zwaar belaên');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('allen-die-willen-naar-island-gaan', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 2, 0, 'Als er de wind van het Noorden waeyt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 2, 1, 'Wy gaen naer de herberge,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 2, 2, 'En wy drinken zonder erge,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 2, 3, 'Wy drinken daer, wy drinken daer op ons gemak,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 2, 4, 'Tot dat den lesten stuyver is uyt onzen zak.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('allen-die-willen-naar-island-gaan', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 3, 0, 'Als er de wind van het Oosten waeyt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 3, 1, 'De schipper, blij van herte,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 3, 2, 'Zegt: “Die wind, die speelt ons perten”;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 3, 3, '’t Zal beter zijn, ’t zal beter zijn, ’t zal beter zijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 3, 4, 'Te lopen voor de wind recht het Kanaal maer in.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('allen-die-willen-naar-island-gaan', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 4, 0, 'Langs de Lezaars, de Schorrels voorbij,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 4, 1, 'Vandaar al naar Kaap Claire,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 4, 2, 'Die niet weet, hij zal wel leren.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 4, 3, 'Toen komt er bij, toen komt er bij ons sture man,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 4, 4, 'En hij geeft ons de koerse recht naer Iseland.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('allen-die-willen-naar-island-gaan', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 5, 0, 'Wij lopen ’t eiland Rockol voorbij,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 5, 1, 'Al naar de Vogelscharen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 5, 2, 'Dat kan ieder openbaren;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 5, 3, 'En dan vandaar, en dan vandaar naar Bredefjord,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 5, 4, 'En daar dan smijten wij de kollen buiten boord.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('allen-die-willen-naar-island-gaan', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 6, 0, 'Eind’lijk dan komen w’op Island aen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 6, 1, 'Om kabeljauw te vangen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 6, 2, 'En te visschen met verlange');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 6, 3, 'Naer Iseland, naer Iseland, naer Island toe:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('allen-die-willen-naar-island-gaan', 6, 4, 'Tot drie-en-dertig reyzen zyn wy nog niet moe.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('alonder-de-blauwe-hemel', 'ALONDER DE BLAUWE HEMEL', 'ALONDER DE BLAUWE HEMEL', 'nederlandstalige-liederen', 'nl', NULL, 112, 112, NULL, 'Boudewijn de Groot', 'Oorspronkelijk ‘Land van Maas en Waal’');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('alonder-de-blauwe-hemel', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alonder-de-blauwe-hemel', 0, 0, 'Alonder de blauwen hemel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alonder-de-blauwe-hemel', 0, 1, 'In het suikerriet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alonder-de-blauwe-hemel', 0, 2, 'Kunde poepen voor ne frank,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alonder-de-blauwe-hemel', 0, 3, 'Tot uw piet er blauw van ziet.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('alonder-de-blauwe-hemel', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alonder-de-blauwe-hemel', 1, 0, 'Maar had ik het maar geweten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alonder-de-blauwe-hemel', 1, 1, 'Ik had het nooit gedaan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alonder-de-blauwe-hemel', 1, 2, 'Mijn piet dien is versleten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alonder-de-blauwe-hemel', 1, 3, 'En mijn kloten zijn naar de maan.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('alonder-de-blauwe-hemel', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alonder-de-blauwe-hemel', 2, 0, 'We waren wel met honderd,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alonder-de-blauwe-hemel', 2, 1, 'Al ieder met een hoer,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alonder-de-blauwe-hemel', 2, 2, 'We poepten dat het dondert,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alonder-de-blauwe-hemel', 2, 3, 'En het vet liep van de vloer.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('als-de-kerels-te-gare-zijn', 'ALS DE KERELS TE GARE ZIJN', 'ALS DE KERELS TE GARE ZIJN', 'nederlandstalige-liederen', 'nl', NULL, 113, 114, 'Albrecht Rodenbach', 'Engels Volkswijsje', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('als-de-kerels-te-gare-zijn', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 0, 0, 'Als de kerels te gare zijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 0, 1, 'Doedle bomle rom dom dom,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 0, 2, 'Wat liedje moet er gezongen zijn?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 0, 3, 'Doedle rom dom dom!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('als-de-kerels-te-gare-zijn', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 1, 0, '’t Kerelslied, ’t kerelslied,');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('als-de-kerels-te-gare-zijn', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 2, 0, 'Doedle bomle rom dom dom,');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('als-de-kerels-te-gare-zijn', 3, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 3, 0, '’t Kerelslied, ’t kerelslied,');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('als-de-kerels-te-gare-zijn', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 4, 0, 'Doedle rom dom dom.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('als-de-kerels-te-gare-zijn', 5, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('als-de-kerels-te-gare-zijn', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 6, 0, 'Zij renden met zessen langs de baan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 6, 1, 'Zij hadden stalen kleren aan,');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('als-de-kerels-te-gare-zijn', 7, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 7, 0, 'Isegrims, Isegrims.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('als-de-kerels-te-gare-zijn', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 8, 0, 'Zij hadden waaiend’ helmen aan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 8, 1, 'Zij renden zingend langs de baan,');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('als-de-kerels-te-gare-zijn', 9, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 9, 0, 'Wat zongen zij? Wat zongen zij?');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('als-de-kerels-te-gare-zijn', 10, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 10, 0, 'Van edele ridders en heren groot,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 10, 1, 'Van nijdige kerels en galgedood,');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('als-de-kerels-te-gare-zijn', 11, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 11, 0, 'Isegrims, Isegrims.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('als-de-kerels-te-gare-zijn', 12, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 12, 0, 'De kerels kennen een schon’ren zang,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 12, 1, 'De zang der kerels is niet lang,');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('als-de-kerels-te-gare-zijn', 13, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 13, 0, 'Maar zegt veel. Maar zegt veel.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('als-de-kerels-te-gare-zijn', 14, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 14, 0, '“Vliegt de Blauwvoet? Storm op zee!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 14, 1, '“Vliegt de Blauwvoet? Storm op zee!”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('als-de-kerels-te-gare-zijn', 15, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 15, 0, 'Storm op zee! Storm op zee!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('als-de-kerels-te-gare-zijn', 16, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 16, 0, 'En als de kerel aan ’t zingen valt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 16, 1, 'zijn liedje vromer als d’andre schalt,');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('als-de-kerels-te-gare-zijn', 17, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('als-de-kerels-te-gare-zijn', 17, 0, 'Storm op zee! Storm op zee!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('beiaardlied', 'BEIAARDLIED', 'BEIAARDLIED', 'nederlandstalige-liederen', 'nl', NULL, 114, 115, 'Julius de Geyter', 'Peter Benoit', 'Ter gelegenheid van de 300e geboortedag van Rubens, kreeg Peter Benoit de opdracht een feestcantate, de ‘Rubenscantate’ te schrijven. Het thema was de verheerlijking van Antwerpen. Hij ontving de opdracht in 1877. Op 18 augustus vond de eerste opvoering plaats op de Antwerpse Groenplaats, waar het podium was opgesteld naast het standbeeld van Rubens. Vanop de nabije toren van de O.L.V.kathedraal werd de opvoering begeleid door de beiaard. Dit zogeheten ‘Beiaardlied’ sloeg zozeer aan, dat het bijna een volkslied werd.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('beiaardlied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('beiaardlied', 0, 0, 'Dan mocht de Beiaard spelen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('beiaardlied', 0, 1, 'Van al uw torentransen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('beiaardlied', 0, 2, 'Dan mocht de grijsheid kwelen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('beiaardlied', 0, 3, 'Dan mocht de jonkheid dansen.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('beiaardlied', 0, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('beiaardlied', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('beiaardlied', 1, 0, 'Dan schiept gij opgetogen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('beiaardlied', 1, 1, 'Tot prinsen, Vlaamse steden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('beiaardlied', 1, 2, 'Die onder zegebogen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('beiaardlied', 1, 3, 'Op zegewagens reden.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('beiaardlied', 1, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('beiaardlied', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('beiaardlied', 2, 0, 'Dan liet gij uw rondelen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('beiaardlied', 2, 1, 'En kanten gevels glanzen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('beiaardlied', 2, 2, 'Dan hieldt gij landjuwelen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('beiaardlied', 2, 3, 'Dan vlocht gij lauwerkransen.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('beiaardlied', 2, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('beiaardlied', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('beiaardlied', 3, 0, 'Dan spreiddet gij voor d’ogen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('beiaardlied', 3, 1, 'Uw vrijheid, kunst en zeden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('beiaardlied', 3, 2, 'Op allen mocht gij bogen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('beiaardlied', 3, 3, 'Om allen werdt g’aanbeden.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('beiaardlied', 3, 3, 3, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('het-beleg-van-berg-op-zoom', 'HET BELEG VAN BERG-OP-ZOOM', 'BELEG VAN BERG-OP-ZOOM, HET', 'nederlandstalige-liederen', 'nl', NULL, 116, 117, 'Adriaen Valerius, uit ‘Nederlantsche Gedenck-klanck’, 1626, Oorspronkelijk ‘Lied op het ontzet van Berg-op-Zoom’', '‘Comediantendans’', 'Overwinningslied over het ontzetten, op 2 oktober 1622, van Spinola en zijn troepen na een drie maanden durend beleg.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-beleg-van-berg-op-zoom', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 0, 0, 'Merck toch hoe sterck nu in ’t werck sich al steld');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 0, 1, 'Die t’allen tyd so ons vryheyt heeft bestreden.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 0, 2, 'Siet hoe hy slaeft, graeft en draeft met geweld');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 0, 3, 'Om onse goet en ons bloet en onse stede!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 0, 4, 'Hoor de Spaensche trommels slaen!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 0, 5, 'Hoor Maraens trompetten!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 0, 6, 'Siet, hoe komt hy trecken aen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 0, 7, 'Bergen te besetten!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 0, 8, 'Berg-op-Zoom, hout U vroom,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 0, 9, 'Stut de Spaensche scharen.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 0, 10, 'Laet ’s lands boom en syn stroom,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 0, 11, 'Trouw’lyk toch bewaren.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-beleg-van-berg-op-zoom', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 1, 0, '’t Moedige bloedige woedige swaerd');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 1, 1, 'Blonck en het klonck, dat de voncken daer uyt stoven.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 1, 2, 'Beving en leving, opgeving der aerd,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 1, 3, 'Wonder gedonder nu onder was nu boven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 1, 4, 'Door al ’t mynen en ’t geschut,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 1, 5, 'Dat men daeglycx hoorde;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 1, 6, 'Menig Spanjaert in syn hut,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 1, 7, 'In syn bloet versmoorde.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 1, 8, 'Berg-op-Zoom, hout sich vroom,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 1, 9, 'Stut de Spaensche scharen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 1, 10, '’t Heeft ’s lands boom en syn stroom,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 1, 11, 'Trouw’lyck doen bewaren.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-beleg-van-berg-op-zoom', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 2, 0, 'Die van Oranje quam Spanjen aen boord');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 2, 1, 'Om uyt het velt, als een helt, ’t geweld te weren;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 2, 2, 'Maer also dra Spinola ’t heeft gehoord');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 2, 3, 'Treckt hy flocx heen op de been met al syn heeren.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 2, 4, 'Cordua kruyd spoedig voort,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 2, 5, 'Sach daer niets te winnen;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 2, 6, 'Don Velasco liep gestoort,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 2, 7, '’t Vlas was niet te spinnen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 2, 8, 'Berg-op-Zoom, hout sich vroom,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 2, 9, 'Stut de Spaensche scharen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 2, 10, '’t Heeft ’s lands boom en syn stroom,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-beleg-van-berg-op-zoom', 2, 11, 'Trouw’lyck doen bewaren.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('de-bieren-van-brussel', 'DE BIEREN VAN BRUSSEL', 'BIEREN VAN BRUSSEL, DE', 'nederlandstalige-liederen', 'nl', NULL, 117, 118, 'François Putman', 'Robert Hemmerdinger', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-bieren-van-brussel', 0, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-bieren-van-brussel', 0, 0, 'Santé, santé pakt der nog iene mei');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-bieren-van-brussel', 0, 1, '‘t Is weiral feest in ‘t staminei');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-bieren-van-brussel', 0, 2, 'Santé, santé pakt der nog iene mei');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-bieren-van-brussel', 0, 3, '‘t Is weiral van ons mei eur prei.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-bieren-van-brussel', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-bieren-van-brussel', 1, 0, 'En ons pepeike en ons memeike');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-bieren-van-brussel', 1, 1, 'Dei droenke Geuze en Kriek van ‘t vat');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-bieren-van-brussel', 1, 2, 'En oek ‘t kadeike van ‘t stamineike');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-bieren-van-brussel', 1, 3, 'Werd van de reuk van ‘t bier strontzat.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-bieren-van-brussel', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-bieren-van-brussel', 2, 0, 'Madame van ‘t hoekske nam bei heur koekske');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-bieren-van-brussel', 2, 1, 'Een klein Framboise en viel flauw');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-bieren-van-brussel', 2, 2, 'Zeide van ‘t kliekske drinkt dan e Lambikske');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-bieren-van-brussel', 2, 3, 'Ge zweirt zo’n pint eeuwige trouw.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-bieren-van-brussel', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-bieren-van-brussel', 3, 0, 'Faro met vrienden, de oogskes blinken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-bieren-van-brussel', 3, 1, 'Den duvel danst me ons oep ‘t vat');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-bieren-van-brussel', 3, 2, 'Een sloekske drinken en dan weir klinken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-bieren-van-brussel', 3, 3, 'Santé, Brussel de schoonste stad.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('t-biervat', '’T BIERVAT', 'BIERVAT, ’T', 'nederlandstalige-liederen', 'nl', NULL, 118, 120, 'Maja Marcucci, Brussels Senioren Konvent', '‘’t Zoutvat’, Laïs', 'Winnend lied op het 15e Vrijzinnig Zangfeest van Vlaanderen, 2000');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-biervat', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 0, 0, 'Een jongeling van 18 jaar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 0, 1, 'Kwam in Brussel studeren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 0, 2, 'Zijn vrienden die verkozen Leuven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 0, 3, 'Dat kon hem niet deren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 0, 4, 'Zijn keuze was gemaakt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 0, 5, 'En hij wist wat daar op hem wachtte');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 0, 6, 'Een wereld waar een mens');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 0, 7, 'Baas is over eigen gedachten');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-biervat', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 1, 0, 'Op zijn kamer en bureau');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 1, 1, 'Was hij snel uitgekeken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 1, 2, 'Verveelde zich te pletter');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 1, 3, 'En dus na enkele weken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 1, 4, 'Kreeg hij de kriebels in zijn bloed,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 1, 5, 'Hij wilde wat beleven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 1, 6, 'Besloot zich te verdiepen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 1, 7, 'In ’t Brussels studentenleven');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-biervat', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 2, 0, 'Hij liet zich dopen bij een club');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 2, 1, 'En was meteen bezeten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 2, 2, 'Door ’t Brussels uitgaansleven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 2, 3, 'Wou van niets anders meer weten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 2, 4, 'Cantus, fuiven en St-V,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 2, 5, 'Hij kon er niet van zwijgen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 2, 6, 'En deed met alles mee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 2, 7, 'Hij kon er niet genoeg van krijgen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-biervat', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 3, 0, 'Menig avond is hij moeizaam');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 3, 1, 'Naar zijn kot gekropen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 3, 2, 'Nadat hij zich weer eens een keer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 3, 3, 'Te pletter had gezopen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 3, 4, 'De kater van de dag erop');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 3, 5, 'Kon nog de pret niet drukken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 3, 6, 'Al wou wat wel begrijp’lijk is');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 3, 7, '’t Studeren niet erg lukken');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-biervat', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 4, 0, 'Het jaar liep op zijn einde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 4, 1, 'En de jongeling zou zakken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 4, 2, 'En kocht meteen een zilv’ren ster');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 4, 3, 'Om op zijn klak te plakken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 4, 4, 'De rij van sterren groeide snel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 4, 5, 'Met af en toe een gouden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 4, 6, 'En elk jaar dat erbij kwam');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 4, 7, 'Ging hij meer van Brussel houden');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-biervat', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 5, 0, 'Na vele jaren van plezier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 5, 1, 'En enk’le van studeren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 5, 2, 'Kon hij met een diploma');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 5, 3, 'In zijn hand naar huis toekeren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 5, 4, 'Maar ergens binnenin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 5, 5, 'Bleef hij de roep van Brussel horen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 5, 6, 'Hij kon er niets aan doen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 5, 7, 'Had er zijn hart voorgoed verloren');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-biervat', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 6, 0, 'Dus telkens als in Brussel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 6, 1, 'd’Avond valt kun je hem verwachten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 6, 2, 'Hij fuift met de studenten mee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 6, 3, 'En keurt de nieuwe schachten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 6, 4, 'En samen gaan ze aan de rol');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 6, 5, 'Zich Brussel eigen maken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 6, 6, 'Ja wie zich eens aan Brussel bindt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-biervat', 6, 7, 'Zal er nooit weg geraken.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('de-blauwvoet', 'DE BLAUWVOET', 'BLAUWVOET, DE', 'nederlandstalige-liederen', 'nl', NULL, 122, 123, 'Albrecht Rodenbach, Emiel Hullebroeck', 'Johan De Stoop', 'Vroeger strijdlied van de Vlaamse studentenbeweging. Dit is de tweede versie van dit lied en werd geschreven op 25 september 1875, de eerdere versie was slechts vijf dagen oud. Het werd twee jaar later nog eens herdicht “om te akkoord te staan met het huidig slaan sommiger piano’s”.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-blauwvoet', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 0, 0, 'Nu het lied der Vlaamse zonen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 0, 1, 'Nu een dreunend kerelslied,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 0, 2, 'Dat in wilde noordertonen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 0, 3, 'Uit het diepst ons herten schiet.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-blauwvoet', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 1, 0, 'Ei! Het lied der Vlaamse zonen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 1, 1, 'Met zijn wilde noordertonen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 1, 2, 'Met het oude Vlaams Hoezee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 1, 3, 'Vliegt de Blauwvoet? Storm op zee!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-blauwvoet', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 2, 0, '’t Wierd gezeid dat Vlaanderen groot was,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 2, 1, 'Groot scheen in der tijden wolk,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 2, 2, 'Maar dat Vlaanderland nu dood was,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 2, 3, 'En het vrije kerelsvolk.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-blauwvoet', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 3, 0, 'Maar dan klonk een stemme krachtig,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 3, 1, 'Over ’t oude Noordzeestrand,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 3, 2, 'En het stormde groots en machtig,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 3, 3, 'In dat dode Vlaanderland.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-blauwvoet', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 4, 0, 'En hier staan wij, ’t hoofd omhoge,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 4, 1, 'Vuisten sidd’rend, kokend bloed,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 4, 2, 'Vlam in ’t herte, vlam in d’oge,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 4, 3, 'En ons naam ons trillen doet!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-blauwvoet', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 5, 0, 'Van de blonde noordse stranden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 5, 1, 'Dwang en buigen ongewend,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 5, 2, 'Onze vaders herwaarts landden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 5, 3, 'Leden, streden, ongetemd.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-blauwvoet', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 6, 0, 'Ja wij zijn der Vlamen zonen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 6, 1, 'Sterk van lijve, sterk van ziel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 6, 2, 'En wij zou’n nog kunnen tonen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 6, 3, 'Hoe de klauw der klauwaards viel.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-blauwvoet', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 7, 0, 'Op ons vane vliegt de Blauwvoet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 7, 1, 'Die voorspelt het zeegedruis,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 7, 2, 'En de leeuw er met zijn klauw hoedt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 7, 3, '’t Lieve dierbaar Geuzenhuis.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-blauwvoet', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 8, 0, 'Weg de bastaards, weg de lauwaards,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 8, 1, 'Ons behoort het noorderstrand,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 8, 2, 'Ons de kerels, ons de klauwaards,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-blauwvoet', 8, 3, 'Leve Geus en Vlaanderland!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('boerenkermis', 'BOERENKERMIS', 'BOERENKERMIS', 'nederlandstalige-liederen', 'nl', NULL, 123, 124, NULL, 'Reylof', 'De oorspronkelijke versie van dit 18e eeuwse lied telt 6 strofen en werd onder de naam “’s Werelds Handel” door Jan Frans Willems opgetekend in zijn “Oude Vlaemsche liederen”.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('boerenkermis', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boerenkermis', 0, 0, 'De boerkens smelten van vreugd en plezier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boerenkermis', 0, 1, 'Als d’oogst is binnen gereden.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boerenkermis', 0, 2, 'Zijn gaan met hunne boerinne te bier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boerenkermis', 0, 3, 'En zij maken zeer goede sier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boerenkermis', 0, 4, 'De bezem steekt ten venster uit.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('boerenkermis', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boerenkermis', 1, 0, 'Men danst er, men speelt er al op de fluit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boerenkermis', 1, 1, 'Op potten en pannen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boerenkermis', 1, 2, 'Op glazen en kannen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boerenkermis', 1, 3, 'Op allerhande geluid:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boerenkermis', 1, 4, 'Op messen, op schup en op zoutevat');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boerenkermis', 1, 5, 'Op hangel, op tangel, op dit en op dat');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boerenkermis', 1, 6, 'Op trommeltje rom, dom domme dom dom:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boerenkermis', 1, 7, 'Op keteltjes, lepeltjes, tikke tik tang');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boerenkermis', 1, 8, 'En dat gaat zo de helen dag lang.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('boerenkermis', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boerenkermis', 2, 0, 'De boerkens hebben het aards paradijs');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boerenkermis', 2, 1, 'Door Adam verloren, hervonden.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boerenkermis', 2, 2, 'Zij roeren de lepel als was het om prijs,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boerenkermis', 2, 3, 'In de rijstpap die hemelse spijs.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boerenkermis', 2, 4, 'De jonkheid kiest een liefje uit.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('chicago-song', 'CHICAGO SONG', 'CHICAGO SONG', 'nederlandstalige-liederen', 'nl', NULL, 124, 125, 'John Pierpont', '‘Jingle Bells’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chicago-song', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 0, 0, 'Mijn lief dat is een chieke');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 0, 1, 'Ze komt van Chicago');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 0, 2, 'En ze heeft daar leren poepen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 0, 3, 'Al op nen dynamo.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 0, 4, 'En de paster moestte pissen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 0, 5, 'En de non die piste mee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 0, 6, 'En ze pakte hem bij zijn sissen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 0, 7, 'En ze stak hem in heur snee.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chicago-song', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 1, 0, 'Djingel bells; djingel bells; djingel all the way');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 1, 1, 'En een mic mic mic en een mac mac mac');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 1, 2, 'En een djingel all the way.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('chicago-song', 1, 0, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chicago-song', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 2, 0, 'En ze had toch zo een leute');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 2, 1, 'Vanonder aan heur preute');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 2, 2, 'En ze was toch zo kontent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 2, 3, 'Van des pasters instrument.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 2, 4, 'En de paster van Wenduine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 2, 5, 'Die stak hem in het zand');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 2, 6, 'En hij kon het niet doen schuimen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 2, 7, 'En hij roerde met zijn hand.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chicago-song', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 3, 0, 'We lagen met zijn allen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 3, 1, 'Al in een boerenschuur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 3, 2, 'We neukten tot het kraakte');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 3, 3, 'Het geil liep van de muur,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 3, 4, 'Maar had ik het geweten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 3, 5, 'Ik had het niet gedaan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 3, 6, 'Mijn lul is nu versleten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chicago-song', 3, 7, 'En haar kut is naar de maan!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('daar-was-e-wuf-die-spon', 'DAAR WAS E WUF DIE SPON', 'DAAR WAS E WUF DIE SPON', 'nederlandstalige-liederen', 'nl', NULL, 126, 126, NULL, NULL, 'Uit Duinkerken');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('daar-was-e-wuf-die-spon', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('daar-was-e-wuf-die-spon', 0, 0, 'Daar was e wuf die spon,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('daar-was-e-wuf-die-spon', 0, 1, 'al op een houten spinnewiel;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('daar-was-e-wuf-die-spon', 0, 2, 'daar was geen toorteltjen aan.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('daar-was-e-wuf-die-spon', 0, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('daar-was-e-wuf-die-spon', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('daar-was-e-wuf-die-spon', 1, 0, 'Viva la peperbusse, Vive la spa,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('daar-was-e-wuf-die-spon', 1, 1, 'Tra la la la');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('daar-was-e-wuf-die-spon', 1, 2, 'Gizegaze goeze, Ron flon floeze,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('daar-was-e-wuf-die-spon', 1, 3, 'Traderadera');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('daar-was-e-wuf-die-spon', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('daar-was-e-wuf-die-spon', 2, 0, 'Haar mutse stond verdraaid,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('daar-was-e-wuf-die-spon', 2, 1, 'gelijk een Hollands moleke');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('daar-was-e-wuf-die-spon', 2, 2, 'die met al windeke draait.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('daar-was-e-wuf-die-spon', 2, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('daar-was-e-wuf-die-spon', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('daar-was-e-wuf-die-spon', 3, 0, 'Dat wuf had enen zin,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('daar-was-e-wuf-die-spon', 3, 1, 'En als zij ’s ochtends buiten kroop;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('daar-was-e-wuf-die-spon', 3, 2, 'des avonds kroop zij erin.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('daar-was-e-wuf-die-spon', 3, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('daar-was-e-wuf-die-spon', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('daar-was-e-wuf-die-spon', 4, 0, 'Dat wuf had enen man,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('daar-was-e-wuf-die-spon', 4, 1, '’s Zondags heet hij Pieter,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('daar-was-e-wuf-die-spon', 4, 2, 'en ’s maandags heet hij Jan.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('daar-was-e-wuf-die-spon', 4, 0, 0, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('dis-in-lucht', 'DIS IN LUCHT', 'DIS IN LUCHT', 'nederlandstalige-liederen', 'nl', NULL, 126, 127, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('dis-in-lucht', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dis-in-lucht', 0, 0, 'Op van stoel, op van stoel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dis-in-lucht', 0, 1, 'Tra la la, la liere,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dis-in-lucht', 0, 2, 'Op van stoel, op van stoel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dis-in-lucht', 0, 3, 'Tra la la, la la.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('dis-in-lucht', 1, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('dis-in-lucht', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dis-in-lucht', 2, 0, 'Voet op stoel');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('dis-in-lucht', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dis-in-lucht', 3, 0, 'Twee voet op stoel');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('dis-in-lucht', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dis-in-lucht', 4, 0, 'Broekske af');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('dis-in-lucht', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dis-in-lucht', 5, 0, 'Onderbroekske af');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('dis-in-lucht', 6, 'direction', 1, 'Op dit moment kunnen er, naargelang de inspiratie van de corona, andere strofen gezongen worden');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('dis-in-lucht', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dis-in-lucht', 7, 0, 'Glas aan mond');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('dis-in-lucht', 8, 'direction', 1, 'Glazen worden hier ad fundum gedronken op commando van de praeses');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('dis-in-lucht', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dis-in-lucht', 9, 0, 'Glas op tafel');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('dis-in-lucht', 10, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dis-in-lucht', 10, 0, 'Onderbroekske op');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('dis-in-lucht', 11, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dis-in-lucht', 11, 0, 'Broekske op');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('dis-in-lucht', 12, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dis-in-lucht', 12, 0, 'Voet van stoel');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('dis-in-lucht', 13, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dis-in-lucht', 13, 0, 'Twee voet van stoel');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('dis-in-lucht', 14, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dis-in-lucht', 14, 0, 'Zit op stoel');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('disco-rolling', 'DISCO ROLLING', 'DISCO ROLLING', 'nederlandstalige-liederen', 'nl', NULL, 128, 129, NULL, NULL, 'De PK bracht dit lied samen met Aloha op het Festival de la Chanson Estudiantine (ULB) van 1982. Het wordt nu traditioneel gezongen op het einde van een cantus, na ‘Le Semeur’.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('disco-rolling', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 0, 0, 'À bas la calotte, à bas la calotte');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 0, 1, 'À bas les calotins;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 0, 2, 'Ils en auront, des coups de poing');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 0, 3, 'Sur la gueule,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 0, 4, 'Ils en auront, autant qu’ils en voudront,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 0, 5, 'Avec, avec plaisir,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 0, 6, 'Dans les ro-oses,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 0, 7, 'Où dans les bégonias');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 0, 8, 'C’est la même cho-ose');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 0, 9, 'Oui, nous irons chasser ohé,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 0, 10, 'Oui, nous irons chasser la calotte,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 0, 11, 'La calotte au poteau');
