INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('disco-rolling', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 1, 0, 'En met poeier en met lood,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 1, 1, 'Schieten wij de sissen dood,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 1, 2, 'D’r mag gene sisse blijven leven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 1, 3, 'En met poeier en met lood,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 1, 4, 'Schieten wij de sissen dood,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 1, 5, 'D’r mag gene sisse blijven staan.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 1, 6, 'En zut zei de pastoor,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 1, 7, 'En schoot zijn zaad in een talloor,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 1, 8, '’t Was ne boekee met pissebloemen.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('disco-rolling', 1, 6, 8, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('disco-rolling', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 2, 0, 'En ’t is al jarenlang bekend,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 2, 1, 'Dat alles wijkt voor de student,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 2, 2, '“VAN BRUSSEL!”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('disco-rolling', 2, 0, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('disco-rolling', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 3, 0, 'En hedde gij meubelen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 3, 1, 'En hedde gij huisgerief,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 3, 2, 'Dan kunde gij trouwen met uw lief,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 3, 3, 'Gij ouwe zot!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 3, 4, 'En hedde gij meubelen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 3, 5, 'En hedde gij huisgerief,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 3, 6, 'Dan kunde gij trouwen met uw lief!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('disco-rolling', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 4, 0, 'Tarara,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 4, 1, 'Viens poupouleke,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 4, 2, 'Viens poupouleke viens,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 4, 3, 'O gij appelsienendief,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 4, 4, 'Ik heb U toch zo lief.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('disco-rolling', 4, 1, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('disco-rolling', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 5, 0, 'En ga je mee, ga je mee,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 5, 1, 'Ga je mee gaan varen?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 5, 2, 'Ga je mee, ga je mee,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 5, 3, 'Ga je mee op zee?');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('disco-rolling', 5, 0, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('disco-rolling', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 6, 0, 'En ’t is te zien aan ons machien,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 6, 1, 'Dat wij van Brussel wezen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 6, 2, '’t Is te zien aan ons machien,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 6, 3, 'Da’ wij van Brussel zijn, HOI!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 6, 4, 'Tatarataaa tarataratatatatataaa, HOI!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('disco-rolling', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 7, 0, 'Mie Katoen komt morgennoen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 7, 1, 'We zullen een pintje drinken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 7, 2, 'Mie Katoen komt morgennoen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 7, 3, 'We zullen een poepke doen, HOI!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('disco-rolling', 7, 4, 'Tatarataaa tarataratatatatataaa, HOI!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('de-dochter-van-de-pachter', 'DE DOCHTER VAN DE PACHTER', 'DOCHTER VAN DE PACHTER, DE', 'nederlandstalige-liederen', 'nl', NULL, 130, 130, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-dochter-van-de-pachter', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-dochter-van-de-pachter', 0, 0, 'En als we waren aan het weven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-dochter-van-de-pachter', 0, 1, 'Lagen we gene wol maar wel katoen te geven;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-dochter-van-de-pachter', 0, 2, 'Tot op zeker ogenblik,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-dochter-van-de-pachter', 0, 3, 'Dat ze zei: “Schei uit ik stik!”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-dochter-van-de-pachter', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-dochter-van-de-pachter', 1, 0, 'En op de dochter van de pachter,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-dochter-van-de-pachter', 1, 1, 'Een keer langs voor, een keer opzij,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-dochter-van-de-pachter', 1, 2, 'Een keer langs achter;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-dochter-van-de-pachter', 1, 3, 'En dan zegt ze tegen mij:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-dochter-van-de-pachter', 1, 4, '“Wa’ ne smeerlap zijdde gij!”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-dochter-van-de-pachter', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-dochter-van-de-pachter', 2, 0, 'En ik pruttelde niet tegen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-dochter-van-de-pachter', 2, 1, 'Want er was voor mij toch niks meer aan gelegen;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-dochter-van-de-pachter', 2, 2, 'Ik had justekens gedaan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-dochter-van-de-pachter', 2, 3, 'En hij bleef al niet meer staan.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-dochter-van-de-pachter', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-dochter-van-de-pachter', 3, 0, 'En als ze dat voelde gebeuren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-dochter-van-de-pachter', 3, 1, 'Want mijne zakdoek ging ik daarmee niet verscheuren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-dochter-van-de-pachter', 3, 2, 'Sloeg ze mij in het gelaat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-dochter-van-de-pachter', 3, 3, 'Maar och god het was te laat.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-dochter-van-de-pachter', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-dochter-van-de-pachter', 4, 0, 'Ik ben niet al te rap van zinnen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-dochter-van-de-pachter', 4, 1, 'Maar er schoot mij daar opeens toch iets te binnen;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-dochter-van-de-pachter', 4, 2, 'Ik liet alles maar begaan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-dochter-van-de-pachter', 4, 3, 'Want ik had een kapootke aan.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('drie-schuintamboers', 'DRIE SCHUINTAMBOERS', 'DRIE SCHUINTAMBOERS', 'nederlandstalige-liederen', 'nl', NULL, 132, 133, NULL, NULL, 'Vrije vertaling van ‘Trois jeunes tambours’, 1745');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-schuintamboers', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 0, 0, 'Drie schuintamboers, die kwamen uit het Oosten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 0, 1, 'Van je rombom, wat maal ik er om');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 0, 2, 'Die kwamen uit het Oosten, rombom.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('drie-schuintamboers', 0, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-schuintamboers', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 1, 0, 'Een van de drie zag daar een aardig meisje');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 1, 1, 'Van je rombom, wat maal ik erom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 1, 2, 'Zag daar een aardig meisje, rombom');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('drie-schuintamboers', 1, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-schuintamboers', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 2, 0, 'Zeg meisje lief, mag ik met jou verkeren?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 2, 1, 'Van je rombom, wat maal ik erom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 2, 2, 'Mag ik met jou verkeren? rombom.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('drie-schuintamboers', 2, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-schuintamboers', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 3, 0, 'Zeg jongeman, dat moet je vader vragen.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 3, 1, 'Zegt die van ja, dan kun je mij behagen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 3, 2, 'Van je rombom, wat maal ik erom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 3, 3, 'Dan kun je mij behagen, rombom.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-schuintamboers', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 4, 0, 'Zeg ouwe heer, mag ik je dochter trouwen?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 4, 1, 'Zij is voorwaar, de schoonste aller vrouwen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 4, 2, 'Van je rombom, wat maal ik erom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 4, 3, 'De schoonste aller vrouwen, rombom.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-schuintamboers', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 5, 0, 'Zeg jongeman, zeg mij wat is je rijkdom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 5, 1, 'Van je rombom, wat maal ik erom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 5, 2, 'Zeg mij wat is je rijkdom, rombom.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('drie-schuintamboers', 5, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-schuintamboers', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 6, 0, 'Mijn rijkdom is, daar wil ik niet om jokken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 6, 1, 'Mijn rijkdom is, een trommel en twee stokken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 6, 2, 'Van je rombom, wat maal ik erom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 6, 3, 'Een trommel met twee stokken, rombom.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-schuintamboers', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 7, 0, 'Nee schuintamboer, dan mag je haar niet trouwen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 7, 1, 'Nee schuintamboer, ik wil mijn dochter houwen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 7, 2, 'Van je rombom, wat maal ik erom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 7, 3, 'Ik wil mijn dochter houwen, rombom.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-schuintamboers', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 8, 0, 'Zeg ouwe heer, ik heb nog iets vergeten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 8, 1, 'Zeg ouwe heer, dit dien je nog te weten.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 8, 2, 'Van je rombom, wat maal ik erom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 8, 3, 'Dit dien je nog te weten, rombom.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-schuintamboers', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 9, 0, 'Mijn vader is Groothertog van Brittanje,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 9, 1, 'Mijn moeder is de Koningin van Spanje!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 9, 2, 'Van je rombom, wat maal ik erom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 9, 3, 'De Koningin van Spanje, rombom.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-schuintamboers', 10, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 10, 0, 'Zeg jongeman, dan kun je haar wel trouwen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 10, 1, 'Van je rombom, wat maal ik erom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 10, 2, 'Dan kun je haar wel trouwen, rombom.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('drie-schuintamboers', 10, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-schuintamboers', 11, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 11, 0, 'Nee ouwe heer, je kunt je dochter houwen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 11, 1, 'Van je rombom, wat maal ik erom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-schuintamboers', 11, 2, 'Je kunt je dochter houwen, rombom.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('drie-schuintamboers', 11, 0, 0, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('drie-vrienden', 'DRIE VRIENDEN', 'DRIE VRIENDEN', 'nederlandstalige-liederen', 'nl', NULL, 133, 135, NULL, NULL, 'John Lundström');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-vrienden', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 0, 0, 'Drie vrienden, drie vrienden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 0, 1, 'Die gingen eens op zwier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 0, 2, 'Zij dronken geen water');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 0, 3, 'Zij dronken bier');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-vrienden', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 1, 0, 'Één, twee, drei');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 1, 1, 'Luister eens naar mij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 1, 2, 'Zij dronken geen water');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 1, 3, 'Zij dronken bier.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-vrienden', 2, 'direction', 1, 'Bij de volgende refreinen worden de laatste 2 lijnen vervangen door de laatste 2 van de voorgaande strofe.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-vrienden', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 3, 0, 'Zij kozen een kafeeke');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 3, 1, 'Op ’t hoekske van de straat');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 3, 2, 'Daar brandde een rood lichteke');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 3, 3, 'Tot ’s avonds laat.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-vrienden', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 4, 0, 'Madammeken en tapt er eens');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 4, 1, 'Een goei pintje bier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 4, 2, 'En roept er eens gauw');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 4, 3, 'Uw schoon dochterken hier.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-vrienden', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 5, 0, 'Da bier da werd geschonken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 5, 1, 'En z’ hemmen het gedronken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 5, 2, 'Maar da maske da kwam niet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 5, 3, 'Want ze had een groot verdriet.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-vrienden', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 6, 0, 'Heuren vrijer die had heur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 6, 1, 'Leed aangedaan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 6, 2, 'En heur op de koop toe');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 6, 3, 'Op straat laten staan.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-vrienden', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 7, 0, 'Ze zijn er dan met gedrien');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 7, 1, 'Naar da kamerken gegaan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 7, 2, 'Ze spraken da maske');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 7, 3, 'Zo vriendelijk aan.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-vrienden', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 8, 0, 'Den eerste die zei');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 8, 1, 'Och schreeuw toch niet meer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 8, 2, 'Een kinderken kopen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 8, 3, 'Dat doet toch geen zeer.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-vrienden', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 9, 0, 'Den tweede die zei');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 9, 1, '’k Hem toch zo ne kou');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 9, 2, 'Schuif een beetje op');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 9, 3, 'En ik leg me bij jou.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-vrienden', 10, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 10, 0, 'Da maske da zei');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 10, 1, 'Ge zijt niet goed');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 10, 2, 'Gaat uit mijn bed');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 10, 3, 'Of ik roep ons moe.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-vrienden', 11, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 11, 0, 'Den derde die raakte');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 11, 1, 'Heur zachtekens aan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 11, 2, 'Toen is er da maske');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 11, 3, 'Al opgestaan.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-vrienden', 12, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 12, 0, 'Ze zijn er dan getrouwd');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 12, 1, 'Al op ne zaterdag');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 12, 2, 'Terwijl er in ’t voitureke');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 12, 3, 'Al een kinneke lag.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('drie-vrienden', 13, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 13, 0, 'Sa vrienden, sa vrienden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 13, 1, 'Voor ’t lest ne goeie raad');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 13, 2, 'Drinkt toch geen bier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('drie-vrienden', 13, 3, 'Als ge naar de maskes gaat.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('dronkemanspraatje', 'DRONKEMANSPRAATJE', 'DRONKEMANSPRAATJE', 'nederlandstalige-liederen', 'nl', NULL, 136, 136, 'Vertaling door pater Bernard van Meurs, 1868', '‘Grad aus dem Wirtshaus’, Heinrich von Mühler, 1840', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('dronkemanspraatje', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dronkemanspraatje', 0, 0, '’k Bracht in dees herberg een avondje door.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dronkemanspraatje', 0, 1, 'Straat maar wat komt gij mij wonderlijk voor!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dronkemanspraatje', 0, 2, 'Rechter en linker, ’t loopt al door elkaar.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dronkemanspraatje', 0, 3, 'Straat, gij zijt dronken zeg of is ’t nietwaar?');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('dronkemanspraatje', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dronkemanspraatje', 1, 0, 'La (×19)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('dronkemanspraatje', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dronkemanspraatje', 2, 0, 'Kijk eens wat een scheef gezicht trekt die maan.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dronkemanspraatje', 2, 1, 'Één oog gesloten en één loert mij aan.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dronkemanspraatje', 2, 2, 'Ja, z’heeft voorzeker een pintje te veel op.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dronkemanspraatje', 2, 3, 'Wag’lend daarboven zij draait lijk nen dop.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('dronkemanspraatje', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dronkemanspraatje', 3, 0, 'En die lantaarns, ik zie toch niet scheel.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dronkemanspraatje', 3, 1, 'Drommels. Zij hebben wat olie teveel.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dronkemanspraatje', 3, 2, 'Draaiend en zwaaiend langs allen kant heen.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dronkemanspraatje', 3, 3, 'Jongens staat vast of ge raakt van de been!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('dronkemanspraatje', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dronkemanspraatje', 4, 0, 'Alles aan ’t hotsen wat ’k zie, klein en groot.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dronkemanspraatje', 4, 1, 'En nu daaronder ik nuchter als brood!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dronkemanspraatje', 4, 2, 'Dat zal niet want ik bemin mij te veel:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('dronkemanspraatje', 4, 3, '’k Ga weer naar de herberg en ’k drink mij daar scheel.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('er-waren-drie-studentjes', 'ER WAREN DRIE STUDENTJES', 'ER WAREN DRIE STUDENTJES', 'nederlandstalige-liederen', 'nl', NULL, 137, 137, NULL, '‘Marlbrough s’en va-t-en guerre’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('er-waren-drie-studentjes', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('er-waren-drie-studentjes', 0, 0, 'Er waren drie studentjes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('er-waren-drie-studentjes', 0, 1, 'Van dingela, dommela, deine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('er-waren-drie-studentjes', 0, 2, 'Er waren drie studentjes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('er-waren-drie-studentjes', 0, 3, 'Aan d’ universiteit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('er-waren-drie-studentjes', 0, 4, 'Er waren drie studentjes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('er-waren-drie-studentjes', 0, 5, 'Aan d’ universiteit.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('er-waren-drie-studentjes', 0, 3, 3, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('er-waren-drie-studentjes', 1, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('er-waren-drie-studentjes', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('er-waren-drie-studentjes', 2, 0, 'De eerste was een blokker');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('er-waren-drie-studentjes', 2, 1, 'En hij heeft zich doodgeblokt.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('er-waren-drie-studentjes', 2, 1, 1, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('er-waren-drie-studentjes', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('er-waren-drie-studentjes', 3, 0, 'De tweede was een vrijer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('er-waren-drie-studentjes', 3, 1, 'En hij heeft zich doodgevrijd.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('er-waren-drie-studentjes', 3, 1, 1, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('er-waren-drie-studentjes', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('er-waren-drie-studentjes', 4, 0, 'De derde was een rolder');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('er-waren-drie-studentjes', 4, 1, 'En hij heeft zich doodgerold.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('er-waren-drie-studentjes', 4, 1, 1, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('er-waren-drie-studentjes', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('er-waren-drie-studentjes', 5, 0, 'Er waren geen studenten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('er-waren-drie-studentjes', 5, 1, 'Aan d’ universiteit.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('er-waren-drie-studentjes', 5, 1, 1, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('er-waren-drie-studentjes', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('er-waren-drie-studentjes', 6, 0, 'De profs die vlogen buiten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('er-waren-drie-studentjes', 6, 1, 'Uit d’ universiteit.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('er-waren-drie-studentjes', 6, 1, 1, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('er-waren-drie-studentjes', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('er-waren-drie-studentjes', 7, 0, 'De doos die werd gesloten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('er-waren-drie-studentjes', 7, 1, 'De paapsen zijn gekelderd');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('er-waren-drie-studentjes', 7, 2, 'Tot in der eeuwigheid.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('er-waren-drie-studentjes', 7, 2, 2, 3, '(TER)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ergo-bibamus', 'ERGO BIBAMUS', 'ERGO BIBAMUS', 'nederlandstalige-liederen', 'nl', NULL, 138, 138, 'Vertaling van ‘Hier sind wir versammelt’, Johann Wolfgang von Goethe, 1810', 'Max Eberwein, 1813', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ergo-bibamus', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 0, 0, 'Hier zijn wij te zamen om leutig te doen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 0, 1, 'Sa broederkens “Ergo Bibamus!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 0, 2, 'De glazekens lachen, toe geeft z’ enen zoen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 0, 3, 'En hertlijker “Ergo Bibamus!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 0, 4, 'Dat is nu het eerste en enige woord,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 0, 5, 'Dat past in ’t begin en het past immer voort');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 0, 6, 'De lustige echo van ’t feestelijk oord,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 0, 7, 'Het heerlijke “Ergo Bibamus!”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ergo-bibamus', 0, 7, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ergo-bibamus', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 1, 0, 'Ons hart is nog jong en ons lied klinkt nog hel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 1, 1, 'Ons feestelijk “Ergo Bibamus!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 1, 2, 'En moeten we scheiden, als laatste vaarwel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 1, 3, 'Zo blijve het ons “Ergo Bibamus!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 1, 4, 'Dat woord zal ons steunen in werk en in strijd');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 1, 5, 'Ons weer doen herdenken het oude jolijt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 1, 6, 'De vrolijke vrienden uit vroegeren tijd');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 1, 7, 'Die ’t zongen, ons “Ergo Bibamus!”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ergo-bibamus', 1, 7, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ergo-bibamus', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 2, 0, 'En komen wij ooit naar de Hogeschool weer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 2, 1, 'En zingt men nog “Ergo Bibamus!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 2, 2, 'Dat ’t dreunt door de straten lijk ’t dreunde weleer,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 2, 3, 'Vol geestdrift ons “Ergo Bibamus!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 2, 4, 'Dan komt ons verfrommelde pet uit de zak');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 2, 5, 'En ’t oude verrompelde lint op den frak');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 2, 6, 'En samen met schachten in splinternieuw pak,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ergo-bibamus', 2, 7, 'Herhalen we ’t “Ergo Bibamus!”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ergo-bibamus', 2, 7, 7, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('het-fiere-geuzenlied', 'HET FIERE GEUZENLIED', 'FIERE GEUZENLIED, HET', 'nederlandstalige-liederen', 'nl', NULL, 139, 140, 'Joeri Dirckx', '‘Jan Klaassen de trompetter’, Rob De Nijs; Arr: Bart Hoefman LWK, Winnend lied op het 14e Vrijzinnig Zangfeest van Vlaanderen, 1999', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-fiere-geuzenlied', 0, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 0, 0, 'We zwaaien met ons vaandel, volgelingen van St V');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 0, 1, 'Wij zijn fiere Geuzen van de VUB');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 0, 2, '’t Is onze tijd, wij lev’ren strijd,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 0, 3, 'Geleid door de vrijzinnigheid');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 0, 4, 'De kerk en bourgeoisie doen niet meer mee');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-fiere-geuzenlied', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 1, 0, 'Vanuit het mooie Brussel slaan wij onze klauwen uit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 1, 1, 'We zitten al het rijk gespuis, kaloten op de huid');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 1, 2, 'De klak op’t hoofd, de pint in d’hand, de labofrakken aan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 1, 3, 'Vrijmetselaars verenigt u we gaan er tegenaan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 1, 4, 'We drinken en we brassen door de nachten kil en koud');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 1, 5, 'Beschenen door de stralen van de zon in grijs en goud');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-fiere-geuzenlied', 2, 'chorus-ref', 1, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-fiere-geuzenlied', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 3, 0, 'Verhaegen is ons voorgegaan, hij toonde wat hij kon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 3, 1, 'Zijn weg die wij nu volgen reikt tot aan de horizon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 3, 2, 'Niets is ons teveel, we nemen elke hindernis');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 3, 3, 'Zijn fakkel zal ons leiden door de diepe duisternis');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 3, 4, 'Wij vechten voor wat goed is, voor hetzelfde ideaal');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 3, 5, 'Iedereen is hier gelijk, de vrijheid staat centraal');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-fiere-geuzenlied', 4, 'chorus-ref', 1, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-fiere-geuzenlied', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 5, 0, 'Wij blijven eeuwig vechten, tot het einde, tot de dood');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 5, 1, 'Gesterkt door de alcohol, die trouwe bondgenoot');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 5, 2, 'Maar soms draait hij zich tegen ons en gaat dan wild tekeer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 5, 3, 'Wij, de fiere Geuzen, vallen dan met bossen neer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 5, 4, '’s Morgens staan wij weeral recht en drinken stevig door');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 5, 5, 'We klinken onze glazen en dan zingen wij in koor');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-fiere-geuzenlied', 6, 'chorus-ref', 1, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-fiere-geuzenlied', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 7, 0, '’t Is onze tijd, wij lev’ren strijd, geleid door de vrijzinnigheid');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-fiere-geuzenlied', 7, 1, 'We zijn de fiere Geuzen van de VUB');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('filia-hospitalis', 'FILIA HOSPITALIS', 'FILIA HOSPITALIS', 'nederlandstalige-liederen', 'nl', NULL, 141, 143, 'Vertaling uit het Duits, Otto Kamp, 1882', 'Otto Lob, 1885', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('filia-hospitalis', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 0, 0, 'O heerlijke studententijd');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 0, 1, 'Met talloze vermaken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 0, 2, 'Met minnetochten wijd en zijd,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 0, 3, 'De schoonsten te genaken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 0, 4, 'Wees mij gegroet, o schone jeugd!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 0, 5, 'Elk aardig meisje baart me vreugd,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 0, 6, 'En toch is niets aequalis,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 0, 7, 'Aan Filia Hospitalis!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('filia-hospitalis', 0, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('filia-hospitalis', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 1, 0, 'Ik kwam als eerstejaars hier aan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 1, 1, 'En speurde door de straten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 1, 2, 'Waar ik een stoel en bed vond staan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 1, 3, 'Om mij daar neer te laten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 1, 4, '’k Vond luie stoel noch canapé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 1, 5, 'En toch viel mij de kamer mee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 1, 6, 'Want niemand is aequalis,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 1, 7, 'Aan Filia Hospitalis!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('filia-hospitalis', 1, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('filia-hospitalis', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 2, 0, 'Het is zo’n alleraardigst kind');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 2, 1, 'Met zachte, blauwe ogen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 2, 2, 'De voetjes trippelend gezwind');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 2, 3, 'Komt zij naar mij gevlogen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 2, 4, 'Haar mondje lacht zo lief zo blij,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 2, 5, 'Geen tweede komt haar ooit nabij;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 2, 6, 'Neen niemand is aequalis,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 2, 7, 'Aan Filia Hospitalis!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('filia-hospitalis', 2, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('filia-hospitalis', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 3, 0, 'Drie huurders heeft ze: de jurist');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 3, 1, 'Bezoekt slechts fijne kringen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 3, 2, 'De medicus heeft zich vergist');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 3, 3, 'Als hij zich op wil dringen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 3, 4, 'Doch mij, slechts de philologus,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 3, 5, 'Gaf zij in eer en deugd een kus');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 3, 6, 'Daarom is niets aequalis,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 3, 7, 'Aan Filia Hospitalis!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('filia-hospitalis', 3, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('filia-hospitalis', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 4, 0, 'O liefste blonde, wist ik toch,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 4, 1, 'Wat Geus wil met ons beiden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 4, 2, 'Een laatste kusje geef me nog');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 4, 3, 'Vóór ik van U moet scheiden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 4, 4, 'En zijt gij mij niet toebedacht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 4, 5, 'Aan U denk ik bij dag en nacht');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 4, 6, 'Want niemand is aequalis,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-hospitalis', 4, 7, 'Aan Filia Hospitalis!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('filia-hospitalis', 4, 6, 7, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('folklore', 'FOLKLORE', 'FOLKLORE', 'nederlandstalige-liederen', 'nl', NULL, 143, 144, NULL, NULL, 'T & M: Drs. P');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('folklore', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 0, 0, 'Wij brengen de Folklore');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 0, 1, 'Van her en der naar hier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 0, 2, 'En doen het con amore,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 0, 3, 'dat betekent ‘met plezier’');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('folklore', 0, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('folklore', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 1, 0, 'We hebben onze rokken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 1, 1, 'En jasjes enzovoort');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 1, 2, 'Vooraf al aangetrokken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 1, 3, 'helemaal zoals het hoort');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('folklore', 1, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('folklore', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 2, 0, 'We trekken volle zalen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 2, 1, 'Met buitenlands gezang');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 2, 2, 'Waarin we veel herhalen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 2, 3, 'en zo duurt het lekker lang');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('folklore', 2, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('folklore', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 3, 0, 'Zo’n lied verwoordt de tover');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 3, 1, 'Van waar het over gaat');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 3, 2, 'Geen mens verstaat waarover');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 3, 3, 'maar ’t houdt ons aan de praat');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('folklore', 3, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('folklore', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 4, 0, 'Wat nimmer mag ontbreken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 4, 1, 'Is pittoreske dans');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 4, 2, 'Precies als in die streken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 4, 3, 'dat geloven wij althans');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('folklore', 4, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('folklore', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 5, 0, 'We doen het Aziatisch');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 5, 1, 'En ook wel Indiaans');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 5, 2, 'En als het moet Kroatisch,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 5, 3, 'of gewoon maar op zijn Spaans');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('folklore', 5, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('folklore', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 6, 0, 'We hebben goede spieren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 6, 1, 'Behoorlijk maatgevoel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 6, 2, 'En guitige manieren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 6, 3, 'dus het wordt een dolle boel');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('folklore', 6, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('folklore', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 7, 0, 'Dan raken we bezeten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 7, 1, 'Van al die danserij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 7, 2, 'Met impulsieve kreten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('folklore', 7, 3, 'want dat moet er altijd bij');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('folklore', 7, 2, 3, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('de-gedachten-zijn-vrij', 'DE GEDACHTEN ZIJN VRIJ', 'GEDACHTEN ZIJN VRIJ, DE', 'nederlandstalige-liederen', 'nl', NULL, 144, 145, NULL, NULL, 'Vertaling van ‘Die Gedanken sind frei’
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-gedachten-zijn-vrij', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 0, 0, 'De gedachten zijn vrij!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 0, 1, 'Wie raadt ze daarbinnen?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 0, 2, 'Zij dansen voorbij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 0, 3, 'Als nacht’lijke schimmen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 0, 4, 'Geen mens kan ze naken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 0, 5, 'Geen jager ze raken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 0, 6, 'Laat wezen wat zij:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 0, 7, 'De gedachten zijn vrij!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-gedachten-zijn-vrij', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 1, 0, 'Ik denk mij wat ik wil');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 1, 1, 'In heimlijke dromen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 1, 2, 'Haar zoetheid laat ik stil');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 1, 3, 'Mijn harte doorstromen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 1, 4, 'Mijn wens en begeren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 1, 5, 'Kan niemand mij weren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 1, 6, 'Laat worden wat zij:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 1, 7, 'De gedachten zijn vrij!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-gedachten-zijn-vrij', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 2, 0, 'En spert men mij geboeid');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 2, 1, 'In duistere toren;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 2, 2, 'Hun zorgen en moeite');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 2, 3, 'Gaan alle verloren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 2, 4, 'Gedachten als vuren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 2, 5, 'Doen storten de muren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 2, 6, 'En de zold’ring erbij!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 2, 7, 'De gedachten zijn vrij!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-gedachten-zijn-vrij', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 3, 0, 'Daarom wil ik nimmer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 3, 1, 'De zorgen verjagen;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 3, 2, 'En zal men mij ook nimmer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 3, 3, 'Met spoken meer plagen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 3, 4, 'Men kan toch daarbinnen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 3, 5, 'Steeds lachen en minnen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 3, 6, 'En denken wat ook zij:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gedachten-zijn-vrij', 3, 7, 'De gedachten zijn vrij!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('geuzenlied', 'GEUZENLIED', 'GEUZENLIED', 'nederlandstalige-liederen', 'nl', NULL, 146, 147, 'Jan De Geyter, 15–17 september 1873', 'Alexander Fernau', 'Oorspronkelijke titel: “De Vlaamsche Leeuw en de Geuzen”
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('geuzenlied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 0, 0, 'Zij brullen: “Leeuw van Vlaanderen!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 0, 1, 'En huilen tegen ons');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 0, 2, 'Zij die de Leeuw doen kruipen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 0, 3, 'Doen kruipen voor Bourbons');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 0, 4, 'O Breydel en De Coninck,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 0, 5, 'Gent Brugge van weleer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 0, 6, 'Heeft Vlaanderen dan geen kerels');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 0, 7, 'Hebt gij geen Klauwaerts meer?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 0, 8, 'Op Geuzen, wreekt uw vaadren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 0, 9, 'Zwaait gij de Leeuwenvaan!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 0, 10, 'Wee wee de landverraadren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 0, 11, 'Wanneer hun uur zal slaan!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('geuzenlied', 0, 10, 11, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('geuzenlied', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 1, 0, 'Blikt om U heen, O Broedren!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 1, 1, 'Trekt gans den wereld rond');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 1, 2, 'Weer rijzen als paleizen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 1, 3, 'De kloosters uit den grond');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 1, 4, 'Het glanzend licht der rede');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 1, 5, 'Het licht moet uitgedoofd');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 1, 6, 'Voor bedevaart, mirakels');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 1, 7, 'En spoken in het hoofd');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 1, 8, 'Ach! Over Leie en Schelde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 1, 9, 'Hangt zulk een sombere nacht ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 1, 10, 'O land van Artevelde,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 1, 11, 'De Geuzen houden wacht!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('geuzenlied', 1, 10, 11, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('geuzenlied', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 2, 0, 'Jezuïeten zaaien tweedracht');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 2, 1, 'Zij blazen haat en twist');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 2, 2, 'Wij juichen “Recht en rede”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 2, 3, 'Zij grijnzen “Laag en list”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 2, 4, 'Hoort! Rome smeedt ons ketens');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 2, 5, 'Voor ’t lijf en voor de ziel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 2, 6, 'Het zwart gespuis zal ’t mensdom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 2, 7, 'Verplettren met den hiel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 2, 8, 'Dan Geuzen, dan te wapen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 2, 9, 'De Vrijheidsvlag ter hand');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 2, 10, 'Van ’t ongediert der papen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 2, 11, 'Verlost ons vaderland!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('geuzenlied', 2, 10, 11, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('geuzenlied', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 3, 0, 'Wanneer rijst eens het daglicht');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 3, 1, 'In d’ aardse rampwoestijn');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 3, 2, 'Dat elk zijn eigen koning');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 3, 3, 'Zijn eigen paus zal zijn?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 3, 4, 'Geen slaven meer aan ketens');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 3, 5, 'Geen ziel aan boei of band');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 3, 6, 'En ’t mensdom, gans het mensdom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 3, 7, 'Een enkel Broederland');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 3, 8, 'Dat willen wij, o Geuzen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 3, 9, 'Al kost het goed en bloed');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 3, 10, 'Wij gaan vooruit als reuzen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('geuzenlied', 3, 11, 'Vooruit met leeuwenmoed!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('geuzenlied', 3, 10, 11, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('de-gilde-viert', 'DE GILDE VIERT', 'GILDE VIERT, DE', 'nederlandstalige-liederen', 'nl', NULL, 148, 149, 'René de Clercq', 'Emiel Hullebroeck, 1910', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-gilde-viert', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 0, 0, 'De gilde viert, de gilde juicht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 0, 1, 'Wat zit gij daar en blokt en buigt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 0, 2, 'Nog over uwe boeken?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 0, 3, 'De wijsheid ligt maar in de kan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 0, 4, 'Wie z’elders zoeken wilt die kan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 0, 5, 'Doch laat hem, laat hem zoeken.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-gilde-viert', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 1, 0, 'Het beste biertje lust hij niet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 1, 1, 'Het liefste liedje sust hem niet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 1, 2, 'Het mooiste meisje kust hem niet.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 1, 3, 'Hoog het glas! Hoog het hart!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 1, 4, 'Hoog het lied!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-gilde-viert', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 2, 0, 'De beker ruist, de beker schuimt!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 2, 1, 'Sa makkers, fris en opgeruimd');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 2, 2, 'Het glas aan uwe lippen!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 2, 3, 'Die op zijn kamer koekeloert,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 2, 4, 'En geestversnipprend dwaashen snoert,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 2, 5, 'Drinkt water als de kippen!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-gilde-viert', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 3, 0, 'Het pijpke dampt in monkelmond,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 3, 1, 'En spreidt wellustig in het rond');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 3, 2, 'Studentikoze geuren!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 3, 3, 'Die steeds aan perkamenten kluift,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 3, 4, 'En perkamenten reuken snuift,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 3, 5, 'Krijgt perkamenten kleuren!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-gilde-viert', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 4, 0, 'De gilde juicht, de gilde viert!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 4, 1, 'Hoera! De pet omhoog gezwierd,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 4, 2, 'En nog eens hard geklonken!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 4, 3, 'De blokker ligt reeds log en loom,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 4, 4, 'Gekweld door nare blokkersdroom,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-gilde-viert', 4, 5, 'Met droge keel te ronken.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('groeninghe', 'GROENINGHE', 'GROENINGHE', 'nederlandstalige-liederen', 'nl', NULL, 149, 149, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('groeninghe', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('groeninghe', 0, 0, 'Het Vlaamse heir staat immer pal,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('groeninghe', 0, 1, 'Daar ’t winnen of daar ’t sterven zal!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('groeninghe', 0, 2, 'Alhier, aldaar aan lange lansen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('groeninghe', 0, 3, 'De leeuwen dansen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('groeninghe', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('groeninghe', 1, 0, 'De winden schudden met geweld,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('groeninghe', 1, 1, 'De zwarte blomme in ’t geluw veld;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('groeninghe', 1, 2, 'De kwaden zien, benêen de transen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('groeninghe', 1, 3, 'De leeuwen dansen!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('groeninghe', 1, 4, 'Met bezemen zo komen z’af,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('groeninghe', 1, 5, 'Om ’t Vlaamse volk af te ransen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('groeninghe', 1, 6, 'Als ijdel kaf, dat ’t zweerd onweerd is.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('groeninghe', 1, 7, 'De leeuwen dansen!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('groeninghe', 1, 7, 7, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('groeninghe', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('groeninghe', 2, 0, 'Harop! Harop! De trompe steekt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('groeninghe', 2, 1, 'De boeien los, de banden breekt!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('groeninghe', 2, 2, 'Ten vijand in! Dat op zijn schansen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('groeninghe', 2, 3, 'De leeuwen dansen!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('groeninghe', 2, 4, 'Sta vuist en voet de vane omtrent!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('groeninghe', 2, 5, 'En gij die Geus noch ere en kent,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('groeninghe', 2, 6, 'Ruimt bane, eer op uw vege bansen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('groeninghe', 2, 7, 'De leeuwen dansen!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('groeninghe', 2, 7, 7, 3, '(TER)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('het-waren-twee-conincskinderen', 'HET WAREN TWEE CONINCSKINDEREN', 'HET WAREN TWEE CONINCSKINDEREN', 'nederlandstalige-liederen', 'nl', NULL, 150, 151, NULL, NULL, 'Van oorsprong middeleeuws minnelied, opgetekend door Florimond van Duyse. Het is waarschijnlijk gebaseerd op het verhaal van Hero en Leander, een griekse mythe, dat onder andere door Ovidius werd opgetekend.
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-waren-twee-conincskinderen', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 0, 0, 'Het waren twee conincskinderen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 0, 1, 'Sy hadden malcander soo lief;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 0, 2, 'Sy conden byeen niet comen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 0, 3, 'Het water was veel te diep.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 0, 4, 'Wat deed sy? Sy stac op drie keersen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 0, 5, 'Als ’s avonts het daghelicht sonc;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 0, 6, '“Och liefste comt swemt er over!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 0, 7, 'Dat deed sconincs sone, was jonc.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-waren-twee-conincskinderen', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 1, 0, 'Dit sach daar een oude quene,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 1, 1, 'Een al soo vilynich vel;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 1, 2, 'Sy ghinker dat licht uytblasen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 1, 3, 'Toen smoorde die jonge held.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 1, 4, '“Och moeder, myn liefste moeder,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 1, 5, 'Myn hoofdjen doet mynder soo wee!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 1, 6, 'Mocht icker een wyle gaan wandlen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 1, 7, 'Gaan wandelen al langs de see?”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-waren-twee-conincskinderen', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 2, 0, '“Och visscher,” soo sprac sy, “visscher');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 2, 1, 'Myns vaders visscherkyn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 2, 2, 'Ghy soudt er voor my eens visschen;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 2, 3, 'Het sal U ghelonet sijn!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 2, 4, 'Hy smeet syne netten in ’t water,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 2, 5, 'De loodekens ginghen te gront;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 2, 6, 'Int corte was daer gevisschet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 2, 7, 'Sconincs sone, van jaren was jonc.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-waren-twee-conincskinderen', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 3, 0, 'Sy hielter haer lief in haer armen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 3, 1, 'En spronc er met hem in de see,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 3, 2, '“Adieu”, seyde sy, “Schoone wereld,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 3, 3, 'Ghy sieter my nimmer meer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 3, 4, 'Adieu, O myn vader en moeder,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 3, 5, 'Myn vriendekens alle ghelyc,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 3, 6, 'Adieu, myn suster en broeder;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-waren-twee-conincskinderen', 3, 7, 'Ic vare naer ’t hemelryck.”');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ik-ben-een-boemelaar', 'IK BEN EEN BOEMELAAR', 'IK BEN EEN BOEMELAAR', 'nederlandstalige-liederen', 'nl', NULL, 151, 152, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-ben-een-boemelaar', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 0, 0, 'Geen enkele avond ben ik thuis, joedeladeliedelee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 0, 1, 'Mijn keelgat is een grote sluis, joedeladeliedelee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 0, 2, 'Ik zit hier eeuwig in de kroeg, joedeladeliedelee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 0, 3, 'Van ’s avonds laat tot ’s morgens vroeg.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 0, 4, 'Joedelaa, joedelee!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-ben-een-boemelaar', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 1, 0, 'Ik ben een boemelaar, een reuze boemelaar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 1, 1, '’s Zomers en ’s winters,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 1, 2, 'Mooi weer of niet.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 1, 3, 'Zie ik de bleke maan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 1, 4, 'Tussen de sterren staan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 1, 5, 'Dan moet ik boemelen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 1, 6, 'Of ik wil of niet.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ik-ben-een-boemelaar', 1, 2, 2, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ik-ben-een-boemelaar', 1, 6, 6, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-ben-een-boemelaar', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 2, 0, 'Ik zuip van baloor en verdriet, joedeladeliedelee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 2, 1, 'College-lopen mag ik niet, joedeladeliedelee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 2, 2, 'Ik ben altijd het zwarte schaap, joedeladeliedelee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 2, 3, 'Wanneer ik daar mijn roes uitslaap.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 2, 4, 'Joedelaa, joedelee!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-ben-een-boemelaar', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 3, 0, 'Mijn hospita ben ik tot last, joedeladeliedelee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 3, 1, 'Mijn vrienden vinden mij een kwast, joedeladeliedelee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 3, 2, 'Mijn meisje heeft het uitgemaakt, joedeladeliedelee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 3, 3, 'Want ik heb voor haar deur gekwaakt.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 3, 4, 'Joedelaa, joedelee!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-ben-een-boemelaar', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 4, 0, 'Ik ga kapot, ik weet het wel, joedeladeliedelee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 4, 1, 'Mijn ziel gaat zeker naar de hel, joedeladeliedelee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 4, 2, 'Al staan de paters op hun kop, joedeladeliedelee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 4, 3, 'Toch hef ik nooit mijn boemel op.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 4, 4, 'Joedelaa, joedelee!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-ben-een-boemelaar', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 5, 0, 'Wanneer ik op het exaam kom, joedeladeliedelee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 5, 1, 'Dan staan de profs gewoonweg stom, joedeladeliedelee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 5, 2, 'Wanneer ik na zo’n boemeljaar, joedeladeliedelee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 5, 3, 'Zoveel verstand aan wijsheid paar.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-een-boemelaar', 5, 4, 'Joedelaa, joedelee!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ik-ben-op-een-avond-met-een-meisje', 'IK BEN OP EEN AVOND MET EEN MEISJE', 'IK BEN OP EEN AVOND MET EEN MEISJE', 'nederlandstalige-liederen', 'nl', NULL, 153, 153, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-ben-op-een-avond-met-een-meisje', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-op-een-avond-met-een-meisje', 0, 0, 'En ik ben op een avond');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-op-een-avond-met-een-meisje', 0, 1, 'Met een meisje uitgeweest');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-op-een-avond-met-een-meisje', 0, 2, 'En ik kocht haar een klein hoedje.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-op-een-avond-met-een-meisje', 0, 3, 'En zo ging dat kopke');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-op-een-avond-met-een-meisje', 0, 4, 'Dat kopke ging alzo.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ik-ben-op-een-avond-met-een-meisje', 0, 0, 2, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ik-ben-op-een-avond-met-een-meisje', 0, 3, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-ben-op-een-avond-met-een-meisje', 1, 'direction', 1, 'De volgende strofen worden op dezelfde manier gezongen maar “klein hoedje” en “kopke” worden vervangen door:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-ben-op-een-avond-met-een-meisje', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-op-een-avond-met-een-meisje', 2, 0, '“soetienke” “tetjes”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-op-een-avond-met-een-meisje', 2, 1, '“korseeke” “buikske”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-op-een-avond-met-een-meisje', 2, 2, '“klein broekske” “foefke”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-op-een-avond-met-een-meisje', 2, 3, '“paar kousen” “beentjes”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-op-een-avond-met-een-meisje', 2, 4, '“paar schoentjes”“voetjes”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-op-een-avond-met-een-meisje', 2, 5, '“kapootken” “pietje”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-ben-op-een-avond-met-een-meisje', 3, 'direction', 1, 'Bovendien wordt achter elke strofe telkens tweemaal de laatste twee regels van alle vorige strofen herhaald. Zo wordt de laatste strofe:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-ben-op-een-avond-met-een-meisje', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-op-een-avond-met-een-meisje', 4, 0, 'En ik ben op een avond');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-op-een-avond-met-een-meisje', 4, 1, 'Met een meisje uitgeweest');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-op-een-avond-met-een-meisje', 4, 2, 'En ik kocht haar een kapootken.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-op-een-avond-met-een-meisje', 4, 3, 'En zo ging dat pietje');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-op-een-avond-met-een-meisje', 4, 4, 'Dat pietje dat ging zo.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-op-een-avond-met-een-meisje', 4, 5, 'En zo gingen die voetjes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-op-een-avond-met-een-meisje', 4, 6, 'Die voetjes gingen zo.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-ben-op-een-avond-met-een-meisje', 4, 7, 'En zo gingen die ...');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ik-ben-op-een-avond-met-een-meisje', 4, 0, 2, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ik-ben-op-een-avond-met-een-meisje', 4, 3, 4, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ik-ben-op-een-avond-met-een-meisje', 4, 5, 6, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ik-drink', 'IK DRINK', 'IK DRINK', 'nederlandstalige-liederen', 'nl', NULL, 154, 154, 'Louis Verbeeck', 'Armand Preud’homme', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-drink', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-drink', 0, 0, 'Mijn handen staan scheef, mijn benen staan krom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-drink', 0, 1, 'Ik weet dat ik leef, maar ik weet niet waarom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-drink', 0, 2, 'Geen vrouw kijkt me aan, geen lief lacht me toe');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-drink', 0, 3, 'Mijn triestig gezicht zijn ze allemaal moe.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-drink', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-drink', 1, 0, 'Ik drink op het heimwee dat knaagt in mijn borst');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-drink', 1, 1, 'Ik drink van miserie, ik drink van de dorst');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-drink', 1, 2, 'Ik drink pint op pint met een zwierig gebaar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-drink', 1, 3, 'Al heb ik dan ’s morgens ook pijn in mijn haar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-drink', 1, 4, 'Toch blijf ik maar drinken, het zit mij in ’t bloed');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-drink', 1, 5, 'Ik ben als de zee met een eeuwige vloed.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-drink', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-drink', 2, 0, 'Ik pas in geen huis, ik slaap in geen bed');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-drink', 2, 1, 'Nooit heeft mij een vrouw een bord soep voorgezet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-drink', 2, 2, 'Ik ben heel alleen, ik heb zo’n verdriet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-drink', 2, 3, 'Ik zucht en ik ween, want mijn hart is failliet.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ik-zag-cecilia-komen', 'IK ZAG CECILIA KOMEN', 'IK ZAG CECILIA KOMEN', 'nederlandstalige-liederen', 'nl', NULL, 155, 155, NULL, NULL, 'Florimond Van Duyse, Gent, 1661
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-zag-cecilia-komen', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zag-cecilia-komen', 0, 0, 'Ik zag Cecilia komen langst eenen watergank.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zag-cecilia-komen', 0, 1, 'Ik zag Cecilia komen met bloemen in haer hand.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zag-cecilia-komen', 0, 2, 'Zy zag naer haren herder, den herder Floriaen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zag-cecilia-komen', 0, 3, 'Die ook zyn schaepjes weyde langs dezelfde baen.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zag-cecilia-komen', 0, 4, 'Cecilia ging zingen; haer hert docht haer t’ontspringen.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zag-cecilia-komen', 0, 5, 'Dit hoorde haren herder: hy kwam by haer terstond,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zag-cecilia-komen', 0, 6, 'En kuste zyn Cecilia aen haren rooden mond.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-zag-cecilia-komen', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zag-cecilia-komen', 1, 0, 'Ik zag Cecilia komen, alleen langs den boulevard.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zag-cecilia-komen', 1, 1, 'Ik zag Cecilia denken: “Mon dieu, que j’en ai marre!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zag-cecilia-komen', 1, 2, 'Den tijd met haren herder, den blonten Floriaen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zag-cecilia-komen', 1, 3, 'Dien dromer mee zijn schapen, die’s al zo lank gedaan.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zag-cecilia-komen', 1, 4, 'En d’eeuwen zijn gevlogen, heur liefde’n is bedrogen.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zag-cecilia-komen', 1, 5, 'Heur dromen zijn gevallen, gestorven op de grond.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zag-cecilia-komen', 1, 6, 'Hun sporen draagt Cecilia op heuren bitt’ren mond.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ik-zou-zo-graag-eens-vogelen', 'IK ZOU ZO GRAAG EENS VOGELEN', 'IK ZOU ZO GRAAG EENS VOGELEN', 'nederlandstalige-liederen', 'nl', NULL, 155, 156, NULL, '‘Daar zat een sneeuwwit vogeltje’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-zou-zo-graag-eens-vogelen', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zou-zo-graag-eens-vogelen', 0, 0, 'Ik zou zo graag eens vogelen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zou-zo-graag-eens-vogelen', 0, 1, 'Al met mijn stekeldoorntje, din don deine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zou-zo-graag-eens-vogelen', 0, 2, 'Al met mijn stekeldoorntje, din don don');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ik-zou-zo-graag-eens-vogelen', 0, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-zou-zo-graag-eens-vogelen', 1, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-zou-zo-graag-eens-vogelen', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zou-zo-graag-eens-vogelen', 2, 0, 'Mijn lief zij had haar regels weer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zou-zo-graag-eens-vogelen', 2, 1, 'Het was dus voor een andere keer.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ik-zou-zo-graag-eens-vogelen', 2, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-zou-zo-graag-eens-vogelen', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zou-zo-graag-eens-vogelen', 3, 0, 'Ik ging dus naar die blonde griet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zou-zo-graag-eens-vogelen', 3, 1, 'En vroeg: “Wilt gij van mijne piet?”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ik-zou-zo-graag-eens-vogelen', 3, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-zou-zo-graag-eens-vogelen', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zou-zo-graag-eens-vogelen', 4, 0, 'Die blonde griet zij liet haar doen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zou-zo-graag-eens-vogelen', 4, 1, 'Dus gaf ik altijd maar katoen!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ik-zou-zo-graag-eens-vogelen', 4, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-zou-zo-graag-eens-vogelen', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zou-zo-graag-eens-vogelen', 5, 0, 'Maar ’s anderendaags, och heer, och god');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zou-zo-graag-eens-vogelen', 5, 1, 'Stond er een broebel op mijne zot.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ik-zou-zo-graag-eens-vogelen', 5, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ik-zou-zo-graag-eens-vogelen', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zou-zo-graag-eens-vogelen', 6, 0, 'Maar nu ben ik alweer gezond');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ik-zou-zo-graag-eens-vogelen', 6, 1, 'En jaag het vuur in de wijven hun kont!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ik-zou-zo-graag-eens-vogelen', 6, 0, 0, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('in-de-stad-van-brussel', 'IN DE STAD VAN BRUSSEL', 'IN DE STAD VAN BRUSSEL', 'nederlandstalige-liederen', 'nl', NULL, 156, 156, NULL, '‘Saint Nicolas, patron des écoliers’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('in-de-stad-van-brussel', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-de-stad-van-brussel', 0, 0, 'In de stad van Brussel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-de-stad-van-brussel', 0, 1, 'Staat een groot pisein,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-de-stad-van-brussel', 0, 2, 'Opdat de stad van Brussel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-de-stad-van-brussel', 0, 3, 'Toch zou proper zijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-de-stad-van-brussel', 0, 4, 'Den ene pist alhier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-de-stad-van-brussel', 0, 5, 'Den andere pist aldaar,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-de-stad-van-brussel', 0, 6, 'Hun broek is nog niet open,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-de-stad-van-brussel', 0, 7, 'Of de flikken zijn al daar!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-de-stad-van-brussel', 0, 8, '’t Is een miserie, nondedju');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-de-stad-van-brussel', 0, 9, 'Ah, nondedju!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('in-de-stad-van-brussel', 0, 8, 8, 3, '(TER)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('jan-broeder', 'JAN BROEDER', 'JAN BROEDER', 'nederlandstalige-liederen', 'nl', NULL, 157, 158, NULL, NULL, 'Anoniem, bewerkt door J. Vermulst');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jan-broeder', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 0, 0, 'Jan Broeder vrijt een maske zoet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 0, 1, 'Een maske boven mate,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 0, 2, 'En as heur pa niet thuis en is:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 0, 3, 'Dan gaat em er wa bij praten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 0, 4, 'Hopsasa, ribedoebeda,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 0, 5, 'Dan gaat em er wa bij praten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 0, 6, 'Falala');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jan-broeder', 1, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jan-broeder', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 2, 0, 'Het wier na twelven van de nacht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 2, 1, 'De klokken luidden alle,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 2, 2, 'Dat maske tegen Jan Broeder sprak:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 2, 3, 'Gaat en leest uw getijen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 2, 4, 'Hopsasa ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jan-broeder', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 3, 0, '“Mijn getijen en lees ik niet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 3, 1, 'De tijd is al lang vergane;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 3, 2, '’k Ben liever al bij mijn zoetelief,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 3, 3, 'Als bij mijn confraters alle.”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 3, 4, 'Hopsasa ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jan-broeder', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 4, 0, 'Jan Broeder over ’t kerkhof kwam,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 4, 1, 'De preekheer kwam hem tegen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 4, 2, 'De preekheer tegen Jan Broeder sprak:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 4, 3, 'Waar zijde van de nacht gebleven?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 4, 4, 'Hopsasa ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jan-broeder', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 5, 0, 'Waar da’k van de nacht gebleve ben,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 5, 1, 'Dat zal mij niet berouwen:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 5, 2, 'Ze schonken er bier en tapten er wijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 5, 3, 'En ze spraken er al van vrouwen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 5, 4, 'Hopsasa ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jan-broeder', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 6, 0, 'Jan Broeder in het klooster kwam,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 6, 1, 'D’inwoners baden alle,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 6, 2, 'Den ene tegen den andere sprak:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 6, 3, 'Jan Broeder zal worden gevangen!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 6, 4, 'Hopsasa ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jan-broeder', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 7, 0, 'Toen hij dat daar dan had verstaan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 7, 1, 'Dat hij zou worden gevangen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 7, 2, 'Met ne sprong hij de venster uit,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 7, 3, 'En hij liet zijn kap daar hangen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 7, 4, 'Hopsasa ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jan-broeder', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 8, 0, 'Toen hij een eind gelopen had,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 8, 1, 'Toen keek hij nog is omme,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 8, 2, 'Hij riep: “O, kap, gij duvelskap,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 8, 3, 'Gij krijgt mij niet weeromme.”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 8, 4, 'Hopsasa ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jan-broeder', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 9, 0, 'Wie dat dees lieke heeft gedicht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 9, 1, 'En ja, ook heeft gezongen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 9, 2, 'Dat was ne pater, hij heette Jan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 9, 3, 'En hij is zijn kap ontsprongen!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-broeder', 9, 4, 'Hopsasa ...');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('jan-klaassen-de-trompetter', 'JAN KLAASSEN DE TROMPETTER', 'JAN KLAASSEN DE TROMPETTER', 'nederlandstalige-liederen', 'nl', NULL, 159, 159, 'Lennaert Nijgh', 'Boudewijn de Groot', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jan-klaassen-de-trompetter', 0, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 0, 0, 'Jan Klaassen was trompetter in het leger van de Prins');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 0, 1, 'Hij marcheerde van Den Helder tot Den Briel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 0, 2, 'Hij had geen geld en hij was geen held');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 0, 3, 'En hij hield niet van het krijgsgeweld');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 0, 4, 'Maar trompetter was hij wel in hart en ziel');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jan-klaassen-de-trompetter', 1, 'direction', 1, 'Het laatste refrein wordt vanaf de derde regel herhaald.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jan-klaassen-de-trompetter', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 2, 0, 'Het leger sloeg z’n tenten op voor Alkmaar in ’t veld');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 2, 1, 'En zolang geen vijand zich liet zien was iedereen een held');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 2, 2, 'De kroeg werd als strategisch punt door ’t hoofdkwartier bezet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 2, 3, 'De officieren brulden: “Jan, kom speel op je trompet!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 2, 4, 'Ze werden wakker in de goot in de morgen kil en koud');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 2, 5, 'Maar Jan Klaassen sliep in de armen van de dochter van de schout');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jan-klaassen-de-trompetter', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 3, 0, 'De Prins sprak op inspectie tot de majoor van de compagnie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 3, 1, '“Ik zag hier alle stukken wel van mijn artillerie.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 3, 2, 'Ja, zelfs dat kleine in uw kraag en dat blonde in uw bed.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 3, 3, 'Maar waar zit dat stuk ongeluk van ’n Jan met z’n trompet?”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 3, 4, 'En niemand die Jan Klaassen zag die bij de stadspoort zat');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 3, 5, 'En honderd liedjes speelde voor de kinderen van de stad');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jan-klaassen-de-trompetter', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 4, 0, 'Jan Klaassen zei: “Vaarwel mijn lief, ik zie je volgend jaar.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 4, 1, 'Wanneer de lente terugkomt dan zijn wij weer bij elkaar.”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 4, 2, 'De winter ging, de zomer kwam, de oorlog was voorbij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 4, 3, 'Maar het leger is nooit teruggekeerd van de Mokerhei');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 4, 4, 'Geen mens die van Jan Klaassen ooit iets teruggevonden heeft');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jan-klaassen-de-trompetter', 4, 5, 'Maar alle kinderen kennen hem; hij is niet dood, hij leeft!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('jerome', 'JEROME', 'JEROME', 'nederlandstalige-liederen', 'nl', NULL, 160, 161, NULL, '‘Que Sera, Sera’, Jay Livingston, Ray Evans', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jerome', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 0, 0, 'Toen ik een jaar of zeven was');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 0, 1, 'Vroeg ik mijn moeder wat zal ik zijn?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 0, 2, 'Word ik een boefer of milicien?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 0, 3, '’t Is wat ze zei tot mij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 0, 4, 'O Jerome, Jerome,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 0, 5, 'Een boefer zijn lul is krom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 0, 6, 'Word toch maar een milicien,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 0, 7, 'Want die poepen bien!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jerome', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 1, 0, 'Toen ik een jaar of veertien was');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 1, 1, 'Vroeg ik mijn moeder wat zal ik zijn?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 1, 2, 'Word ik een kaloot of VUB/VAT*-ancien?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 1, 3, '’t Is wat ze zei tot mij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 1, 4, 'O Cesar, Cesar,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 1, 5, 'Een kaloot die komt niet klaar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 1, 6, 'Word toch maar een VUB/VAT*-ancien,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 1, 7, 'Want die poepen bien!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jerome', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 2, 0, 'Toen ik een jaar of achttien was');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 2, 1, 'Vroeg ik mijn moeder wat zal ik zijn?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 2, 2, 'Word ik een dokter of econoom?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 2, 3, '’t Is wat ze zei tot mij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 2, 4, 'O Alain, Alain,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 2, 5, 'een dokter die vingert niet bien');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 2, 6, 'Word toch maar een ekonoom,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 2, 7, 'Want die schiet een zoon!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jerome', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 3, 0, 'Toen ik een jaar of twintig was');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 3, 1, 'Vroeg ik mijn moeder wat zal ik zijn?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 3, 2, 'Word ik een dopper of voyageur?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 3, 3, '’t Is wat ze zei tot mij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 3, 4, 'O Jean-Claude, Jean-Claude,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 3, 5, 'Een dopper die poept zich dood');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 3, 6, 'Word toch maar een voyageur,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jerome', 3, 7, 'Want die pakt ze van veur!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jerome', 4, 'direction', 1, 'Verdere versies kunnen aan de inspiratie van de corona overgelaten worden');
INSERT INTO footnote (song_id, position, text) VALUES ('jerome', 0, '* De keuze wordt overgelaten aan de zanger.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('jucheidi', 'JUCHEIDI', 'JUCHEIDI', 'nederlandstalige-liederen', 'nl', NULL, 162, 163, NULL, '‘Studio auf seiner Reis’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jucheidi', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 0, 0, 'De student is vrolijk man,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 0, 1, 'Jucheidi, jucheida,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 0, 2, 'Zingt en drinkt zoveel hij kan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 0, 3, 'Jucheidi, heida');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 0, 4, 'Springt en lacht maar altijd voort,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 0, 5, 'En kent nergens droevig oord,');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jucheidi', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 1, 0, 'Jucheidi, jucheida,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 1, 1, 'Jucheidi, heida');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('jucheidi', 1, 0, 0, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jucheidi', 2, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jucheidi', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 3, 0, 'Komt hij ene herberg in,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 3, 1, 'Hij drinkt immer blij van zin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 3, 2, 'En is ’t met het geld gedaan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 3, 3, 'Nog blijft zijne pret bestaan.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jucheidi', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 4, 0, 'Er blijft hem zo menig woon,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 4, 1, 'Waar men bier schenkt zonder loon,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 4, 2, 'En daarbij nog menig vriend');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 4, 3, 'Die hem graag tot gastheer dient.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jucheidi', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 5, 0, 'Daarom zingt hij op de straat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 5, 1, 'Blijde zangen vroeg of laat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 5, 2, 'Minnend elke schone maagd');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 5, 3, 'Die hem naar zijn hartje zaagt.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jucheidi', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 6, 0, 'Munich, Hop, Lambik of wijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 6, 1, '’t Kan hem nooit te vele zijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 6, 2, 'Altijd heeft hij honger, dorst,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 6, 3, 'Wijl hij zingt uit volle borst.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jucheidi', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 7, 0, 'En zo leeft hij vrolijk voort,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 7, 1, 'In het schoon studentenoord,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 7, 2, 'Tussen boek en pijp en pint,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 7, 3, 'Waar elk meisje hem bemint.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jucheidi', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 8, 0, 'Overal de vlag in top!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 8, 1, 'Held’re ogen, warme kop,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 8, 2, 'En de strijdzang langs de ree:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 8, 3, '“Vliegt de blauwvoet? Storm op zee!”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jucheidi', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 9, 0, 'Leefden wij nog honderd jaar,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 9, 1, 'Nooit en rouwde ’t onze schaar,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 9, 2, 'Al ons doen voor ’t Vlaamse diet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jucheidi', 9, 3, '’t Gildeleven, ’t Gildelied.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('het-kaerelslied', 'HET KAERELSLIED', 'KAERELSLIED, HET', 'nederlandstalige-liederen', 'nl', NULL, 163, 165, 'Hertaald uit het Gruuthuse handschrift door Alf. Wybo', 'Florimond van Duyse', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-kaerelslied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 0, 0, 'Ic wil van den kaerle singhen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 0, 1, 'Al met sinen langen baert;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 0, 2, 'Hine laet ghenen ruter hem dwinghen;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 0, 3, 'Ontembaer so is hi vanaert,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 0, 4, 'Ende of sine cleeder ontnaeit sijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 0, 5, 'Sin hooft mit een hoetkin ghecapt;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 0, 6, 'En mach sin caproen ooc verdraeit sijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 0, 7, 'Sin scoen ende cousen ghelapt.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-kaerelslied', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 1, 0, 'Al eti maer wronghelen, caes ende broot;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 1, 1, 'Al slaepti up stro ende cruut;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 1, 2, 'Vri alset veulen en kenti gheen noot;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 1, 3, 'Ende lacht di ruters uut.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-kaerelslied', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 2, 0, 'Hi esser een vriman gheboren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 2, 1, 'Ter see, upt velt of int bosch,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 2, 2, 'Waerom sou gheen plek hem behoren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 2, 3, 'Gheen plek vor een paert oft een os?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 2, 4, 'Die ruter heeft alles ghenomen;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 2, 5, 'Men loopet, als hi ghebiet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 2, 6, 'Bi dunen, bi vlacten, bi stromen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 2, 7, 'Dat en doet die kaerel niet!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-kaerelslied', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 3, 0, 'Hine wert niet den ruter een slave,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 3, 1, 'Ter kermesse blifdi gaen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 3, 2, 'Met ghespen, knijf ende stave,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 3, 3, 'Sin wijf met een mantelkin aen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 3, 4, 'Daer pijpen die cornemusen:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 3, 5, 'Daer springen ende dansen si ront,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 3, 6, 'Daer swieren si lanx die husen:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 3, 7, 'Daer singhen suut luder mont:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-kaerelslied', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 4, 0, 'Sine wijf is een vroudighe daerne;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 4, 1, 'Hi ploeght, ende si, si spint,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 4, 2, 'Hi cust ende blust se so gaerne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 4, 3, 'So winnen si kint up kint,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 4, 4, 'Ter kermesse drinken wi wine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 4, 5, 'Want wine verhoghet verstand;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 4, 6, 'Nu esser die waerelt de sine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 4, 7, 'Met steden, casteel ende lant,');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-kaerelslied', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 5, 0, 'Si willen den kaerel doen greinsen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 5, 1, 'Al dravende over ’t velt;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 5, 2, 'Hi es coener dan si wael peinsen;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 5, 3, 'Hine bevet voor gheen ghewelt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 5, 4, 'Si willen hem sleepen en hangen;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 5, 5, 'Te lanc es haer sin baert,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 5, 6, 'O ruter, als hi U moet vanghen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-kaerelslied', 5, 7, 'Wi weter hoe ghi dan vaert!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('kalinka', 'KALINKA', 'KALINKA', 'nederlandstalige-liederen', 'nl', NULL, 165, 165, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('kalinka', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kalinka', 0, 0, '’k Zou zo geiren ne kie kakken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kalinka', 0, 1, 'Maar mijn broekske wil niet zakken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kalinka', 0, 2, '’t Is aan mijn billen blijven plakken.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('kalinka', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kalinka', 1, 0, 'Kak hier, kak al hier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kalinka', 1, 1, 'Kak al hier, kak al daar!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('kalinka', 1, 0, 1, 4, '(QUAT)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('kalinka', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kalinka', 2, 0, '’k Heb hem eindelijk afgekregen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kalinka', 2, 1, 'O mijn god was dat een zegen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kalinka', 2, 2, '’t Komt uit mijn holleken gerezen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('kalinka', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kalinka', 3, 0, 'O mijn god, ’k kan niet meer stoppen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kalinka', 3, 1, 'Heel de kamer ligt vol brokken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kalinka', 3, 2, '’k Ben hier het schijtrekord aan ’t kloppen.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('kempenland', 'KEMPENLAND', 'KEMPENLAND', 'nederlandstalige-liederen', 'nl', NULL, 166, 166, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('kempenland', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 0, 0, 'Kempenland, aan de Dietse kroon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 0, 1, 'Wonderfrisse perel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 0, 2, 'Kempenland, welig zoete woon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 0, 3, 'Van de koene kerel.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 0, 4, 'Op de heide gloort de zon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 0, 5, 'Ons zo stralend tegen;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 0, 6, 'Of uit frisse hemelbron,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 0, 7, 'Ruist zo vro de regen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('kempenland', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 1, 0, 'Op de heide waait de wind');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 1, 1, 'Vrij van haag en heg,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 1, 2, 'Op de heide waait de wind');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 1, 3, 'Alle zorgen weg!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('kempenland', 2, 'direction', 1, 'De eerste vier regels van de eerste strofe worden voor elke andere strofe herhaald.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('kempenland', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 3, 0, 'Op de heide staat een huis');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 3, 1, 'Rondom in het lover;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 3, 2, 'Wolken blank of grauw als gruis');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 3, 3, 'Trekken traag daarover.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('kempenland', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 4, 0, 'Op de heide zoete meid,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 4, 1, 'Hebt ge mij verkoren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 4, 2, 'Bij de gagel voor altijd,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 4, 3, 'Wij u trouw gezworen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('kempenland', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 5, 0, 'Kempisch volk, zo vrij en blij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 5, 1, 'Schoon van ziel en lijve;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 5, 2, 'Harde tijden gaan voorbij,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kempenland', 5, 3, 'Maar een volk moet blijven.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('klein-marleentje', 'KLEIN MARLEENTJE', 'KLEIN MARLEENTJE', 'nederlandstalige-liederen', 'nl', NULL, 167, 167, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('klein-marleentje', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klein-marleentje', 0, 0, 'Ik pakte mijn Marleentje');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klein-marleentje', 0, 1, 'Al bij haar kleine hoofdje');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klein-marleentje', 0, 2, 'En vroeg aan mijn Marleentje:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klein-marleentje', 0, 3, 'Wat is dat? Staat er daar haar op?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klein-marleentje', 0, 4, 'Dat is mijn krullebol.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klein-marleentje', 0, 5, 'Ik heb elke avond lol');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klein-marleentje', 0, 6, 'Wanneer ik even kijk naar mijne kleine krullebol.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('klein-marleentje', 1, 'direction', 1, 'Volgende strofen worden op dezelfde manier gevormd, maar “hoofdje” en “krullebol” worden vervangen door:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('klein-marleentje', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klein-marleentje', 2, 0, '“neusje” “ruikerderuik”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klein-marleentje', 2, 1, '“oogjes” “kijkerdekijk”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klein-marleentje', 2, 2, '“mondje” “smakkerdesmak”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klein-marleentje', 2, 3, '“keeltje” “slikkerdeslik”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klein-marleentje', 2, 4, '“borstjes”“melkfabriek”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klein-marleentje', 2, 5, '“buikje” “kindertuin”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klein-marleentje', 2, 6, '“foefke” “daar mag je alleen maar naar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klein-marleentje', 2, 7, 'kijken maar niet aankomen”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('klein-marleentje', 3, 'direction', 1, 'Bovendien wordt na elke regel al het voorgaande herhaald. Zo wordt deze regel bvb. voor de vierde strofe:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('klein-marleentje', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klein-marleentje', 4, 0, 'Dat is mijn smakkerdesmak, mijn kijkerdekijk,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klein-marleentje', 4, 1, 'Mijn ruikerderuik, mijn krullebol.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('klokke-roeland', 'KLOKKE ROELAND', 'KLOKKE ROELAND', 'nederlandstalige-liederen', 'nl', NULL, 168, 169, 'Albrecht Rodenbach, 1877', 'Johan De Stoop', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('klokke-roeland', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 0, 0, 'Boven Gent rijst, eenzaam en grijs,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 0, 1, '’t Oud Belfort, zinbeeld van ’t verleden;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 0, 2, 'Somber en groots, steeds stom en doods.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 0, 3, 'Treurt d’oude reus op ’t Gent van heden;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 0, 4, 'Maar soms hij rilt en eensklaps gilt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 0, 5, 'Zijn bronzen stemme door de stede:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 0, 6, '“Trilt in uw graf, trilt Gentse helden;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 0, 7, 'Gij, Jan Hyoens, gij Artevelden;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 0, 8, 'Mijn naam is Roeland, ’k kleppe brand');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 0, 9, 'En luide storm in Vlaanderland!”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('klokke-roeland', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 1, 0, 'Een bont verschiet schept ’t bronzen lied,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 1, 1, 'Prachtig weertov’rend mij voor d’ogen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 1, 2, 'Mijn ziel herkent het oude Gent;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 1, 3, '’t Volk komt gewapend toegevlogen.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 1, 4, '’t Land is in nood: “Vrijheid of dood!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 1, 5, 'De gilden komen aangetogen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 1, 6, '’k Zie Jan Hyoens, ’k zie Artevelden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 1, 7, 'En stormend roept Roeland den helden;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 1, 8, '“Mijn naam is Roeland, ’k kleppe brand,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 1, 9, 'En luide storm in Vlaanderland!”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('klokke-roeland', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 2, 0, 'O heldenvolk, o reuzenvolk,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 2, 1, 'O pracht en macht van vroeger dagen!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 2, 2, 'O bronzen lied, ’k wete uw bedied,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 2, 3, 'En ik versta ’t verwijtend klagen;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 2, 4, 'Doch wees getroost: zie ’t Oosten bloost');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 2, 5, 'En Vlaandrens zonne gaat aan ’t dagen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 2, 6, '“Vlaanderen die Leu”, trilt d’ oude toren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 2, 7, 'En paart een lied met onze koren;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 2, 8, 'Zing: “Ik ben Roeland, ’k kleppe brand,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('klokke-roeland', 2, 9, 'Luide triomf in Vlaanderland!”');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('het-koekoekslied', 'HET KOEKOEKSLIED', 'KOEKOEKSLIED, HET', 'nederlandstalige-liederen', 'nl', NULL, 169, 169, 'Geertje Drieghe', NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-koekoekslied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-koekoekslied', 0, 0, 'Als de bomen zacht ruisen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-koekoekslied', 0, 1, 'In de zomerse regen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-koekoekslied', 0, 2, 'Roept de koekoek ons tegen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-koekoekslied', 0, 3, 'Om naar buiten te gaan');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-koekoekslied', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-koekoekslied', 1, 0, 'Holderia tiria holderia koekoek');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-koekoekslied', 1, 1, 'Holderia tiria ho ...');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('het-koekoekslied', 1, 0, 0, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-koekoekslied', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-koekoekslied', 2, 0, 'Laten w’eens goed door drinken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-koekoekslied', 2, 1, '’t Gerstenat laten zinken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-koekoekslied', 2, 2, 'Met ons kiel en ons linten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-koekoekslied', 2, 3, 'Onze lever moet eraan');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('komt-vrienden-in-het-ronde', 'KOMT, VRIENDEN, IN HET RONDE', 'KOMT, VRIENDEN, IN HET RONDE', 'nederlandstalige-liederen', 'nl', NULL, 170, 171, NULL, NULL, 'Opgetekend door J. Bols');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('komt-vrienden-in-het-ronde', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 0, 0, 'Komt, vrienden, in het ronde,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 0, 1, 'Minnaars van enen stiel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 0, 2, 'Ik zal U gaan verkonden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 0, 3, 'Hoe ik door ’t slijperswiel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 0, 4, 'Den kost verdien voor vrouw en kind,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 0, 5, 'Schoon blootgesteld aan sneeuw en wind.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('komt-vrienden-in-het-ronde', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 1, 0, 'Terliererom Terla!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 1, 1, 'Van linksom, rechtsom draait mijnen steen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 1, 2, 'Bij het roeren van mijn been,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 1, 3, 'Ju! Ju! Ju! Ju! Ju! Ju! Ju! Ju!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('komt-vrienden-in-het-ronde', 1, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('komt-vrienden-in-het-ronde', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 2, 0, 'De smid die moet hard werken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 2, 1, 'Gestatig voor het vier;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 2, 2, 'Hij durft hem niet versterken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 2, 3, 'Met ene kan goed bier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 2, 4, 'Terwijl ik ga op mijn gemak,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 2, 5, 'Soms ook wel met een lege zak.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('komt-vrienden-in-het-ronde', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 3, 0, 'De schoenpik, stijf gezeten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 3, 1, 'Op ene pikkelstoel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 3, 2, 'Mag kees en droog brood eten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 3, 3, 'Maar als ik nood gevoel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 3, 4, 'Dan slijp ik tot den avond toe');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 3, 5, 'En zo heb ik nooit arremoe.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('komt-vrienden-in-het-ronde', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 4, 0, 'De kleerfrik maakt ons kleren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 4, 1, 'Voor acht stuivers per dag');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 4, 2, 'Wil hij den loon vermeren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 4, 3, 'Hij snijdt meer dan hij mag');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 4, 4, 'Maar ik met mijnen slijperssteen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 4, 5, 'Ik win meer op een uur alleen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('komt-vrienden-in-het-ronde', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 5, 0, 'De maalder moet graan malen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 5, 1, 'Tot in het fijnste meel;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 5, 2, 'Hij doet dubbel betalen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 5, 3, 'Voor zijne droge keel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 5, 4, 'Maar ik door iever en door vlijt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 5, 5, 'Ik win mijn brood in eerlijkheid.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('komt-vrienden-in-het-ronde', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 6, 0, 'Mijn vrouw die roept victoria');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 6, 1, 'Over den slijpersstiel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 6, 2, 'Zij vindt haar grootste gloria');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 6, 3, 'In ’t draaien van het wiel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 6, 4, 'Mijn kinders hebben geen ongemak');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 6, 5, 'Zij lopen met den bedelzak!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('komt-vrienden-in-het-ronde', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 7, 0, 'Sa, vrienden, voor het leste');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 7, 1, 'All’ ambachten zijn goed,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 7, 2, 'Maar ’t mijn is toch het beste,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 7, 3, 'Schoon ik soms slapen moet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 7, 4, 'Op hooi of strooi in enen stal:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('komt-vrienden-in-het-ronde', 7, 5, 'Daar heb ik kost voor niemendal.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('krambambouli', 'KRAMBAMBOULI', 'KRAMBAMBOULI', 'nederlandstalige-liederen', 'nl', NULL, 172, 173, 'Duits studentenlied, vertaling van Jef Vanden Eynde', 'Duitse volkmelodie uit Göttinge, Otto Deneke', 'Voor het eerst gepubliceerd in 1745 bestond dit lied uit 49 strofen. Twee jaar later publiceerde Christoph Friedrich Wittekind, onder het pseudoniem ‘Crescentius Koromandel’, een aangevulde versie van 102 strofen. In tegenstelling tot in de vertaling is Krambambouli een warme drank op basis van wijn, rum en karamel, die 1 maal per jaar op een speciale ‘Krambamboulikneipe’ wordt bereid, volgens een even vast als uitgebreid ritueel.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('krambambouli', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 0, 0, '“Krambambouli”, zo wordt geheten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 0, 1, 'Dat schuimend blond studentennat');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 0, 2, 'Wie zou d’r op aard iets beters weten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 0, 3, 'In alle pijn en smart als dat?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 0, 4, 'Van ’s avonds laat tot ’s morgens vroeg');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 0, 5, 'Drink ik mijn glas krambambouli,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 0, 6, 'Krambimbambambouli, krambambouli!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('krambambouli', 0, 6, 6, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('krambambouli', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 1, 0, 'En brandt mijn hoofd en mijne wangen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 1, 1, 'Of breekt mijn herte van verdriet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 1, 2, 'Of krult mijn maag in duizend tangen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 1, 3, 'Of bibbert ’t lijf gelijk een riet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 1, 4, 'Ik lach met al die medici');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 1, 5, 'En drink mijn glas krambambouli,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 1, 6, 'Krambimbambambouli, krambambouli!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('krambambouli', 1, 6, 6, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('krambambouli', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 2, 0, 'Waar ik als edelman geboren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 2, 1, 'Keizer zoals Maximiliaan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 2, 2, 'Ik stichtte een orde uitverkoren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 2, 3, 'En als devies hing ik daaraan:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 2, 4, '“Toujours fidèle et sans souci');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 2, 5, 'C’est l’ordre du krambambouli,”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 2, 6, 'Krambimbambambouli, krambambouli!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('krambambouli', 2, 6, 6, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('krambambouli', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 3, 0, 'Is moeders geld nog uitgebleven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 3, 1, 'En heb ik schulden met de macht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 3, 2, 'Heeft ’t zoete lief me niet geschreven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 3, 3, 'De post van thuis droef nieuws gebracht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 3, 4, 'Dan drink ik uit melancholie,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 3, 5, 'Een schuimend glas krambambouli,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 3, 6, 'Krambimbambambouli, krambambouli!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('krambambouli', 3, 6, 6, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('krambambouli', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 4, 0, 'En is mijn geld al naar de donder');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 4, 1, 'Dan peezuig ik van elke schacht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 4, 2, 'Al heb ik geld, al zit ik zonder,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 4, 3, 'Eens wordt het heelal tot stof gebracht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 4, 4, 'Want dat is de filosofie,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 4, 5, 'Naar de geest van krambambouli,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('krambambouli', 4, 6, 'Krambimbambambouli, krambambouli!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('krambambouli', 4, 6, 6, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('het-land-van-hawai', 'HET LAND VAN HAWAÏ', 'LAND VAN HAWAÏ, HET', 'nederlandstalige-liederen', 'nl', NULL, 174, 174, NULL, '‘Marche Américaine’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-land-van-hawai', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-land-van-hawai', 0, 0, 'Wij gaan naar het land van Hawaï,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-land-van-hawai', 0, 1, 'Naar het land van de wuivende wijven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-land-van-hawai', 0, 2, 'Daar lopen ze bloot in de wei,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-land-van-hawai', 0, 3, 'Tot dat g’er niet meer af kunt blijven!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('lied-der-dekadentie', 'LIED DER DEKADENTIE', 'LIED DER DEKADENTIE', 'nederlandstalige-liederen', 'nl', NULL, 174, 174, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-der-dekadentie', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-der-dekadentie', 0, 0, 'Blote tetten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-der-dekadentie', 0, 1, 'En daar twee choepkens op');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('lied-der-dekadentie', 0, 0, 0, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-der-dekadentie', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-der-dekadentie', 1, 0, 'Stijve pieten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-der-dekadentie', 1, 1, 'En daar twee ballen aan');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('lied-der-dekadentie', 1, 0, 0, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-der-dekadentie', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-der-dekadentie', 2, 0, 'Hete foefen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-der-dekadentie', 2, 1, 'En daar die piet d’erin');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('lied-der-dekadentie', 2, 0, 0, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-der-dekadentie', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-der-dekadentie', 3, 0, 'Dekadentie');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('lied-der-dekadentie', 3, 0, 0, 3, '(TER)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('het-lied-der-vlamingen', 'HET LIED DER VLAMINGEN', 'LIED DER VLAMINGEN, HET', 'nederlandstalige-liederen', 'nl', NULL, 175, 175, 'Emmanuel Hiel', 'Peter Benoit, uit het oratorium ‘De Schelde’, 1868', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lied-der-vlamingen', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 0, 0, 'Waar Maas en Schelde vloeien');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 0, 1, 'De Noordzee bruist en stormt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 0, 2, 'Waar vrede en kunsten bloeien');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 0, 3, 'De vrijheid mannen vormt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 0, 4, 'Waar velden, wouden, weiden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 0, 5, 'Als gaarden rijk beplant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 0, 6, 'De weelde en vreugd verspreiden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 0, 7, 'Daar is, daar is ons Vaderland');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 0, 8, 'Daar is ons Vaderland');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lied-der-vlamingen', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 1, 0, 'Daar stijgen uit ’t verleden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 1, 1, 'De Keer’l en Klauwaert op');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 1, 2, 'Zij hebben stout gestreden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 1, 3, 'Verplet hun vreemde kop');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 1, 4, 'Hun goed, hun bloed, hun leven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 1, 5, 'Met mildheid steeds verpand');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 1, 6, 'Om ons te kunnen geven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 1, 7, 'Het vrij, het vrije Vaderland');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 1, 8, 'Het vrije Vaderland');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lied-der-vlamingen', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 2, 0, 'O Nederland! O Vrijheid!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 2, 1, 'Gij adelt ons gevoel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 2, 2, 'Wij zweren ook met blijheid');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 2, 3, 'Uw toekomst is ons doel!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 2, 4, 'Wij zullen, jonge scharen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 2, 5, 'Steeds onze plicht gestand');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 2, 6, 'Met hand en hart bewaren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 2, 7, 'Het vrij, het vrije Vaderland');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-der-vlamingen', 2, 8, 'Het vrije Vaderland');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('lied-van-antoon', 'LIED VAN ANTOON', 'LIED VAN ANTOON', 'nederlandstalige-liederen', 'nl', NULL, 176, 177, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-van-antoon', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 0, 0, 'Er was een boerenmeisje,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 0, 1, 'Er was een boerenzoon,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 0, 2, 'Sofie heette dat meisje,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 0, 3, 'Antoon heette die zoon.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-van-antoon', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 1, 0, 'En heddem niet gezien,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 1, 1, '’t Was zo ne grote smeerlap,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 1, 2, 'En heddem niet gezien, Antoon?');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-van-antoon', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 2, 0, 'Het meisje had seksappeal,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 2, 1, 'De jongen was heel heet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 2, 2, 'Daaruit ontstond een drang,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 2, 3, 'Die ieder zelden kan.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-van-antoon', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 3, 0, 'Ze hadden saam besloten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 3, 1, 'Ze hadden saam beslist,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 3, 2, 'Eens lekker te gaan vogelen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 3, 3, 'Al in de haverkist.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-van-antoon', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 4, 0, 'Maar door het danig wrijven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 4, 1, 'En stoten van zijn zot,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 4, 2, 'Daar vloog hij godverdomme,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 4, 3, 'Die haverkist op slot.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-van-antoon', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 5, 0, 'De vader moe van werken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 5, 1, 'Kwam ’s avonds laat naar huis,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 5, 2, 'Wat vond hij te bemerken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 5, 3, 'Noch zoon noch meid was thuis.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-van-antoon', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 6, 0, 'Na lang en pijnlijk zoeken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 6, 1, 'Wat vond hij tot zijn spijt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 6, 2, 'Zijn allerliefste zoontje,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 6, 3, 'Al boven op die meid.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-van-antoon', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 7, 0, 'In dolle woede ontstoken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 7, 1, 'Wat toen die smeerlap deed,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 7, 2, 'Hij nam een emmer water,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 7, 3, 'En goot hem op die twee.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-van-antoon', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 8, 0, 'Op haar blanke navel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 8, 1, 'Kreeg zij een volle scheut,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 8, 2, 'Ze zei: “Het is toch spijtig,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 8, 3, 'Want w’hadden heel veel leut.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-van-antoon', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 9, 0, 'Maar negen maanden later,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 9, 1, 'Toen kwam een kleine guit,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 9, 2, 'En die had me godverdomme,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 9, 3, 'De haver op zijn snuit.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lied-van-antoon', 10, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 10, 0, 'Daaruit wordt nu besloten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 10, 1, 'Daaruit wordt nu beslist,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 10, 2, 'Dat vogelen godverdomme,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lied-van-antoon', 10, 3, 'Geen kinderspelen is.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('het-lied-van-hertog-jan', 'HET LIED VAN HERTOG JAN', 'LIED VAN HERTOG JAN, HET', 'nederlandstalige-liederen', 'nl', NULL, 179, 181, 'Harrie Beex, 1947', 'Floris van de Putt, 1947', 'Loflied op Jan I Hertog van Brabant (1235–1294), één van de eerste in de Dietse volkstaal schrijvende dichters uit ons taalgebied. Zijn bekendste minnelied heet “Harba lori fa”, ofte “Eens meienmorgens vroeg ”. De zinsnede “Harba lori fa” zou uit het Provencaals afkomstig zijn “Herba flors fa”, wat in het Frans “l’herbe fait des fleurs” wordt ofte “het gras staat in bloei”. Hiermee had onze Middelnederlandse vriend het niet over zijn tuinierskwalitieten maar bedoelde hij hoogstwaarschijnlijk “ik sta heet”.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lied-van-hertog-jan', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 0, 0, 'Toen den hertog Jan kwam varen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 0, 1, 'Te peerd parmant, al triumfant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 0, 2, 'Na zevenhonderd jaren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 0, 3, 'Hoe zong men ’t allen kant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 0, 4, 'Harba lorifa, zong den Hertog, harba lorifa,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 0, 5, 'Na zevenhonderd jaren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 0, 6, 'In dit edel Brabants land');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lied-van-hertog-jan', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 1, 0, 'Hij kwam van over ’t water');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 1, 1, 'Den Scheldevloed, aan wal te voet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 1, 2, '’t Antwerpen op de straten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 1, 3, 'Zilv’ren veren op zijn hoed');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 1, 4, 'Harba lorifa, zong den Hertog, harba lorifa');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 1, 5, '’t Antwerpen op de straten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 1, 6, 'Lere leerzen aan zijn voet');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lied-van-hertog-jan', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 2, 0, 'Och Turnhout, stedeke schone');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 2, 1, 'Zijn uw ruitjes groen, maar uw hertjes koen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 2, 2, 'Laat den Hertog binnen komen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 2, 3, 'In dit zomers vrolijk seizoen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 2, 4, 'Harba lorifa, zong den Hertog, harba lorifa');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 2, 5, 'Laat den Hertog binnen komen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 2, 6, 'Hij heeft een peerd van doen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lied-van-hertog-jan', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 3, 0, 'Hij heeft een peerd gekregen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 3, 1, 'Een schoon, wit peerd, een schimmelpeerd');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 3, 2, 'Daar is hij opgestegen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 3, 3, 'Dien ridder onverveerd');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 3, 4, 'Harba lorifa, zong den Hertog, harba lorifa');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 3, 5, 'Daar is hij opgestegen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 3, 6, 'En hij reed naar Valkensweerd');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lied-van-hertog-jan', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 4, 0, 'In Valkensweerd daar zaten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 4, 1, 'Al in de kast, de zilverkast');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 4, 2, 'De guldenkoning zijn platen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 4, 3, 'Die wierd’ aaneen gelast');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 4, 4, 'Harba lorifa, zong den Hertog, harba lorifa');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 4, 5, 'De guldenkoning zijn platen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 4, 6, 'Toen had hij een harnas');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lied-van-hertog-jan', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 5, 0, 'Rooise boeren, komt naar buiten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 5, 1, 'Met de grote trom, met de kleine trom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 5, 2, 'Trompetten en cornetten en de fluiten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 5, 3, 'Want den Hertog komt weerom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 5, 4, 'Harba lorifa, zong den Hertog, harba lorifa');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 5, 5, 'Trompetten en cornetten en de fluiten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 5, 6, 'In dit Brabants Hertogdom');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lied-van-hertog-jan', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 6, 0, 'Wij reden allemaal samen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 6, 1, 'Op Oirschot aan, door een Kanidasselaan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 6, 2, 'En Jan riep: “In Geus name!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 6, 3, 'Hier heb ik meer gestaan.”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 6, 4, 'Harba lorifa, zong den Hertog, harba lorifa');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 6, 5, 'En Jan riep: “In Geus name!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 6, 6, 'Reikt mij mijn standaard aan!”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lied-van-hertog-jan', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 7, 0, 'De standaard was de gouwe');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 7, 1, 'Die waaide dan, die draaide dan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 7, 2, 'Die droeg de leeuw met klauwen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 7, 3, 'Wij zongen alleman');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 7, 4, 'Harba lorifa, zong den Hertog, harba lorifa');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 7, 5, 'Die droeg de leeuw met klauwen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 7, 6, 'Ja, de Leeuw van Hertog Jan');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lied-van-hertog-jan', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 8, 0, 'Hij is in Den Bosch gekomen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 8, 1, 'Al in de nacht, niemand die ’t zag');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 8, 2, 'En op Sint Jan geklommen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 8, 3, 'Daar ging hij staan op wacht');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 8, 4, 'Harba lorifa, zong den Hertog, harba lorifa');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 8, 5, 'En op Sint Jan geklommen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-hertog-jan', 8, 6, 'Daar staat hij dag en nacht');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('het-lied-van-koppelstock-de-veerman', 'HET LIED VAN KOPPELSTOCK DE VEERMAN', 'LIED VAN KOPPELSTOCK DE VEERMAN, HET', 'nederlandstalige-liederen', 'nl', NULL, 183, 184, NULL, NULL, 'A.J. Schooleman, 1872
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lied-van-koppelstock-de-veerman', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 0, 0, 'In naam van Oranje, doet open de poort!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 0, 1, 'De watergeus ligt aan de wal:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 0, 2, 'De vlootvoogd der Geuzen, hij maakt geen akkoord');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 0, 3, 'Hij vordert Den Briel of uw val');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 0, 4, 'Dat is het bevel van Lumey op mijn eer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 0, 5, 'En burgers, hier baat nu geen tegenstand meer,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 0, 6, 'De watergeus komt om Den Briel!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('het-lied-van-koppelstock-de-veerman', 0, 6, 6, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lied-van-koppelstock-de-veerman', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 1, 0, 'De vloot is met vijfduizend koppen bemand,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 1, 1, 'De mannen zijn kloek en vol vuur.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 1, 2, 'Een ogenblik nog en zij stappen aan land,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 1, 3, 'Zij wachten bericht binnen ’t uur;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 1, 4, 'Gij moogt dus niet dralen, doet open die poort,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 1, 5, 'Dan nemen de Geuzen terstond zonder moord');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 1, 6, 'Bezit van de vesting Den Briel!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('het-lied-van-koppelstock-de-veerman', 1, 6, 6, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lied-van-koppelstock-de-veerman', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 2, 0, 'Komt, geeft de verzek’ring, ’k moet spoedig terug');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 2, 1, 'De klok heeft het uur reeds gemeld.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 2, 2, 'Ik zeg ’t U, geeft gij mij de sleutels niet vlug');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 2, 3, 'Dan is reeds uw vonnis geveld.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 2, 4, 'De wakkere Geuzen staan tandenknarsend daar.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 2, 5, 'Zij wetten hun zwaarden en maken zich klaar.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 2, 6, 'En zweren: “Den dood of Den Briel!”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('het-lied-van-koppelstock-de-veerman', 2, 6, 6, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lied-van-koppelstock-de-veerman', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 3, 0, 'Hier dringt men naar buiten, daar schuilt men bijeen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 3, 1, 'En spreekt over Koppelstocks last:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 3, 2, '“De stad in hun handen of anders de dood”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 3, 3, '’t Besluit tot het eerste staat vast!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 3, 4, 'Maar nauw’lijks is hiermee de veerman gevleid,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 3, 5, 'Of Simon de Rijck heeft de poort gerammeid');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lied-van-koppelstock-de-veerman', 3, 6, 'En zo kwam de Geus in Den Briel!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('het-lied-van-koppelstock-de-veerman', 3, 6, 6, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('de-liereman', 'DE LIEREMAN', 'LIEREMAN, DE', 'nederlandstalige-liederen', 'nl', NULL, 184, 185, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-liereman', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 0, 0, 'Der was eens ne liereman');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 0, 1, 'Uit lieren ja gegaan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 0, 2, 'En wat vond hij onder');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 0, 3, 'Zijne wegen staan:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 0, 4, 'Een overschoon juffrouw;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 0, 5, 'Een overschoon juffrouw.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 0, 6, 'En hij vroeg of zij een deuntje;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 0, 7, 'Op zijn liere spelen wou.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('de-liereman', 0, 4, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-liereman', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 1, 0, 'Die juffrouw sprak de liereman');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 1, 1, 'Zo vriendelijk aan:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 1, 2, 'Zijt gij zeker dat de snare van');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 1, 3, 'Uw liere nog zal gaan?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 1, 4, 'Kom mee naar mijn salet;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 1, 5, 'Kom mee naar mijn salet.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 1, 6, 'En dan spelen we een deuntje;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 1, 7, 'Op de liere in mijn bed');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('de-liereman', 1, 4, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-liereman', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 2, 0, 'De speleman die speelde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 2, 1, 'Al zijn kleren uit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 2, 2, 'En de snaren van zijn liere');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 2, 3, 'Stonden recht vooruit.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 2, 4, 'Ze slingerden alhier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 2, 5, 'Ze slingerden aldaar.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 2, 6, 'En ze slingerden voor ’t gaatje;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 2, 7, 'Van je weet wel waar!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('de-liereman', 2, 4, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-liereman', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 3, 0, 'En toen dat de liereman zijn');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 3, 1, 'Lusten had voldaan.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 3, 2, 'Is hij met een slappe slinger naar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 3, 3, 'Zijn vrouwke toegegaan!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 3, 4, 'En zo komt hij naar huis;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 3, 5, 'En zo komt hij naar huis.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 3, 6, 'En hij komt er zonder geld en;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-liereman', 3, 7, 'Met ne slappe slinger thuis.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('de-liereman', 3, 4, 7, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('het-lindenmeisje', 'HET LINDENMEISJE', 'LINDENMEISJE, HET', 'nederlandstalige-liederen', 'nl', NULL, 185, 187, 'Rudolf Baumbach, vertaling: Jef Vanden Eynde', '‘Keinen Tropfen im Becher mehr’, Franz Abt', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lindenmeisje', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 0, 0, '’k Zoog uit ’t glas het laatste nat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 0, 1, 'Mijne beurs is leeg en plat');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 0, 2, 'Dorstig hart en tonge!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 0, 3, '’t Is de schuld van uwen wijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 0, 4, 'Uwer oogjes hellen schijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 0, 5, 'Lindenmeisje, gij jonge!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('het-lindenmeisje', 0, 5, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lindenmeisje', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 1, 0, '“Nimmer schrijft men hier in ’t krijt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 1, 1, 'Wij zijn ’t laatste brokje kwijt!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 1, 2, 'Lacht het meisje lustig!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 1, 3, '“Hebt gij gene duiten meer,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 1, 4, 'Leg uw reiszak hier maar neer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 1, 5, 'En drink op dan rustig!”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('het-lindenmeisje', 1, 5, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lindenmeisje', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 2, 0, 'Zijnen reiszak heeft de gast');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 2, 1, 'Gauw voor enen kruik belast!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 2, 2, 'Nu voor ’t scheiden der zorgen!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 2, 3, '’t Meisje fluistert: “Jeugdig bloed,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 2, 4, 'G’hebt nog mantel, stok en hoed,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 2, 5, 'Drink en laat ze borgen!”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('het-lindenmeisje', 2, 5, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lindenmeisje', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 3, 0, 'Zijne mantel, hoed en stok,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 3, 1, 'Ruilde hij voor enen slok,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 3, 2, 'Spraak bedroefd: “Vervlogen!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 3, 3, 'O, vaarwel, gij koele drank,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 3, 4, 'Lindenmeisje, jong en slank,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 3, 5, 'Vreugde mijner ogen!”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('het-lindenmeisje', 3, 5, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lindenmeisje', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 4, 0, 'Het meisje fluistert nogmaals: “Blijf');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 4, 1, 'G’hebt een hart nog in uw lijf;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 4, 2, 'Laat het mij ten pande!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 4, 3, 'Wat gebeurde doe ’k U kond;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 4, 4, 'Op des meisjes roden mond');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 4, 5, 'Warm een ander brandde!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('het-lindenmeisje', 4, 5, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-lindenmeisje', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 5, 0, 'Wie dit nieuwe liedje dacht');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 5, 1, 'Zong het in de zomernacht');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 5, 2, 'Lustig in den winde!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 5, 3, 'Voor hem stond het schuimend nat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 5, 4, 'Nevens hem het meisje zat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-lindenmeisje', 5, 5, 'Onder de bloeiende linde!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('het-lindenmeisje', 5, 5, 5, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('het-loze-vissertje', 'HET LOZE VISSERTJE', 'LOZE VISSERTJE, HET', 'nederlandstalige-liederen', 'nl', NULL, 187, 188, NULL, NULL, 'Gent, 18e eeuw');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-loze-vissertje', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-loze-vissertje', 0, 0, 'Des winters als het regent,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-loze-vissertje', 0, 1, 'Dan zijn de paadjes diep, ja diep,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-loze-vissertje', 0, 2, 'Dan komt het loze vissertje');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-loze-vissertje', 0, 3, 'Vissen al in het riet, ja riet.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-loze-vissertje', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-loze-vissertje', 1, 0, 'Met zijnen rijfstok, met zijnen strijkstok.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-loze-vissertje', 1, 1, 'Met zijnen lapzak, met zijnen knapzak,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-loze-vissertje', 1, 2, 'Met zijne lere van dire domme dere,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-loze-vissertje', 1, 3, 'Met zijne lere laarsjes aan.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('het-loze-vissertje', 1, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-loze-vissertje', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-loze-vissertje', 2, 0, 'Dat loze molenarinnetje');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-loze-vissertje', 2, 1, 'Ging in heur deurtje staan, ja staan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-loze-vissertje', 2, 2, 'Opdat het aardig vissertje');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-loze-vissertje', 2, 3, 'Voorbij haar heen zou gaan, ja gaan.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-loze-vissertje', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-loze-vissertje', 3, 0, '“Wat heb ik U misdreven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-loze-vissertje', 3, 1, 'Wat heb ik U misdaan, ja daan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-loze-vissertje', 3, 2, 'Opdat ik niet met vrede');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-loze-vissertje', 3, 3, 'Voorbij uw deur mag gaan, ja gaan.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-loze-vissertje', 4, 'chorus-ref', 1, 'waarbij ‘zijnen’ door ‘mijnen’ vervangen wordt.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-loze-vissertje', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-loze-vissertje', 5, 0, '“Gij hebt mij niets misdreven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-loze-vissertje', 5, 1, 'Gij hebt mij niets misdaan, ja daan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-loze-vissertje', 5, 2, 'Maar moet mij driemaal zoenen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-loze-vissertje', 5, 3, 'Eer gij van hier moogt gaan. Ja gaan.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-loze-vissertje', 6, 'chorus-ref', 1, 'waarbij ‘zijnen’ door ‘uwen’ vervangen wordt.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('het-luiaardsgild', 'HET LUIAARDSGILD', 'LUIAARDSGILD, HET', 'nederlandstalige-liederen', 'nl', NULL, 188, 189, NULL, NULL, 'Traditional, op de wijze van Kadril');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-luiaardsgild', 0, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 0, 0, 'Ik ben van het luiaardsgild');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 0, 1, 'En van de bedelklerken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 0, 2, 'Die liever spelen en drinken gaan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 0, 3, 'Dan dat ze zouden werken');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-luiaardsgild', 1, 'direction', 1, 'Het refrein wordt om de twee strofen herhaald.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-luiaardsgild', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 2, 0, 'Eten en drinken is mijn motief');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 2, 1, 'Vrij en vrolijk te leven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 2, 2, 'Soms vind ik mij er een zoete lief');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 2, 3, 'Om haar weer alles te geven');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-luiaardsgild', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 3, 0, 'Mijn geld verteerd, het doet me pijn');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 3, 1, 'Het doet mijn vreugd verdrogen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 3, 2, 'Ik zou zo geren vrolijk zijn');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 3, 3, 'Mijn beurs is leeggelopen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-luiaardsgild', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 4, 0, 'Wanneer ik in de kroegen kom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 4, 1, 'En daar lang heb gezeten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 4, 2, 'Dan maak ik mij langs achter weg');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 4, 3, 'Betalen ben ik vergeten');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-luiaardsgild', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 5, 0, 'Nacht na nacht op zwier geweest');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 5, 1, 'Waar is de tijd gevaren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 5, 2, 'De vrouw bij wie ik het heb geleerd');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 5, 3, 'Die moet ik nu betalen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-luiaardsgild', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 6, 0, 'Sparen ligt niet in mijnen aard');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 6, 1, 'Want geld is om uit te geven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 6, 2, 'Heb ik in mijn leven niets vergaard');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 6, 3, 'Het blijft mij om het even');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-luiaardsgild', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 7, 0, 'Ik ben verdwenen in de nacht');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 7, 1, '’t Was in de vroege uren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 7, 2, 'En ’k denk nog dikwijls terwijl ik lach');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-luiaardsgild', 7, 3, 'Aan wilde avonturen');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('me-moeder-kocht-nen-hering', 'ME MOEDER KOCHT NEN HERING', 'ME MOEDER KOCHT NEN HERING', 'nederlandstalige-liederen', 'nl', NULL, 190, 190, NULL, NULL, 'Opgetekend door Edmond De Coussemaker, Chants populaires des Flamands de France, 1856');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('me-moeder-kocht-nen-hering', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('me-moeder-kocht-nen-hering', 0, 0, 'Me moeder, me moeder die kocht nen hèring,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('me-moeder-kocht-nen-hering', 0, 1, 'Oemba, oemba, tralalalala,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('me-moeder-kocht-nen-hering', 0, 2, 'Me moeder, me moeder die kocht nen hèring,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('me-moeder-kocht-nen-hering', 0, 3, '’t Was nen hèring zonder kop');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('me-moeder-kocht-nen-hering', 0, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('me-moeder-kocht-nen-hering', 1, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('me-moeder-kocht-nen-hering', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('me-moeder-kocht-nen-hering', 2, 0, 'Ze lee ’m, ze lee ’m voor de venster,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('me-moeder-kocht-nen-hering', 2, 1, 'Maar ’t was niemand die ’m kocht.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('me-moeder-kocht-nen-hering', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('me-moeder-kocht-nen-hering', 3, 0, 'D’r kwamen, d’r kwamen twee agenten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('me-moeder-kocht-nen-hering', 3, 1, 'En die namen den hèring mee.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('me-moeder-kocht-nen-hering', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('me-moeder-kocht-nen-hering', 4, 0, 'Me moeder, me moeder begost te blèten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('me-moeder-kocht-nen-hering', 4, 1, 'En den hèring blète mee.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('merlijn-de-grote-vogelaar', 'MERLIJN DE GROTE VOGELAAR', 'MERLIJN DE GROTE VOGELAAR', 'nederlandstalige-liederen', 'nl', NULL, 191, 192, NULL, '‘De Vogel’, Tim Visterin', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('merlijn-de-grote-vogelaar', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 0, 0, 'Merlijn de grote vogelaar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 0, 1, 'Zag op een dag langs de boulevard');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 0, 2, 'Een dikke hoer: zeer behaard,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 0, 3, 'Een bierbuik en weerspannig haar.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 0, 4, 'Merlijn zei: “Hoerke, kom eens hier.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 0, 5, 'Met wat doe ik je nou plezier?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 0, 6, 'Je moet het overwegen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 0, 7, 'Ik kan je al mijn sperma geven.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('merlijn-de-grote-vogelaar', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 1, 0, 'Maar die hoer zei onbevreesd:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 1, 1, '“Mijnheer, mijnheer, ach, mijnheer!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 1, 2, 'Ach, mijnheer, een mooie hoer dat wil ik zijn.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 1, 3, 'Met sterke borsten, asjeblieft, mijnheer Merlijn.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 1, 4, 'Een mooie hoer in bed,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 1, 5, 'Met tepels, billen en een tet.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 1, 6, 'En uw kloten in mijn foef.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('merlijn-de-grote-vogelaar', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 2, 0, '“Ach mijnheer, een mooie hoer dat wil ik zijn.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 2, 1, 'Geef mij uw sperma, asjeblieft, mijnheer Merlijn.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 2, 2, 'Dan wil ik poepen dagenlang,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 2, 3, 'Uw fluit afspelen met mijn hand');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 2, 4, 'En het sperma vangen met mijn mond.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 2, 5, 'Ach, mijnheer, een mooie hoer dat wil ik zijn.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('merlijn-de-grote-vogelaar', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 3, 0, 'En toen gingen ze samen naar bed.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 3, 1, 'Een mooie hoer met zeer veel pret.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 3, 2, 'U zeggen dat ze heeft gepoept,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 3, 3, 'Het sperma uit zijn kloten sloeg,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 3, 4, 'Heeft dat belang?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 3, 5, 'Al wat ze deed:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 3, 6, 'Ze had plezier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 3, 7, 'Als een mooi dier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('merlijn-de-grote-vogelaar', 3, 8, 'Ergens ver van hier.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('merlijn-de-grote-vogelaar', 3, 5, 5, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('merlijn-de-grote-vogelaar', 3, 6, 6, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('mie-de-appeltrut', 'MIE DE APPELTRUT', 'MIE DE APPELTRUT', 'nederlandstalige-liederen', 'nl', NULL, 192, 192, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('mie-de-appeltrut', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mie-de-appeltrut', 0, 0, 'Mie de appeltrut');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mie-de-appeltrut', 0, 1, 'Heeft ze eens uitgeschud.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mie-de-appeltrut', 0, 2, 'Ze heeft een puist op haar arm');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mie-de-appeltrut', 0, 3, 'En een koperen kut.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mie-de-appeltrut', 0, 4, 'Kom eens hier, ik zal u naaien');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mie-de-appeltrut', 0, 5, 'Dat uw oogskens d’r van draaien');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mie-de-appeltrut', 0, 6, 'En de schijn van de maan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mie-de-appeltrut', 0, 7, 'Op uw gat zal staan.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('mie-de-appeltrut', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mie-de-appeltrut', 1, 0, 'Jan de appelfluit,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mie-de-appeltrut', 1, 1, 'Heeft ze eens uitgebuit.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mie-de-appeltrut', 1, 2, 'Hij heeft een puist op zijn arm');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mie-de-appeltrut', 1, 3, 'En een koperen fluit.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mie-de-appeltrut', 1, 4, 'Kom eens hier, ik zal u poepen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mie-de-appeltrut', 1, 5, 'Dat uw oogskens er van druppen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mie-de-appeltrut', 1, 6, 'En de schijn van de maan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('mie-de-appeltrut', 1, 7, 'Op uwen hol zal staan.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('de-moorsoldaten', 'DE MOORSOLDATEN', 'MOORSOLDATEN, DE', 'nederlandstalige-liederen', 'nl', NULL, 193, 193, 'Johann Esser, Wolfgang Langhoff', 'Rudi Goguel', 'Uit het concentratiekamp Papenburg te Börgermoor, 1933
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-moorsoldaten', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-moorsoldaten', 0, 0, 'Waarheen wij ook mogen kijken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-moorsoldaten', 0, 1, 'Zien wij veen en hei rondom,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-moorsoldaten', 0, 2, 'Vogelzang kan ons niet verblijden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-moorsoldaten', 0, 3, 'Bomen staan er kaal en stom.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-moorsoldaten', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-moorsoldaten', 1, 0, 'Wij zijn de moorsoldaten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-moorsoldaten', 1, 1, 'En zwoegen heelder dagen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-moorsoldaten', 1, 2, 'In ’t veen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-moorsoldaten', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-moorsoldaten', 2, 0, 'Heen en weer zo gaan de posten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-moorsoldaten', 2, 1, 'Niemand kan er langs voorbij!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-moorsoldaten', 2, 2, 'Vluchten zou ons het leven kosten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-moorsoldaten', 2, 3, 'Prikkeldraad, vier op een rij.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-moorsoldaten', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-moorsoldaten', 3, 0, 'Toch zal voor ons ook het uur gaan komen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-moorsoldaten', 3, 1, '’t Kan niet eeuwig winter zijn!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-moorsoldaten', 3, 2, 'Dan roepen en zingen w’ in alle tonen:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-moorsoldaten', 3, 3, '“Land van mij, gij zijt weer vrij.”');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('naar-oostland', 'NAAR OOSTLAND', 'NAAR OOSTLAND', 'nederlandstalige-liederen', 'nl', NULL, 194, 194, NULL, NULL, 'Oud brabants volkslied
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('naar-oostland', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('naar-oostland', 0, 0, 'Naar Oostland willen wij rijden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('naar-oostland', 0, 1, 'Naar Oostland willen wij mee,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('naar-oostland', 0, 2, 'Al over die groene heiden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('naar-oostland', 0, 3, 'Fris over die heiden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('naar-oostland', 0, 4, 'Daar is er een betere stee.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('naar-oostland', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('naar-oostland', 1, 0, 'Als wij binnen Oostland komen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('naar-oostland', 1, 1, 'Al onder dat hoge huis fijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('naar-oostland', 1, 2, 'Daar worden wij binnen gelaten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('naar-oostland', 1, 3, 'Fris over die heiden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('naar-oostland', 1, 4, 'Zij heten ons willekom zijn.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('naar-oostland', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('naar-oostland', 2, 0, 'Ja, willekom moeten wij wezen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('naar-oostland', 2, 1, 'Zeer willekom moeten wij zijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('naar-oostland', 2, 2, 'Daar zullen wij avond en morgen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('naar-oostland', 2, 3, 'Fris over die heiden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('naar-oostland', 2, 4, 'Nog drinken den koelen wijn.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('naar-oostland', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('naar-oostland', 3, 0, 'Wij drinken den wijn er uit schalen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('naar-oostland', 3, 1, 'En ’t bier ook zo veel ons belieft;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('naar-oostland', 3, 2, 'Daar is het zo vrolijk te leven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('naar-oostland', 3, 3, 'Fris over die heiden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('naar-oostland', 3, 4, 'Daar woont mijn zoete lief.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('niemand-verslaat-de-saint-v', 'NIEMAND VERSLAAT DE SAINT-V', 'NIEMAND VERSLAAT DE SAINT-V', 'nederlandstalige-liederen', 'nl', NULL, 195, 196, 'Nicolas D’Hondt, Adam Brooking', '‘Piano Man’, Billy Joel', 'PK, 30e Vrijzinnig Zangfeest van Vlaanderen, reactie op de afschaffing van de St V stoet na de aanslagen in Parijs van 13 november 2015. Prijs van de Vrijzinnigheid.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('niemand-verslaat-de-saint-v', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 0, 0, 'Ons Laura was altijd een braaf student');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 0, 1, 'Zij blokte, zij feestte niet mee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 0, 2, 'Haar ouders bewaakten haar dag en nacht');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 0, 3, 'Toen kwam ze naar de VUB');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 0, 4, 'Ze liet zich dan dopen ’s nachts in de tent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 0, 5, 'Z’was blauw, het zat haar niet mee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 0, 6, 'Haar ma, niet content, vond het decadent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 0, 7, 'Maar Laura gaat wel naar Saint-V');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('niemand-verslaat-de-saint-v', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 1, 0, 'Lalala ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 1, 1, 'Want de Saint-V is van iedereen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 1, 2, 'Een glas, een kus, goed gevoel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 1, 3, 'Het lijkt misschien soms op een zottenfeest');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 1, 4, 'Maar ’t heeft wel ook zeker een doel');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('niemand-verslaat-de-saint-v', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 2, 0, 'De Jos is moe en gepensioneerd');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 2, 1, 'Kapot, gebogen en oud');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 2, 2, 'Maar één keer per jaar, grijpt hij weer naar haar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 2, 3, 'Die klak waar hij zo veel van houdt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 2, 4, 'Hij was jaren t’rug praeses van zijn kring');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 2, 5, 'Nu moet hij met ’t vrouwtje mee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 2, 6, 'Vandaag echter niet, Josiane weet het ook');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 2, 7, 'Vandaag gaat hij naar de Saint-V');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('niemand-verslaat-de-saint-v', 3, 'chorus-ref', 1, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('niemand-verslaat-de-saint-v', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 4, 0, 'Descendant du Sablon les chars ULB');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 4, 1, 'Si lents, si bien décorés');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 4, 2, 'Se suivant tous au pied d’égalité');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 4, 3, 'Guindaill’nt avec la VUB');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 4, 4, 'Un jeune comitard bien habitué');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 4, 5, 'Sa toge, tout’ déchirée');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 4, 6, 'Fait découvrir à ses sales bleus pénés');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 4, 7, 'Le folklore autour d’la Saint-V');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('niemand-verslaat-de-saint-v', 5, 'chorus-ref', 1, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('niemand-verslaat-de-saint-v', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 6, 0, 'Terreur, politiek, er is veel kritiek');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 6, 1, 'De media doet ook wel mee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 6, 2, 'Klaag gerust voort, ’t is niemand die ’t hoort');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 6, 3, 'Want iedereen is op Saint-V');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 6, 4, 'En als we daar op de zavel staan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 6, 5, 'We zijn jong, oud, pees en vree');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 6, 6, 'Dan weet je het wel, ’t vergaat niet zo snel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('niemand-verslaat-de-saint-v', 6, 7, 'Want niemand verslaat de Saint-V');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('niemand-verslaat-de-saint-v', 6, 7, 7, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('nooit-met-krijt', 'NOOIT MET KRIJT', 'NOOIT MET KRIJT', 'nederlandstalige-liederen', 'nl', NULL, 197, 197, NULL, NULL, 'Kadril');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('nooit-met-krijt', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 0, 0, 'Beste vriend ik moet je vragen:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 0, 1, '“Hou maar vlug je mond!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 0, 2, 'Want ik moet het maar verdragen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 0, 3, 'Dat jij kust haar mond');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 0, 4, '’t Zijn dezelfde mooie haren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 0, 5, 'Die ik heb bemind');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 0, 6, '’t Was dezelfde mooie lach');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 0, 7, 'Van hetzelfde kind');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('nooit-met-krijt', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 1, 0, 'Ja, ik hoor mezelf nog zeggen:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 1, 1, '“Kijk eens naar die kont!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 1, 2, 'En je stem daarna weerleggen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 1, 3, '“’k Hou alleen van blond”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 1, 4, 'Nee je wou die kleur van haren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 1, 5, 'Liever niet in bed');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 1, 6, 'Maar wat later geen bezwaren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 1, 7, '’t Was maar voor de pret');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('nooit-met-krijt', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 2, 0, 'Beste vriend je stal mijn dromen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 2, 1, 'Van zo’n lange tijd');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 2, 2, 'Nee je hoeft niet meer te komen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 2, 3, 'Met je valse spijt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 2, 4, 'En vergeet wanneer de dag komt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 2, 5, 'Dat de kleur verslijt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 2, 6, 'Met een spons al op mijn deur bonkt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-met-krijt', 2, 7, 'Ik schreef nooit met krijt');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('nooit-met-krijt', 2, 4, 7, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('nooit-sterft-het-studentenras', 'NOOIT STERFT HET STUDENTENRAS', 'NOOIT STERFT HET STUDENTENRAS', 'nederlandstalige-liederen', 'nl', NULL, 198, 198, NULL, '‘Auld lang syne’', 'Orde van het Laurier, Nicolas Joschko, 1981
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('nooit-sterft-het-studentenras', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-sterft-het-studentenras', 0, 0, 'Wij zijn hier als student bijeen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-sterft-het-studentenras', 0, 1, 'Met Verhaegen hoog in ’t hart,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-sterft-het-studentenras', 0, 2, 'Ons vriendschap is zoals geeneen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-sterft-het-studentenras', 0, 3, 'Als geuzen steeds vermaard,');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('nooit-sterft-het-studentenras', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-sterft-het-studentenras', 1, 0, 'In voorspoed steeds bijeen mijn vriend,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-sterft-het-studentenras', 1, 1, 'In tegenspoed getrouw!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-sterft-het-studentenras', 1, 2, 'Sta recht, mijn vriend en klinkt het glas;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-sterft-het-studentenras', 1, 3, 'Nooit sterft ’t studentenras!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('nooit-sterft-het-studentenras', 2, 'direction', 1, 'De melodie wordt verder geneuried terwijl de glazen geklonken worden');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('nooit-sterft-het-studentenras', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-sterft-het-studentenras', 3, 0, 'Sta recht, mijn vriend en klinkt het glas;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nooit-sterft-het-studentenras', 3, 1, 'Nooit sterft ’t studentenras!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('o-nederland-let-op-uw-zaak', 'O NEDERLAND! LET OP UW ZAAK', 'O NEDERLAND! LET OP UW ZAAK', 'nederlandstalige-liederen', 'nl', NULL, 199, 199, NULL, NULL, 'Adriaen Valerius, uit ‘Nederlantsche Gedenck-klanck’, 1625
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('o-nederland-let-op-uw-zaak', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 0, 0, 'O Nederland! let op u saeck,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 0, 1, 'De tyt en stont is daer,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 0, 2, 'Op dat nu inden hoeck niet raeck,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 0, 3, 'U vryheyt, die voorwaer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 0, 4, 'U ouders hebben dier gecocht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 0, 5, 'Met goet en bloet en leven:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 0, 6, 'Want sy werd nu gantsch en t’eenemael gesocht');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 0, 7, 'Tot niet te zyn verdreven.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('o-nederland-let-op-uw-zaak', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 1, 0, 'Neemt acht op uwer Landen staet.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 1, 1, 'U volck end’ steden meest');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 1, 2, 'Syn sterck, end’ daer is raet en daet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 1, 3, 'Van outs altyt geweest.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 1, 4, 'U adel is manhaftich vroom,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 1, 5, 'Men vind niet haers gelijcken;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 1, 6, 'Houd den Spanjaert doch, ick bid u, inden thoom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 1, 7, 'Dat hy van ons mach wycken.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('o-nederland-let-op-uw-zaak', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 2, 0, 'Beschut, beschermt, bewaerd u land,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 2, 1, 'Let op het Spaensch bedrog,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 2, 2, 'Ey laet niet nemen uyt u hant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 2, 3, 'U Previlegien toch:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 2, 4, 'Maer thoont u elck een man vol moet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 2, 5, 'In’t houden van u wetten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 2, 6, 'Boven al dient Geus, en valt hem steets te voet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-nederland-let-op-uw-zaak', 2, 7, 'Dat hy op u mach letten.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('omdat-ik-vlaming-ben', 'OMDAT IK VLAMING BEN', 'OMDAT IK VLAMING BEN', 'nederlandstalige-liederen', 'nl', NULL, 200, 200, 'Lambrecht Lambrechts', 'Maria Matthyssens', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('omdat-ik-vlaming-ben', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('omdat-ik-vlaming-ben', 0, 0, 'Waarom (TER) ik voor geen vreemden buig,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('omdat-ik-vlaming-ben', 0, 1, 'Waarom ik met van Maerlant juich,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('omdat-ik-vlaming-ben', 0, 2, 'Zijn leuze voor de mijne erken?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('omdat-ik-vlaming-ben', 0, 3, 'Omdat ik Vlaming ben!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('omdat-ik-vlaming-ben', 0, 2, 2, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('omdat-ik-vlaming-ben', 0, 3, 3, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('omdat-ik-vlaming-ben', 1, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('omdat-ik-vlaming-ben', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('omdat-ik-vlaming-ben', 2, 0, 'Waarom ik bij mijn stillen haard');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('omdat-ik-vlaming-ben', 2, 1, 'De taal der vaad’ren heb bewaard,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('omdat-ik-vlaming-ben', 2, 2, 'En aan geen and’ren toon gewen?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('omdat-ik-vlaming-ben', 2, 3, 'Omdat ik Vlaming ben!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('omdat-ik-vlaming-ben', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('omdat-ik-vlaming-ben', 3, 0, 'Waarom ik aan mijn kinderen leer:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('omdat-ik-vlaming-ben', 3, 1, 'Maakt Vlaand’ren groot gelijk weleer!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('omdat-ik-vlaming-ben', 3, 2, 'Waarom ik, hopend, juich met hen?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('omdat-ik-vlaming-ben', 3, 3, 'Omdat ik Vlaming ben!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('omdat-ik-vlaming-ben', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('omdat-ik-vlaming-ben', 4, 0, 'Waarom ik ’t goede Vlaamse diet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('omdat-ik-vlaming-ben', 4, 1, 'Mijn hart blijft schenken en mijn lied');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('omdat-ik-vlaming-ben', 4, 2, 'Mijn adem en mijn wakk’re pen?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('omdat-ik-vlaming-ben', 4, 3, 'Omdat ik Vlaming ben!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('op-de-purp-ren-hei', 'OP DE PURP’REN HEI', 'OP DE PURP’REN HEI', 'nederlandstalige-liederen', 'nl', NULL, 201, 201, 'Eugeen de Ridder', 'Armand Preud’homme', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('op-de-purp-ren-hei', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('op-de-purp-ren-hei', 0, 0, 'In de stille Kempen, op de purp’ren hei,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('op-de-purp-ren-hei', 0, 1, 'Staat een eenzaam huisje, met een berk erbij,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('op-de-purp-ren-hei', 0, 2, 'En een zomeravond, in gedroom alleen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('op-de-purp-ren-hei', 0, 3, 'Kwam ik ongeweten langs dat huisje heen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('op-de-purp-ren-hei', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('op-de-purp-ren-hei', 1, 0, 'Hoe schoon op de wereld de zomerse hei,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('op-de-purp-ren-hei', 1, 1, 'Dat is hier op aarde de hemel voor mij!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('op-de-purp-ren-hei', 1, 0, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('op-de-purp-ren-hei', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('op-de-purp-ren-hei', 2, 0, 'In het eenzaam huisje, zat een meisje ach!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('op-de-purp-ren-hei', 2, 1, 'Lijk ik nergens anders ooit een meisje zag!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('op-de-purp-ren-hei', 2, 2, 'Door het venster keek ze mij verlegen aan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('op-de-purp-ren-hei', 2, 3, 'Schoof ’t gordijntje toe en is maar opgestaan.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('op-de-purp-ren-hei', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('op-de-purp-ren-hei', 3, 0, 'Maar wat heeft de liefde, ook hier niet verricht!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('op-de-purp-ren-hei', 3, 1, 'Want nu schuift ’t gordijntje nooit nog voor me dicht!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('op-de-purp-ren-hei', 3, 2, 'Door het open venster, dat men vroeger sloot,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('op-de-purp-ren-hei', 3, 3, 'Lach ik op ons kindje op zijn moeders schoot.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('oud-tafellied', 'OUD TAFELLIED', 'OUD TAFELLIED', 'nederlandstalige-liederen', 'nl', NULL, 201, 202, 'X. Janssens', '‘Ça ça geschmauset’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oud-tafellied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oud-tafellied', 0, 0, 'Nu aan het smullen!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oud-tafellied', 0, 1, 'Werp ’t kommervolle masker af');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oud-tafellied', 0, 2, 'En drinkt de gulle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oud-tafellied', 0, 3, 'Wijn tot aan ’t graf.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oud-tafellied', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oud-tafellied', 1, 0, 'Edite, bibite, collegiales!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oud-tafellied', 1, 1, 'Post multa saecula! Pocula nulla!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('oud-tafellied', 1, 1, 1, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oud-tafellied', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oud-tafellied', 2, 0, 'Geen “koers” in d’hallen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oud-tafellied', 2, 1, 'De prof heeft in de kele zeer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oud-tafellied', 2, 2, 'We drinken allen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oud-tafellied', 2, 3, 'Te zijner eer.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oud-tafellied', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oud-tafellied', 3, 0, 'Jubelt als zotten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oud-tafellied', 3, 1, 'Broers, binst uw jonkheid zoet en schoon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oud-tafellied', 3, 2, 'En plukt maar botten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oud-tafellied', 3, 3, 'Voor Bacchus’ kroon.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oud-tafellied', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oud-tafellied', 4, 0, 'Op vette akkers');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oud-tafellied', 4, 1, 'Schieten de botten weelderig uit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oud-tafellied', 4, 2, 'Toch is ’t de zonne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oud-tafellied', 4, 3, 'Die hen ontsluit.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oud-tafellied', 5, 'direction', 1, 'koers = les (cfr. cours in ’t Frans)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ouwe-zakken', 'OUWE ZAKKEN', 'OUWE ZAKKEN', 'nederlandstalige-liederen', 'nl', NULL, 202, 204, 'Maja Marcucci', '‘Breek de stilte’, Stef Bos en Bob Savenberg', '’t VAT, 19e Vrijzinnig Zangfeest van Vlaanderen, 2004');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ouwe-zakken', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 0, 0, 'Hij is gedoopt maar zou niet weten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 0, 1, 'Bij welke club, hij is’t vergeten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 0, 2, 'En de schimmel op zijn klak verbergt de kleur.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 0, 3, 'Zijn ouwe toga is versleten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 0, 4, 'Door de motten aangevreten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 0, 5, 'En alles wat blijft hangen is de geur.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ouwe-zakken', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 1, 0, 'Hij wil nog graag zijn mening geven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 1, 1, 'Zijn visie op’t studentenleven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 1, 2, 'Maar er is niemand die hem ooit nog om iets vraagt.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 1, 3, 'Of hij nu roept of tiert of fluistert,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 1, 4, 'Er is geen kat die naar hem luistert,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 1, 5, 'Want ze vinden allemaal dat hij zaagt.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ouwe-zakken', 2, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 2, 0, 'Ouwe zakken, ouwe zakken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 2, 1, 'Stel vandaag een goede daad,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 2, 2, 'Vraag een ouwe zak om raad.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ouwe-zakken', 2, 0, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ouwe-zakken', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 3, 0, 'Zijn codex plakt van klash en pinten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 3, 1, 'En hij bezwijkt onder zijn linten.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 3, 2, 'Elke kaloot die hij ontmoette heeft ’t berouwd.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 3, 3, 'Hij is vrij man in hart en nieren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 3, 4, 'Maar om zijn ouders te plezieren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 3, 5, 'Is hij lang geleden voor de kerk getrouwd.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ouwe-zakken', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 4, 0, 'Een monument van de folklore,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 4, 1, 'Maar zijn ervaring gaat verloren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 4, 2, 'Want als hij spreekt, slaat ied’reen op de vlucht.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 4, 3, 'Als hij komt kijken naar de dopen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 4, 4, 'Dan gaan de schachten van hem lopen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 4, 5, 'Al doet dat pijn, hij komt altijd terug.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ouwe-zakken', 5, 'chorus-ref', 1, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ouwe-zakken', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 6, 0, 'Dus geef ze aandacht, laat ze spreken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 6, 1, 'Doe of je luistert naar hun preken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 6, 2, 'En maak een ouwe zak gelukkig en voldaan.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 6, 3, 'Want ook al wil je het niet horen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 6, 4, 'Knoop één ding in je oren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 6, 5, 'Ook voor jou komt ’t ouwe-zakkenschap er aan.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ouwe-zakken', 7, 'chorus-ref', 1, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ouwe-zakken', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 8, 0, 'Ze zijn in oorlog met het heden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 8, 1, 'Maar hou ze aan de praat.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 8, 2, 'Ja, want baat het niet, dan schaadt het niet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ouwe-zakken', 8, 3, 'Vraag een ouwe zak om raad!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ouwe-zakken', 9, 'chorus-ref', 1, NULL);
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('pieter-breughel-in-brussel', 'PIETER BREUGHEL IN BRUSSEL', 'PIETER BREUGHEL IN BRUSSEL', 'nederlandstalige-liederen', 'nl', NULL, 205, 207, NULL, NULL, 'Wannes Van De Velde');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('pieter-breughel-in-brussel', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 0, 0, 'Pieter Breughel de Oude');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 0, 1, 'Zou opstaan uit de dood');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 0, 2, 'Om de wereld te aanschouwen:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 0, 3, 'Was ’t bloed er nog zo rood, als karmijn?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 0, 4, 'Zou er nog oorlog zijn?');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('pieter-breughel-in-brussel', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 1, 0, 'Al eerst ging hem naar Brussel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 1, 1, 'Naar zijnen atelier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 1, 2, 'En hij nam zijnen bussel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 1, 3, 'Penselen en wat houtskool mee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 1, 4, 'Naar zijn Brabantse stee.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('pieter-breughel-in-brussel', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 2, 0, 'Hij was nog niet vergeten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 2, 1, 'Waar dat zijn woonhuis was');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 2, 2, 'Het was wel wat versleten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 2, 3, 'De memel woonde in zijn kas');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 2, 4, 'Kapot was ’t vensterglas.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('pieter-breughel-in-brussel', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 3, 0, 'Eerst vroeg hem aan de mensen;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 3, 1, 'Is Spanje hier nog baas?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 3, 2, 'Leefde naar eigen wensen?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 3, 3, 'Zijn ze nog even dwaas in ons land?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 3, 4, 'Of kregen ze verstand?');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('pieter-breughel-in-brussel', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 4, 0, 'De mensen wouden Breughel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 4, 1, 'Zijn Brabants niet verstaan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 4, 2, 'Dus is hem stil en treurig');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 4, 3, 'Naar een café gegaan, die daar in');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 4, 4, 'Zijn jeugd al had gestaan.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('pieter-breughel-in-brussel', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 5, 0, 'Hij vroeg in ’t zuiver Brabants');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 5, 1, 'De kastelein om drank');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 5, 2, 'Maar de patron die zei: “Pardon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 5, 3, 'Je ne comprends pas Flamand” emmerdant,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 5, 4, 'Dans le cœur du Brabant!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('pieter-breughel-in-brussel', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 6, 0, 'Pieter Breughel den Ouwe');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 6, 1, 'Die dacht ’t is weer zover');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 6, 2, 'Da’ ze hier den Geuze nog brouwen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 6, 3, 'Da’s fijn maar dat ’t in ’t Frans moet zijn');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 6, 4, 'Da vin’k een groot sjagrijn.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('pieter-breughel-in-brussel', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 7, 0, 'Het Spaans is nu verdreven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 7, 1, 'Uit ons klein vaderland');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 7, 2, 'Maar nu hebben we gekregen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 7, 3, 'Het Frans aan de Marollenkant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 7, 4, 'Da’s boven mijn verstand.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('pieter-breughel-in-brussel', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 8, 0, 'Piet Breughel is dan droevig');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 8, 1, 'Terug naar zijn graf gegaan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 8, 2, 'Nadat hem op zijn kamer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 8, 3, 'Een heel klein maar een fijn schilderij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 8, 4, 'Vol kleur had doen ontstaan.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('pieter-breughel-in-brussel', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 9, 0, 'En daarop stond geschilderd');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 9, 1, 'Ne Vlaming in ’t gevang');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 9, 2, '’t Gevang van zijn kompleksen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 9, 3, 'De sleutel ligt erbij aan zijn zij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('pieter-breughel-in-brussel', 9, 4, 'Doet open, maakt hem vrij!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('pieter-breughel-in-brussel', 10, 'direction', 1, 'Tijdens het tweede Vrijzinnig Zangfeest van Vlaanderen in 1992 werd deze laatste strofe door Wannes Van De Velde zelf geactualiseerd:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('pieter-breughel-in-brussel', 11, 'direction', 1, 'En daarop stond geschilderd Ne Vlaming in den val De val van zijn kompleksen ’t Fanatisme staat erbij aan zijn zij Zo geraakt hem nooit nie vrij!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('reuzenlied', 'REUZENLIED', 'REUZENLIED', 'nederlandstalige-liederen', 'nl', NULL, 207, 207, NULL, NULL, 'Traditioneel Zuid-Nederlands');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('reuzenlied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reuzenlied', 0, 0, 'Al die daar zegt:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reuzenlied', 0, 1, '“De Reus die kom, de Reus die kom,”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reuzenlied', 0, 2, 'Zij liegen daarom.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('reuzenlied', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reuzenlied', 1, 0, 'Kere weerom, Reusken, Reusken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reuzenlied', 1, 1, 'Kere weerom, Reuzegom.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('reuzenlied', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reuzenlied', 2, 0, 'Sa, moeder, zet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reuzenlied', 2, 1, 'Den pot op’t vier, den pot op’t vier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reuzenlied', 2, 2, 'De Reus is hier.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('reuzenlied', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reuzenlied', 3, 0, 'Sa, moeder, snijd');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reuzenlied', 3, 1, 'Een boterham, een boterham');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reuzenlied', 3, 2, 'De Reus is gram.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('reuzenlied', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reuzenlied', 4, 0, 'Sa, moeder, tap');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reuzenlied', 4, 1, 'Van’t beste bier, van’t beste bier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reuzenlied', 4, 2, 'De Reus is gier.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('reuzenlied', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reuzenlied', 5, 0, 'Sa, moeder, stopt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reuzenlied', 5, 1, 'Nu maar het vat, nu maar het vat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reuzenlied', 5, 2, 'De Reus is zat.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('de-rolders-in-de-nacht', 'DE ROLDERS IN DE NACHT', 'ROLDERS IN DE NACHT, DE', 'nederlandstalige-liederen', 'nl', NULL, 208, 209, NULL, NULL, 'J. De Lepeleire, 1954');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-rolders-in-de-nacht', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 0, 0, 'Iedereen slaapt, het is rustig, het is nacht.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 0, 1, 'Een smalle straat, een lantaarn, ’t lijkt verdacht:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 0, 2, 'Geen pandoeren, slechts de stilte houdt de wacht');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 0, 3, 'Plots het brullen van de rolders in de nacht:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 0, 4, 'Ohohohohohoho ... Ohohohohohoho ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 0, 5, 'Want immer gaan de rolders op de zwier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 0, 6, 'Want zij blijven steeds maar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 0, 7, 'Dorsten naar het bier.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 0, 8, 'Ohohohohohoho ... Ohohohohohoho ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-rolders-in-de-nacht', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 1, 0, 'En gij zijt mijnen allerbeste vriend,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 1, 1, 'Zo nen chikken tip heb ekik nog niet gekind:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 1, 2, 'Doevei drinke w’oep aaf gezondheid nog een pint,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 1, 3, 'Want dat hedde nondedoeme dik verdiend!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 1, 4, 'Ohohohohohoho ... Ohohohohohohoho ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 1, 5, 'En wijle gon met ons getwee op de rol');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 1, 6, 'En ons pinten moeten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 1, 7, 'Op de slag terug vol!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 1, 8, 'Ohohohohohoho ... Ohohohohohohoho ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-rolders-in-de-nacht', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 2, 0, 'Bij Margot was er overlest bagaar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 2, 1, 'Daar was ambras en dat ambeteerde haar,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 2, 2, 'Ze werd koleirig en ze deed geweldig raar:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 2, 3, '’t Was terug zover want de pandoeren waren daar!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 2, 4, 'Ohohohohohoho ... Ohohohohohohoho ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 2, 5, 'En toen heeft Margot haar caféke toegedaan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 2, 6, 'En haar Vlaamse jongens zijn toen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 2, 7, 'Op een ander moeten gaan!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 2, 8, 'Ohohohohohoho ... Ohohohohohohoho ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-rolders-in-de-nacht', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 3, 0, 'Daar laveert nog een eenzaat door de stad,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 3, 1, 'Hij is bedronken, hij is bezopen, stapelzat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 3, 2, 'Zijn lijf zit vol alkohol en gerstenat ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 3, 3, 'En hij piert op de kasseien van de stad!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 3, 4, 'Ohohohohohoho ... Ohohohohohohoho ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 3, 5, 'En nu ligt hij daar te slapen in de straat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 3, 6, 'En niemand die heeft kompassie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 3, 7, '’t Is maar ne zatte kameraad');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-rolders-in-de-nacht', 3, 8, 'Ohohohohohoho ... Ohohohohohohoho ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-rolders-in-de-nacht', 4, 'direction', 1, 'Margot Weissgerber, baatte in de jaren ’70 de kroeg “Chez Margot - Au Student” uit op de hoek van de Lentestraat en de Kroonlaan. In de oorspronkelijke versie van het lied heeft men het over ‘Marraine’, de ‘Moeder’ der Vlaamse studenten, tot 1968 uitbaatster van een café op de Leuvense Oude Markt.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('t-ros-beyaard', '’T ROS BEYAARD', 'ROS BEYAARD, ’T', 'nederlandstalige-liederen', 'nl', NULL, 210, 211, 'K. Wijtsman, opgetekend door Florimond Van Duyse, 1868 M: Oud Volkswijsje uit Dendermonde, 12e eeuw', NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-ros-beyaard', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 0, 0, '’t Ros Beyaard doet zijn ronde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 0, 1, 'In de stad van Dendermonde:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 0, 2, 'Die van Aalst die zijn zo kwaad');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 0, 3, 'Omdat hier ’t Ros Beyaard gaat.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-ros-beyaard', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 1, 0, 'De vier Aymonskinderen jent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 1, 1, 'Met blanke zweerd in d’hand');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 1, 2, 'Ziet ze rijden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 1, 3, '’t Zijn de schoonste al van ons land!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-ros-beyaard', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 2, 0, '’t Ros Beyaard ogen fonk’len,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 2, 1, 'Zijne brede manen kronk’len,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 2, 2, 'En hij wendt hem fraai en vlug,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 2, 3, 'Met vier broers op zijnen rug.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-ros-beyaard', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 3, 0, 'Hun harnas schild en lansen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 3, 1, 'Blinken bij de zonneglansen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 3, 2, 'En den Beyaard ’t vooisken geeft,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 3, 3, 'Daar het ros zijn eer in heeft.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-ros-beyaard', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 4, 0, 'O Dendermondenaren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 4, 1, 'Blijft altijd den roem bewaren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 4, 2, 'Van het peerd zo wijd vermaard');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 4, 3, 'Als den grootsten man op aard.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-ros-beyaard', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 5, 0, '’t Ros Beyaard is ons glorie,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 5, 1, 'En benijdt g’ons die victorie,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 5, 2, 'Aalst, gij hebt nog min verstand');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 5, 3, 'Als ons ridderros vaillant.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-ros-beyaard', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 6, 0, '’t Ros Beyaard is verheven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 6, 1, 'Heeft hem in het vuur begeven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 6, 2, 'En het week op ’t oorlogsveld,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-ros-beyaard', 6, 3, 'Alles voor zijn groot geweld!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('rue-des-bouchers', 'RUE DES BOUCHERS', 'RUE DES BOUCHERS', 'nederlandstalige-liederen', 'nl', NULL, 211, 212, 'Jan De Baets, bewerkt door Johan Verminnen', 'Johan Verminnen', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('rue-des-bouchers', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 0, 0, 'As ge Brussel wilt zien leive');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 0, 1, 'Moede ni veul geld oeitgeive');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 0, 2, 'Do es ne cotei wo da ga ni moet geneire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 0, 3, 'Got door nen oevend passeire');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('rue-des-bouchers', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 1, 0, 'In de rue des Bouchers');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('rue-des-bouchers', 1, 0, 0, 4, '(QUATER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('rue-des-bouchers', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 2, 0, '’t Es de stroet van de studente');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 2, 1, 'Dei studere op d’agente');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 2, 2, 'En dei kadees dei komt van Wemmel en van Loeke');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 2, 3, 'Uile slechte reputoese moeke');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('rue-des-bouchers', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 3, 0, '’t Es de stroet par excellence');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 3, 1, 'Van d’artiste zonder cense');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 3, 2, 'Da komt zaupe, da komt poeffe');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 3, 3, 'Da komt drinke, da komt stoeffe');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('rue-des-bouchers', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 4, 0, 'Ge kunt do vanalles vinne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 4, 1, 'Russe, macreaux en sardinne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 4, 2, 'Fritten en moules parquées');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 4, 3, 'Da sloege dei Brusseleirs in uile gilé');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('rue-des-bouchers', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 5, 0, '’t Volk got doe van ’t ien in ’t ander');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 5, 1, 'Van hee trekt da dis oep een ander');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 5, 2, 'En ze komme mè een giel kudde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 5, 3, 'De mense uile zak oeitschudde');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('rue-des-bouchers', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 6, 0, 'Do we’d getapt en do we’d gezaupe');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 6, 1, 'Da blaift do tot smerges aupe');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 6, 2, 'En as ze do de dui toodroie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rue-des-bouchers', 6, 3, 'Den es den oen al on ’t kroie');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ruiterslied', 'RUITERSLIED', 'RUITERSLIED', 'nederlandstalige-liederen', 'nl', NULL, 213, 214, 'Georg Herwegh, Burschenschaft Patrioten Tübingen, 1841 M: Justus Wilhelm Lyra, Burschenschaft Knorschia Bonn, 1843', NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ruiterslied', 0, 'direction', 1, 'Dit lied wordt door de laatstejaars gezongen. Voor ze beginnen worden de glazen gevuld.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ruiterslied', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 1, 0, 'De bange nacht is weeral om,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 1, 1, 'We rijden stil, we rijden stom,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 1, 2, 'We rijden ten verderve!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 1, 3, 'Hoe koud waait toch de morgenwind!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 1, 4, 'Weerdin, nu nog een glas gezwind');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 1, 5, 'Voor ’t sterven.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ruiterslied', 1, 5, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ruiterslied', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 2, 0, 'Hoe staat het jonge gras nu groen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 2, 1, 'Maar bloeden zal het morgen doen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 2, 2, 'Mijn eigen bloed zal ’t verven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 2, 3, 'De eerste slok, met ’t zweerd in hand,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 2, 4, 'Gedronken voor het vaderland');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 2, 5, 'Voor ’t sterven.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ruiterslied', 2, 5, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ruiterslied', 3, 'direction', 1, 'Hier wordt een eerste slok gedronken');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ruiterslied', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 4, 0, 'De tweede slok van d’edele wijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 4, 1, 'Zal voor de heilige vrijheid zijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 4, 2, 'Voor vrijheid, have en erve;');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ruiterslied', 5, 'direction', 1, 'Hier wordt de tweede slok gedronken');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ruiterslied', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 6, 0, 'De rest zij nog een huldeblijk,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 6, 1, 'De laatst aan ’t oud Romeinse rijk');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 6, 2, 'Voor ’t sterven.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ruiterslied', 6, 2, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ruiterslied', 7, 'direction', 1, 'Hier wordt het glas geledigd');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ruiterslied', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 8, 0, 'Voor ’t liefken, maar mijn glas is uit,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 8, 1, 'De spere blinkt, de kogel fluit,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 8, 2, 'Draag aan mijn kind de scherven,');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ruiterslied', 9, 'direction', 1, 'Hier wordt het glas kapotgegooid');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ruiterslied', 10, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 10, 0, 'Vooruit nu naar de laatste slag.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 10, 1, 'O, ruiterslust in vroege dag.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ruiterslied', 10, 2, 'En sterven.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ruiterslied', 10, 2, 2, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 'SCHOON LIEF, HOE LIGT GY HIER EN SLAEPT', 'SCHOON LIEF, HOE LIGT GY HIER EN SLAEPT', 'nederlandstalige-liederen', 'nl', NULL, 214, 215, NULL, NULL, 'Brabants Meilied, rond 1610');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 0, 0, 'Schoon lief, hoe ligt gy hier en slaept');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 0, 1, 'In uwen eersten drome?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 0, 2, 'Wilt opstaen en den mei ontfaen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 0, 3, 'Hy staet hier al zoo schoone.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 1, 0, '’k En zou voor geenen mei opstaen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 1, 1, 'Myn vensterken niet ontsluiten:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 1, 2, 'Plant uwen mei waer ’t u gerei');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 1, 3, 'Plant uwen mei daer buiten!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 2, 0, 'Waer zou ’k hem planten of waer doen?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 2, 1, '’t Is al op ’s heeren strate;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 2, 2, 'De winternacht is koud en lang,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 2, 3, 'Hy zou zyn bloeyene laten.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 3, 0, 'Schoon lief, laet hy zyn bloeyen staen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 3, 1, 'Wy zullen hem begraven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 3, 2, 'Op ’t kerkhof by den eglantier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 3, 3, 'Zyn graf zal roozekens dragen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 4, 0, 'Schoon lief, en om die roozekens');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 4, 1, 'Zal ’t nachtegaelken springen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 4, 2, 'En voor ons bei in elken mei');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lief-hoe-ligt-gy-hier-en-slaept', 4, 3, 'Zyn zoete liedekens zingen.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('schoon-lieveken-waar-waarde-gij', 'SCHOON LIEVEKEN WAAR WAARDE GIJ', 'SCHOON LIEVEKEN WAAR WAARDE GIJ', 'nederlandstalige-liederen', 'nl', NULL, 216, 216, NULL, NULL, 'Pol de Mont, Brabants Meilied
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('schoon-lieveken-waar-waarde-gij', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 0, 0, '“Schoon lieveken waar waarde gij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 0, 1, 'Den eerste meienacht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 0, 2, 'Dat gij mij gene meie bracht?”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 0, 3, '“Den eerste meienacht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 0, 4, 'Schoon lief dan was ik ziek!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 0, 5, 'Schoon lieveke, dan kon ik uit mijn beddeke niet.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('schoon-lieveken-waar-waarde-gij', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 1, 0, '“Schoon lieveken waar waarde gij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 1, 1, 'Den tweede meienacht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 1, 2, 'Dat gij mij gene meie bracht?”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 1, 3, '“Den tweede meienacht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 1, 4, 'Zocht ik een eglantier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 1, 5, 'Schoon lieveke, staat op en uwe mei is hier.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('schoon-lieveken-waar-waarde-gij', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 2, 0, '“’k En sta der voorwaar,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 2, 1, 'Voor uwe schone mei niet op,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 2, 2, 'Nog en zal er mijn venster niet ontsluiten!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 2, 3, 'Uwe mei die komt te laat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 2, 4, 'Plant vrij hem op de straat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 2, 5, 'Schoon lieveke, plant uwen mei daar buiten.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('schoon-lieveken-waar-waarde-gij', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 3, 0, '“En als ik mijnen mei');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 3, 1, 'Hier buiten planten zal,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 3, 2, 'En zal het u dan niet verdrieten?”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 3, 3, '“Neen! Zijt dan maar verblijd!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 3, 4, 'Met den lieven meientijd,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schoon-lieveken-waar-waarde-gij', 3, 5, 'Met den mei zal hij wederom schieten.”');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('slaat-op-den-trommele', 'SLAAT OP DEN TROMMELE', 'SLAAT OP DEN TROMMELE', 'nederlandstalige-liederen', 'nl', NULL, 217, 217, 'Arent Dircksz Vos, 1566, uit het “Nieu Geusen Liet-boeck” uit 1581. Er zou nog een ouder Geuzenliedboek bestaan (1574), maar daarvan is tot op heden geen enkel exemplaar teruggevonden. De schrijver werd in 1570 in ’s Gravenhage verbrand onder beschuldiging van beeldenstormerij, de gereformeerde godsdienst te propageren en het bezitten van een oproerig refrein of rondeel, waarschijnlijk dit lied.', NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('slaat-op-den-trommele', 0, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('slaat-op-den-trommele', 0, 0, 'Slaat op den trommele van dirredomdeine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('slaat-op-den-trommele', 0, 1, 'Slaat op den trommele van dirredomdoes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('slaat-op-den-trommele', 0, 2, 'Slaat op den trommele van dirredomdeine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('slaat-op-den-trommele', 0, 3, 'Vive le Geus is nu de loes!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('slaat-op-den-trommele', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('slaat-op-den-trommele', 1, 0, 'De inquisitie godverge en schande,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('slaat-op-den-trommele', 1, 1, 'De inquisitie zo bloeddorstig en fel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('slaat-op-den-trommele', 1, 2, 'De inquisitie zal ter helle verbranden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('slaat-op-den-trommele', 1, 3, 'En ze verliest haar valse spel!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('slaat-op-den-trommele', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('slaat-op-den-trommele', 2, 0, 'Vive le Geus! Wilt Geuselijk leven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('slaat-op-den-trommele', 2, 1, 'Vive le Geus! Houdt fraaien moed;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('slaat-op-den-trommele', 2, 2, 'Vive le Geus! Geus behoedt U voor ’t sneven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('slaat-op-den-trommele', 2, 3, 'Vive le Geus! Edel Geuzenbloed!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('slaat-op-den-trommele', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('slaat-op-den-trommele', 3, 0, 'Of laat intijds nog, Geus’ woord te krenken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('slaat-op-den-trommele', 3, 1, 'Of laat intijds nog uw Geusloos spel;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('slaat-op-den-trommele', 3, 2, 'Of laat intijds! Och wilt U bedenken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('slaat-op-den-trommele', 3, 3, 'Of laat intijds, weest geen rebel!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('t-smidje', '’T SMIDJE', 'SMIDJE, ’T', 'nederlandstalige-liederen', 'nl', NULL, 218, 218, 'Traditioneel', 'Laïs', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-smidje', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 0, 0, 'Wie wil horen een historie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 0, 1, 'Al van ene jonge smid');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 0, 2, 'Die verbrand had zijn memorie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 0, 3, 'Daaglijks bij het vuur verhit');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-smidje', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 1, 0, 'Was ik nog, nog met mijnen hamer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 1, 1, 'Was ik nog met geweld op mijn aambeld');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-smidje', 2, 'direction', 1, 'Na de laatste strofe wordt het refrein twee maal gezongen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-smidje', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 3, 0, '’k Geef den bras aan al dat smeden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 3, 1, 'Ik ga naar de Franse zwier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 3, 2, '’k Wil mij tot den trouw begeven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 3, 3, 'Nooit een schoner vrouw gezien');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-smidje', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 4, 0, '’t Is de schoonste van de vrouwen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 4, 1, 'Maar nooit was er zo’n serpent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 4, 2, 'Nooit kan zij haar bakkes houden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 4, 3, 'Nooit is zij eens wel content');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-smidje', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 5, 0, 'Nooit mag ik een pintje drinken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 5, 1, 'Nooit mag ik eens vrolijk zijn');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 5, 2, 'Nooit kan ik iemand beschinken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 5, 3, 'Met een glaasje bier of wijn');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-smidje', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 6, 0, '’k Geef den bras van al dat trouwen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 6, 1, 'Werd ik maar eens weduwnaar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 6, 2, '’k Zou mij in een hoeksken houden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-smidje', 6, 3, 'En mij stellen uit gevaar');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('de-stoompruim', 'DE STOOMPRUIM', 'STOOMPRUIM, DE', 'nederlandstalige-liederen', 'nl', NULL, 219, 219, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-stoompruim', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-stoompruim', 0, 0, 'Zie, ginds komt de stoomboot uit Spanje weer aan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-stoompruim', 0, 1, 'Hij brengt ons de hoeren, ik zie ze al staan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-stoompruim', 0, 2, 'Hoe huppelt mijn pietje mijn broek op en neer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-stoompruim', 0, 3, 'Hoe waaien mijn kloten al heen en al weer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-stoompruim', 0, 4, 'Bim bom');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('de-stoompruim', 0, 4, 4, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('tinneke-van-heulen', 'TINNEKE VAN HEULEN', 'TINNEKE VAN HEULEN', 'nederlandstalige-liederen', 'nl', NULL, 219, 220, NULL, 'Emiel Hullebroeck', 'Oorspronkelijke tekst: René de Clercq');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('tinneke-van-heulen', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 0, 0, 'Tinneke van Heulen, ons maartje');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 0, 1, 'Kan poepen gelijk een paardje');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 0, 2, 'Kan sussen, kan kussen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 0, 3, 'Ze steekt hem er zelf tussen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('tinneke-van-heulen', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 1, 0, 'Tinneke van Heulen, mijn minneken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 1, 1, 'Komt zo geerne aan mijn pinneken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 1, 2, 'Dat hem schiet gelijk ne zot');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 1, 3, 'En dan hangt gelijk een vod');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 1, 4, 'Zoals die van ’t kerstekinneke.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('tinneke-van-heulen', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 2, 0, 'Beter dan een boer die op zijn varken kruipt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 2, 1, 'Beter dan een oude die zijn hand gebruikt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 2, 2, 'Beter dan een hemel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 2, 3, 'Een gat gelijk een kemel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 2, 4, 'Tinneke ons maartje in haar hemd.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('tinneke-van-heulen', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 3, 0, 'Tinneke van Heulen, ons maartje,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 3, 1, 'Komt zo geerne aan mijn staartje');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 3, 2, 'Als ze tippelt naar de bron');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 3, 3, 'Met haar tetten in de zon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 3, 4, 'Kom ik zo geerne aan haar baardje.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('tinneke-van-heulen', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 4, 0, 'Beter dan een boer die op zijn varken kruipt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 4, 1, 'Beter dan een oude die zijn hand gebruikt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 4, 2, 'Beter dan een hemel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 4, 3, 'Een gat gelijk een kemel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tinneke-van-heulen', 4, 4, 'Tinneke ons maartje in haar hemd.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('toen-ik-in-brussel-kwam', 'TOEN IK IN BRUSSEL KWAM', 'TOEN IK IN BRUSSEL KWAM', 'nederlandstalige-liederen', 'nl', NULL, 221, 221, NULL, NULL, 'Moraal van het verhaal:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('toen-ik-in-brussel-kwam', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 0, 0, 'Toen ik in Brussel kwam');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 0, 1, 'Die hoer stond aan de deur,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 0, 2, 'Ze waggelde met haar tetten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 0, 3, 'En ik stelde mijn eigen veur.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('toen-ik-in-brussel-kwam', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 1, 0, 'Poepeke zwam, zwam, zwam.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('toen-ik-in-brussel-kwam', 1, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('toen-ik-in-brussel-kwam', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 2, 0, 'Toen ik naar boven ging');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 2, 1, 'Die hoer lag op haar bed,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 2, 2, 'Ze deed haar beentjes open');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 2, 3, 'En ik heb me d’rop gezet.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('toen-ik-in-brussel-kwam', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 3, 0, 'Toen ik naar buiten kwam');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 3, 1, 'Ik voelde mij zo ziek,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 3, 2, 'Mijn piet begon te lopen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 3, 3, 'En ik moest naar de kliniek.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('toen-ik-in-brussel-kwam', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 4, 0, 'Toen ik in ’t gasthuis lag');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 4, 1, 'Die hoer kwam aan mijn bed,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 4, 2, 'Ze grabbelde onder ’t laken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 4, 3, 'Maar mijn piet was afgezet!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('toen-ik-in-brussel-kwam', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 5, 0, 'Toen ik op ’t kerkhof lag');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 5, 1, 'Die hoer stond aan mijn graf,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 5, 2, 'Ze zei: “Hier ligt die smeerlap');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 5, 3, 'Die zijn cens aan d’ hoeren gaf!”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('toen-ik-in-brussel-kwam', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 6, 0, 'Toen die hoer van ’t kerkhof kwam');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 6, 1, 'Toen zag ze daar nen hond,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 6, 2, 'Met olifantenkloten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('toen-ik-in-brussel-kwam', 6, 3, 'En ne piet tot op de grond!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('het-vendel', 'HET VENDEL', 'VENDEL, HET', 'nederlandstalige-liederen', 'nl', NULL, 222, 223, 'Jan Hoogensteyn', 'Oud-Nederlands soldatenlied circa 1560', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-vendel', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 0, 0, 'Het vendel moet marsjeren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 0, 1, 'Want Vlaand’ren is in nood.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 0, 2, 'Sint Joris geeft ons kleren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 0, 3, 'Geef ons soldij en brood.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 0, 4, 'Dat wij geen koude lijden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 0, 5, 'Geef ons de boer zijn wijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 0, 6, 'Zijn wolhemd en zijn duiten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 0, 7, 'Dat kan geen zonde zijn!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 0, 8, 'Marsjeer, landsknecht, marsjeer!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-vendel', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 1, 0, 'Wij slikken stof bij ’t wandlen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 1, 1, 'Verstomd zijn lied en lach;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 1, 2, 'De Keizer slikt heel Vlaanderen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 1, 3, 'Hij heeft een sterke maag!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 1, 4, 'Hij denkt al onder ’t kauwen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 1, 5, 'Aan nieuwe roem en eer,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 1, 6, 'Thuis weent een blonde vrouwe,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 1, 7, 'Als ik niet wederkeer.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 1, 8, 'Marsjeer, landsknecht, marsjeer!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-vendel', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 2, 0, 'De tamboer slaat parade,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 2, 1, 'Sint Joris sterke held,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 2, 2, 'Bescherm ons in genade,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 2, 3, 'Het vendel trekt ten veld.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 2, 4, 'De pijper wil niet fluiten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 2, 5, 'Wij trekken stil en stom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 2, 6, 'Over de groene heide,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 2, 7, 'Opwaarts naar Berg-op-Zoom.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-vendel', 2, 8, 'Marsjeer, landsknecht, marsjeer!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('verbroedering-te-brussel', 'VERBROEDERING TE BRUSSEL', 'VERBROEDERING TE BRUSSEL', 'nederlandstalige-liederen', 'nl', NULL, 223, 224, NULL, NULL, 'T & M: Hans Van de Casseye. Naar Vioolconcerto op.35 in RE (Tchaikovsky) & Bro Hymn (Pennywise)
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('verbroedering-te-brussel', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 0, 0, 'Verse schachten komen aan de VUB,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 0, 1, 'Nieuw en alleen in deze grote stad.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 0, 2, 'Weet goed, er is leven naast de les:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 0, 3, 'Sociaal engag’ment en student’koziteit.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 0, 4, 'Vergeet het niet, de tijd die dringt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 0, 5, 'Studentenleven, mis het niet.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('verbroedering-te-brussel', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 1, 0, 'Student zijn is meer dan studeren alleen.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 1, 1, 'Verbroedering, da’s ons VUB-ideaal.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('verbroedering-te-brussel', 1, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('verbroedering-te-brussel', 1, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('verbroedering-te-brussel', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 2, 0, 'Kijk eens rond in onze hoofdstad.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 2, 1, 'Je zult zien, er zit serieus veel fout:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 2, 2, 'Miserie in d’huizen en armoed’ in ’t straat.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 2, 3, 'Kom, geef die clochard eens een pint.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 2, 4, 'Trek het je aan, ’t is onze taak,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 2, 5, 'Naar buiten te gaan, iedereen tesaam.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('verbroedering-te-brussel', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 3, 0, 'In Brussel lopen veel kleurlingen rond,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 3, 1, 'Maar waarom toch zoveel onbegrip?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 3, 2, 'Ons bloed is toch even rood als karmijn?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 3, 3, 'Dan moeten we ook elkander verstaan!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 3, 4, 'Wordt niet meegesleept, door bruin gezweep,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 3, 5, '’t Is toch zo leep, extreem gedweep.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('verbroedering-te-brussel', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 4, 0, 'Miljarden mensen hebben hun geloof.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 4, 1, 'Wij Vrijdenkers hebben er geen nodig.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 4, 2, 'Maar we moeten wel verdraagzaam zijn');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 4, 3, 'Tegenover ied’reen die anders denkt.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 4, 4, 'Respecteer iedereen, Afghaan tot Chileen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 4, 5, 'Minacht niemand, ga hand in hand.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('verbroedering-te-brussel', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 5, 0, 'Sprekte Vloms, Français, of nog eet an’ers?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 5, 1, 'Wa in Brussel emme doe gin complexe mei.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 5, 2, 'De Brusseleirs zaain étrangeis gewuun.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 5, 3, 'In ons stad es alleman bienvenu.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 5, 4, 'Codex uit de kast, een Geuze vast,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 5, 5, 'Zingt een lied in ’t Frans, en ’t Nederlands.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('verbroedering-te-brussel', 6, 'direction', 1, 'Laatste refrein:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('verbroedering-te-brussel', 7, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 7, 0, 'Être étudiant, c’est plus que seulement étudier.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('verbroedering-te-brussel', 7, 1, 'Fraternité, c’est notre idéal de la VUB.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('verbroedering-te-brussel', 7, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('verbroedering-te-brussel', 7, 1, 1, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('de-verlopen-student', 'DE VERLOPEN STUDENT', 'VERLOPEN STUDENT, DE', 'nederlandstalige-liederen', 'nl', NULL, 225, 226, 'Brussels soldatenlied', NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-verlopen-student', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 0, 0, '’k Heb zoveel jaren student geweest');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 0, 1, 'En nou zen ik soldaatje');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 0, 2, 'Voor gienen duvel of hel bevreesd');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 0, 3, 'Nog voor gien vrouwepraatje');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 0, 4, 'Want al die studies ston mij ni aan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 0, 5, 'Ik heb ze gaan verlaten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 0, 6, 'Ik heb de wijsheid laten staan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 0, 7, 'En ’k zen bij de soldaten');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-verlopen-student', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 1, 0, 'Met me geweer en m’n bajonet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 1, 1, 'Trek ik naar de parade');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 1, 2, 'Me menen hoed proper opgezet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 1, 3, 'Doen ik m’n saluade');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 1, 4, 'Van linksom rechtsom ik marcheer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 1, 5, 'En da wel honderd keren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 1, 6, 'Is er nog iet da me mankeert');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 1, 7, 'Ik zal ’t wel beter leren');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-verlopen-student', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 2, 0, 'Der woont e juffrouwke in de straat');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 2, 1, 'Zeer wel naar mijn behagen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 2, 2, 'Ik heb ze vriendelijk begroet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 2, 3, 'En ’k zen aan heur gaan vragen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 2, 4, 'Of dat ik mocht uit liefde zoet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 2, 5, 'Kussen heur roze wangen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 2, 6, '“Och ja” sprak zij, “soldaat voldoet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 2, 7, 'Naar aa is mijn verlangen”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-verlopen-student', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 3, 0, 'De troemmel roefelt in ons kwartier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 3, 1, 'Adieu, schoon lief, we scheiden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 3, 2, 'Al is het ni voor mijn plezier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 3, 3, 'Ik mag ni langer blijven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 3, 4, 'Ik moet nog gaan naar den doktoor');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 3, 5, 'Om mij te doen soigneren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 3, 6, 'Want ’k heb vanbinnen een grote pijn');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 3, 7, 'Die mij komt ambeteren');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-verlopen-student', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 4, 0, 'En den doktoor heit aan mij gezee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 4, 1, 'Den drank die zal u doden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 4, 2, 'En ook de kussen al van dees meid');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 4, 3, 'Heit em aan mij verboden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 4, 4, '’k Moest de jenevel laten staan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 4, 5, 'En ook de vrouwe derven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 4, 6, 'Ik zei “doktoor, vive l’amour');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-verlopen-student', 4, 7, 'Veul liever zoun ik sterven”');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('vier-weverkens', 'VIER WEVERKENS', 'VIER WEVERKENS', 'nederlandstalige-liederen', 'nl', NULL, 226, 227, 'Pol de Mont, 1889', NULL, 'Herinnert aan de hongersnood die Vlaanderen tot 1900 veelvuldig trof.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vier-weverkens', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 0, 0, 'Vier weverkens zag men te botermarkt gaan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 0, 1, 'En de boter die was er zo diere,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 0, 2, 'Zij hadden geen duit haast meer in hunne tas');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 0, 3, 'En ze kochten een pond sa vieren.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 0, 4, 'Schietspoele, sjerrebekke spoelza!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 0, 5, 'Djikke djakke, kerrekoltjes, klitsklets!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 0, 6, 'En ze kochten een pond sa vieren.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vier-weverkens', 1, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vier-weverkens', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 2, 0, 'En als zij dat boterken hadden gekocht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 2, 1, 'Zij hadden er vier platelen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 2, 2, 'Zij spraken dat vrouwken zo vriendelijk aan:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 2, 3, 'Sa vrouwken en wilt het ons delen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vier-weverkens', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 3, 0, 'Dat vrouwken dat sprak: “Ja dat zal ik wel doen.”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 3, 1, 'Ja zo wel als een vrouwken vol eren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 3, 2, 'Want ik wete wel wat er de weverkens zijn');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 3, 3, 'En de weverkens zijn er geen heren.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vier-weverkens', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 4, 0, 'Wat zouden de weverkens heren zijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 4, 1, 'Zij en hebben er huize noch erven!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 4, 2, 'En kruipt er een muisken in hunne schapraai,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 4, 3, 'Van honger zo moet het er sterven.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vier-weverkens', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 5, 0, 'En als dan dat muisken gestorven zal zijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 5, 1, 'Waar zullen zij het begraven?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 5, 2, 'Al onder de weverkens hunne getouw');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vier-weverkens', 5, 3, 'En het grafke zal rooskens dragen.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('vive-la-companeia', 'VIVE LA COMPANEIA', 'VIVE LA COMPANEIA', 'nederlandstalige-liederen', 'nl', NULL, 227, 228, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vive-la-companeia', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-la-companeia', 0, 0, 'Ik steek mijn pintje naar omlaag,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-la-companeia', 0, 1, 'Vive la companeia!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-la-companeia', 0, 2, 'En druk het teder aan mijn maag,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-la-companeia', 0, 3, 'Vive la companeia!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vive-la-companeia', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-la-companeia', 1, 0, 'Vivela, vivela, vivelala');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-la-companeia', 1, 1, 'Vivela, vivela, hopsasa,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-la-companeia', 1, 2, 'Vive la companeia!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vive-la-companeia', 2, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vive-la-companeia', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-la-companeia', 3, 0, 'Mijn pintje voor het sterven moet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-la-companeia', 3, 1, 'Geef ik een kus tot afscheidsgroet.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vive-la-companeia', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-la-companeia', 4, 0, 'Ik hef mijn pint tot aan de mond,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-la-companeia', 4, 1, 'En drink ze leeg tot op de grond.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vive-la-companeia', 5, 'direction', 1, 'Glazen worden na het refrein ad fundum gedronken');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vive-la-companeia', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-la-companeia', 6, 0, 'Het pintje heeft zijn dienst gedaan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-la-companeia', 6, 1, 'En ’t onderste moet boven staan.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vive-la-companeia', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-la-companeia', 7, 0, 'Ei schachtje kom nog eens langs hier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-la-companeia', 7, 1, 'En vul mijn pint met schuimend bier!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vive-la-companeia', 8, 'direction', 1, 'De praeses drinkt even en terwijl hij zijn pint in wijzerzin doorgeeft in de corona, zingt hij:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vive-la-companeia', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-la-companeia', 9, 0, 'Nu gaat mijn pint van keel tot keel;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-la-companeia', 9, 1, 'Dat ieder drink maar niet te veel!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vive-la-companeia', 10, 'direction', 1, 'En de corona vervolgt:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vive-la-companeia', 11, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-la-companeia', 11, 0, 'Nu gaat de pint van keel tot keel:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-la-companeia', 11, 1, 'Dat ieder drink maar niet te veel!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vive-la-companeia', 12, 'direction', 1, 'Men blijft deze strofe verder zingen tot de pint terug bij de praeses is. De laatste commilito vòòr de praeses drinkt wat overblijft ad fundum.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('vive-vive-le-geus', 'VIVE, VIVE LE GEUS', 'VIVE, VIVE LE GEUS', 'nederlandstalige-liederen', 'nl', NULL, 229, 230, NULL, NULL, 'Uit het ‘Nieu Geusen Liet-boeck’, 1581. Het lied gaat terug op de slag bij Oosterweel van 13 maart 1567. De oorspronkelijke titel is: ‘Hier beginnen de Liedekens van Paepken uut’. Er moet opgemerkt worden dat onze 16e eeuwse medemens klaarblijkelijk een ander gevoel voor ritme had dan wat tegenwoordig als normaal wordt beschouwd. Naast de Geus/God kwestie werd het lied dan ook op verschillende plaatsen vervormd om de “zingbaarheid” te verbeteren. Vijf strofen werden zelfs weggelaten, omdat vervorming ervan weinig van de oorspronkelijke betekenis van zou overlaten.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vive-vive-le-geus', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 0, 0, 'Ick hope dat den tijdt noch komen sal');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 0, 1, 'Dat men sal roepen overal,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 0, 2, 'De klinkende leus');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 0, 3, 'Als Brederode met blij geschal:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 0, 4, 'Vive, vive le Geus!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vive-vive-le-geus', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 1, 0, 'Die edele heere van Breero soet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 1, 1, 'Met graaf van Nassou, dat edel bloet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 1, 2, 'Seer ingenieus,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 1, 3, 'De grave van Culenborch metter spoet:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 1, 4, 'Vive, vive le Geus!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vive-vive-le-geus', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 2, 0, 'Dese hebben ons verlost van den Cardinael,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 2, 1, 'Van ketter meesters int generael,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 2, 2, 'Van den bisschop pompeus,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 2, 3, 'Dus roepen wij met blij gheschal:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 2, 4, 'Vive, vive le Geus!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vive-vive-le-geus', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 3, 0, 'De prins van Oranjen triumfant,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 3, 1, 'Met and’re baroenen hier int land,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 3, 2, 'Sijn damboreus');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 3, 3, 'Geus maakte haar zijnen wille bekand,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 3, 4, 'Vive, vive le Geus!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vive-vive-le-geus', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 4, 0, 'Bisschop en prelaten, acht men niet meer,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 4, 1, 'Noch den paus met zijn valsche leer,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 4, 2, 'Zy zijn venineus;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 4, 3, 'Dus roepen wy tegen haer eer:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 4, 4, 'Vive, vive le Geus!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vive-vive-le-geus', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 5, 0, 'Verblijdt u allen met groot jolijt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 5, 1, 'Die den kardinael draagt den trouw ten spijt;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 5, 2, 'Als zy vragen de leus,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 5, 3, 'Dus zegt ge altijd en weest verblydt:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 5, 4, 'Vive, vive le Geus!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vive-vive-le-geus', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 6, 0, 'Dankt Geus den prins van ’t wereltrijck,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 6, 1, 'Gij die de waarheid zoekt gelijk,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 6, 2, 'Hoe langer hoe meer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 6, 3, 'Betert u, geeft Geus authentijk,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vive-vive-le-geus', 6, 4, 'Glorie, lof, prijs en eer!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('de-vlaamse-leeuw', 'DE VLAAMSE LEEUW', 'VLAAMSE LEEUW, DE', 'nederlandstalige-liederen', 'nl', NULL, 231, 232, 'Hippoliet Jan van Peene, 1833', 'Karel van Miry, 1847', 'Dit lied was tot begin jaren 90 één van de afsluiters van de cantus.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-vlaamse-leeuw', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 0, 0, 'Zij zullen Hem niet temmen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 0, 1, 'De fiere Vlaamse Leeuw');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 0, 2, 'Al dreigen zij Zijn vrijheid');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 0, 3, 'Met kluisters en geschreeuw');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 0, 4, 'Zij zullen Hem niet temmen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 0, 5, 'Zolang één Vlaming leeft');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 0, 6, 'Zolang de Leeuw kan klauwen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 0, 7, 'Zolang Hij tanden heeft.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-vlaamse-leeuw', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 1, 0, 'Zij zullen Hem niet temmen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 1, 1, 'Zolang één Vlaming leeft');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 1, 2, 'Zolang de Leeuw kan klauwen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 1, 3, 'Zolang hij tanden heeft.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('de-vlaamse-leeuw', 1, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-vlaamse-leeuw', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 2, 0, 'De tijd verslindt de steden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 2, 1, 'Geen tronen blijven staan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 2, 2, 'De legerbenden sneven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 2, 3, 'Een volk zal nooit vergaan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 2, 4, 'De vijand trekt ten velde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 2, 5, 'Omringd van doodsgevaar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 2, 6, 'Wij lachen met zijn woede');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 2, 7, 'De Vlaamse Leeuw is daar.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-vlaamse-leeuw', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 3, 0, 'Hij strijdt nu duizend jaren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 3, 1, 'Voor vrijheid, land en Geus');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 3, 2, 'En nog zijn Zijne krachten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 3, 3, 'In al hun jeugdgenot');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 3, 4, 'Als zij Hem machteloos denken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 3, 5, 'En tergen met een schop');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 3, 6, 'Dan richt Hij zich bedreigend');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 3, 7, 'En vreeslijk voor hen op.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-vlaamse-leeuw', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 4, 0, 'Wee hem die onbezonnen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 4, 1, 'Die vals en vol verraad,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 4, 2, 'De Vlaamse Leeuw komt strelen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 4, 3, 'En trouweloos Hem slaat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 4, 4, 'Geen enkele handbeweging');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 4, 5, 'Die Hij uit ’t oog verliest,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 4, 6, 'En voelt Hij zich getroffen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 4, 7, 'Hij stelt zijn maan en briest.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-vlaamse-leeuw', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 5, 0, 'Het wraaksein is gegeven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 5, 1, 'Hij is hun tergen moe');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 5, 2, 'Met vuur in ’t oog, met woede');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 5, 3, 'Springt Hij de vijand toe');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 5, 4, 'Hij scheurt, vernielt, verplettert');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 5, 5, 'Bedekt met bloed en slijk');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 5, 6, 'En zegepralend grijnst Hij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-leeuw', 5, 7, 'Op ’s vijands trillend lijk.');
