INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-meisjes', 7, 0, 'Vanaf hun borst, tot aan hun knie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vlaamse-meisjes', 7, 1, 'Genoeg krijgen ze nooit nie');
