INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('t-vliegerke', '’T VLIEGERKE', 'VLIEGERKE, ’T', 'nederlandstalige-liederen', 'nl', NULL, 235, 236, NULL, NULL, 'Gents straatliedje');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-vliegerke', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 0, 0, '’k Ben nie al te zot van ’t spel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 0, 1, 'Maar ’k vange gere musschen;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 0, 2, 'Marblen, toppen kan ik wel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 0, 3, 'Maar daarin ben ik nie fel!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 0, 4, '’k Zie tegenwoordig overal,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 0, 5, 'En ook al in mijn strate,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 0, 6, 'Jongens schuppen op nen bal,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 0, 7, 'Maar ik spele ’t liefst van al:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-vliegerke', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 1, 0, 'Mee mijne vlieger, mee zijne steert,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 1, 1, 'Hij gaat omhoge, ’t es ’t ziene weerd;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 1, 2, '’k Geve maar klauwe, op mijn gemak,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 1, 3, '’k Hè nog drij bollekes, in mijne zak!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-vliegerke', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 2, 0, 'Mietje van de koolmarsjant,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 2, 1, 'Een meisje uit mijn strate,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 2, 2, 'Keurde mijne cerf-volant,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 2, 3, 'En ze had er ’t handje van.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 2, 4, 'Want zo rap alsof de wind');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 2, 5, 'Was ze aan ’t spelen mee mijn klauwen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 2, 6, 'En ze zei: “’t Es ’t spele weerd.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 2, 7, 'Want hij hee ne goeie steert!”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-vliegerke', 3, 'chorus-ref', 1, 'waarbij ‘drij bollekes’ wordt vervangen door ‘twee bollekes’.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-vliegerke', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 4, 0, 'Tsjeef liet zijne vlieger op');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 4, 1, 'Van tsjoepe, tsjoepe, tsoepe,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 4, 2, 'Maar hij stuikt op zijne kop,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 4, 3, 'En muile dat hij trok;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 4, 4, 'Zijne spankoorde was veel te kort');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 4, 5, 'En mee zijn tsietse klauwe,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 4, 6, 'En daarbij was zijne steert');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 4, 7, 'Geen sjieke toebak weerd,');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-vliegerke', 5, 'chorus-ref', 1, 'waarbij ‘drij bollekes’ wordt vervangen door ‘een bolleke’.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-vliegerke', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 6, 0, 'Overlaatst op ’t St.-Denijsplein,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 6, 1, 'Mijne vlieger was aan ’t zweven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 6, 2, 'Er kwam een wijf, een groot venijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 6, 3, 'En ze zei: “Da mag nie zijn');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 6, 4, 'Hij hangt te veel in mijne weg!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 6, 5, 'Ze begost er aan te sleuren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 6, 6, 'En op één, twee, drij, pardaf,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 6, 7, 'De koorde schoot eraf!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-vliegerke', 7, 'direction', 1, 'laatste refrein');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-vliegerke', 8, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 8, 0, 'Hij was gaan vliegen, al mee de wind.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 8, 1, '’k Stonde te schriemen, ’k was maar een kind.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 8, 2, 'Mijne bol klauwe, die ging ne gang,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-vliegerke', 8, 3, 'Da zal ’k onthouden, mijn leven lang!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('voor-outer-en-heerd', 'VOOR OUTER EN HEERD', 'VOOR OUTER EN HEERD', 'nederlandstalige-liederen', 'nl', NULL, 237, 237, 'Jozef Simons', 'Armand Preud’homme', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('voor-outer-en-heerd', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 0, 0, 'Geen roekeloze wagers:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 0, 1, 'Stil volk dat zich beraadt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 0, 2, 'Aleer het zijn belagers');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 0, 3, 'Manhaft te lijve gaat.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 0, 4, 'Zij wisten wat zij wilden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 0, 5, 'Toen zij tot stout verweer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 0, 6, 'De piek of zeis optilden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 0, 7, 'Of grepen naar ’t geweer');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('voor-outer-en-heerd', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 1, 0, 'Voor vrijheid en recht; ongeknecht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 1, 1, 'Onverveerd voor outer en heerd.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('voor-outer-en-heerd', 1, 0, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('voor-outer-en-heerd', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 2, 0, 'Zij steunden op Oranjes:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 2, 1, 'De Nederlanden één!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 2, 2, 'En juichten toen Brittannis');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 2, 3, 'Beloofde vloot verscheen.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 2, 4, 'Kloekmoedig in de gouwen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 2, 5, 'Van Diets Zuid-Nederland');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 2, 6, 'Zijn alle sterk en trouwe');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 2, 7, 'Gesprongen in den band');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('voor-outer-en-heerd', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 3, 0, 'Rollier, Corbeels, Van Gansen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 3, 1, 'Bevochten onverveerd,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 3, 2, 'Met wisselende kansen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 3, 3, 'Den vijand van hun heerd.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 3, 4, 'Zij kampten koen als leeuwen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 3, 5, 'En werden ze overmand,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 3, 6, 'Hun namen staan voor eeuwen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('voor-outer-en-heerd', 3, 7, 'In ’t hart van ’t volk gebrand');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('de-vorige-pastoor-van-elsene', 'DE VORIGE PASTOOR VAN ELSENE', 'VORIGE PASTOOR VAN ELSENE, DE', 'nederlandstalige-liederen', 'nl', NULL, 239, 240, 'Bart Vermijlen', '‘Pauvre Martin’, George Brassens', 'PERSkring, Winnend lied van het 17e Vrijzinnig Zangfeest van Vlaanderen, 2002');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-vorige-pastoor-van-elsene', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 0, 0, 'Met de zon in zijn geest geboren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 0, 1, 'Uit een zeer religieus gezin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 0, 2, 'Was hij vanaf ’t begin verloren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 0, 3, 'Vrijzinnig zijn zat er niet in');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('de-vorige-pastoor-van-elsene', 0, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-vorige-pastoor-van-elsene', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 1, 0, 'Zijn lichaam is vrij, zijn geest kent gedonder');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 1, 1, 'Laat hem zijn eigen meester zijn');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-vorige-pastoor-van-elsene', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 2, 0, 'Kon in de kerk zijn draai nooit vinden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 2, 1, 'Volgde zijn ouders zeer devoot');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 2, 2, 'Hield aan de vrijheid van het denken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 2, 3, 'Maar toen ging zijn moeder dood');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('de-vorige-pastoor-van-elsene', 2, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-vorige-pastoor-van-elsene', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 3, 0, 'Zij deed hem nog voor haar dood beloven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 3, 1, 'Om te gaan leren voor pastoor');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 3, 2, 'Ooit aan de VUB studeren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 3, 3, 'Was een droom die hij verloor');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('de-vorige-pastoor-van-elsene', 3, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-vorige-pastoor-van-elsene', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 4, 0, 'Op het moment van zijn gelofte');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 4, 1, 'Zag hij Verhaegen Théodore');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 4, 2, 'En een verlichte stoet van rede');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 4, 3, 'Ziet ook de fakkel fier vanvoor');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('de-vorige-pastoor-van-elsene', 4, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-vorige-pastoor-van-elsene', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 5, 0, 'Koos voor een Elsense parochie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 5, 1, 'Wat kregen ze daar aan hun gehoor');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 5, 2, 'Want in zijn liturgische preken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 5, 3, 'Klonk een meer kritisch‘ houding door');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('de-vorige-pastoor-van-elsene', 5, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-vorige-pastoor-van-elsene', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 6, 0, 'Verbroederde vaak met de studenten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 6, 1, 'Werd op menig meisje smoor');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 6, 2, 'Zong “Le Semeur” luidkeels op cantus');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 6, 3, 'Rolde door tot ’t ochtendgloor');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('de-vorige-pastoor-van-elsene', 6, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-vorige-pastoor-van-elsene', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 7, 0, 'Helaas de bisschop kwam ‘t aan d’oren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 7, 1, 'Zodat hij dra zijn job verloor');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 7, 2, 'Zong het “A bas la calotte”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 7, 3, 'Met zijn laatste kerkkoor');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('de-vorige-pastoor-van-elsene', 7, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-vorige-pastoor-van-elsene', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 8, 0, 'Verketterd en in de ban geslagen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 8, 1, 'Draaide ’t verleden in het slot');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 8, 2, 'Maar denk nu niet dat g’hem moet troosten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 8, 3, 'Is hier student en zit op kot');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('de-vorige-pastoor-van-elsene', 8, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-vorige-pastoor-van-elsene', 9, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 9, 0, 'Draagt steeds zijn klak, kan niet meer zonder');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vorige-pastoor-van-elsene', 9, 1, 'Kan zijn eigen meester zijn');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('de-vorige-pastoor-van-elsene', 9, 0, 1, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('de-voyageur', 'DE VOYAGEUR', 'VOYAGEUR, DE', 'nederlandstalige-liederen', 'nl', NULL, 241, 241, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-voyageur', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-voyageur', 0, 0, 'Doe was ne ki ne voyageur,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-voyageur', 0, 1, 'Trim, tram, troulala,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-voyageur', 0, 2, 'Doe was ne ki ne voyageur,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-voyageur', 0, 3, 'Pirewierewiet jambon.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-voyageur', 1, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-voyageur', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-voyageur', 2, 0, 'Doe stond e maske on de deu.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-voyageur', 2, 1, 'Schuun maske, es moema nie thuis?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-voyageur', 2, 2, 'Nee, menier, z’es noa de met.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-voyageur', 2, 3, 'Schuun maske let ons bove goen.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-voyageur', 2, 4, 'Het maske leep de trappen op.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-voyageur', 2, 5, 'De voyageur heur achterna.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-voyageur', 2, 6, 'Ze vloog van schrik het bedde oep');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-voyageur', 2, 7, 'De voyageur doe boven oep.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-voyageur', 2, 8, 'De panch stak deu den beddezak.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-voyageur', 2, 9, 'De fouter sprong deu ’t sleutelgat.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-voyageur', 2, 10, 'De fouter leep de trappen af.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-voyageur', 2, 11, 'De meid die dacht dat ’t zeepsop was.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-voyageur', 2, 12, 'Noe negen mond en ienen dag,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-voyageur', 2, 13, 'Kwam er ne klachkop veu den dag.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-voyageur', 2, 14, 'Wie es de voeder van da kinch?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-voyageur', 2, 15, 'Hij es goen vliege met de winch.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('de-vreselijke-moord-van-slissen', 'DE VRESELIJKE MOORD VAN SLISSEN', 'VRESELIJKE MOORD VAN SLISSEN, DE', 'nederlandstalige-liederen', 'nl', NULL, 242, 242, NULL, '‘De Zilvervloot’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-vreselijke-moord-van-slissen', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vreselijke-moord-van-slissen', 0, 0, 'Hebt ge al gehoord van de vreselijke moord');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vreselijke-moord-van-slissen', 0, 1, 'De vreselijke moord van Slissen?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vreselijke-moord-van-slissen', 0, 2, 'Ze schoten een hond de ballen van zijn kont');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vreselijke-moord-van-slissen', 0, 3, 'Terwijl hij stond te pissen.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vreselijke-moord-van-slissen', 0, 4, 'Wat laf, wat laf,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vreselijke-moord-van-slissen', 0, 5, 'Zijn kloten waren af');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vreselijke-moord-van-slissen', 0, 6, 'Zijn ballen was hij kwijt.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vreselijke-moord-van-slissen', 0, 7, 'Hij heeft gekregen, het vliegend schijt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vreselijke-moord-van-slissen', 0, 8, 'Hij heeft gekregen, gekregen het vliegend schijt.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('de-vreselijke-moord-van-slissen', 0, 6, 6, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-vreselijke-moord-van-slissen', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vreselijke-moord-van-slissen', 1, 0, 'Hebt ge al gehoord van de vreselijke moord');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vreselijke-moord-van-slissen', 1, 1, 'De vreselijke moord van Spanje');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vreselijke-moord-van-slissen', 1, 2, 'Ze sneden een wijf de tetten van heur lijf');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vreselijke-moord-van-slissen', 1, 3, 'Om er viskens mee te vangen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vreselijke-moord-van-slissen', 1, 4, '’t Pissein, ’t pissein,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vreselijke-moord-van-slissen', 1, 5, '’t Pissein van ’t statieplein,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vreselijke-moord-van-slissen', 1, 6, '’t Pissein da’s veel te klein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vreselijke-moord-van-slissen', 1, 7, 'Ze gaan ’t vergroten, dat klein pissein,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-vreselijke-moord-van-slissen', 1, 8, 'Ze gaan vergroten, vergroten dat klein pissein.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('de-vreselijke-moord-van-slissen', 1, 6, 6, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('een-vrolijk-lentelied', 'EEN VROLIJK LENTELIED', 'VROLIJK LENTELIED, EEN', 'nederlandstalige-liederen', 'nl', NULL, 242, 243, NULL, NULL, 'Jan De Wilde');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('een-vrolijk-lentelied', 0, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('een-vrolijk-lentelied', 0, 0, 'Daar is de lente, daar is de zon!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('een-vrolijk-lentelied', 0, 1, 'Bijna, maar ik denk dat ze weldra zal komen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('een-vrolijk-lentelied', 0, 2, 'De Phallus impudicus staat al in bloei,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('een-vrolijk-lentelied', 0, 3, 'En de blaadjes krijgen bomen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('een-vrolijk-lentelied', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('een-vrolijk-lentelied', 1, 0, 'M’n vrouw en mijn kat zijn allebei krols,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('een-vrolijk-lentelied', 1, 1, 'Het valt me moeilijk ze rustig te houden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('een-vrolijk-lentelied', 1, 2, 'Ik zal binnenkort weer een heleboel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('een-vrolijk-lentelied', 1, 3, 'Nesten moeten bouwen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('een-vrolijk-lentelied', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('een-vrolijk-lentelied', 2, 0, 'De bloembollen barsten open met een');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('een-vrolijk-lentelied', 2, 1, 'Knal en de meisjes ontbloten de kuiten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('een-vrolijk-lentelied', 2, 2, 'De bouwvakkers hebben na een nare tijd');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('een-vrolijk-lentelied', 2, 3, 'Weer iets om naar te fluiten.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('een-vrolijk-lentelied', 3, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('een-vrolijk-lentelied', 3, 0, 'Daar is de lente, daar is de zon!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('een-vrolijk-lentelied', 3, 1, 'Bijna, maar ik denk dat ze weldra zal komen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('een-vrolijk-lentelied', 3, 2, 'De Phallus impudicus staat al in bloei,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('een-vrolijk-lentelied', 3, 3, 'En de klokken vertrekken naar Rome ...');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 'WAAR HET HART VAN VOL IS, LOOPT DE MOND VAN OVER', 'WAAR HET HART VAN VOL IS, LOOPT DE MOND VAN OVER', 'nederlandstalige-liederen', 'nl', NULL, 243, 245, 'Thomas Schoenmakers, Andrew Crosby, William Schoenmakers, Lodewijk Janssen, Benjamin Van de Pol', '‘Misery’, Greenday', 'LWK, Winnend lied op het 25e Vrijzinnig Zangfeest van Vlaanderen, 2010');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 0, 0, 'Mijn liefste schat, de dingen die je graag doet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 0, 1, 'als knuff’len, samen dansen op TD,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 0, 2, 'steeds zeggen dat ik je graag zie,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 0, 3, 'omgaan met je jaloezie;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 0, 4, 'Maar eigenlijk boeit het mij niet.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 1, 0, 'Want ik doe graag, graag, graag');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 1, 1, 'wat je haat, haat, haat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 1, 2, 'niet omdat het leuker is ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 1, 3, 'Maar ik doe graag, graag, graag');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 1, 4, 'wat je haat, haat, haat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 1, 5, 'al is het maar omdat je ’t niet tof vindt!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 1, 6, 'Verwend kutkind!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 2, 0, 'En als ik straalbezopen in je bed pis');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 2, 1, 'dan denk je dat ik niet weet wat ik doe.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 2, 2, 'Weet: ik ben nog vigilant,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 2, 3, '’k doe gewoon graag ambetant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 2, 4, 'Jou zien kuisen is plezant!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 3, 0, 'Ik vind schat dat we eeuwig moeten trouw zijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 3, 1, 'maar jij dan toch wel net iets meer dan mij.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 3, 2, 'Zuigt een ander aan mijn piet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 3, 3, '’t is niet da ’k ervan geniet.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 3, 4, 'Ik heb graag jouw verdriet.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 4, 'chorus-ref', 1, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 5, 0, 'Wanneer ik met mijn maten aan de toog hang,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 5, 1, 'hebben we gespreksonderwerpen zat.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 5, 2, 'Toch gaat het over je ravijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 5, 3, 'kont te groot, tetten te klein.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 5, 4, 'Jou kleineren is zo fijn.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 6, 0, 'Schat, dit geheim moet ik je nog vertellen:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 6, 1, 'kut of kont voor mij is dat één pot nat.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 6, 2, 'Toch dring ik altijd zo hard aan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 6, 3, 'uit verlangen naar je traan.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 6, 4, 'Nu is uranus naar de maan.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 7, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 7, 0, 'Want ik neuk je graag, graag, graag');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 7, 1, 'in je aars, aars, aars,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 7, 2, 'niet omdat het strakker is ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 7, 3, 'Maar ik neuk je graag, graag, graag');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 7, 4, 'in je aars, aars, aars,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 7, 5, 'al is het maar omdat je ’t niet tof vindt!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 7, 6, 'Verwend kutkind!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 8, 'direction', 1, 'Moraal:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 9, 0, 'Je denkt misschien dat dit lied niet ruimdenkend is,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 9, 1, 'maar onze allerliefste Théodore');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 9, 2, 'kreeg ook al in zijnen tijd');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 9, 3, 'van zijn wijf het vliegend schijt.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waar-het-hart-van-vol-is-loopt-de-mond-van-over', 9, 4, 'Hip hip hoera vrijzinnigheid!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('wat-zullen-we-drinken', 'WAT ZULLEN WE DRINKEN', 'WAT ZULLEN WE DRINKEN', 'nederlandstalige-liederen', 'nl', NULL, 245, 246, 'Hans Sanders, Bots', 'Traditioneel Bretoens', 'Enkel de eerste, derde en vijfde strofe kwamen, daarenboven in een andere volgorde, in het origineel lied voor.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wat-zullen-we-drinken', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 0, 0, 'Wat zullen we drinken, zeven dagen lang,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 0, 1, 'Wat zullen we drinken, wat een dorst');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 0, 2, 'Er is genoeg voor iedereen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 0, 3, 'Dus drinken we samen, sla het vat maar aan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 0, 4, 'Dus drinken we samen, niet alleen.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('wat-zullen-we-drinken', 0, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('wat-zullen-we-drinken', 0, 2, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wat-zullen-we-drinken', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 1, 0, 'Dan zullen we eten, zeven dagen lang,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 1, 1, 'Dan zullen we eten, met elkaar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 1, 2, 'Er is genoeg voor iedereen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 1, 3, 'Dus eten we samen, verdeel onder ons het brood,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 1, 4, 'Dus eten we samen, niet alleen.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('wat-zullen-we-drinken', 1, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('wat-zullen-we-drinken', 1, 2, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wat-zullen-we-drinken', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 2, 0, 'Eerst moeten we vechten, niemand weet hoelang,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 2, 1, 'Eerst moeten we vechten, voor ons belang,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 2, 2, 'Voor het belang van iedereen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 2, 3, 'Dus vechten we samen, samen staan we sterk,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 2, 4, 'Dus vechten we samen, niet alleen.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('wat-zullen-we-drinken', 2, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('wat-zullen-we-drinken', 2, 2, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wat-zullen-we-drinken', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 3, 0, 'Dan zullen we vrijen, zeven nachten lang,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 3, 1, 'Dan zullen we vrijen, met mekaar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 3, 2, 'Er is een lief voor iedereen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 3, 3, 'Dus vrijen we samen, samen in een bed,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 3, 4, 'Dus vrijen we samen en met mekaar.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('wat-zullen-we-drinken', 3, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('wat-zullen-we-drinken', 3, 2, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wat-zullen-we-drinken', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 4, 0, 'Dan zullen we werken, zeven dagen lang,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 4, 1, 'Dan zullen we werken voor elkaar.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 4, 2, 'Dan is er werk voor iedereen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 4, 3, 'Dus werken we samen, zeven dagen lang');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wat-zullen-we-drinken', 4, 4, 'Dus werken we samen, niet alleen.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('wat-zullen-we-drinken', 4, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('wat-zullen-we-drinken', 4, 2, 4, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('wie-anders', 'WIE ANDERS', 'WIE ANDERS', 'nederlandstalige-liederen', 'nl', NULL, 247, 248, 'K. Biscop, E. Delay, J. De Groote, T. De Trogh, J. Karlsson, D. Vanhonacker', '‘Santiano’, Les Marins d’Iroise', 'Winnend lied op het 31e Vrijzinnig Zangfeest van Vlaanderen, 2016');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wie-anders', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 0, 0, 'Na lang vrij onderzoek zijn wij weeral mee,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 0, 1, '’t Is de schuld – van het BSG,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 0, 2, 'Wij hackten de server van de VUB,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 0, 3, 'D’ouwe zakken, niet de NSA.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wie-anders', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 1, 0, 'De jungle van Calais, Arabieren in de zee,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 1, 1, '’t Is de schuld – van het BSG,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 1, 2, 'Ook den Theo die doet lustig mee,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 1, 3, 'Met zijn vriendjes van de NSV.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wie-anders', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 2, 0, 'Wie nam er dan de meubels van Herr Francken mee?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 2, 1, 'Ze staan nu – in het BSG,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 2, 2, 'Ze worden verkocht voor een duit of twee,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 2, 3, 'Terug geld voor camions op St V.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wie-anders', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 3, 0, 'Waar is toch dat geld van onze St V?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 3, 1, '’t Is de schuld – van het BSG,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 3, 2, 'Zij sponsorden er den Donald mee,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 3, 3, 'Die is nu baas van de USA.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wie-anders', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 4, 0, 'Wie schreef er aan de tekst van het CETA mee?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 4, 1, '’t Was Maxime – van het BSG,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 4, 2, 'Maar Magnette zegt ook altijd nee,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 4, 3, 'Vuile Walen, wij willen TTIP!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wie-anders', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 5, 0, 'Nigel Farage is ook heel tevree,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 5, 1, 'Den Brexit – dank u BSG!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 5, 2, 'Werkloosheid, Gert Verhulst op TV,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 5, 3, 'Lange files en de piétonnier.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wie-anders', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 6, 0, 'Slechte muggenspray en den diarree:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 6, 1, '’t Is de schuld – van het BSG,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 6, 2, 'Warme pinten op TD,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 6, 3, 'Dankzij u hebben wij nu gonoree.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wie-anders', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 7, 0, 'Wij vinden nu geen woorden meer die rijmen op -e,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 7, 1, 'We zijn oud, we zijn fatigué,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 7, 2, 'En crashen we straks samen op café,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wie-anders', 7, 3, 'Dan is’t nog de schuld van’t BSG!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('wij-zijn-al-bijeen', 'WIJ ZIJN AL BIJEEN', 'WIJ ZIJN AL BIJEEN', 'nederlandstalige-liederen', 'nl', NULL, 248, 249, NULL, NULL, 'Opgetekend door Edmond De Coussemaker, Chants populaires des Flamands de France, 1856');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wij-zijn-al-bijeen', 0, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wij-zijn-al-bijeen', 0, 0, 'Wij zijn al bijeen, zotte kadullekes, zotte kadullen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wij-zijn-al-bijeen', 0, 1, 'Wij zijn al bijeen, zotte kadullen groot en kleen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wij-zijn-al-bijeen', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wij-zijn-al-bijeen', 1, 0, 'Zou me niet meugen een pintje drinken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wij-zijn-al-bijeen', 1, 1, 'Zoude daarom ne zatlap zijn?');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('wij-zijn-al-bijeen', 1, 0, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wij-zijn-al-bijeen', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wij-zijn-al-bijeen', 2, 0, 'Zou me niet meugen een viske eten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wij-zijn-al-bijeen', 2, 1, 'Zoude daarom ne snoeper zijn?');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('wij-zijn-al-bijeen', 2, 0, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wij-zijn-al-bijeen', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wij-zijn-al-bijeen', 3, 0, 'Zou me niet meugen eens vrolijk wezen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wij-zijn-al-bijeen', 3, 1, 'Zou me niet meugen eens vrolijk zijn?');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('wij-zijn-al-bijeen', 3, 0, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wij-zijn-al-bijeen', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wij-zijn-al-bijeen', 4, 0, 'Zou me niet meugen een foutje maken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wij-zijn-al-bijeen', 4, 1, 'Zoude daarom ne stommerik zijn?');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('wij-zijn-al-bijeen', 4, 0, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wij-zijn-al-bijeen', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wij-zijn-al-bijeen', 5, 0, 'Zou me niet meugen een pijpke roken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wij-zijn-al-bijeen', 5, 1, 'Zoude daarom een schoorsteen zijn?');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('wij-zijn-al-bijeen', 5, 0, 1, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('de-wijn', 'DE WIJN', 'WIJN, DE', 'nederlandstalige-liederen', 'nl', NULL, 249, 250, NULL, NULL, 'Laïs');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-wijn', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 0, 0, 'Het beste van de wijne dat is er voor mijne mond');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 0, 1, 'Al lag ik ziek te bedde dan werd ik weer gezond');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 0, 2, 'Al lag ik ziek te bedde gekweld door menig venijn');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 0, 3, 'De wijn geneest de pijne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 0, 4, 'O wijn, weest welkom wijn');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-wijn', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 1, 0, 'Men mag de wijn wel loven, zij is er het prijzen waard');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 1, 1, 'En ook de schone vrouwen die zijn er naar onzen aard');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 1, 2, 'Ik heb er nog meer te doen dan enkel dit glaasje klein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 1, 3, 'Daarom wil ik ze roemen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 1, 4, 'O wijn, weest welkom wijn');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-wijn', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 2, 0, 'De wijn die komt van verre, zo menig mijl gereden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 2, 1, 'Op wagens en op karren tot hier al binnen de steden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 2, 2, 'Zij komt er uit het land van Keulen, al over de Rijn');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 2, 3, 'Getond in volle vaten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 2, 4, 'O wijn, weest welkom wijn');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-wijn', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 3, 0, 'En is ze rood en helder dan is ze ons goed gezind');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 3, 1, 'En streelt zij onze tongen dan is zij ongekend');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 3, 2, 'O als de mensen drinken met vrienden al bijeen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 3, 3, 'Uit glazen die daar klinken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 3, 4, 'O wijn, weest welkom wijn');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-wijn', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 4, 0, 'Ach vrienden hebt geen zorgen, al hebben wij nu geen geld');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 4, 1, 'De waard zal ons wel borgen, zo heeft hij mij verteld');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 4, 2, 'We zullen hem laten schenken en vrolijk zullen we zijn');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 4, 3, 'Kom laat ons vanavond blijven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-wijn', 4, 4, 'O wijn, weest welkom wijn');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('het-wilhelmus', 'HET WILHELMUS', 'WILHELMUS, HET', 'nederlandstalige-liederen', 'nl', NULL, 250, 251, 'Vermoedelijk Philips van Marnix, Heer van St. Aldegonde M: ‘Chartres’, een Frans soldatenlied uit 1568', NULL, 'Oorspronkelijk een acrostichon van 15 strofen. De beginletters van elk eerste woord van elke strofe vormen samen ‘Willem van Nassov’. Geschreven tussen 1568 en ’72.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-wilhelmus', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 0, 0, 'Wilhelmus van Nassouwe');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 0, 1, 'Ben ik van Duytschen bloet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 0, 2, 'Den Vaderlant ghetrouwe');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 0, 3, 'Blyf ick tot in den doet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 0, 4, 'Een Prince van Orangien');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 0, 5, 'Ben ick vry onverveert,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 0, 6, 'Den Coninck van Hyspaengien');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 0, 7, 'Heb ick altyd gheert.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-wilhelmus', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 1, 0, 'In Geuzes vrees te leven');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 1, 1, 'Heb ick altyd betracht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 1, 2, 'Daerom ben ick verdreven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 1, 3, 'Om landt, om luyd gebracht:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 1, 4, 'Maer Geus sal my negeren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 1, 5, 'Als een goet instrument,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 1, 6, 'Dat ick sal wederkeeren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 1, 7, 'In mynen regiment.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-wilhelmus', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 2, 0, 'Lydt U, myn ondersaten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 2, 1, 'Die oprecht syn van aert;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 2, 2, 'Geus sal U niet verlaten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 2, 3, 'Al syt ghy nu beswaert;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 2, 4, 'Die vroom begheert te leven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 2, 5, 'Bidt Geus nacht ende dach,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 2, 6, 'Dat hy my cracht wil gheven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 2, 7, 'Dat ick U helpen mach.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-wilhelmus', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 3, 0, 'Myn schilt ende betrouwen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 3, 1, 'Syt ghy, O Geus myn Heer,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 3, 2, 'Op U soo wil ick bouwen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 3, 3, 'Verlaet my nemmermeer;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 3, 4, 'Dat ick doch vroom mach blyven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 3, 5, 'U dienaer taller stondt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 3, 6, 'De tyrrany verdryven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 3, 7, 'Die my myn hert doorwondt.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-wilhelmus', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 4, 0, 'Oorlof, myn arme schapen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 4, 1, 'Die syt in groote noot,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 4, 2, 'U herder sal niet slapen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 4, 3, 'Al syt ghy nu verstroyt;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 4, 4, 'Tot Geus wilt U begheven,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 4, 5, 'Syn heylsaam woort neemt aen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 4, 6, 'Als vrome Geuzen leven;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-wilhelmus', 4, 7, 'Tsal hier haest syn ghedaen.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('zeemanslied', 'ZEEMANSLIED', 'ZEEMANSLIED', 'nederlandstalige-liederen', 'nl', NULL, 252, 252, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('zeemanslied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zeemanslied', 0, 0, 'Ik heb op zee mijn leven lang gevaren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zeemanslied', 0, 1, 'Mijn vissersdorp ligt aan het Noordzeestrand,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zeemanslied', 0, 2, 'Ik win mijn brood met zwalpen op de baren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zeemanslied', 0, 3, 'Toch denk ik vaak, mijn rijkdom ligt aan land!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('zeemanslied', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zeemanslied', 1, 0, 'Waar het lied der branding ruist bij dag en nacht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zeemanslied', 1, 1, 'Waar ’t vertrouwde huisje altijd op me wacht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zeemanslied', 1, 2, 'Waar de meeuwen schreeuwen boven ’t golfgedruis,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zeemanslied', 1, 3, 'Daar ben ik geboren, daar voel ik me thuis,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zeemanslied', 1, 4, 'Waar de klokken luiden: “Visser, vaar naar huis!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zeemanslied', 1, 5, 'Daar ben ik geboren, daar voel ik me thuis.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('zeemanslied', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zeemanslied', 2, 0, 'Ik voel mij klein wanneer de stormen huilen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zeemanslied', 2, 1, 'Bij donkere nacht, belust op zwakke buit,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zeemanslied', 2, 2, 'Maar voor geen geld ter wereld wil ik ruilen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('zeemanslied', 2, 3, 'Mijn vrij bestaan, als koning op mijn schuit!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('de-zilvervloot', 'DE ZILVERVLOOT', 'ZILVERVLOOT, DE', 'nederlandstalige-liederen', 'nl', NULL, 252, 253, 'Jan Pieter Heye', 'Johannes J. Viotta', '19e eeuws huldelied ter ere van de verovering van de ‘Spaanse Zilvervloot’ door admiraal Piet Hein in 1628.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-zilvervloot', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 0, 0, 'Heb je van de Zilveren Vloot wel gehoord');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 0, 1, 'De Zilveren Vloot van Spanje?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 0, 2, 'Die had er veel Spaanse matten aan boord');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 0, 3, 'En appeltjes van Oranje!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-zilvervloot', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 1, 0, 'Piet Hein, Piet Hein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 1, 1, 'Piet Hein zijn naam is klein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 1, 2, 'Zijn daden bennen groot:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 1, 3, 'Die heeft gewonnen de Zilveren Vloot,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 1, 4, 'Die heeft gewonnen, gewonnen de Zilvervloot.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('de-zilvervloot', 1, 2, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-zilvervloot', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 2, 0, 'Zei toen niet Piet Hein met een aalwarig woord');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 2, 1, '“Wel jongetjes van Oranje,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 2, 2, 'Kom klim ’reis aan dit en dat Spaanse boord');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 2, 3, 'En rol me de matten van Spanje!”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-zilvervloot', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 3, 0, 'Klommen niet de jongens als katten in ’t want');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 3, 1, 'En vochten ze niet als leeuwen?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 3, 2, 'Ze maakten de Spanjers duchtig te schand,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 3, 3, 'Tot Spanje klonk hun schreeuwen!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-zilvervloot', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 4, 0, 'Kwam er nu nog eenmaal zo ’n Zilveren Vloot');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 4, 1, 'Zeg, zou jullie nog zo kloppen?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 4, 2, 'Of zoudt gij u veilig buiten schoot');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 4, 3, 'Maar stil in je hangmat stoppen?');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-zilvervloot', 5, 'direction', 1, 'Laatste refrein:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-zilvervloot', 6, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 6, 0, '“Wel, Neerlands bloed,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 6, 1, 'Dat bloed heeft nog wel moed!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 6, 2, 'Al bennen we niet groot,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 6, 3, 'We zouen winnen een Zilvervloot,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-zilvervloot', 6, 4, 'We zouen winnen, nog winnen een Zilvervloot!”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('de-zilvervloot', 6, 2, 2, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('het-zwartbruine-bier', 'HET ZWARTBRUINE BIER', 'ZWARTBRUINE BIER, HET', 'nederlandstalige-liederen', 'nl', NULL, 254, 254, NULL, 'Duits studentenlied: ‘Das schwarzbraune Bier’, Jena, 1857', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-zwartbruine-bier', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-zwartbruine-bier', 0, 0, 'Het zwartbruine bier dat drink ik zo geern');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-zwartbruine-bier', 0, 1, 'En zwartbruine meisjes die kus ik zo geern');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-zwartbruine-bier', 0, 2, 'Ei gij, ei gij,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-zwartbruine-bier', 0, 3, 'Ei gij bekoorlijk dudeldudeldij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-zwartbruine-bier', 0, 4, 'Juvivallerallera');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-zwartbruine-bier', 0, 5, 'En ge laat geen rust aan mij');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-zwartbruine-bier', 0, 6, 'Ge laat geen rust');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-zwartbruine-bier', 0, 7, 'En ge laat geen rust aan mij!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('het-zwartbruine-bier', 0, 4, 4, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('het-zwartbruine-bier', 0, 6, 6, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-zwartbruine-bier', 1, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-zwartbruine-bier', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-zwartbruine-bier', 2, 0, 'Het meisje heeft twee oogskens fijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-zwartbruine-bier', 2, 1, 'Die fonk’len als een sterrekijn.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-zwartbruine-bier', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-zwartbruine-bier', 3, 0, 'Het meisje heeft een rozige mond,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-zwartbruine-bier', 3, 1, 'En wie die kust die wordt gezond.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-zwartbruine-bier', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-zwartbruine-bier', 4, 0, 'Het meisje heeft een rozige kin,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-zwartbruine-bier', 4, 1, 'Met in het midden een putteken in.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-zwartbruine-bier', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-zwartbruine-bier', 5, 0, 'Het meisje heeft een hertekijn:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('het-zwartbruine-bier', 5, 1, 'Dat zal voor eeuwig ’t mijne zijn!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('het-zwartbruine-bier', 6, 'direction', 1, 'Naargelang de inspiratie van de corona worden er vrije versies gezongen!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('t-zwien', '’T ZWIEN', 'ZWIEN, ’T', 'nederlandstalige-liederen', 'nl', NULL, 255, 255, NULL, NULL, '‘Trink, trink, brüderlein, trink’');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-zwien', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 0, 0, 'Het zwien is het schoonste der beesten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 0, 1, 'Zonder varken wat zouden we zijn?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 0, 2, '’t Is nodig voor al onze feesten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 0, 3, 'En ’k eet al eens geren van ’t zwien.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-zwien', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 1, 0, 'Smout, vet, hespe en spek,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 1, 1, 'Hoofdvlees, koteletten en paté.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 1, 2, 'Worsten en bloeling en vette darms,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 1, 3, 'Schotelvlees en zwienepoot.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('t-zwien', 1, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('t-zwien', 1, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-zwien', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 2, 0, 'Hebt ge nog dat beestje zien slakken?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 2, 1, '’t Is altijd zo op zijn gemak.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 2, 2, 'Het jeunt hem in sop en in brokken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 2, 3, 'Zijn pootjes staan ook in de bak.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-zwien', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 3, 0, 'In ’t zwienskot, ge zoudt daar wegsleeren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 3, 1, 'Niet dat de zwiens daarmee afzien.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 3, 2, 'Ze wroeten, zen’t al om an’t keren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 3, 3, 'Hoe wilder, hoe schoonder om zien.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-zwien', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 4, 0, 'Een plaatje da ook nog kan tellen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 4, 1, 'Voor ’t ’s winters ons vlees gereed te doen:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 4, 2, 'Een schoon stukse zwienerauwélle,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 4, 3, 'Met kolen gestoofd in andjoen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('t-zwien', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 5, 0, 'Die gerenaars, ’k’ kan gene rieken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 5, 1, 'En koeietong, ’k’ wille gene meer zien.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 5, 2, 'En zwijg me van haze of kieken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('t-zwien', 5, 3, 'Maar geef mi een brokske van ’t zwien.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('a-bas-la-calotte', 'À BAS LA CALOTTE', 'À BAS LA CALOTTE', 'franstalige-liederen', 'fr', NULL, 259, 259, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-bas-la-calotte', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-bas-la-calotte', 0, 0, 'À bas la calotte, à bas la calotte');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-bas-la-calotte', 0, 1, 'À bas les calotins');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-bas-la-calotte', 0, 2, 'Ils en auront, des coups de poing sur la gueule');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-bas-la-calotte', 0, 3, 'Ils en auront, autant qu’ils en voudront,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-bas-la-calotte', 0, 4, 'Avec, avec plaisir ou dans les roses');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-bas-la-calotte', 0, 5, 'Et dans les bégonias, c’est la même chose');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('a-bas-la-calotte', 0, 0, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-bas-la-calotte', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-bas-la-calotte', 1, 0, 'Oui, nous irons chasser ohé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-bas-la-calotte', 1, 1, 'Oui, nous irons chasser la calotte.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-bas-la-calotte', 1, 2, 'La calotte au poteau!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('a-bas-la-calotte', 1, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('a-bas-la-calotte', 1, 2, 2, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('a-fond-liegeois', 'À FOND LIÈGEOIS', 'À FOND LIÈGEOIS', 'franstalige-liederen', 'fr', NULL, 260, 261, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-fond-liegeois', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 0, 0, 'Amis, il existe un moment');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 0, 1, 'Où les femm’s, les fill’s et les mères,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 0, 2, 'Amis, il existe un moment');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 0, 3, 'Où les femmes ont besoin d’un amant,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 0, 4, 'Qui les chatouille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 0, 5, 'Jusqu’à ce qu’ ell’s mouillent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 0, 6, 'Et qui les baise,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 0, 7, 'Le cul sur un’ chaise.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-fond-liegeois', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 1, 0, 'Mes amis, pour bien chanter l’amour');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 1, 1, 'Il faut boire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 1, 2, 'Mes amis, pour bien chanter l’amour,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 1, 3, 'Il faut boire et la nuit et le jour,');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('a-fond-liegeois', 1, 1, 1, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-fond-liegeois', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 2, 0, 'À la santé du petit conduit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 2, 1, 'Par où Margot fait pipi.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 2, 2, 'Margot fait pipi par son petit concon,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 2, 3, 'Par son petit duit duit, par son petit conduit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 2, 4, 'À la santé du petit conduit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 2, 5, 'Par où Margot fait pipi');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-fond-liegeois', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 3, 0, 'Il est en face du trou');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 3, 1, 'La trou la trou la trou la lère');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 3, 2, 'Il est en face du trou');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 3, 3, 'La trou la trou la trou la la');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-fond-liegeois', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 4, 0, 'Il est en haut du trou, ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 4, 1, 'Il est en bas du trou, ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 4, 2, 'Il est à gauche du trou, ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 4, 3, 'Il est à droite du trou, ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 4, 4, 'Il est très loin du trou, ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 4, 5, 'Il est très près du trou, ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 4, 6, 'Il passera par le trou, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-fond-liegeois', 5, 'direction', 1, 'Gesproken:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-fond-liegeois', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 6, 0, 'Attention! Verre aux lèvres!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 6, 1, 'Un instant de silence!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 6, 2, 'Une minute de recueillement!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 6, 3, 'Une seconde d’abnégation!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 6, 4, 'Un moment de méditation!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 6, 5, 'Vérolés, verre aux lèvres: À fond!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-fond-liegeois', 7, 'direction', 1, 'Hier wordt een ad fundum gedronken');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-fond-liegeois', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 8, 0, 'Il est passé par le trou, ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 8, 1, 'Il descendra par le trou, ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 8, 2, 'Il repassera par le trou, ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-fond-liegeois', 8, 3, 'Il sortira par le trou, ...');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ah-que-nos-peres-etaient-heureux', 'AH! QUE NOS PERES ÉTAIENT HEUREUX', 'AH! QUE NOS PERES ÉTAIENT HEUREUX', 'franstalige-liederen', 'fr', NULL, 261, 263, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ah-que-nos-peres-etaient-heureux', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 0, 0, 'Ah! Que nos pèr’s étaient heureux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 0, 1, 'Quand ils étaient à table,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 0, 2, 'Le vin coulait à côté d’eux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 0, 3, 'Ça leur était fort agréable.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ah-que-nos-peres-etaient-heureux', 0, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ah-que-nos-peres-etaient-heureux', 0, 2, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ah-que-nos-peres-etaient-heureux', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 1, 0, 'Et ils buvaient à leurs tonneaux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 1, 1, 'Comme des trous.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 1, 2, 'Comme des trous, morbleu!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 1, 3, 'Bien autrement que nous, morbleu!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 1, 4, 'Bien autrement que nous.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ah-que-nos-peres-etaient-heureux', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 2, 0, 'Ils n’avaient ni riches buffets');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 2, 1, 'Ni verres de Venise,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 2, 2, 'Mais ils avaient des gobelets');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 2, 3, 'Aussi grands que leur barbe grise.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ah-que-nos-peres-etaient-heureux', 2, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ah-que-nos-peres-etaient-heureux', 2, 2, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ah-que-nos-peres-etaient-heureux', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 3, 0, 'Ils ne savaient ni le latin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 3, 1, 'Ni la théosophie,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 3, 2, 'Mais ils avaient le goût du vin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 3, 3, 'C’était là leur philosophie.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ah-que-nos-peres-etaient-heureux', 3, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ah-que-nos-peres-etaient-heureux', 3, 2, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ah-que-nos-peres-etaient-heureux', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 4, 0, 'Quand ils avaient quelque chagrin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 4, 1, 'Ou quelque maladie,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 4, 2, 'Ils plantaient là le médecin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 4, 3, 'L’apothicair’, sa pharmacie.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ah-que-nos-peres-etaient-heureux', 4, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ah-que-nos-peres-etaient-heureux', 4, 2, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ah-que-nos-peres-etaient-heureux', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 5, 0, 'Et quand le petit dieu Amour');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 5, 1, 'Leur envoyait quelque donzelle,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 5, 2, 'Sans peur, sans feinte et sans détour');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 5, 3, 'Ils plantaient là la demoiselle.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ah-que-nos-peres-etaient-heureux', 5, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ah-que-nos-peres-etaient-heureux', 5, 2, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ah-que-nos-peres-etaient-heureux', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 6, 0, 'Celui qui planta le provin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 6, 1, 'Au beau pays de France');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 6, 2, 'Dans le flot du rubis divin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 6, 3, 'Sut planter là notre espérance.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ah-que-nos-peres-etaient-heureux', 6, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ah-que-nos-peres-etaient-heureux', 6, 2, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ah-que-nos-peres-etaient-heureux', 7, 'direction', 1, 'Laatste refrein:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ah-que-nos-peres-etaient-heureux', 8, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 8, 0, 'Amis buvons à nos tonneaux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 8, 1, 'Comme des trous.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 8, 2, 'Comme des trous, morbleu!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 8, 3, 'L’avenir est à nous, morbleu!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ah-que-nos-peres-etaient-heureux', 8, 4, 'L’avenir est à nous.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('l-aimable-fanchon', 'L’AIMABLE FANCHON', 'AIMABLE FANCHON, L’', 'franstalige-liederen', 'fr', NULL, 264, 264, 'Antoine-Charles-Louis de Lasalle, 1798', NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('l-aimable-fanchon', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 0, 0, 'Amis, il faut faire une pause');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 0, 1, 'J’aperçois l’ombre d’un bouchon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 0, 2, 'Buvons à l’aimable Fanchon,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 0, 3, 'Chantons pour elle quelque chose.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('l-aimable-fanchon', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 1, 0, 'Ah! Que son entretien est doux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 1, 1, 'Qu’elle a de mérite et de gloire,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 1, 2, 'Elle aime à rire; elle aime à boire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 1, 3, 'Elle aime à chanter comme nous');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 1, 4, 'Oui, comme nous.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('l-aimable-fanchon', 1, 2, 3, 3, '(TER)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('l-aimable-fanchon', 1, 4, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('l-aimable-fanchon', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 2, 0, 'Fanchon quoique bonne chrétienne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 2, 1, 'Fut baptisée avec du vin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 2, 2, 'Un Bourguignon fut son parrain,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 2, 3, 'Une Bretonne sa marraine.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('l-aimable-fanchon', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 3, 0, 'Fanchon préfère la grillade');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 3, 1, 'A d’autres mets plus délicats,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 3, 2, 'Son teint prend un nouvel éclat');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 3, 3, 'Quand on lui sert une rasade.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('l-aimable-fanchon', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 4, 0, 'Fanchon ne se montre cruelle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 4, 1, 'Que quand on lui parle d’amour.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 4, 2, 'Mais moi, si je lui fais la cour,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 4, 3, 'C’est pour m’enivrer avec elle.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('l-aimable-fanchon', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 5, 0, 'Un jour, le voisin La Grenade');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 5, 1, 'Lui mit la main dans le corset;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 5, 2, 'Ell’répondit par un soufflet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-aimable-fanchon', 5, 3, 'Sur le museau du camarade.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ali-alo-pour-maschero', 'ALI ALO POUR MASCHERO', 'ALI ALO POUR MASCHERO', 'franstalige-liederen', 'fr', NULL, 265, 265, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ali-alo-pour-maschero', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ali-alo-pour-maschero', 0, 0, 'Ali, alo pour Maschero! Ali, alo');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ali-alo-pour-maschero', 0, 1, 'Il mange la viande et nous laisse les os ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ali-alo-pour-maschero', 0, 2, 'Ali, ali, ali, alo... Ali, alo');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ali-alo-pour-maschero', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ali-alo-pour-maschero', 1, 0, 'Ali, alo pour Maschero! Ali, alo');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ali-alo-pour-maschero', 1, 1, 'Il boit de la bière et nous donne de l’eau ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ali-alo-pour-maschero', 1, 2, 'Ali, ali, ali, alo... Ali, alo');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ali-alo-pour-maschero', 2, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ali-alo-pour-maschero', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ali-alo-pour-maschero', 3, 0, 'A chaque morceau il prend le plus gros ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ali-alo-pour-maschero', 3, 1, 'Pour nous les coups, pour lui le magot ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ali-alo-pour-maschero', 3, 2, 'C’est toujours les p’tits qui payent pour les gros ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ali-alo-pour-maschero', 3, 3, 'Lui boit le vin et nous donne de l’eau ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ali-alo-pour-maschero', 3, 4, 'Il fume le cigare et nous donne les mégots ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ali-alo-pour-maschero', 3, 5, 'Moi je suis laid, mais lui l’est pas beau ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ali-alo-pour-maschero', 3, 6, 'On a les p’tits sous, mais lui l’a les gros ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ali-alo-pour-maschero', 3, 7, 'Et qui est malin et qui est le sot ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ali-alo-pour-maschero', 3, 8, 'Il mange le poisson et nous laisse la peau ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ali-alo-pour-maschero', 3, 9, 'On trime dans le froid et lui l’est au chaud ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ali-alo-pour-maschero', 3, 10, 'A chaque morceau, il prend le plus gros ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ali-alo-pour-maschero', 3, 11, 'Lui remplit sa caisse, nous on vide les bateaux ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ali-alo-pour-maschero', 3, 12, 'Il roule en carrosse, nous on tire les charriots ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ali-alo-pour-maschero', 3, 13, 'Il mange du saumon et nous laisse les maquereaux ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ali-alo-pour-maschero', 3, 14, 'Il nous laissera que la peau sur les os ...');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('aloha', 'ALOHA', 'ALOHA', 'franstalige-liederen', 'fr', NULL, 266, 266, 'Nick Trachet, Rikus Daems', NULL, 'PK, 2e prijs Festival de la Chanson Estudiantine, 1982');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('aloha', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 0, 0, 'Quand j’ai bu, le soir sous les étoiles');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 0, 1, 'J’ai Bruxelles étendu à mes pieds');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 0, 2, 'Quand le cantus se termine en guindaille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 0, 3, 'Rêvant des îles je me mets à chanter.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('aloha', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 1, 0, 'À l’ULB, à l’ULB');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 1, 1, 'Le seul plaisir ... c’est s’enivrer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 1, 2, 'l’Avenue Héger, plein’ d’cocotiers');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 1, 3, 'St V, chez les Vahinés.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('aloha', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 2, 0, 'Quand le soir, on est à la Bécasse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 2, 1, 'Et j’observe mon dixième verre d’lambic');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 2, 2, 'Le parfum me transporte dans l’espace');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 2, 3, 'Je m’imagine que j’bois le Pacifique.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('aloha', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 3, 0, 'La seconde session fait des ravages');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 3, 1, 'Mais pour mieux digérer ce coup-là');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 3, 2, 'Pas besoin de sable sur les plages');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 3, 3, 'A Bruxelles nous dirons “Aloha”.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('aloha', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 4, 0, 'Quand je suis rond et tombe dans une ruelle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 4, 1, 'Les vagues m’emportent chez les Vahinés');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 4, 2, 'Mais le matin je m’réveille à Bruxelles');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 4, 3, 'Avenue de la Plaine, à la VUB');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('aloha', 5, 'direction', 1, 'Laatste refrein:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('aloha', 6, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 6, 0, 'À la V.U.B.; à la V.U.B.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 6, 1, 'Tout le plaisir c’est de draguer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 6, 2, 'À la V.U.B.; à la V.U.B');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aloha', 6, 3, 'Allons baiser les Vahinés.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('aloha', 6, 0, 3, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('aupres-de-ma-blonde', 'AUPRÈS DE MA BLONDE', 'AUPRÈS DE MA BLONDE', 'franstalige-liederen', 'fr', NULL, 267, 267, NULL, NULL, 'In 1674 werd het franse eiland Noirmoutiers bezet door het Hollandse leger in de oorlog tegen Lodewijk XV. Om de koning tot betaling van losgeld te dwingen, werden zes bewoners van het eiland twee jaar in Amsterdam vastgehouden. Eén van hen, Joseph André Joubert, zou dit lied geschreven hebben tijdens zijn ballingschap.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('aupres-de-ma-blonde', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aupres-de-ma-blonde', 0, 0, 'Dans les jardins d’mon père les lilas ont fleuri');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aupres-de-ma-blonde', 0, 1, 'Tous les oiseaux du monde vienn’nt y faire leur nid.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('aupres-de-ma-blonde', 0, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('aupres-de-ma-blonde', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aupres-de-ma-blonde', 1, 0, 'Auprès de ma blonde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aupres-de-ma-blonde', 1, 1, 'Qu’il fait bon, fait bon, fait bon,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aupres-de-ma-blonde', 1, 2, 'Auprès de ma blonde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aupres-de-ma-blonde', 1, 3, 'Qu’il fait bon dormir.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('aupres-de-ma-blonde', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aupres-de-ma-blonde', 2, 0, 'Tous les oiseaux du monde vienn’nt y faire leur nid,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aupres-de-ma-blonde', 2, 1, 'La caille, la tourterelle et la jolie perdrix.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('aupres-de-ma-blonde', 2, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('aupres-de-ma-blonde', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aupres-de-ma-blonde', 3, 0, '... Et ma jolie colombe, qui chante jour et nuit.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aupres-de-ma-blonde', 3, 1, '... Qui chante pour les filles qui n’ont point de mari.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aupres-de-ma-blonde', 3, 2, '... Pour moi ne chante guère car j’en ai un joli.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aupres-de-ma-blonde', 3, 3, '... Dites-nous donc, la belle, où donc est votr’ mari?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aupres-de-ma-blonde', 3, 4, '... Il est dans la Hollande, les Hollandais l’ont pris.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aupres-de-ma-blonde', 3, 5, '... Que donneriez-vous, belle, pour avoir votre ami?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aupres-de-ma-blonde', 3, 6, '... Je donnerai Versailles, Paris et Saint-Denis.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aupres-de-ma-blonde', 3, 7, '... Les tours de Notre-Dame et l’clocher d’mon pays.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('aupres-de-ma-blonde', 3, 8, '... Et ma jolie colombe qui chante jour et nuit.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('au-trente-et-un-du-mois-d-aout', 'AU TRENTE ET UN DU MOIS D’AOÛT', 'AU TRENTE ET UN DU MOIS D’AOÛT', 'franstalige-liederen', 'fr', NULL, 268, 269, NULL, '‘Le Corsaire’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('au-trente-et-un-du-mois-d-aout', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 0, 0, 'Au trente-et-un du mois d’août');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 0, 1, 'Nous vîm’s venir sous l’vent à nous');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 0, 2, 'Une frégate d’Angleterre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 0, 3, 'Qui fendait la mer-z-et les flots:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 0, 4, 'C’était pour bombarder Bordeaux.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('au-trente-et-un-du-mois-d-aout', 0, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('au-trente-et-un-du-mois-d-aout', 0, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('au-trente-et-un-du-mois-d-aout', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 1, 0, 'Buvons un coup, buvons en deux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 1, 1, 'A la santé des amoureux.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 1, 2, 'A la santé du Roi de France,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 1, 3, 'Et merd’ pour le Roi d’Angleterre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 1, 4, 'Qui nous a déclaré la guerre!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('au-trente-et-un-du-mois-d-aout', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 2, 0, 'Le capitain’ du bâtiment');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 2, 1, 'Fit appeler son lieutenant,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 2, 2, '“Lieutenant, te sens-tu capable:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 2, 3, 'Dis-moi, te sens-tu assez fort');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 2, 4, 'Pour prendre l’Anglais à son bord?”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('au-trente-et-un-du-mois-d-aout', 2, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('au-trente-et-un-du-mois-d-aout', 2, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('au-trente-et-un-du-mois-d-aout', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 3, 0, 'Le lieutenant, fier-z-et hardi');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 3, 1, 'Lui répondit: “Capitain’-z-oui!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 3, 2, 'Fair’s branle-bas à l’équipage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 3, 3, 'Je vais hisser le pavillon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 3, 4, 'Qui rest’ra haut nous le jurons!”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('au-trente-et-un-du-mois-d-aout', 3, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('au-trente-et-un-du-mois-d-aout', 3, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('au-trente-et-un-du-mois-d-aout', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 4, 0, 'Le maître donne un coup d’sifflet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 4, 1, 'Cargue les voiles au perroquet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 4, 2, 'File l’écoute et vent arrière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 4, 3, 'Laisse porter jusqu’à son bord');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 4, 4, 'On verra bien qui s’ra le plus fort!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('au-trente-et-un-du-mois-d-aout', 4, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('au-trente-et-un-du-mois-d-aout', 4, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('au-trente-et-un-du-mois-d-aout', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 5, 0, 'Vir’ lof pour lof, au même instant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 5, 1, 'Nous l’attaquâm’s par son avant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 5, 2, 'A coups de haches d’abordage,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 5, 3, 'De sabres, piq’s et mousquetons,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 5, 4, 'Nous l’eûm’s vit’ mis à la raison.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('au-trente-et-un-du-mois-d-aout', 5, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('au-trente-et-un-du-mois-d-aout', 5, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('au-trente-et-un-du-mois-d-aout', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 6, 0, 'Que dira-t-on dudit bateau');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 6, 1, 'En Angleterr’-z-et à Bordeaux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 6, 2, 'Qu’a laissé prendr’ son équipage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 6, 3, 'Par un corsair’ de six canons,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('au-trente-et-un-du-mois-d-aout', 6, 4, 'Lui qu’en avait trente et si bons?');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('au-trente-et-un-du-mois-d-aout', 6, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('au-trente-et-un-du-mois-d-aout', 6, 1, 1, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-ballade-des-braves-gueux', 'LA BALLADE DES BRAVES GUEUX', 'BALLADE DES BRAVES GUEUX, LA', 'franstalige-liederen', 'fr', NULL, 269, 270, 'Philippe Vandermeer, BSG', '‘La ballade des gens heureux’, Gérard Lenorman', 'Winnend lied, Festival de la Chanson Estudiantine, 1991');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-des-braves-gueux', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 0, 0, 'Chers amis qui aimez la rigolade');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 0, 1, 'Approchez, écoutez-nous un peu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 0, 2, 'On vient vous chanter la ballade');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 0, 3, 'La ballade des Braves Gueux');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-braves-gueux', 0, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-des-braves-gueux', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 1, 0, 'C’était au temps où il n’y avait pas de guindailles');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 1, 1, 'Les Espagnols occupaient nos lieux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 1, 2, 'Ils ont perdu une grande bataille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 1, 3, 'La bataille des Braves Gueux');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-braves-gueux', 1, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-des-braves-gueux', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 2, 0, 'Nos ancêtres étant buveurs capables');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 2, 1, 'La bière coulait non pas un petit peu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 2, 2, 'L’odeur était invraisemblable');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 2, 3, 'Increvables, les Braves Gueux');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-braves-gueux', 2, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-des-braves-gueux', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 3, 0, 'Les Espagnols n’ayant plus d’oxygène');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 3, 1, 'Tombaient par terre comm’ des moustiques lépreux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 3, 2, 'En maudissant la mauvaise haleine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 3, 3, 'La mauvaise haleine des Braves Gueux');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-braves-gueux', 3, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-des-braves-gueux', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 4, 0, 'Nos héros voyaient périr les malades');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 4, 1, 'Et ils criaient “Sacré nom de Dieu!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 4, 2, 'Ils subiront toutes nos brimades');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 4, 3, 'Les brimades des Braves Gueux');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-braves-gueux', 4, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-des-braves-gueux', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 5, 0, 'Les Espagnols après cette bastonade');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 5, 1, 'Sont retournés comm’ des moutons chatouilleux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 5, 2, 'Laissant place à une grande parade');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 5, 3, 'La parade des Braves Gueux');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-braves-gueux', 5, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-des-braves-gueux', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 6, 0, 'La morale de cette histoire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 6, 1, 'On vous la révélera d’ici peu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 6, 2, 'C’est simplement que vous d’vez boire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 6, 3, 'Vous devez boire aux Braves Gueux');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-braves-gueux', 6, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-des-braves-gueux', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 7, 0, 'Si toi aussi tu aimes les rasades');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 7, 1, 'Et détestes tout occupant fâcheux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 7, 2, 'Tu seras notre camarade');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-braves-gueux', 7, 3, 'Camarade des Braves Gueux');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-braves-gueux', 7, 2, 3, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-ballade-des-cocus', 'LA BALLADE DES COCUS', 'BALLADE DES COCUS, LA', 'franstalige-liederen', 'fr', NULL, 270, 272, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-des-cocus', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 0, 0, 'C’est pour la somme de dix francs,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 0, 1, 'Qu’on fait cocu un étudiant.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 0, 2, 'Les étudiants eux-autres');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 0, 3, 'En font cocus bien d’autres');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-cocus', 0, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-cocus', 0, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-des-cocus', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 1, 0, 'Et tout au long d’la s’maine, les cocus se promènent.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 1, 1, 'Cocu, cocu, cocu, cocu, cocu, cocu!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 1, 2, 'Mon dieu qu’ les cocus sont heureux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 1, 3, 'Quand on leur tient la chandelle.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 1, 4, 'Mon dieu qu’ les cocus sont heureux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 1, 5, 'Quand donc le serais-j’ comme eux.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-des-cocus', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 2, 0, 'C’est pour la somme d’un florin,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 2, 1, 'Qu’on fait cocu un pharmacien.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 2, 2, 'Les pharmaciens eux-autres');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 2, 3, 'En font cocus bien d’autres');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-cocus', 2, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-cocus', 2, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-des-cocus', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 3, 0, 'C’est pour la somme d’un ducat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 3, 1, 'Qu’on fait cocu un avocat.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 3, 2, 'Les avocats eux-autres');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 3, 3, 'En font cocus bien d’autres');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-cocus', 3, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-cocus', 3, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-des-cocus', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 4, 0, 'C’est pour la somme d’un kopeck,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 4, 1, 'Qu’on fait cocu la polytech.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 4, 2, 'Les polytech eux-autres');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 4, 3, 'En font cocus bien d’autres');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-cocus', 4, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-cocus', 4, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-des-cocus', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 5, 0, 'C’est pour la somm’ de presque rien,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 5, 1, 'Qu’on fait cocus les trois doyens.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 5, 2, 'Les trois doyens eux-autres,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 5, 3, 'En font cocus peu d’autres');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-cocus', 5, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-cocus', 5, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-des-cocus', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 6, 0, 'C’est pour la somme d’un douro,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 6, 1, 'Qu’on fait cocu tout’ la philo.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 6, 2, 'Les philosophes eux-autres');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 6, 3, 'En font cocus bien d’autres');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-cocus', 6, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-cocus', 6, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-des-cocus', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 7, 0, 'C’est pour la somm’ d’un fifrelin,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 7, 1, 'Qu’on fait cocu un carabin.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 7, 2, 'Les carabins eux-autres');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 7, 3, 'En font cocus bien d’autres');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-cocus', 7, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-cocus', 7, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-des-cocus', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 8, 0, 'C’est pour la somm’ d’un’ pièc’ de bois,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 8, 1, 'Qu’on fait cocus tous les bourgeois.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 8, 2, 'Tous les bourgeois eux-autres');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 8, 3, 'N’en font cocu point d’autre ...');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-cocus', 8, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-cocus', 8, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-des-cocus', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 9, 0, 'Et moi j’ m’en fous si j’ suis cocu,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 9, 1, 'Pourvu qu’ ça m’ rapporte un écu.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 9, 2, 'Avec l’écu des autres,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-des-cocus', 9, 3, 'J’en f’rai cocu bien d’autres ...');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-cocus', 9, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ballade-des-cocus', 9, 1, 1, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-ballade-du-mutant', 'LA BALLADE DU MUTANT', 'BALLADE DU MUTANT, LA', 'franstalige-liederen', 'fr', NULL, 272, 273, NULL, '‘Malheur à celui qui blesse un enfant’, Enrico Macias, 1976 Corporation Bruxellensis, Festival de la chanson estudiantine, 1981', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-du-mutant', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-du-mutant', 0, 0, 'Il est né un soir près d’un’ central’ nucléaire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-du-mutant', 0, 1, 'D’un père alcoolique et d’un’ mère éthéromane');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-du-mutant', 0, 2, 'Il avait trois jambes, de longs bras tous verts');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-du-mutant', 0, 3, 'Son grand nez tout jaune luisait comme un’ banane.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-du-mutant', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-du-mutant', 1, 0, 'Qu’il soit vert ou bleu, depuis sa naissance');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-du-mutant', 1, 1, 'Il a les yeux roug’s il est plein d’excroissances');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-du-mutant', 1, 2, 'Qu’il soit asthmatique, goîtreux ou rampant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-du-mutant', 1, 3, 'Malheur à celui qui blesse un mutant.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-du-mutant', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-du-mutant', 2, 0, 'Dans l’institution où l’on plaça le p’tit chauve');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-du-mutant', 2, 1, 'Il faisait bien rire avec sa douzain’ de doigts');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-du-mutant', 2, 2, 'Il faut reconnaître qu’une main tout’ mauve');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-du-mutant', 2, 3, 'Ça n’est pas courant sur la têt’ d’un p’tit gars.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-du-mutant', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-du-mutant', 3, 0, 'Il y avait des jours où c’était dur pour l’ pauvr’ gosse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-du-mutant', 3, 1, 'Quand avec un’ sonde il fallait l’alimenter');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-du-mutant', 3, 2, 'Car je n’vous l’ai pas dit, mais en plus d’sa bosse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-du-mutant', 3, 3, 'Le pauvre chéri était paralysé.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ballade-du-mutant', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-du-mutant', 4, 0, 'Et quand il eut l’âge enfin d’aller voir les filles');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-du-mutant', 4, 1, 'Qu’il voulut sortir sa queue en forme de tire-bouchon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-du-mutant', 4, 2, 'Sa petit’ peau flasque était molle et sans vie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ballade-du-mutant', 4, 3, 'Et sa couille unique avait l’air d’un ballon.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('bandais-tu', 'BANDAIS-TU?', 'BANDAIS-TU?', 'franstalige-liederen', 'fr', NULL, 273, 274, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bandais-tu', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 0, 0, 'Si tous les pavés étaient des biroutes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 0, 1, 'On verrait les femmes s’coucher sur les routes.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bandais-tu', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 1, 0, 'Bandais-tu, ban-ban-ban, bandais-tu fort');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 1, 1, 'Quand tu pelotais les nichons d’Adèle?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 1, 2, 'Bandais-tu, ban-ban-ban, bandais-tu fort');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 1, 3, 'Quand tu tripotais ces divins trésors?');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bandais-tu', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 2, 0, 'Si les cons poussaient comm’ des pomm’s de terre,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 2, 1, 'On verrait les pin’s labourer la terre.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bandais-tu', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 3, 0, 'Si tous les curés n’avaient plus de verges,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 3, 1, 'On verrait les nonn’s employer des cierges.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bandais-tu', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 4, 0, 'Si les cons nageaient comme des grenouilles,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 4, 1, 'On verrait flotter plus d’un’ pair’ de couilles.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bandais-tu', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 5, 0, 'Si les cons volaient comme des bécasses,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 5, 1, 'On verrait les pines partir à la chasse.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bandais-tu', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 6, 0, 'Si tout’s les putains étaient lumineuses,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 6, 1, 'La terr’ ne serait qu’une immens’ veilleuse.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bandais-tu', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 7, 0, 'Si tous les cocus avaient des clochettes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 7, 1, 'On n’ s’entendrait plus sur notre planète.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bandais-tu', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 8, 0, 'Si les cons nichaient comm’ des hirondelles,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 8, 1, 'On verrait les vits monter à l’échelle.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bandais-tu', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 9, 0, 'Si les cons pissaient de l’encre de Chine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 9, 1, 'On verrait s’y tremper toutes les pines.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bandais-tu', 10, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 10, 0, 'Si les cons savaient l’ théorèm’ de Rolle,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 10, 1, 'On verrait les vits leur poser des colles.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bandais-tu', 11, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 11, 0, 'Si les cons dansaient comm’ des ballerines,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bandais-tu', 11, 1, 'On verrait les log’s se garnir de pines.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ben-laden', 'BEN LADEN', 'BEN LADEN', 'franstalige-liederen', 'fr', NULL, 275, 276, 'Guilde Horus', '‘Dirk Frimout’, Les Snuls', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ben-laden', 0, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 0, 0, 'Ben, Ben Laden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 0, 1, 'Ben (X 3), Ben Laden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 0, 2, 'Ben (X 7), Ben Laden');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ben-laden', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 1, 0, 'Je m’appelle Ben Laden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 1, 1, 'J’suis pas terroriste tchétchène');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 1, 2, 'Moi, c’est pas à la machette');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 1, 3, 'Que je vais couper vos têtes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 1, 4, 'Moi je préfère l’aviation');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 1, 5, 'Ça fait plus de sensations');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 1, 6, 'Regardez le WTC,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 1, 7, 'C’est moi qui l’ai rasé');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ben-laden', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 2, 0, 'Je m’appelle Ben Laden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 2, 1, 'Je suis planqué dans ma caverne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 2, 2, 'Tout au fond de l’Afghanistan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 2, 3, 'Protégé par les Talibans');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 2, 4, 'Planqué sous ma Burka');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 2, 5, 'Double-V, y m’trouv’ra pas');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 2, 6, 'Si j’ai plus d’timbre pour l’anthrax,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 2, 7, 'Je l’lui envoie par fax');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ben-laden', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 3, 0, 'Je m’appelle Ben Laden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 3, 1, 'Et j’ai plein de mauvaises nouvelles');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 3, 2, 'Ils ont pétés mon chez-moi');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 3, 3, 'Emprisonnés tout Al-Qaïda');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 3, 4, 'Il reste plus que mon pote Omar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 3, 5, 'Qui a perdu la mémoire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 3, 6, 'Avec sa Honda 500');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 3, 7, 'Il se croit à Francorchamps');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ben-laden', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 4, 0, 'Je m’appelle Ben Laden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 4, 1, 'Maintenant je loge à l’hôtel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 4, 2, 'Un cinq étoiles d’Islamabad');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 4, 3, 'Ca vaut toujours mieux qu’à Bagdad');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 4, 4, 'C’est bientôt le 11 septembre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 4, 5, 'Le monde n’en peut plus d’attendre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 4, 6, 'Vais-je encore tout faire péter');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 4, 7, 'Où juste laisser parler');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ben-laden', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 5, 0, '36-15 code Ben Laden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 5, 1, 'Maintenant je suis sur le minitel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 5, 2, 'Grâce aux fonds de la CIA');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 5, 3, 'J’ai pu monter ma S.A.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 5, 4, 'Bali, Washington, Moscou');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 5, 5, 'À chaque fois, je suis dans le coup');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 5, 6, 'Al-Jazeera m’interview');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ben-laden', 5, 7, 'Et moi j’nique Double-U');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-biere', 'LA BIÈRE', 'BIÈRE, LA', 'franstalige-liederen', 'fr', NULL, 276, 277, NULL, NULL, 'T & M: Antoine Clesse (Bergen)
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-biere', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 0, 0, 'Elle a vraiment d’une bière flamande');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 0, 1, 'L’air avenant, l’éclat et la douceur,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 0, 2, 'Joyeux Wallons, elle nous affriande');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 0, 3, 'Et le Faro trouve en elle une soeur.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-biere', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 1, 0, 'À plein verre, mes bons amis,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 1, 1, 'En la buvant, il faut chanter la bière,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 1, 2, 'À plein verre, mes bons amis.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 1, 3, 'Il faut chanter la bière du pays.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-biere', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 2, 0, 'Voyez là-bas la kermesse en délire:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 2, 1, 'Les pots sont pleins, jouez ménétriers!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 2, 2, 'Quels jeux bruyants et quels éclats de rire!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 2, 3, 'Ce sont encore les Flamands de Teniers!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-biere', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 3, 0, 'Aux souverains, portant tout haut leurs plaintes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 3, 1, 'Bourgeois jaloux des droits de la cité,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 3, 2, 'Nos francs aïeux, tout en vidant leur pinte,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 3, 3, 'Fondaient les arts avec la liberté.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-biere', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 4, 0, 'Quand leurs tribuns à l’attitude altière,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 4, 1, 'Faisaient sonner le tocsin des beffrois,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 4, 2, 'Tous ces fumeurs, tous ces buveurs de Bière,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 4, 3, 'Savaient combattre et mourir pour leurs droits.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-biere', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 5, 0, 'Belges, chantons, à ce refrein à boire,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 5, 1, 'Peintres, guerriers qui nous illustrent tous,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 5, 2, 'Géants couchés dans leur linceul de gloire,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 5, 3, 'Vont se lever, pour redire avec nous.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-biere', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 6, 0, 'Salut à toi, Bière limpide et blonde!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 6, 1, 'Je tiens mon verre, et le bonheur en main,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 6, 2, 'Ah! J’en voudrais verser à tout le monde,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-biere', 6, 3, 'Pour le bonheur de tout le genre humain.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-bite-a-dudule', 'LA BITE A DUDULE', 'BITE A DUDULE, LA', 'franstalige-liederen', 'fr', NULL, 278, 279, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-bite-a-dudule', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 0, 0, 'Il était deux amants');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 0, 1, 'Qui s’aimaient tendrement;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 0, 2, 'Ils étaient heureux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 0, 3, 'Et du soir au matin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 0, 4, 'Ils allaient au turbin,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 0, 5, 'Le coeur plein d’entrain.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 0, 6, 'À l’atelier, les copin’s lui disaient:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 0, 7, '“Pourquoi qu’ tu l’aim’s, ton Dudule?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 0, 8, 'Il est pas beau, il est mal fait”;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 0, 9, 'Mais elle, tendrement, répondait:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 0, 10, '“Z’ en fait’s pas, tagadagada,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 0, 11, 'Les amies tiguidiguidi,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 0, 12, 'Moi c’que j’aime en lui ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-bite-a-dudule', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 1, 0, 'C’est la gross’ bite à Dudule,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 1, 1, 'J’la prends, j’la suce, elle m’encule,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 1, 2, 'Ah! Que c’est bon que c’est chaud, que c’est rond');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 1, 3, 'Quand il m’la cale dans l’oignon!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 1, 4, 'C’est pas un’ bite ordinaire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 1, 5, 'Quand il m’la fout dans l’derrière,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 1, 6, 'De foutre et de merde elle est toute remplie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 1, 7, 'Des couill’s jusqu’au nombril,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 1, 8, 'À Dudu-ule.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-bite-a-dudule', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 2, 0, 'Ça durait d’puis longtemps');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 2, 1, 'Entre les deux amants');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 2, 2, 'Ça dev’nait gênant.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 2, 3, 'Voilà que d’jour en jour');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 2, 4, 'S’accroissait leur amour,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 2, 5, 'C’était pour toujours.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 2, 6, 'Quand un’ bell’ fill’ pas trop mal fagotée');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 2, 7, 'Vint lui chiper son Dudule,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 2, 8, 'L’était pas beau, l’était mal fait,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 2, 9, 'Mais elle, tendrement, répondait:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 2, 10, '“Z’ en fait’s pas, tagadagada,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 2, 11, 'Les amies tiguidiguidi,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 2, 12, 'Moi c’que j’aime en lui ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-bite-a-dudule', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 3, 0, 'J’étais seule un beau soir');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 3, 1, 'J’avais perdu l’espoir');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 3, 2, 'Je broyais du noir.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 3, 3, 'Mais voilà que l’on sonne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 3, 4, 'Je n’attendais personne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 3, 5, 'Je reprends espoir.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 3, 6, 'Mon petit coeur s’ mit à faire boum-boum!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 3, 7, 'Si c’était là mon Dudule?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 3, 8, 'L’était pas beau, l’était mal fait,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 3, 9, 'Mais moi, tendrement, je l’aimais.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 3, 10, 'J’ouvr’ la porte, tagadagada,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 3, 11, 'J’tends les bras, tagadagada');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bite-a-dudule', 3, 12, 'Et qu’est-ce que je vois ...');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('le-bordel-a-ferme-ses-volets', 'LE BORDEL A FERMÉ SES VOLETS', 'BORDEL A FERMÉ SES VOLETS, LE', 'franstalige-liederen', 'fr', NULL, 280, 281, NULL, '‘La guinguette a fermé ses volets’, Léon Montagné', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-bordel-a-ferme-ses-volets', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 0, 0, 'Le bordel a fermé ses volets;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 0, 1, 'Ell’s sont tout’s vérolées,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 0, 2, 'Y’a plus moyen qu’on baise;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 0, 3, 'L’ dernier qu’ est allé pour s’fair’ faire un pompier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 0, 4, 'Est rev’nu avec la pin’ enflée. Ohé!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 0, 5, 'Le toubib, qui les a visitées,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 0, 6, 'A tout d’suit’ déclaré:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 0, 7, '“Y faut plus qu’on les baise.”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 0, 8, 'La maréchaussée les a toutes bouclées,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 0, 9, 'Et l’bordel a fermé ses volets!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-bordel-a-ferme-ses-volets', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 1, 0, 'Et Totor, qu’est un habitué,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 1, 1, 'A voulu y aller');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 1, 2, 'Disant: “C’est d’la foutaise!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 1, 3, 'Mais trois jours après, y n’pouvait plus marcher');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 1, 4, 'Tant sa pine elle était délabrée. Ohé!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 1, 5, 'À l’hosto, où on l’a transporté');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 1, 6, 'Lui laissant supposer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 1, 7, 'Que ce léger malaise');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 1, 8, 'Ne l’empêch’rait pas de revenir baiser');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 1, 9, 'Quand l’ bordel rouvrirait ses volets.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-bordel-a-ferme-ses-volets', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 2, 0, 'Le toubib lui ayant conseillé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 2, 1, 'De ne plus coïter');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 2, 2, 'Sans un’ capot’ anglaise,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 2, 3, 'Sitôt r’mis sur pied, il en a commandé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 2, 4, 'Douz’ douzain’s avec bout renforcé. Ohé!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 2, 5, 'Au premier coup qu’il a tiré,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 2, 6, 'C’est ses couill’s qu’ont lâché.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 2, 7, 'Pas la capot’ anglaise;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 2, 8, 'On les a r’trouvées aux quatr’ coins du quartier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 2, 9, 'Et l’bordel a r’fermé ses volets');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-bordel-a-ferme-ses-volets', 3, 'direction', 1, 'M: ‘Marche Funèbre’, Frédérique Chopin');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-bordel-a-ferme-ses-volets', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 4, 0, 'Totor n’est plus, les putains l’ont descendu!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 4, 1, 'Un Français d’plus qu’les Anglais auront foutu!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 4, 2, 'Et sa jolie pine, qu’avait si bell’ mine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 4, 3, 'Ne band’ra plus! Ainsi triomph’ la vertu.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-bordel-a-ferme-ses-volets', 5, 'direction', 1, 'M: ‘La guinguette a fermé ses volets’');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-bordel-a-ferme-ses-volets', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 6, 0, 'Le bordel a rouvert ses volets');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 6, 1, 'Par un beau matin d’mai,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 6, 2, 'Au temps des premièr’s fraises,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 6, 3, 'L’personnel était entièr’ment renouv’lé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 6, 4, 'La taulière était tout en beauté! Ohé!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 6, 5, 'La foul’ se pressait et riait,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 6, 6, 'Elle avait oublié');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 6, 7, 'Que l’danger quand on baise');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 6, 8, 'Était de s’confier aux machins anglais');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-bordel-a-ferme-ses-volets', 6, 9, 'Et l’bordel a monté des bidets.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('boudins-et-tequila', 'BOUDINS ET TEQUILA', 'BOUDINS ET TEQUILA', 'franstalige-liederen', 'fr', NULL, 282, 283, NULL, '‘Vive la rose’ Guy Béart', 'Guilde Polytechnique, Festival de la chanson estudiantine, 1992');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('boudins-et-tequila', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 0, 0, 'Partis entre copains');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 0, 1, 'Pour une noble cause');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 0, 2, 'Direction le Gauguin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 0, 3, 'Je ne sais pas si j’ose');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 0, 4, 'Le foie ne tiendra pas');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 0, 5, 'Viv’ la cirrhose, la gueule de bois!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('boudins-et-tequila', 0, 4, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('boudins-et-tequila', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 1, 0, 'Un’ fois sur le terrain');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 1, 1, 'Un p’tit “À-fond” s’impose');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 1, 2, 'Avec un verr’ en main');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 1, 3, 'C’est déjà moins morose');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 1, 4, 'Le foie ne tiendra pas');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 1, 5, 'Viv’ la cirrhose, la gueule de bois!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('boudins-et-tequila', 1, 4, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('boudins-et-tequila', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 2, 0, 'Le lendemain matin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 2, 1, 'Aïe! Aïe! Ma têt’ explose');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 2, 2, 'Je n’ me souviens de rien');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 2, 3, 'Ne cherchons pas la cause');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 2, 4, 'Le lavabo est plein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 2, 5, 'J’ai r’tapissé la sall’ de bain!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('boudins-et-tequila', 2, 4, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('boudins-et-tequila', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 3, 0, 'Mais sous mon traversin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 3, 1, 'Ça ne sent pas la rose');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 3, 2, 'Y a-t-il donc quelqu’un');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 3, 3, 'Infecté de mycoses?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 3, 4, 'Ne cherchons pas plus loin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 3, 5, 'J’ai encore ram’né un boudin!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('boudins-et-tequila', 3, 4, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('boudins-et-tequila', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 4, 0, 'Et si un bon matin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 4, 1, 'Un’ occasion s’arrose');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 4, 2, 'Laissez-lá le brassin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 4, 3, 'Buvez donc autre chose');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 4, 4, 'Frappez la Tequila');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 4, 5, 'Vous courez à votre trépas!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('boudins-et-tequila', 4, 4, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('boudins-et-tequila', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 5, 0, 'Mêm’ si on en revient');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 5, 1, 'De ces orgies grandioses');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 5, 2, 'Avec un intestin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 5, 3, 'Qui se métamorphose');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 5, 4, 'On les regrettera');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('boudins-et-tequila', 5, 5, 'La cirrhose et la Tequila.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('boudins-et-tequila', 5, 4, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('boudins-et-tequila', 6, 'direction', 1, 'Bij de laatste herhaling wordt “Tequila” vervangen door “gueule de bois”.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-bourguignonne', 'LA BOURGUIGNONNE', 'BOURGUIGNONNE, LA', 'franstalige-liederen', 'fr', NULL, 284, 285, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-bourguignonne', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 0, 0, 'C’est dans une vigne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 0, 1, 'Que j’ai vu le jour.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 0, 2, 'Ma mère était digne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 0, 3, 'De tout mon amour.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 0, 4, 'Depuis ma naissance,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 0, 5, 'Elle m’a nourri.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 0, 6, 'En reconnaissance,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 0, 7, 'Mon cœur la chérit.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-bourguignonne', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 1, 0, 'Joyeux enfants de la Bourgogne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 1, 1, 'Je n’ai jamais eu de guignon,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 1, 2, 'Quand je vois rougir ma trogne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 1, 3, 'Je suis fier d’être Bourguignon.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-bourguignonne', 1, 0, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-bourguignonne', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 2, 0, 'Toujours ma bouteille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 2, 1, 'A côté de moi.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 2, 2, 'Buvant sous la treille,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 2, 3, 'Plus heureux qu’ un roi.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 2, 4, 'Jamais je n’ m’ embrouille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 2, 5, 'Car chaque matin,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 2, 6, 'Je me débarbouille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 2, 7, 'Dans un verre de vin.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-bourguignonne', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 3, 0, 'Madère et champagne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 3, 1, 'Approchez un peu;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 3, 2, 'Et vous, vins d’Espagne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 3, 3, 'Malgré tous vos feux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 3, 4, 'Amis de l’ivrogne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 3, 5, 'Réclamez vos droits,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 3, 6, 'Devant la Bourgogne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 3, 7, 'Saluez trois fois!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-bourguignonne', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 4, 0, 'Ma femme est aimable');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 4, 1, 'Et sur ses appas,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 4, 2, 'Quand je sors de table,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 4, 3, 'Je ne m’endors pas.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 4, 4, 'Je lui dis: “Mignonne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 4, 5, 'Je plains ton destin!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 4, 6, 'Mais ma Bourguignonne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 4, 7, 'Jamais ne s’en plaint.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-bourguignonne', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 5, 0, 'Je veux qu’on enterre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 5, 1, 'Quand je serai mort,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 5, 2, 'Près de moi, un verre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 5, 3, 'Empli jusqu’au bord.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 5, 4, 'J’veux êtr’ dans ma cave,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 5, 5, 'Tout près de mon vin,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 5, 6, 'Dans un’ pose grave,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-bourguignonne', 5, 7, 'Le nez sous l’robin.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-brabanconne-d-une-putain', 'LA BRABANÇONNE D’UNE PUTAIN', 'BRABANÇONNE D’UNE PUTAIN, LA', 'franstalige-liederen', 'fr', NULL, 286, 286, NULL, '‘La Brabançonne’, François Van Campenhout, september 1830', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-brabanconne-d-une-putain', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 0, 0, 'Je me souviens, lorsque j’étais jeune fille,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 0, 1, 'D’un jeun’ garçon qui passait par bonheur,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 0, 2, 'Il me trouva si jeune et si gentille,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 0, 3, 'Qu’il me fit voir sa grosse pine en chaleur,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 0, 4, 'Et tout à coup sous mes jupons s’élance,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 0, 5, 'L’énorme queue qu’il tenait à la main,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 0, 6, 'Il déchira mon voile d’innocence,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 0, 7, 'Voilà pourquoi je me suis fait putain!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-brabanconne-d-une-putain', 0, 7, 7, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-brabanconne-d-une-putain', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 1, 0, 'Je ne sais pas si j’étais déjà coquine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 1, 1, 'J’aimais déjà qu’on me chatouillât le bouton,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 1, 2, 'J’avais gouté de ce bon jus de pine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 1, 3, 'J’avais reçu du foutre dans le con,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 1, 4, 'J’avais baisé, je n’étais plus pucelle,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 1, 5, 'Je chérissais le métier de putain,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 1, 6, 'Plus je baisais, plus je devenais belle,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 1, 7, 'Voilà pourquoi je me suis fait putain!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-brabanconne-d-une-putain', 1, 7, 7, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-brabanconne-d-une-putain', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 2, 0, 'Quoique je ne sois qu’une fille publique,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 2, 1, 'J’ai de l’amour et de l’humanité,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 2, 2, 'Tout citoyen de notre libre Belgique,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 2, 3, 'Doit baiser et jouir en liberté,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 2, 4, 'Pour de l’argent, le riche a ma fente,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 2, 5, 'Le pauvre, lui, peut en jouir pour rien,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 2, 6, 'Pour soulager l’humanité souffrante,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-brabanconne-d-une-putain', 2, 7, 'Voilà pourquoi je me suis fait putain!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-brabanconne-d-une-putain', 2, 7, 7, 3, '(TER)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('bruxelles', 'BRUXELLES', 'BRUXELLES', 'franstalige-liederen', 'fr', NULL, 287, 288, NULL, NULL, 'T & M: ‘Ik wil deze nacht ...’, Wannes Van De Velde
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bruxelles', 0, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 0, 0, 'Je veux me promener dans les rues de Bruxelles,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 0, 1, 'Les bruits de cette ville me rendent amoureux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 0, 2, 'Venez voir comm’ toutes les putes sont belles,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 0, 3, 'Vous y trouverez un accueil chaleureux.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bruxelles', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 1, 0, 'Sous la lumière des grands reverbères');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 1, 1, 'On voit un couple s’aimer tendrement');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 1, 2, 'Dans une autre ruelle, une scène cruelle,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 1, 3, 'Deux sales mecs au poing qui se rentrent dedans.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bruxelles', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 2, 0, 'Les étudiants sont en train de guindailler');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 2, 1, 'Dans les bistrots et dans les cafés,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 2, 2, 'Et, dehors dans le froid, un clochard solitaire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 2, 3, 'Cherche une place, pour dormir par terre.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bruxelles', 3, 'chorus-ref', 1, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bruxelles', 4, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 4, 0, 'Ik wil deze nacht in de straten verdwalen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 4, 1, 'De klank van de stad maakt mijn ziel amoureus');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 4, 2, 'Al heb ik geen geld om plezier te betalen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 4, 3, 'Ik vind wel een vrouwke heel net en genereus.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bruxelles', 5, 'direction', 1, 'De volgende malen vervangt men in het refrein ’heel net en genereus’ door ’naar mijne keus’.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bruxelles', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 6, 0, 'Onder de glans van de manestralen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 6, 1, 'Wordt heel onze wereld een huwelijksbed,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 6, 2, 'Ga mee naar de kroegen vol wijven en matrozen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 6, 3, 'Vergeet uwe naam en al de rest.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bruxelles', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 7, 0, 'Laat ons dan samen de wereld verteren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 7, 1, 'Met klinkende glazen vol Franse wijn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 7, 2, 'Zingt mee met de mensen, dat hebben ze geren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bruxelles', 7, 3, 'En laat deze nacht nooit een einde zijn.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('buiten-die-walen', 'BUITEN DIE WALEN', 'BUITEN DIE WALEN', 'franstalige-liederen', 'fr', NULL, 289, 290, 'M. Adriaenssens, K. Biscop, J. De Groote, M. Heiremans', '‘Le Chant des étudiants wallons’', 'De Gilde, winnend lied van het Festival de la Chanson Estudiantine Belge, 2014
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('buiten-die-walen', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 0, 0, 'Dans la nord de belgiek');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 0, 1, 'On dit que c’est le flandre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 0, 2, 'Les autres ces alcooliques');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 0, 3, 'On devrait tous les pendre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 0, 4, 'Le coq patriotique');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 0, 5, 'Par la lion s’fait prendre');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('buiten-die-walen', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 1, 0, 'Car nous n’voulons plus des wallons');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 1, 1, 'Indignes de leurs aïeux nom de dieu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 1, 2, 'Qu’ils restent bien chez eux nom de dieu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 1, 3, 'Disciples d’Elio et de sa gestapo');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('buiten-die-walen', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 2, 0, 'Bartjen était l’élu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 2, 1, 'C’est notre bourgemestre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 2, 2, 'Mais nous en voulons plus');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 2, 3, 'De tout être le eerste');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 2, 4, 'C’est dommage qu’on a cru');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 2, 5, 'Que tout serait une fieste');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('buiten-die-walen', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 3, 0, 'Mais pour nous rien ne change');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 3, 1, 'Malgré ce brave peye');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 3, 2, 'Vous parle d’un libre échange');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 3, 3, 'C’est toujours nous qui paye');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 3, 4, 'Van Voeren à Tihange');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 3, 5, 'On leur met la pareille');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('buiten-die-walen', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 4, 0, 'À nous le VUB');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 4, 1, 'C’est notr’alma mater');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 4, 2, 'Gardez donc vos TD’s');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 4, 3, 'Luigi je préfère');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 4, 4, 'Sans wallons trop bourrés');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 4, 5, 'Qui vident jamais leurs verres');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('buiten-die-walen', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 5, 0, 'Mais nous sommes pragmatistes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 5, 1, 'Nous restons camarades');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 5, 2, 'Sans vous nous serions tristes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 5, 3, 'Plus trop de déconnade');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 5, 4, 'Nous sommes les spécialistes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 5, 5, 'Pour baiser vos pintades');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('buiten-die-walen', 6, 'direction', 1, 'Laatste refrein:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('buiten-die-walen', 7, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 7, 0, 'Car les wallonnes, on les pillonnes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 7, 1, 'Qu’elles sucent le grand phlamand nom de dieu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 7, 2, 'C’est plus gros c’est plus grand nom de dieu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 7, 3, 'On garde les femelles avec les grosses mamelles');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('buiten-die-walen', 8, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 8, 0, 'Want onze Slang, spuit op ’t behang');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 8, 1, 'Van al dat Waals gebleit tedju');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 8, 2, 'Krijg ik het vliegend schijt tedju');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('buiten-die-walen', 8, 3, 'Dus neemt uw pint ter hand en drinkt in eigen land');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('caca-hola', 'CACA HOLA', 'CACA HOLA', 'franstalige-liederen', 'fr', NULL, 291, 292, 'Paul Hanson et son Caca Quartet', 'Reclamemelodie voor Coca-Cola', 'Médecine, Festival de la chanson estudiantine, 1977');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('caca-hola', 0, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 0, 0, 'Un gros caca, une chiasse bien grasse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 0, 1, 'Un bronze bien coulé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 0, 2, 'Une crotte molle, des fèces lubriques');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 0, 3, 'Un étron distingué');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 0, 4, 'Bouffe aujourd’hui');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 0, 5, 'Caca demain');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 0, 6, 'Si tu n’bouffes pas');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 0, 7, 'Pas de caca');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 0, 8, 'Caca à l’eau');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('caca-hola', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 1, 0, 'Y en a des p’tits, y en a des gros,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 1, 1, 'Y en a de tous menus.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 1, 2, 'Y en a des mous, y en a des durs');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 1, 3, 'Y en a de bien dodus.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('caca-hola', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 2, 0, 'C’est chaud, c’est rond, c’est doux, c’est bon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 2, 1, 'Ça fait du bien par où ça passe');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 2, 2, 'C’est chaud, c’est rond, c’est bon, c’est doux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 2, 3, 'Quand ça passe par mon p’tit trou.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('caca-hola', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 3, 0, 'Bien calés au fond du derrière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 3, 1, 'Y’en a des durs qui se terrent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 3, 2, 'On les décale d’un jet d’clystère');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 3, 3, 'C’est la fin du mystère.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('caca-hola', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 4, 0, 'Jamais les goûts ni les couleurs');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 4, 1, 'Ne se discuteront');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 4, 2, 'Ni les égouts ni les odeurs');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 4, 3, 'Jamais ne disparaîtront.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('caca-hola', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 5, 0, 'Ceux qui au bout de cette chanson');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 5, 1, 'N’ont vraiment rien pigé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 5, 2, 'Nous vous jurons chers compagnons');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caca-hola', 5, 3, 'Ce sont des constipés.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('caroline-la-putain', 'CAROLINE, LA PUTAIN', 'CAROLINE, LA PUTAIN', 'franstalige-liederen', 'fr', NULL, 292, 294, 'Marion de Mersan, 1770', 'Air de cor', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('caroline-la-putain', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 0, 0, 'Amis, amis, versez à boire,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 0, 1, 'Versez à boir’ et du bon vin,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 0, 2, 'Tintin, tintin, tintain’ et tintin.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 0, 3, 'Je m’en vais vous conter l’histoire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 0, 4, 'De Caroline, la putain');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 0, 5, 'Tintin, tintain’ et tintin.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('caroline-la-putain', 1, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('caroline-la-putain', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 2, 0, 'Son pèr’ était un machiniste');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 2, 1, 'Au théâtre de l’Odéon ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 2, 2, 'Sa mèr’ était une fleuriste');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 2, 3, 'Qui vendait sa fleur en bouton ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('caroline-la-putain', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 3, 0, 'Elle perdit son pucelage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 3, 1, 'Le jour d’sa premièr’ communion, ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 3, 2, 'Avec un garçon de son âge');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 3, 3, 'Derrièr’ les fortifications ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('caroline-la-putain', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 4, 0, 'À quatorz’ ans, suçant les pines,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 4, 1, 'Elle fit son éducation, ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 4, 2, 'À dix-huit ans, dans la débine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 4, 3, 'Elle s’engagea dans un boxon ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('caroline-la-putain', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 5, 0, 'À vingt-quatr’ ans, sur ma parole,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 5, 1, 'C’était une fière putain, ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 5, 2, 'Elle avait foutu la vérole');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 5, 3, 'Au trois quarts du Quartier Latin ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('caroline-la-putain', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 6, 0, 'Le marquis de la Couillemolle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 6, 1, 'Lui fit bâtir une maison, ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 6, 2, 'À l’enseign’ du “Morpion qui Vole”,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 6, 3, 'Une bell’ enseign’ pour un boxon ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('caroline-la-putain', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 7, 0, 'Elle voulut aller à Rome');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 7, 1, 'Pour recevoir l’absolution ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 7, 2, 'Le pape était fort bien à Rome,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 7, 3, 'Mais il était dans un boxon ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('caroline-la-putain', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 8, 0, 'Et s’adressant au grand vicaire,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 8, 1, 'Elle dit: “J’ai trop prêté mon con ... ”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 8, 2, '“Si tu l’as tant prêté, ma chère,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 8, 3, 'À moi aussi, prête-le donc ... ”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('caroline-la-putain', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 9, 0, 'En la serrant entre ses cuisses,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 9, 1, 'Il lui donna l’absolution, ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 9, 2, 'Il attrapa la chaude-pisse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 9, 3, 'Et trent’-six douzain’s de morpions ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('caroline-la-putain', 10, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 10, 0, 'Elle finit cette tourmente');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 10, 1, 'Entre les bras d’un marmiton ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 10, 2, 'Elle mourut la pin’ au ventre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 10, 3, 'Le con fendu jusqu’au menton ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('caroline-la-putain', 11, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 11, 0, 'Et quand on la mit dans la bière,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 11, 1, 'On vit pleurer tous ses morpions, ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 11, 2, 'Et quand on la mit dans la terre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('caroline-la-putain', 11, 3, 'Ils entonnèr’nt cette chanson ...');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-ceinture', 'LA CEINTURE', 'CEINTURE, LA', 'franstalige-liederen', 'fr', NULL, 294, 295, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ceinture', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 0, 0, 'Partant pour la croisade, un sire fort jaloux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 0, 1, 'De l’honneur de son nom et de son droit d’époux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 0, 2, 'Fit fair’ une ceintur’ à solide fermoir');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 0, 3, 'Qu’il attacha lui-mêm’ à sa femm’ un beau soir.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ceinture', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 1, 0, 'Tra la la la la lère, tra la la la la la');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-ceinture', 1, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ceinture', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 2, 0, 'Une fois son honneur solidement bouclé,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 2, 1, 'Le sire s’en alla en emportant la clef');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 2, 2, 'Depuis la tendr’ Yseult soupire nuit et jour:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 2, 3, '“Quand donc t’ouvriras-tu, prison de mes amours?”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ceinture', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 3, 0, 'Elle fit la rencontre le soir au fond d’un bois,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 3, 1, 'D’un jeune troubadour, poète montmartrois,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 3, 2, 'Elle lui demanda gentiment d’essayer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 3, 3, 'Si d’un poèt’ l’amour peut fair’ un serrurier.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ceinture', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 4, 0, 'Elle était désirable et belle tant et tant,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 4, 1, 'Que le fermoir céda et qu’elle en fit autant.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 4, 2, 'Depuis bientôt deux ans durait leur tendr’amour,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 4, 3, 'Quand le seigneur revint avec corn’s et tambours.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ceinture', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 5, 0, 'La bell’ étant enceinte depuis bientôt neuf mois,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 5, 1, 'S’écria: “Sur ma vie, quel malheur j’entrevois,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 5, 2, 'En mettant la ceintur’ et la serrant un peu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 5, 3, 'Notre seigneur jaloux n’y verra que du feu.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ceinture', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 6, 0, 'Le sir’ s’en aperçut et se mit en courroux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 6, 1, '“Seigneur, s’écria-t-elle, cet enfant est de vous!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 6, 2, 'Depuis votre départ, votre fils enfermé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 6, 3, 'Attend votre retour pour être délivré.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-ceinture', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 7, 0, '“Miracle, cria-t-il, femm’ au con vertueux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 7, 1, 'Ouvrons vite la porte au fils respectueux!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 7, 2, 'De joie, la tendr’ Yseult, à ces mots, enfantait');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-ceinture', 7, 3, 'Et depuis, la ceintur’, c’est lui qui s’la mettait.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 'C’ÉTAIT AU TEMPS QUE BRUXELLES GUINDAILLAIT', 'C’ÉTAIT AU TEMPS QUE BRUXELLES GUINDAILLAIT', 'franstalige-liederen', 'fr', NULL, 295, 297, NULL, '‘Bruxelles bruxellait’, P. Jouannest door Jacques Brel', 'CEB, Festival de la Chanson Estudiantine, 1980');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 0, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 0, 0, 'C’était au temps où Bruxelles guindaillait');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 0, 1, 'C’était au temps où les students buvaient!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 0, 2, 'C’était au temps où Bruxelles se marrait');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 0, 3, 'C’était au temps où les students chantaient!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 1, 0, 'Place de Brouckère on bouffait des marrons');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 1, 1, 'On dégueulait tell’ment on était ronds.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 1, 2, 'En ce temps-là on avait la vérole');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 1, 3, 'On n’en bouffait pas moins des caracoles.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 1, 4, 'Et plac’ Saint’-Cath’rine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 1, 5, 'On montrait nos pines');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 1, 6, 'Et aussi nos fesses');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 1, 7, 'Après la grand’ messe');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 1, 8, 'Et le vieux vicaire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 1, 9, 'Ne sachant que faire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 1, 10, 'Nous engueulait, on s’en foutait');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 1, 11, 'Et on faisait c’qui nous plaisait.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 2, 0, 'Au Grand Sablon démarrait la St V');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 2, 1, 'On y voyait des pennes par milliers.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 2, 2, 'À la Grand’ Place, on était tous bourrés');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 2, 3, 'À l’ “Amigo”, les flics nous ont emm’nés');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 2, 4, 'Et rue de l’étuve');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 2, 5, 'Dans sa petit’ cuve');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 2, 6, 'Y’avait Manneken Pis');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 2, 7, 'Qu’ entret’nait sa chaud’-pisse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 2, 8, 'Souvenir d’une Ibère');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 2, 9, 'Qui s’était laissée faire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 2, 10, 'Des petits seins, un gros vagin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 2, 11, 'Il s’en foutait, elle baisait bien.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 3, 0, 'À la Bourse on s’arrêtait pour chanter');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 3, 1, '“Le Semeur”, en choeur était entonné.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 3, 2, 'Puis tous ensemble on r’gagnait l’ULB');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 3, 3, 'Où la soirée n’ faisait que commencer.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 3, 4, 'À la Mort Subite');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 3, 5, 'On s’foutait un’ cuite');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 3, 6, 'En buvant de la Kriek');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 3, 7, 'Et aussi du Lambic,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 3, 8, 'Et chaussée d’ Boondael(e)');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 3, 9, 'On s’rinçait la dalle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 3, 10, 'Puis au Villon, là chez Simon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 3, 11, 'On n’arrêtait pas d’fair’ les cons.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 4, 'direction', 1, 'Laatste refrein:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 5, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 5, 0, 'C’était au temps où Bruxelles guindaillait');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 5, 1, 'C’était au temps où les students buvaient!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 5, 2, 'C’était au temps où Bruxelles se marrait,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('c-etait-au-temps-que-bruxelles-guindaillait', 5, 3, 'C’était au temps où le folklore vivait!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('chanson-a-boire', 'CHANSON À BOIRE', 'CHANSON À BOIRE', 'franstalige-liederen', 'fr', NULL, 298, 298, 'Gabriël Bataille, 1615', 'Tri Yann', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chanson-a-boire', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-a-boire', 0, 0, 'Qui veut chasser une migraine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-a-boire', 0, 1, 'N’a qu’à boire toujours du bon,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-a-boire', 0, 2, 'Et maintenir la table pleine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-a-boire', 0, 3, 'De servelas et de jambon.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chanson-a-boire', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-a-boire', 1, 0, 'L’eau ne fait rien que pourrir le poulmon,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-a-boire', 1, 1, 'Boute, boute, boute, boute compagnons,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-a-boire', 1, 2, 'Vuide nous ce verre et nous le remplirons.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('chanson-a-boire', 1, 0, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chanson-a-boire', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-a-boire', 2, 0, 'Le vin gousté par ce bon pere');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-a-boire', 2, 1, 'Qui s’en rendit si beau garçon,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-a-boire', 2, 2, 'Nous fait discourir sans grammere,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-a-boire', 2, 3, 'Et nous rend savants sans leçon.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chanson-a-boire', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-a-boire', 3, 0, 'Loth beuvant dans une caverne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-a-boire', 3, 1, 'De ses filles enfla le sein,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-a-boire', 3, 2, 'Montrant qu’un cyropt de taverne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-a-boire', 3, 3, 'Passe celuy d’un médecin.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chanson-a-boire', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-a-boire', 4, 0, 'Beuvons donc tous à la bonne heure');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-a-boire', 4, 1, 'Pour nous esmouvoir le rognon.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-a-boire', 4, 2, 'Et que celuy d’entre nous meure');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-a-boire', 4, 3, 'Qui dedira son compangnon.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('chanson-de-bicetre', 'CHANSON DE BICÊTRE', 'CHANSON DE BICÊTRE', 'franstalige-liederen', 'fr', NULL, 299, 300, NULL, NULL, 'Dit lied werd geschreven tussen 1846 en 1851. ‘L’hospice du Bicêtre’ is een ziekenhuis in de Parijse randgemeente Kremlin-Bicêtre (Valde-Marne), gebouwd in 1632 als rusthuis voor de gepensioneerde en kreupele soldaten van Lodewijk XIII. Het was in het Bicêtre dat Dr. Guillotin in 1792 zijn ‘onthoofdingsmachine’ uitvond en testte op de rijkelijk voorhanden zijnde lijken. Traditioneel werden veel Franse studentenliederen geschreven door geneeskundestudenten met wachtdienst in de ‘salles de garde’ van de vele Parijse ‘Hospices’, en later verzameld in de ‘Chansons des salles de garde’, vergelijkbaar met onze codex.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chanson-de-bicetre', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 0, 0, 'Dans ce Bicêtre où l’on s’embête,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 0, 1, 'Loin de Paris que je regrette,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 0, 2, 'J’ai bien souvent et longtemps médité');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 0, 3, 'Sur la vieilless’ et la caducité.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 0, 4, 'Or, écoutez ce refrain de Bicêtre,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 0, 5, 'Cette leçon vous servira peut-être:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chanson-de-bicetre', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 1, 0, 'On n’ peut pas bander toujours,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 1, 1, 'Il faut jouir de ses roupettes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 1, 2, 'On n’ peut pas bander toujours,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 1, 3, 'Il faut jouir de ses amours.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chanson-de-bicetre', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 2, 0, 'D’un vieux, un jour je tenais la quéquette');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 2, 1, 'La sond’ en main, de l’autre la cuvette,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 2, 2, 'Pendant ce temps, mon esprit méditait,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 2, 3, 'Ce que tout en bas une voix me disait:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 2, 4, '“Prenez bien soin de ces pauvres gogottes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 2, 5, 'Vous en viendrez à pisser sur vos bottes.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chanson-de-bicetre', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 3, 0, 'Idiot, fou, épileptique');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 3, 1, 'Sont des arguments sans réplique.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 3, 2, 'Tout dépérit, le pauvre genr’ humain');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 3, 3, 'N’a plus d’espoir que dans le carabin.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 3, 4, 'Or, pour créer une race nouvelle,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 3, 5, 'Jamais, enfants, ne mouchez la chandelle.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chanson-de-bicetre', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 4, 0, 'Quand la vieillesse trist’ et caduque');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 4, 1, 'Vous foutra son pied sur la nuque,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 4, 2, 'Quand votre vit à jamais désossé,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 4, 3, 'Sur vos roustons, pendra flasqu’ et glacé,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 4, 4, 'Au mêm’ instant, crachez au nez du traître,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 4, 5, 'Répétez-lui ce refrain de Bicêtre:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chanson-de-bicetre', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 5, 0, 'À l’oeuvre donc, jeunes athlètes.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 5, 1, 'Gaillardement, engrossez les fillettes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 5, 2, 'Baisez, foutez, ne craignez nul écueil.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 5, 3, 'Quand on est jeun’ il faut baiser à l’oeil.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 5, 4, 'Avec le temps, Vénus devient avare.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chanson-de-bicetre', 5, 5, 'Aux pauvres vieux, le coup est cher ... et rare.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-chanson-du-roi-albert', 'LA CHANSON DU ROI ALBERT', 'CHANSON DU ROI ALBERT, LA', 'franstalige-liederen', 'fr', NULL, 301, 302, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-chanson-du-roi-albert', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 0, 0, 'C’était un soir sur les bords de l’Yser(e)');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 0, 1, 'Un soldat belg’ qui montait la faction');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 0, 2, 'Vinr’nt à passer trois braves militaires');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 0, 3, 'Parmi lesquels se trouvait le Roi Albert.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 0, 4, '“Qui vive-là, cria la sentinelle,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 0, 5, 'Qui vive-là, vous ne passerez pas;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 0, 6, 'Si vous passez, craignez ma baïonnette,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 0, 7, 'Retirez-vous, vous ne passerez pas');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 0, 8, 'Halte là!”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-chanson-du-roi-albert', 0, 7, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-chanson-du-roi-albert', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 1, 0, 'Le Roi Albert mit la main à la poche:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 1, 1, '“Tiens, lui dit-il, et laisse-nous passer”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 1, 2, '“Non, répondit la brave sentinelle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 1, 3, 'L’argent n’est rien pour un vrai soldat belge.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 1, 4, 'Dans mon pays, je cultivais la terre,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 1, 5, 'Dans mon pays, je gardais les moutons;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 1, 6, 'Mais maintenant que je suis militaire,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 1, 7, 'Retirez-vous, vous ne passerez pas');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 1, 8, 'Halte là!”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-chanson-du-roi-albert', 1, 7, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-chanson-du-roi-albert', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 2, 0, 'Le Roi Albert dit à son capitaine:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 2, 1, '“Fusillons-le, c’est un mauvais sujet.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 2, 2, 'Fusillons-le, passons-le par les armes.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 2, 3, 'Fusillons-le, et puis nous passerons.”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 2, 4, '“Fusillez-moi, cria la sentinelle,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 2, 5, 'Fusillez-moi vous ne passerez pas,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 2, 6, 'Si vous passez, craignez ma baïonnette,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 2, 7, 'Retirez-vous, vous ne passerez pas');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 2, 8, 'Halte là!”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-chanson-du-roi-albert', 2, 7, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-chanson-du-roi-albert', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 3, 0, 'Le lendemain, au grand conseil de guerre.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 3, 1, 'Le Roi Albert l’appela par son nom: “Hé, Julot!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 3, 2, 'Tiens, lui dit-il, voici la croix de guerre,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 3, 3, 'La croix de guerre et la décoration.”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 3, 4, '“Ah, que dira ma douce et tendre mère,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 3, 5, 'En me voyant tout couvert de lauriers;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 3, 6, 'La croix de guerre pend à ma boutonnière,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 3, 7, 'Pour avoir dit: Vous ne passerez pas,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-chanson-du-roi-albert', 3, 8, 'Halte là!”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-chanson-du-roi-albert', 3, 7, 7, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('chant-des-braves-gueux', 'CHANT DES BRAVES GUEUX', 'CHANT DES BRAVES GUEUX', 'franstalige-liederen', 'fr', NULL, 302, 302, 'Vrij naar G. Hubens', '‘Au trente et un du mois d’août’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chant-des-braves-gueux', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-des-braves-gueux', 0, 0, 'Buvons un coup, buvons en deux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-des-braves-gueux', 0, 1, 'A la santé des braves gueux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-des-braves-gueux', 0, 2, 'A la santé du Prince d’Orange,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-des-braves-gueux', 0, 3, 'Et merde aux curés, aux vicaires,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-des-braves-gueux', 0, 4, 'Qui nous ont déclaré la guerre.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chant-des-braves-gueux', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-des-braves-gueux', 1, 0, 'Buvons un coup, buvons en deux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-des-braves-gueux', 1, 1, 'À la santé des crapuleux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-des-braves-gueux', 1, 2, 'À la santé de Saint Verhaegen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-des-braves-gueux', 1, 3, 'Et merde aux curés, aux vicaires,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chant-des-braves-gueux', 1, 4, 'Qui nous ont déclaré la guerre.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('le-chant-des-partisans', 'LE CHANT DES PARTISANS', 'CHANT DES PARTISANS, LE', 'franstalige-liederen', 'fr', NULL, 303, 303, 'Maurice Druon, Joseph Kessel', 'Anna Marly', 'Frans verzetsnummer');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-chant-des-partisans', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-chant-des-partisans', 0, 0, 'Ami, entends-tu le vol noir des corbeaux sur nos plaines?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-chant-des-partisans', 0, 1, 'Ami, entends-tu les cris sourds du pays qu’on enchaîne?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-chant-des-partisans', 0, 2, 'Ohé, partisans, ouvriers et paysans, c’est l’alarme.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-chant-des-partisans', 0, 3, 'Ce soir l’ennemi connaîtra le prix du sang et les larmes.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-chant-des-partisans', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-chant-des-partisans', 1, 0, 'Montez de la mine, descendez des collines, camarades!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-chant-des-partisans', 1, 1, 'Sortez de la paille les fusils, la mitraille, les grenades.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-chant-des-partisans', 1, 2, 'Ohé, les tueurs à la balle et au couteau, tuez vite!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-chant-des-partisans', 1, 3, 'Ohé, saboteur, attention à ton fardeau: Dynamite.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-chant-des-partisans', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-chant-des-partisans', 2, 0, 'C’est nous qui brisons les barreaux des prisons pour nos frères.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-chant-des-partisans', 2, 1, 'La haine à nos trousses et la faim qui nous pousse, la misère.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-chant-des-partisans', 2, 2, 'Il y a des pays où les gens au creux des lits font des rêves.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-chant-des-partisans', 2, 3, 'Ici, nous, vois-tu, nous on marche et nous on tue, nous on crève.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-chant-des-partisans', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-chant-des-partisans', 3, 0, 'Ici chacun sait ce qu’il veut, ce qu’il fait quand il passe.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-chant-des-partisans', 3, 1, 'Ami, si tu tombes un ami sort de l’ombre à ta place.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-chant-des-partisans', 3, 2, 'Demain du sang noir sèchera au grand soleil sur les routes.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-chant-des-partisans', 3, 3, 'Chantez, compagnons, dans la nuit la Liberté nous écoute.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-chant-des-partisans', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-chant-des-partisans', 4, 0, 'Ami, entends-tu ces cris sourds du pays qu’on enchaîne?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-chant-des-partisans', 4, 1, 'Ami, entends-tu le vol noir des corbeaux sur nos plaines?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-chant-des-partisans', 4, 2, 'Oh oh oh oh oh oh oh oh oh oh oh oh oh oh oh oh.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-chant-des-partisans', 4, 2, 2, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('chantons-pour-passer-le-temps', 'CHANTONS POUR PASSER LE TEMPS', 'CHANTONS POUR PASSER LE TEMPS', 'franstalige-liederen', 'fr', NULL, 304, 305, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chantons-pour-passer-le-temps', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 0, 0, 'Chantons pour passer le temps');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 0, 1, 'Les amours charmants d’une belle fille,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 0, 2, 'Chantons pour passer le temps');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 0, 3, 'D’une belle fill’ les amours charmants.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 0, 4, 'Aussitôt que son amant l’eût prise,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 0, 5, 'Aussitôt elle changea de mise,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 0, 6, 'Et prit l’habit de matelot');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 0, 7, 'Et vint s’embarquer à bord du navire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 0, 8, 'Et prit l’habit de matelot');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 0, 9, 'Et vint s’embarquer à bord du vaisseau.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chantons-pour-passer-le-temps', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 1, 0, 'Le capitaine enchanté');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 1, 1, 'D’avoir à son bord un si beau jeune homme,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 1, 2, 'Le capitaine enchanté');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 1, 3, 'Lui dit: “A mon bord, je vais te garder.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 1, 4, 'Tes beaux yeux, ton joli visage,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 1, 5, 'Tes cheveux et ton joli corsage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 1, 6, 'Me font toujours me rappeler');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 1, 7, 'D’anciennes amours avec une belle;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 1, 8, 'Me font toujours me rappeler');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 1, 9, 'Un’ beauté d’ jadis que j’ai tant aimée!”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chantons-pour-passer-le-temps', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 2, 0, '“Monsieur vous vous moquez de moi,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 2, 1, 'Vous me badinez, vous me faites rire;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 2, 2, 'Je n’ai ni frère ni parents');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 2, 3, 'Et ne suis pas née z’au port de Lorient.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 2, 4, 'Je suis née z’à la Martinique,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 2, 5, 'Je suis mêm’ z’une enfant unique');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 2, 6, 'Et c’est un vaisseau hollandais');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 2, 7, 'Qui m’a débarquée en venant des îles,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 2, 8, 'Et c’est un vaisseau hollandais');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 2, 9, 'Qui m’a débarquée au port de Calais!”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chantons-pour-passer-le-temps', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 3, 0, 'Ils ont bien vécu sept ans');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 3, 1, 'Sur le bâtiment sans se reconnaître;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 3, 2, 'Ils ont bien vécu sept ans');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 3, 3, 'Se sont reconnus au débarquement.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 3, 4, '“Puisqu’ici l’amour nous rassemble,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 3, 5, 'Nous allons nous marier ensemble;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 3, 6, 'L’argent que nous avons gagné,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 3, 7, 'Il nous servira dans notre ménage;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 3, 8, 'L’argent que nous avons gagné,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 3, 9, 'Il nous servira z’à nous marier!”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chantons-pour-passer-le-temps', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 4, 0, 'C’ui-là qu’a fait la chanson,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 4, 1, 'C’est le gars Camus, le gabier d’misaine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 4, 2, 'C’ui-là qu’a fait la chanson,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 4, 3, 'C’est le gars Camus’ l’gabier d’artimon.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 4, 4, 'Oh! mat’lots, larguez la grand-voile,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 4, 5, 'Aux palans, que tout l’monde y soye;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 4, 6, 'Et vire, et vire, vire donc');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 4, 7, 'Sinon t’auras pas d’vin plein ta bedaine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 4, 8, 'Et vire, et vire, vire donc,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chantons-pour-passer-le-temps', 4, 9, 'Ou t’auras pas ta ration dans l’bedon');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('charlotte', 'CHARLOTTE', 'CHARLOTTE', 'franstalige-liederen', 'fr', NULL, 306, 307, NULL, NULL, 'Andere titels: ‘La petite Charlotte’, ‘Branle Charlotte’');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('charlotte', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 0, 0, 'Dans son boudoir la petite Charlotte');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 0, 1, 'Chaude du con faute d’avoir un vit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 0, 2, 'Se masturbait avec une carotte');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 0, 3, 'Et jouissait étendue sur son lit.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('charlotte', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 1, 0, 'Branle, branle, branle Charlotte');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 1, 1, 'Branle, branle ça fait du bien.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 1, 2, 'Branle, branle, branle ma chère');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 1, 3, 'Branle, branle jusqu’à demain.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('charlotte', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 2, 0, '“Ah! Disait-elle, en ce siècle ou nous sommes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 2, 1, 'Il faut savoir se passer des garçons,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 2, 2, 'Moi, pour ma part, je me fous bien des hommes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 2, 3, 'Avec ardeur, je me branle le con!”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('charlotte', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 3, 0, 'Alors sa main n’étant plus paresseuse,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 3, 1, 'Allait, venait, comme un petit ressort');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 3, 2, 'Et faisait jouir la petite farceuse;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 3, 3, 'Aussi ce jeu lui plaisait-il bien fort.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('charlotte', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 4, 0, 'Mais, ô malheur! Ô fatale disgrâce!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 4, 1, 'Dans son bonheur, ell’ fait un brusque saut,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 4, 2, 'Du contre-coup, la carotte se casse,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 4, 3, 'Et dans le con, il en reste un morceau!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('charlotte', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 5, 0, 'Un médecin, practicien fort habile,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 5, 1, 'Fut appelé, qui lui fit bien du mal;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 5, 2, 'Mais, par malheur, la carotte indocile');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 5, 3, 'Ne put sortir du conduit vaginal.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('charlotte', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 6, 0, 'Mesdemoisell’s, que le sort de Charlotte');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 6, 1, 'Puisse longtemps vous servir de leçon;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 6, 2, 'Ah! Croyez-moi, laissez là la carotte');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 6, 3, 'Préférez-lui le vit d’un beau garçon.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('charlotte', 7, 'direction', 1, 'Laatste refrein:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('charlotte', 8, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 8, 0, 'Baise, baise, baise Charlotte');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 8, 1, 'Baise, baise ça fait du bien.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 8, 2, 'Baise, baise, baise ma chère');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('charlotte', 8, 3, 'Baise, baise jusqu’ à demain.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('chevaliers-de-la-table-ronde', 'CHEVALIERS DE LA TABLE RONDE', 'CHEVALIERS DE LA TABLE RONDE', 'franstalige-liederen', 'fr', NULL, 307, 309, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chevaliers-de-la-table-ronde', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 0, 0, 'Chevaliers de la table ronde,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 0, 1, 'Goûtons voir si le vin est bon.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 0, 2, 'Goûtons voir, oui, oui, oui,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 0, 3, 'Goûtons voir, non, non, non,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 0, 4, 'Goûtons voir si le vin est bon.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('chevaliers-de-la-table-ronde', 0, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('chevaliers-de-la-table-ronde', 0, 2, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chevaliers-de-la-table-ronde', 1, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chevaliers-de-la-table-ronde', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 2, 0, 'S’il est bon, s’il est agréable,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 2, 1, 'J’en boirai jusqu’à mon plaisir.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 2, 2, 'J’en boirai, oui, oui, oui, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chevaliers-de-la-table-ronde', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 3, 0, 'J’en boirai cinq à six bouteilles,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 3, 1, 'Une femme sur les genoux.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 3, 2, 'Une femme, oui, oui, oui, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chevaliers-de-la-table-ronde', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 4, 0, 'Et s’il en reste quelques gouttes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 4, 1, 'Ce sera pour nous rafraîchir.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 4, 2, 'Ce sera, oui, oui, oui, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chevaliers-de-la-table-ronde', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 5, 0, 'Mais voici qu’on frappe à la porte?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 5, 1, 'Je crois bien que c’est le mari.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 5, 2, 'Je crois bien, oui, oui, oui, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chevaliers-de-la-table-ronde', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 6, 0, 'Si c’est lui, que le diabl’ l’emporte,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 6, 1, 'Car il vient troubler mon plaisir.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 6, 2, 'Car il vient, oui, oui, oui, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chevaliers-de-la-table-ronde', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 7, 0, 'Si je meurs, je veux qu’on m’enterre,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 7, 1, 'Dans une cave où y a du bon vin.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 7, 2, 'Dans une cave, oui, oui, oui, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chevaliers-de-la-table-ronde', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 8, 0, 'Les deux pieds contre la muraille,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 8, 1, 'Et la tête sous le robinet.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 8, 2, 'Et la tête, oui, oui, oui, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chevaliers-de-la-table-ronde', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 9, 0, 'Et mes os de cette manière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 9, 1, 'Resteront imbibés de vin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 9, 2, 'Resteront oui, oui, oui, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chevaliers-de-la-table-ronde', 10, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 10, 0, 'Et les quatre plus grands ivrognes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 10, 1, 'Porteront les quatr’coins du drap.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 10, 2, 'Porteront, oui, oui, oui, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chevaliers-de-la-table-ronde', 11, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 11, 0, 'Pour donner le discours d’usage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 11, 1, 'On prendra le bistrot du coin.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 11, 2, 'On prendra oui, oui, oui, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chevaliers-de-la-table-ronde', 12, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 12, 0, 'Et si le tonneau se débonde,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 12, 1, 'J’en boirai jusqu’à mon loisir.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 12, 2, 'J’en boirai, oui, oui, oui, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chevaliers-de-la-table-ronde', 13, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 13, 0, 'Sur ma tombe, je veux qu’on inscrive,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 13, 1, 'Ici gît le roi des buveurs.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 13, 2, 'Ici gît, oui, oui, oui, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('chevaliers-de-la-table-ronde', 14, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 14, 0, 'La morale de cette histoire,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 14, 1, 'Est qu’il faut boire avant d’mourir!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('chevaliers-de-la-table-ronde', 14, 2, 'Est qu’il faut, oui, oui, oui ...');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('le-cordonnier-pamphyle', 'LE CORDONNIER PAMPHYLE', 'CORDONNIER PAMPHYLE, LE', 'franstalige-liederen', 'fr', NULL, 309, 310, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-cordonnier-pamphyle', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 0, 0, 'Le cordonnier Pamphyle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 0, 1, 'A élu domicile');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 0, 2, 'Près d’un couvent de filles');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 0, 3, 'Et bien il s’en trouva');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 0, 4, 'Ahah! Ahah!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 0, 5, 'Et bien il s’en trouva.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-cordonnier-pamphyle', 0, 4, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-cordonnier-pamphyle', 1, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-cordonnier-pamphyle', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 2, 0, 'Car la gent monastique');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 2, 1, 'Jetait dans sa boutique');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 2, 2, 'Des trognons et des chiques,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 2, 3, 'Restes de ses repas ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-cordonnier-pamphyle', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 3, 0, 'Un jour la soeur Charlotte');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 3, 1, 'S’asticotait la motte');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 3, 2, 'Avec une carotte');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 3, 3, 'Grosse comme le bras ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-cordonnier-pamphyle', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 4, 0, 'Mais quelque effort qu’elle fasse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 4, 1, 'En vain elle se masse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 4, 2, 'Ell’ s’astiqu’ la culasse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 4, 3, 'Le foutre ne vient pas ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-cordonnier-pamphyle', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 5, 0, 'Mais comm’ tout à son terme');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 5, 1, 'Enfin jaillit le sperme,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 5, 2, 'Le con s’ouvre et se ferme');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 5, 3, 'Et elle déchargera ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-cordonnier-pamphyle', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 6, 0, 'Alors toute contente');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 6, 1, 'Ell’ retir’ de sa fente');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 6, 2, 'La carotte écumante');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 6, 3, 'Et puis ell’ la jeta ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-cordonnier-pamphyle', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 7, 0, 'Par un hasard comique');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 7, 1, 'La carotte impudique');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 7, 2, 'Tomba dans la boutique,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 7, 3, 'Du cordonnier d’en bas ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-cordonnier-pamphyle', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 8, 0, 'Cré nom de Dieu, quelle chance,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 8, 1, 'Elle est à la sauc’ blanche,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 8, 2, 'Bourrons-nous-en la panse,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 8, 3, 'Et il la boulotta ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-cordonnier-pamphyle', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 9, 0, 'Cré nom de dieu Fifine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 9, 1, 'Cette carott’ sent l’urine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 9, 2, 'Elle a servi de pine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cordonnier-pamphyle', 9, 3, 'Et il la dégueula ...');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-corrida', 'LA CORRIDA', 'CORRIDA, LA', 'franstalige-liederen', 'fr', NULL, 311, 311, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-corrida', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 0, 0, 'Le soir de la grande corrida, olé!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 0, 1, 'Alors qu’il plantait ses banderillas, olé!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 0, 2, 'Il faisait frémir les mantillas');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 0, 3, 'De toutes les señoritas.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-corrida', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 1, 0, 'Parara papoum papoum papoum!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-corrida', 1, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-corrida', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 2, 0, 'La señorita Goutalez, olé!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 2, 1, 'Qui était fière de ses colores, olé!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 2, 2, 'Lui dit: “Ricardo,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 2, 3, 'Tu es terrible, parapapoum');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 2, 4, 'Tu es vraiment phénoménal.”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-corrida', 2, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-corrida', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 3, 0, 'Un soir qu’il rentrait de la corrida, olé!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 3, 1, 'Un peu plus tôt que d’habitude, olé!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 3, 2, 'Il la trouva sur la carpette');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 3, 3, 'Elle était nue jusqu’au nombril.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-corrida', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 4, 0, 'Alors, il lui dit sans s’émouvoir, olé!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 4, 1, 'Habilles-toi tu vas attraper un rhume, olé!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 4, 2, 'Mais elle lui dit: “Ricardo');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 4, 3, 'Tu es terrible, parapapoum');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 4, 4, 'Tu es vraiment phénoménal.”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-corrida', 4, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-corrida', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 5, 0, 'Ricardo, olé!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 5, 1, 'Tu es un drôle de coco ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 5, 2, 'Tu ne vois pas que j’ai envie (7 keer “envie”)');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 5, 3, 'Tu es terrible, parapapoum');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-corrida', 5, 4, 'Tu es vraiment phénoménal.”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-corrida', 5, 3, 3, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('le-cul-de-ma-blonde', 'LE CUL DE MA BLONDE', 'CUL DE MA BLONDE, LE', 'franstalige-liederen', 'fr', NULL, 312, 313, NULL, '‘La nature’, Pierre Gaveaux', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-cul-de-ma-blonde', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 0, 0, 'J’ai tâté du vin d’Argenteuil');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 0, 1, 'Et ce vin m’a foutu la foire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 0, 2, 'J’ai voulu tâter de la gloire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 0, 3, 'Une balle m’a crevé l’oeil');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 0, 4, 'Des catins du grand monde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 0, 5, 'J’ai tâté la vertu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 0, 6, 'Des splendeurs, revenu,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 0, 7, 'Je veux tâter le cul');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 0, 8, 'De ma blonde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 0, 9, 'Des splendeurs, revenu,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 0, 10, 'Je veux tâter le cul');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 0, 11, 'De ma blonde.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-cul-de-ma-blonde', 0, 8, 8, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-cul-de-ma-blonde', 0, 9, 10, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-cul-de-ma-blonde', 0, 10, 10, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-cul-de-ma-blonde', 0, 11, 11, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-cul-de-ma-blonde', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 1, 0, 'Preux guerriers, vaillants conquérants,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 1, 1, 'Fi de la gloire qui vous éclope');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 1, 2, 'Votre maîtress’ est une salope');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 1, 3, 'Qui vous pince en vous caressant!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 1, 4, 'Empoignez-moi la ronde,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 1, 5, 'Et la lanc’ et l’écu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 1, 6, 'De peur d’être cocu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 1, 7, 'Moi j’empoigne le cul');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 1, 8, 'De ma blonde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 1, 9, 'De peur d’être cocu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 1, 10, 'Moi j’empoigne le cul');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 1, 11, 'De ma blonde.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-cul-de-ma-blonde', 1, 8, 8, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-cul-de-ma-blonde', 1, 9, 10, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-cul-de-ma-blonde', 1, 10, 10, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-cul-de-ma-blonde', 1, 11, 11, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-cul-de-ma-blonde', 2, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-cul-de-ma-blonde', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 3, 0, 'Y’a des gens qui font la grimace');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 3, 1, 'Quand ils voient monsieur le curé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 3, 2, 'Qui promène dans une châsse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 3, 3, 'Un bon dieu en cuivre doré.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 3, 4, 'Ce bon curé se trompe');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 3, 5, 'Il serait mieux venu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 3, 6, 'Si, foutant là Jésus,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 3, 7, 'Il promenait le cul ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-cul-de-ma-blonde', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 4, 0, '“Mon fils, me dit un vieux dervî,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 4, 1, 'Souffrez qu’on vous le dise');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 4, 2, 'À baiser sans permis d’église');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 4, 3, 'Vous perdez le saint paradis.”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 4, 4, '“Vous foutez-vous du monde?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 4, 5, 'Dis-j’à ce noir cocu,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 4, 6, 'Le paradis perdu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 4, 7, 'Vaut-il un poil du cul” ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-cul-de-ma-blonde', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 5, 0, 'Puisqu’ici bas, l’homme jeté');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 5, 1, 'Doit mourir comm’ une victime,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 5, 2, 'Je me fous d’un trépas sublime,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 5, 3, 'J’emmerde l’immortalité!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 5, 4, 'Puissé-j’en passant l’onde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 5, 5, 'Du fleuve au dieu cornu,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 5, 6, 'Godiller ferm’ et dru,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-cul-de-ma-blonde', 5, 7, 'Et mourir dans le cul ...');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('de-profundis-morpionibus', 'DE PROFUNDIS MORPIONIBUS', 'DE PROFUNDIS MORPIONIBUS', 'franstalige-liederen', 'fr', NULL, 315, 316, NULL, '‘L’enterrement du Maréchal Gérard’, M. Reyze', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-profundis-morpionibus', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 0, 0, 'Ô! Muse prête-moi ta lyre,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 0, 1, 'Afin qu’en vers je puisse dire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 0, 2, 'Un des combats les plus fameux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 0, 3, 'Qui s’est déroulé sous les cieux.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-profundis-morpionibus', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 1, 0, 'De Profundis Morpionibus,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 1, 1, 'Tra, la, la, ...');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('de-profundis-morpionibus', 1, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-profundis-morpionibus', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 2, 0, 'Un jour de fêt’ comm’ Sainte Thérèse,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 2, 1, 'À Sainte Gudule chantait la messe');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 2, 2, 'Elle sentit soudainement');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 2, 3, 'Un énorme chatouillement.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-profundis-morpionibus', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 3, 0, 'Dans son vagin de forte taille,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 3, 1, 'Six cent mille poux livraient bataille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 3, 2, 'À nombre égal de morpions');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 3, 3, 'Qui défendaient l’entrée du con.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-profundis-morpionibus', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 4, 0, 'Dans un bouzin de tous les diables,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 4, 1, 'Le choc fut si épouvantable');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 4, 2, 'Qu’les femmes enceintes en accouchant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 4, 3, 'Chiaient d’la merde au lieu d’enfants.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-profundis-morpionibus', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 5, 0, 'La bataille fut gigantesque,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 5, 1, 'Tous les morpions moururent ou presque');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 5, 2, 'À l’exception des plus trapus');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 5, 3, 'Qui s’accrochèrent aux poils du cul.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-profundis-morpionibus', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 6, 0, 'Et ils bouchent toute la fente,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 6, 1, 'Que les morpions morts ensanglantent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 6, 2, 'Et la valée du cul au con');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 6, 3, 'Etait jonchée de morpions.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-profundis-morpionibus', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 7, 0, 'À cheval sur une roupette,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 7, 1, 'Tenant à la main la lorgnette');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 7, 2, 'Le capitaine des morpions');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 7, 3, 'Examinait les positions.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-profundis-morpionibus', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 8, 0, 'Le capitaine de l’embuscade,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 8, 1, 'Voyant fléchir ses camerades');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 8, 2, 'Cria: “Morpions nous sommes foutus');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-profundis-morpionibus', 8, 3, 'Piquons une charge au trou du cul”.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-digue-du-cul', 'LA DIGUE DU CUL', 'DIGUE DU CUL, LA', 'franstalige-liederen', 'fr', NULL, 316, 317, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-digue-du-cul', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-digue-du-cul', 0, 0, 'La digue du cul, en revenant de Nantes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-digue-du-cul', 0, 1, 'De Nantes à Montaigu, la digue, la digue,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-digue-du-cul', 0, 2, 'De Nantes à Montaigu, la digue du cul.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-digue-du-cul', 0, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-digue-du-cul', 1, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-digue-du-cul', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-digue-du-cul', 2, 0, 'La digue du cul, je rencontr’ une belle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-digue-du-cul', 2, 1, 'Qui dormait le cul nu, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-digue-du-cul', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-digue-du-cul', 3, 0, 'La digue du cul, je band’ mon arbalète');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-digue-du-cul', 3, 1, 'Et la lui fous dans l’cul, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-digue-du-cul', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-digue-du-cul', 4, 0, 'La digue du cul, la belle se réveille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-digue-du-cul', 4, 1, 'Et dit: “J’ai l’diable au cul!” ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-digue-du-cul', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-digue-du-cul', 5, 0, 'La digue du cul, non ce n’est pas le diable');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-digue-du-cul', 5, 1, 'Mais mon gros dard velu, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-digue-du-cul', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-digue-du-cul', 6, 0, 'La digue du cul, qui band’ et qui décharge');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-digue-du-cul', 6, 1, 'Et qui t’en fout plein l’cul, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-digue-du-cul', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-digue-du-cul', 7, 0, 'La digue du cul, puisqu’il y est qu’il y reste');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-digue-du-cul', 7, 1, 'Et qu’il n’en sorte plus, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-digue-du-cul', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-digue-du-cul', 8, 0, 'La digue du cul, il fallut bien qu’il sorte');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-digue-du-cul', 8, 1, 'Il est entré bien raide, la digue, la digue');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-digue-du-cul', 8, 2, 'Il en sortit menu, la digue du cul.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-digue-du-cul', 8, 0, 0, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('le-duc-de-bordeaux', 'LE DUC DE BORDEAUX', 'DUC DE BORDEAUX, LE', 'franstalige-liederen', 'fr', NULL, 318, 319, NULL, 'Sonnerie de chasse', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-duc-de-bordeaux', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 0, 0, 'Le duc de Bordeaux ressemble à son frère,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 0, 1, 'Son frère à son père et son père à mon cul;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 0, 2, 'De là je conclus qu’le duc de Bordeaux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 0, 3, 'Ressemble à mon cul comme deux gouttes d’eau.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-duc-de-bordeaux', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 1, 0, 'Taïaut Taïaut Taïaut!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 1, 1, 'Ferme ta gueule, répondit l’écho.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-duc-de-bordeaux', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 2, 0, 'Le duc de Chevreuse ayant déclaré');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 2, 1, 'Que tous les cocus devraient être noyés,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 2, 2, 'Madam’ de Chevreuse lui a demandé,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 2, 3, 'S’il était certain de savoir bien nager.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-duc-de-bordeaux', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 3, 0, 'Madam’ la duchesse de la Trémouille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 3, 1, 'Malgré sa pudeur et sa grande piété,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 3, 2, 'A patiné plus de paires de couilles,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 3, 3, 'Que la Grande Armée n’a usé de souliers.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-duc-de-bordeaux', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 4, 0, 'Le roy Dagobert a un’ pine en fer;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 4, 1, 'Le bon Saint-Éloi lui dit: “Eh bien, mon roi,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 4, 2, 'Si vous m’enculez, vous m’écorcherez.”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 4, 3, '“C’est vrai”, dit le roi, “j’en f’rai faire un’ de bois.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-duc-de-bordeaux', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 5, 0, 'J’emmerde le roi et le comt’ d’Artois');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 5, 1, 'Le duc de Berry et la duchesse aussi,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 5, 2, 'Le duc de Nemours, je l’emmerde à son tour');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 5, 3, 'Le duc d’Orléans, je l’emmerde en même temps!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-duc-de-bordeaux', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 6, 0, '“Chasseur, as-tu vu le trou de mon cul?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 6, 1, 'Si tu veux le voir, tu reviendras ce soir.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 6, 2, 'Moi, j’ai vu le tien, je n’en ai rien dit;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 6, 3, 'Si tu vois le mien, tu n’en di-iras rien.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-duc-de-bordeaux', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 7, 0, 'La p’tite Amélie m’avait bien promis');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 7, 1, 'Trois poils de son cul pour en faire un tapis');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 7, 2, 'Les poils sont tombés, l’tapis est foutu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 7, 3, 'La p’tite Amélie n’a plus d’poil à son cul.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-duc-de-bordeaux', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 8, 0, 'La bite à papa qu’on croyait perdue,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 8, 1, 'C’était la p’tit’ bonn’ qui l’avait dans les fesses');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 8, 2, 'La bite à papa n’était pas perdue,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-duc-de-bordeaux', 8, 3, 'C’était la p’tit’ bonn’ qui l’avait dans le cul.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('elephant-story', 'ELEPHANT STORY', 'ELEPHANT STORY', 'franstalige-liederen', 'fr', NULL, 319, 320, NULL, NULL, 'T & M: Eric Saintrond
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('elephant-story', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 0, 0, 'Dans la savane tropicale,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 0, 1, 'Sous un soleil étourdissant,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 0, 2, 'Se branlait un éléphant mâle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 0, 3, 'À grands coups de trompe, goulûment.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 0, 4, 'Prenant son naseau pour femelle,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 0, 5, 'Il aspirait à pleins poumons');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 0, 6, 'À s’en faire péter les aisselles;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 0, 7, 'Son jus coulant à gros flocons.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('elephant-story', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 1, 0, 'Les éléphants, ça tronche énormément');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 1, 1, 'Mais il leur arrive, dans la solitude,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 1, 2, 'De penser aux plaisirs d’adolescent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 1, 3, 'Mais n’y voyez point là de turpitude.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 1, 4, 'Car tout ce qu’ils déchargent en se branlant,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 1, 5, 'Ils le renifl’nt et l’aval’nt d’une traite.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 1, 6, 'Les éléphants, ça se branle proprement');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 1, 7, 'Sans déborder sur leurs roupettes.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('elephant-story', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 2, 0, 'Dans la savane tropicale,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 2, 1, 'J’ai rencontré cet éléphant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 2, 2, 'Qui me dit gentiment: “Madame,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 2, 3, 'J’aimerais tant êt’ votr’ amant!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 2, 4, 'Mais son vit de si forte taille,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 2, 5, 'Coiffé de son énorme gland,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 2, 6, 'Jamais ne pénétra ma faille,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 2, 7, 'Et il du jouir en se pompant.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('elephant-story', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 3, 0, 'Dans la savane tropicale,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 3, 1, 'Erra ce pauvre éléphant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 3, 2, 'Dans l’espoir qu’une femelle fatale');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 3, 3, 'Lui offre ses bons sentiments.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 3, 4, 'Mais au bout de plusieurs semaines,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 3, 5, 'À siroter son jus d’roustons,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 3, 6, 'Il attrapa une migraine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('elephant-story', 3, 7, 'Et mourut d’une indigestion.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('en-descendant-la-rue-tronchet', 'EN DESCENDANT LA RUE TRONCHET', 'EN DESCENDANT LA RUE TRONCHET', 'franstalige-liederen', 'fr', NULL, 321, 321, NULL, '‘Où allez vous monsieur l’ abbé’, uit ‘Le panier aux ordures’, 1878', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-descendant-la-rue-tronchet', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 0, 0, 'En descendant la rue Tronchet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 0, 1, 'Par un’ putain, j’ fus racolé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 0, 2, 'Elle me dit d’un air tendre, eh bien?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 0, 3, 'Viens coucher dans ma chambre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 0, 4, 'Et vous m’entendez bien.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-descendant-la-rue-tronchet', 0, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-descendant-la-rue-tronchet', 0, 1, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-descendant-la-rue-tronchet', 0, 4, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-descendant-la-rue-tronchet', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 1, 0, 'Moi qui suis poil à l’ULB,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 1, 1, 'J’aime à savoir où j’ mets les pieds');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 1, 2, 'J’allume ma chandelle, eh bien?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 1, 3, 'J’éclaire le bordel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 1, 4, 'Et vous m’entendez bien.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-descendant-la-rue-tronchet', 1, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-descendant-la-rue-tronchet', 1, 1, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-descendant-la-rue-tronchet', 1, 4, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-descendant-la-rue-tronchet', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 2, 0, 'Quand le bordel fut éclairé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 2, 1, 'J’ la prends, j’ la fous sur l’ canapé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 2, 2, 'Et je la carambole si bien');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 2, 3, 'Qu’elle me fout la vérole,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 2, 4, 'Et vous m’entendez bien.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-descendant-la-rue-tronchet', 2, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-descendant-la-rue-tronchet', 2, 1, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-descendant-la-rue-tronchet', 2, 4, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-descendant-la-rue-tronchet', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 3, 0, 'Un vieux toubib, quatr’ infirmiers');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 3, 1, 'Fur’nt désignés pour me soigner');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 3, 2, 'Mais cette band’ d’andouilles, eh bien!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 3, 3, 'Ils m’ont coupé les couilles,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 3, 4, 'Et vous m’entendez bien.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-descendant-la-rue-tronchet', 3, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-descendant-la-rue-tronchet', 3, 1, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-descendant-la-rue-tronchet', 3, 4, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-descendant-la-rue-tronchet', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 4, 0, 'Depuis ce jour, soir et matin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 4, 1, 'Je maudis toutes les putains');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 4, 2, 'Mais ce que je regrette, eh bien,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 4, 3, 'C’est ma pair’ de roupettes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-descendant-la-rue-tronchet', 4, 4, 'Et vous m’entendez bien.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-descendant-la-rue-tronchet', 4, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-descendant-la-rue-tronchet', 4, 1, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-descendant-la-rue-tronchet', 4, 4, 4, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('en-passant-par-la-lorraine', 'EN PASSANT PAR LA LORRAINE', 'EN PASSANT PAR LA LORRAINE', 'franstalige-liederen', 'fr', NULL, 322, 322, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-passant-par-la-lorraine', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-passant-par-la-lorraine', 0, 0, 'En passant par la Lorraine, avec mes sabots');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-passant-par-la-lorraine', 0, 1, 'Rencontrai trois capitaines, avec mes sabots');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-passant-par-la-lorraine', 0, 2, 'Dondaine, Oh! Oh! Oh! Avec mes sabots!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-passant-par-la-lorraine', 0, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-passant-par-la-lorraine', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-passant-par-la-lorraine', 1, 0, 'Rencontrai trois capitaines, avec mes sabots');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-passant-par-la-lorraine', 1, 1, 'Ils m’ ont appelée: vilaine, avec mes sabots');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-passant-par-la-lorraine', 1, 2, 'Dondaine, Oh! Oh! Oh! Avec mes sabots!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-passant-par-la-lorraine', 1, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-passant-par-la-lorraine', 2, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-passant-par-la-lorraine', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-passant-par-la-lorraine', 3, 0, 'Je ne suis pas si vilaine.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-passant-par-la-lorraine', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-passant-par-la-lorraine', 4, 0, 'Puisque le fils du roi m’aime.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-passant-par-la-lorraine', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-passant-par-la-lorraine', 5, 0, 'Il m’a donné pour étrenne.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-passant-par-la-lorraine', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-passant-par-la-lorraine', 6, 0, 'Un bouquet de marjolaines.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-passant-par-la-lorraine', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-passant-par-la-lorraine', 7, 0, 'Je l’ai planté dans la plaine.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-passant-par-la-lorraine', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-passant-par-la-lorraine', 8, 0, 'S’il fleurit, je serai reine.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-passant-par-la-lorraine', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-passant-par-la-lorraine', 9, 0, 'S’il y meurt, je perds ma peine.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('en-revenant-de-la-foire', 'EN REVENANT DE LA FOIRE', 'EN REVENANT DE LA FOIRE', 'franstalige-liederen', 'fr', NULL, 323, 324, NULL, NULL, 'Te Saint-Cloud, in de Parijse stadsrand, was de jaarlijkse herfstbeurs (foire) een ideaal excuus om te feesten voor de studenten van het Quartier Latin.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-revenant-de-la-foire', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 0, 0, 'En revenant de la foire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 0, 1, 'La a la a la a la a la a la a la');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 0, 2, 'En revenant de la foire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 0, 3, 'De la foire de Saint-Cloud.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-de-la-foire', 0, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-revenant-de-la-foire', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 1, 0, 'Je rencontrai une belle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 1, 1, 'La a la a la a la a la a la a la');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 1, 2, 'Je rencontrai une belle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 1, 3, 'Qui me demanda cent sous.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-de-la-foire', 1, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-revenant-de-la-foire', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 2, 0, 'Pour acheter une robe ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 2, 1, 'Une robe de quatr’ sous.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-de-la-foire', 2, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-revenant-de-la-foire', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 3, 0, 'Mais la rob’ était si courte ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 3, 1, 'Qu’on y voyait par dessous.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-de-la-foire', 3, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-revenant-de-la-foire', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 4, 0, 'On voyait une chapelle ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 4, 1, 'La chapelle de Saint-Cloud.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-de-la-foire', 4, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-revenant-de-la-foire', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 5, 0, 'Pour entrer dans cett’ chapelle ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 5, 1, 'Fallait se mettr’ à genoux.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-de-la-foire', 5, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-revenant-de-la-foire', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 6, 0, 'Et tenir une chandelle ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 6, 1, 'Qui n’avait pas de mèch’ au bout.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-de-la-foire', 6, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-revenant-de-la-foire', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 7, 0, 'Car s’il y avait une mèche ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 7, 1, 'Elle aurait mis l’feu partout.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-de-la-foire', 7, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-revenant-de-la-foire', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 8, 0, 'Et les pompiers du village ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-de-la-foire', 8, 1, 'N’en pourraient venir à bout.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-de-la-foire', 8, 1, 1, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('en-revenant-du-piemont', 'EN REVENANT DU PIÉMONT', 'EN REVENANT DU PIÉMONT', 'franstalige-liederen', 'fr', NULL, 324, 325, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-revenant-du-piemont', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 0, 0, 'C’était en rev’nant du Piémont');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 0, 1, 'Nous étions six jeunes garçons');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 0, 2, 'De l’argent nous n’en avions guère,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 0, 3, 'Sans dessus dessous et sans devant derrière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 0, 4, 'A nous six nous n’avions qu’un sou.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 0, 5, 'Sans devant derrière et par derrier’ surtout!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-du-piemont', 0, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-du-piemont', 0, 1, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-du-piemont', 0, 5, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-revenant-du-piemont', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 1, 0, 'Nous arrivâm’s à un logis');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 1, 1, 'Madam’ l’hôtess’, qu’avez-vous cuit?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 1, 2, 'J’ai du lapin, du civet d’lièvre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 1, 3, 'Sans dessus dessous et sans devant derrière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 1, 4, 'Et de la bonne soupe aux choux.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 1, 5, 'Sans devant derrière et par derrier’ surtout!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-du-piemont', 1, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-du-piemont', 1, 1, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-du-piemont', 1, 5, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-revenant-du-piemont', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 2, 0, 'Et quand nous eûmes bien dîné');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 2, 1, 'Madam’ l’hôtesse où nous loger?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 2, 2, 'Vous coucherez sur la litière,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 2, 3, 'Sans dessus dessous et sans devant derrière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 2, 4, 'Ou bien vous couch’rez avec nous.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 2, 5, 'Sans devant derrière et par derrier’ surtout!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-du-piemont', 2, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-du-piemont', 2, 1, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-du-piemont', 2, 5, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-revenant-du-piemont', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 3, 0, 'Sur les onze heur’s on entendit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 3, 1, 'L’hôtesse pousser des grands cris:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 3, 2, 'Vous m’avez rompu la charnière,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 3, 3, 'Sans dessus dessous et sans devant derrière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 3, 4, 'Allez-y donc un peu plus doux.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 3, 5, 'Sans devant derrière et par derrier’ surtout!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-du-piemont', 3, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-du-piemont', 3, 1, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-du-piemont', 3, 5, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-revenant-du-piemont', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 4, 0, 'Et la bonn’ qui était en bas');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 4, 1, 'Dit: “N’y en a-t-il pas pour moi?”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 4, 2, 'Y en aura pour la chambrière,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 4, 3, 'Sans dessus dessous et sans devant derrière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 4, 4, 'Car nous tirons chacun six coups.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 4, 5, 'Sans devant derrière et par derrier’ surtout!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-du-piemont', 4, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-du-piemont', 4, 1, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-du-piemont', 4, 5, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-revenant-du-piemont', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 5, 0, 'Mais quand ce fut sur les minuit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 5, 1, 'Il se fit un bien plus grand bruit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 5, 2, 'Le lit du d’ssus se fichait par terre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 5, 3, 'Sans dessus dessous et sans devant derrière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 5, 4, 'Avec la bonn’ qui baisait d’ssous');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 5, 5, 'Sans devant derrière et par derrier’ surtout!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-du-piemont', 5, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-du-piemont', 5, 1, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-du-piemont', 5, 5, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('en-revenant-du-piemont', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 6, 0, 'Quand vous repass’rez par ici');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 6, 1, 'Souvenez-vous du bon logis');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 6, 2, 'Souvenez-vous d’la bonne hôtesse,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 6, 3, 'Qui savait si bien se remuer les fesses');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 6, 4, 'Et de la p’tite bonne au lit si doux.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('en-revenant-du-piemont', 6, 5, 'Sans devant derrière et par derrier’ surtout!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-du-piemont', 6, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-du-piemont', 6, 1, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('en-revenant-du-piemont', 6, 5, 5, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-femme-du-roulier', 'LA FEMME DU ROULIER', 'FEMME DU ROULIER, LA', 'franstalige-liederen', 'fr', NULL, 325, 327, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-femme-du-roulier', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 0, 0, 'Il est minuit,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 0, 1, 'La femme du roulier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 0, 2, 'S’ en va de port’ en port’');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 0, 3, 'De tavern’ en taverne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 0, 4, 'Pour chercher son mari, tireli,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 0, 5, 'Avec une lanterne.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-femme-du-roulier', 0, 4, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-femme-du-roulier', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 1, 0, 'Madam’ l’hôtesse,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 1, 1, 'Où donc est mon mari?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 1, 2, 'Ton mari est ici,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 1, 3, 'Il est dans la soupente');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 1, 4, 'Il y prend ses ébats, tirela,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 1, 5, 'Avec notre servante.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-femme-du-roulier', 1, 4, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-femme-du-roulier', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 2, 0, 'Cochon d’mari,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 2, 1, 'Pilier de cabaret,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 2, 2, 'Ainsi tu fais la noce,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 2, 3, 'Ainsi tu fais ripaille,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 2, 4, 'Pendant que tes enfants, tirelan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 2, 5, 'Sont couchés sur la paille.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-femme-du-roulier', 2, 4, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-femme-du-roulier', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 3, 0, 'Et toi la belle,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 3, 1, 'Aux yeux de merlan frit,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 3, 2, 'Tu m’as pris mon mari,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 3, 3, 'Je vais te prendr’ mesure');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 3, 4, 'D’un’ bell’ culott’ de peau, tirelo,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 3, 5, 'Qui ne craint pas l’usure.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-femme-du-roulier', 3, 4, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-femme-du-roulier', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 4, 0, 'Tais-toi, ma femme,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 4, 1, 'Tais-toi, tu me fais chier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 4, 2, 'Dans la bonne société,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 4, 3, 'Est-ce ainsi qu’on s’comporte');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 4, 4, 'J’ te fous mon pied dans le cul, tirelu,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 4, 5, 'Si tu n’ prends pas la porte.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-femme-du-roulier', 4, 4, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-femme-du-roulier', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 5, 0, 'Pauvres enfants,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 5, 1, 'Pauvres petits enfants,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 5, 2, 'Plaignez votre destin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 5, 3, 'Vous n’avez plus de père,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 5, 4, 'Je l’ai trouvé couché, Tirelé,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 5, 5, 'Avec une autre mère.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-femme-du-roulier', 5, 4, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-femme-du-roulier', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 6, 0, 'Il a bien fait,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 6, 1, 'Répondirent les enfants,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 6, 2, 'D’aller tirer un coup');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 6, 3, 'Avec celle qu’il aime,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 6, 4, 'Et quand nous serons grands, tirelan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 6, 5, 'Nous ferons tous de même.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-femme-du-roulier', 6, 4, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-femme-du-roulier', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 7, 0, 'Cochons d’enfants,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 7, 1, 'Dit la mère en courroux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 7, 2, 'Taisez vos gueules');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 7, 3, 'Vos propos m’exaspèrent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 7, 4, 'Vous serez tous cocus, tirelu,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-roulier', 7, 5, 'Comm’ le fut votre père.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-femme-du-roulier', 7, 4, 5, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-femme-du-vidangeur', 'LA FEMME DU VIDANGEUR', 'FEMME DU VIDANGEUR, LA', 'franstalige-liederen', 'fr', NULL, 328, 329, NULL, NULL, 'Andere titel: ‘Le pendu’
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-femme-du-vidangeur', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 0, 0, 'L’autre jour, l’idée m’est venue,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 0, 1, 'Cré nom de dieu d’enculer un pendu!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 0, 2, 'Le vent soufflant sur la potence,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 0, 3, 'Voilà mon pendu qui s’balance');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 0, 4, 'Je n’ai pu l’enculer qu’en volant!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 0, 5, 'Cré nom de dieu, on n’est jamais content.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-femme-du-vidangeur', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 1, 0, 'La femme du vidangeur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 1, 1, 'Préfère à toute odeur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 1, 2, 'L’odeur de son amant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 1, 3, 'Qu’elle aime éperdument.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 1, 4, 'Il était deux amants');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 1, 5, 'Qui s’aimaient tendrement');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 1, 6, 'Qui faisaient par devant, par derrière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 1, 7, 'Il était deux amants');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 1, 8, 'Qui s’aimaient tendrement');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 1, 9, 'Qui faisaient par derrière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 1, 10, 'Ce qu’on fait par devant.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-femme-du-vidangeur', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 2, 0, 'À baiser un con trop petit,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 2, 1, 'On risque fort de s’écorcher le vit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 2, 2, 'Mais quand le vagin est trop large,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 2, 3, 'On ne sait pas où l’on décharge');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 2, 4, 'S’ masturber n’est pas très élégant.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 2, 5, 'Cré nom de dieu, on ne jouit jamais tant!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-femme-du-vidangeur', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 3, 0, 'En arrivant au paradis,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 3, 1, 'Je sentis se redresser mon long vit.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 3, 2, 'J’ai baisé saint Michel l’archange,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 3, 3, 'La sainte vierge et tous les anges.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 3, 4, 'Si l’ bon dieu n’ s’était pas cavalé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-femme-du-vidangeur', 3, 5, 'Cré nom de dieu, je l’aurais enculé!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-fille-de-la-bouchere', 'LA FILLE DE LA BOUCHÈRE', 'FILLE DE LA BOUCHÈRE, LA', 'franstalige-liederen', 'fr', NULL, 329, 330, 'Bram Desmet, Vincent Godderis', '‘Les filles du bord de mer’, Adamo', 'Polytechnic, Festival de la chanson estudiantine, 1998
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-fille-de-la-bouchere', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 0, 0, 'Je me souviens de la fille de la bouchère,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 0, 1, 'Elle était vraiment conne comme sa mère,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 0, 2, 'Mais quand on avait bu assez de bière,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 0, 3, 'On lui mettait dans son derrière.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 0, 4, 'Sortant du Wapps en état plus potable,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 0, 5, 'Envie de niquer cette pétasse sur la table,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 0, 6, 'Tellement bourré ma vision très minable,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 0, 7, 'J’ai éclaté un pot de salade de crabe.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 0, 8, 'En douceur, en douceur, en douceur et profondeur.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-fille-de-la-bouchere', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 1, 0, 'L’était chouette la fille de la bouchère,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 1, 1, '(Schwing, schwing, schwing)');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 1, 2, 'Elle nous faisait bander comme des cerfs.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-fille-de-la-bouchere', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 2, 0, 'Après St V et beaucoup de chopines,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 2, 1, 'Je voulais bien lui faire sucer ma pine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 2, 2, 'La tête pressée trop près de sa poitrine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 2, 3, 'Et sur mon bout collait de la gélatine.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 2, 4, 'Le soir d’un fût il m’fallait de la baise,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 2, 5, 'Entr’les jambons je me sentais bien à l’aise,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 2, 6, 'Je lui ai mis ma saucisse ardennaise,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 2, 7, 'Bien lubrifiée avec d’la dijonnaise.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 2, 8, 'En douceur, en douceur, j’ai tripoté sa petite fleur.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-fille-de-la-bouchere', 3, 'chorus-ref', 2, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-fille-de-la-bouchere', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 4, 0, 'Elle s’était réfugiée dans le frigo,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 4, 1, 'La porte s’est fermée derrière mon dos,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 4, 2, 'Je me suis fait lécher mon Calippo,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 4, 3, 'Par une gigantesque tête de veau.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 4, 4, 'J’ai raconté toutes mes chaudes histoires,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 4, 5, 'De sorte que tout le Cercle y aille la voir,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 4, 6, 'Et complètement bourré comme tous les soirs,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 4, 7, 'On sautait tout ce qu’y avait dans le comptoir.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-fille-de-la-bouchere', 5, 'direction', 1, 'Moraal:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-fille-de-la-bouchere', 6, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 6, 0, 'La morale de cette histoire est ferme,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 6, 1, 'Boire et baiser ça tue le commerce.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 6, 2, 'La boucherie s’est fermée car à long terme,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 6, 3, 'Toute la viande y goûtait fort le sperme.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 6, 4, 'Eh encore, eh encore,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-fille-de-la-bouchere', 6, 5, 'Au Cercle Popo on est des porcs.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-fille-de-la-bouchere', 7, 'chorus-ref', 1, 'ad libitum');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('les-filles-de-camaret', 'LES FILLES DE CAMARET', 'FILLES DE CAMARET, LES', 'franstalige-liederen', 'fr', NULL, 331, 333, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-camaret', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 0, 0, 'Les filles de Camaret');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 0, 1, 'Se disent toutes vierges');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 0, 2, 'Mais quand elles sont dans mon lit,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 0, 3, 'Elles préfèrent tenir mon vit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 0, 4, 'Qu’un cierge.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 0, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 0, 4, 4, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-camaret', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 1, 0, '“Oh, fille de Camaret');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 1, 1, 'Où est ton pucelage?”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 1, 2, '“Il s’en est allé sur l’eau,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 1, 3, 'Dans les bras d’un matelot,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 1, 4, 'Il nage!”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 1, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 1, 4, 4, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-camaret', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 2, 0, 'Le maire de Camaret');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 2, 1, 'Vient d’acheter un âne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 2, 2, 'Un âne républicain,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 2, 3, 'Pour enculer les putains');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 2, 4, 'D’Bretagne.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 2, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 2, 4, 4, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-camaret', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 3, 0, 'Mon mari que fais-tu là?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 3, 1, 'Tu me perces la cuisse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 3, 2, 'Faut-il donc que tu sois saoûl,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 3, 3, 'Pour ne pas trouver le trou');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 3, 4, 'Qui pisse.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 3, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 3, 4, 4, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-camaret', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 4, 0, 'Mon mari s’en est allé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 4, 1, 'A la pêche en Espagne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 4, 2, 'Il m’a laissée sans un sou');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 4, 3, 'Mais avec mon petit trou');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 4, 4, 'J’en gagne.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 4, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 4, 4, 4, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-camaret', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 5, 0, 'Sur la place de Camaret');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 5, 1, 'Y a une statue d’Hercule');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 5, 2, 'Monsieur le maire et monsieur le curé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 5, 3, 'Qui sont tous les deux pédés');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 5, 4, 'L’enculent.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 5, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 5, 4, 4, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-camaret', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 6, 0, 'Une simple supposition,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 6, 1, 'Que tu serais ma tante');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 6, 2, 'Je te ferais le présent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 6, 3, 'De l’andouille qui me pend');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 6, 4, 'Z’au ventre.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 6, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 6, 4, 4, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-camaret', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 7, 0, 'Les rideaux de notre lit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 7, 1, 'Sont faits de serge rouge');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 7, 2, 'Mais quand nous sommes dedans');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 7, 3, 'La rage du cul nous prend');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 7, 4, 'Tout bouge.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 7, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 7, 4, 4, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-camaret', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 8, 0, 'Le curé de Camaret');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 8, 1, 'A les couilles qui pendent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 8, 2, 'Et quand il s’asseoit dessus');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 8, 3, 'Elles lui rentrent dans le cul');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 8, 4, 'Il bande.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 8, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 8, 4, 4, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-camaret', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 9, 0, 'Amélie, si tu m’aimais,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 9, 1, 'Tu me ferais des nouilles');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 9, 2, 'Et pendant qu’elles cuiraient');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 9, 3, 'Tu me les chatouillerais');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 9, 4, 'Les couilles.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 9, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 9, 4, 4, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-camaret', 10, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 10, 0, 'Si les filles de Camaret,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 10, 1, 'S’en vont à la prière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 10, 2, 'C’ n’est pas pour prier l’seigneur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 10, 3, 'C’est pour branler le prieur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 10, 4, 'Qui bande.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 10, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 10, 4, 4, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-camaret', 11, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 11, 0, 'La servante à m’sieur l’curé,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 11, 1, 'A le ventre qui gargouille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 11, 2, 'C’est qu’elle en a trop mangé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 11, 3, 'de l’andouille à m’sieur l’curé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 11, 4, 'D’ l’andouille.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 11, 0, 1, 2, '(BIS)');
