INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 12, 0, 'Au couvent de Camaret');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 12, 1, 'Il n’y a que d’vieilles nonnes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 12, 2, 'Réservées à l’aumonnier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 12, 3, 'Qui aime à les confesser');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 12, 4, 'Il baise');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 12, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 12, 4, 4, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-camaret', 13, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 13, 0, 'Quand vous irez communier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 13, 1, 'Et qu’vous mordrez l’hostie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 13, 2, 'Prenez garde à Jésus Christ');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 13, 3, 'Mordez pas dans son zizi:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-camaret', 13, 4, 'Prudence!');
