INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-camaret', 13, 4, 4, 3, '(TER)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('les-filles-de-la-rochelle', 'LES FILLES DE LA ROCHELLE', 'FILLES DE LA ROCHELLE, LES', 'franstalige-liederen', 'fr', NULL, 333, 335, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-la-rochelle', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 0, 0, 'Sont les filles de La Rochelle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 0, 1, 'Qu’ ont armé un bâtiment.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 0, 2, 'Ell’s ont la cuisse légère');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 0, 3, 'Et la fess’ à l’avenant.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-la-rochelle', 0, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-la-rochelle', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 1, 0, 'Ah! la feuille s’envole, s’envole');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 1, 1, 'Ah! la feuille s’envol’ au vent.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-la-rochelle', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 2, 0, 'Sont parties aux Amériques');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 2, 1, 'Un matin, la voil’ au vent;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 2, 2, 'Ont choisi pour capitaine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 2, 3, 'Une fille de quinz’ ans.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-la-rochelle', 2, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-la-rochelle', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 3, 0, 'Nous n’avons pas besoin d’hommes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 3, 1, 'Disaient-ell’s à tout venant;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 3, 2, 'Mais au bout de six semaines');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 3, 3, 'Ell’s avaient le cul brûlant.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-la-rochelle', 3, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-la-rochelle', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 4, 0, 'Un beau soir, une frégate');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 4, 1, 'Apparut sur l’océan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 4, 2, 'Pleine de jolis pirates,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 4, 3, 'De beaux gars appétissants.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-la-rochelle', 4, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-la-rochelle', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 5, 0, 'Ell’s allèr’nt à l’abordage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 5, 1, 'À coups d’ sabre et à coups d’ dents');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 5, 2, 'Ell’s y prirent l’avantage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 5, 3, 'Et se ram’nèr’nt des galants.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-la-rochelle', 5, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-la-rochelle', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 6, 0, 'Et sous la lune jolie,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 6, 1, 'Étendues sans vêtements,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 6, 2, 'Ell’s ont écarté les cuisses');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 6, 3, 'Tout’s sur le gaillard d’avant.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-la-rochelle', 6, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-la-rochelle', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 7, 0, 'Ont baisé à perdre haleine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 7, 1, 'Jusqu’au clair soleil levant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 7, 2, 'Et c’était la capitaine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 7, 3, 'Qui menait le mouvement.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-la-rochelle', 7, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-la-rochelle', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 8, 0, 'Le lend’main le beau navire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 8, 1, 'Repartit vers le couchant,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 8, 2, 'Et les fill’s de La Rochelle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 8, 3, 'Le cul frais allaient chantant:');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-la-rochelle', 8, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-la-rochelle', 9, 'direction', 1, 'Geen refrein!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-de-la-rochelle', 10, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 10, 0, '“J’ai perdu mon pucelage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 10, 1, 'Au milieu de l’océan.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 10, 2, 'Il est parti vent arrière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-de-la-rochelle', 10, 3, 'Reviendra-z-en louvoyant.”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-de-la-rochelle', 10, 1, 1, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('les-filles-des-forges', 'LES FILLES DES FORGES', 'FILLES DES FORGES, LES', 'franstalige-liederen', 'fr', NULL, 335, 336, NULL, NULL, 'Traditioneel Bretoens');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-des-forges', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-des-forges', 0, 0, 'La-la-la, lalala ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-des-forges', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-des-forges', 1, 0, 'Digue, ding don, don, ce sont les filles des forges');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-des-forges', 1, 1, 'Des forges de Paimpont, digue ding dondaine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-des-forges', 1, 2, 'Des forges de Paimpont, dingue ding dondon');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-des-forges', 1, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-des-forges', 1, 1, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-des-forges', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-des-forges', 2, 0, 'Digue, ding don, don, elles s’en vont à confesse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-des-forges', 2, 1, 'Au curé du canton, digue ding dondaine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-des-forges', 2, 2, 'Au curé du canton, dingue ding dondon');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-des-forges', 2, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-des-forges', 2, 1, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-des-forges', 3, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-des-forges', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-des-forges', 4, 0, '... qu’avez-vous fait les filles');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-des-forges', 4, 1, 'Pour demander pardon, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-des-forges', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-des-forges', 5, 0, '... j’avions couru les bals');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-des-forges', 5, 1, 'Et les jolis garçons, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-des-forges', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-des-forges', 6, 0, '... ma fille pour pénitence');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-des-forges', 6, 1, 'Nous nous embrasserons, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-des-forges', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-des-forges', 7, 0, 'Digue, ding don, don, je n’embrasse point les prêtres');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-des-forges', 7, 1, 'Mais les jolis garçons, digue ding dondaine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-des-forges', 7, 2, 'Qu’ont du poil au menton, dingue ding dondon');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-des-forges', 7, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-filles-des-forges', 7, 1, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-des-forges', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-des-forges', 8, 0, '... ce sont les filles des forges');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-des-forges', 8, 1, 'Des forges de Paimpont, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-filles-des-forges', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-filles-des-forges', 9, 0, 'La-la-la, lalala ...');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('les-fraises-et-les-framboises', 'LES FRAISES ET LES FRAMBOISES', 'FRAISES ET LES FRAMBOISES, LES', 'franstalige-liederen', 'fr', NULL, 336, 337, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-fraises-et-les-framboises', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 0, 0, 'En revenant d’Montmartre,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 0, 1, 'De Montmartre à Paris,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 0, 2, 'J’ai rencontré trois filles,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 0, 3, 'Trois fill’s de mon pays.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-fraises-et-les-framboises', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 1, 0, 'Ah! Les fraises et les framboises');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 1, 1, 'Et l’bon vin qu’nous avons bu,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 1, 2, 'Et les belles villageoises');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 1, 3, 'Que nous n’reverrons plus.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-fraises-et-les-framboises', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 2, 0, 'J’ai rencontré trois filles,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 2, 1, 'Trois fill’s de mon pays.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 2, 2, 'J’embrassai la plus jeune');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 2, 3, 'Et la plus belle aussi.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-fraises-et-les-framboises', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 3, 0, '... L’emm’nai dans ma chambrette');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 3, 1, 'Pour parler du pays');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-fraises-et-les-framboises', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 4, 0, '... Ell’ me dit: “Soyez sage”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 4, 1, 'Et près de moi s’assit.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-fraises-et-les-framboises', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 5, 0, '... Comme il n’y avait pas d’chaise');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 5, 1, 'Elle s’assit sur le lit.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-fraises-et-les-framboises', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 6, 0, '... J’entrouvis sa ch’misette');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 6, 1, 'Et vis un joli nid');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-fraises-et-les-framboises', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 7, 0, '... Puis je lui dis: “Regarde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 7, 1, 'Mon joli canari.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-fraises-et-les-framboises', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 8, 0, '... Ell’ caressa l’oisille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 8, 1, 'Et voilà qu’il grandit.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-fraises-et-les-framboises', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 9, 0, '... Et puis, battant des ailes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 9, 1, 'Il entra dans le nid.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-fraises-et-les-framboises', 10, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 10, 0, '... Il y entra si fort,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 10, 1, 'Que le cou s’y rompit.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-fraises-et-les-framboises', 11, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 11, 0, '... Pleurez, pleurez, mesdames');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 11, 1, 'La mort du canari.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-fraises-et-les-framboises', 12, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 12, 0, '... Ne pleurez plus, mesdames');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 12, 1, 'La mort du canari.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-fraises-et-les-framboises', 13, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 13, 0, '... Car la fillette, adroite,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-fraises-et-les-framboises', 13, 1, 'Le rendit à la vie.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('gilde-halewyn', 'GILDE HALEWYN', 'GILDE HALEWYN', 'franstalige-liederen', 'fr', NULL, 339, 339, 'Eric Schelstraete, februari 1988', 'Angelo Branduardi', 'Lied van de gilde van Cercle Philo, ULB');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gilde-halewyn', 0, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gilde-halewyn', 0, 0, 'Nous chantons le folklore');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gilde-halewyn', 0, 1, 'Nous chantons l’amitié');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gilde-halewyn', 0, 2, 'Nous veillons Théodore');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gilde-halewyn', 0, 3, 'Aux feux de la St V.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gilde-halewyn', 0, 4, 'Nous avons la penne fière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gilde-halewyn', 0, 5, 'Et aimons la Liberté');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gilde-halewyn', 0, 6, 'Buvons toujours à l’Université');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gilde-halewyn', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gilde-halewyn', 1, 0, 'L’ULB est la mère');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gilde-halewyn', 1, 1, 'D’un idéal de vérité');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gilde-halewyn', 1, 2, 'Et nous irons sans crainte chanter sa lumière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gilde-halewyn', 1, 3, 'C’est ainsi que la Gilde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gilde-halewyn', 1, 4, 'Pointant Laurianne vers les cieux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gilde-halewyn', 1, 5, 'Fera trembler les dogmes religieux');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gilde-halewyn', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gilde-halewyn', 2, 0, 'La VUB éclaire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gilde-halewyn', 2, 1, 'De mille feux nos horizons');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gilde-halewyn', 2, 2, 'Nous porterons sa flamme au-delà des frontières');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gilde-halewyn', 2, 3, 'C’est ainsi que la Gilde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gilde-halewyn', 2, 4, 'Mêlera le gris et le bleu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gilde-halewyn', 2, 5, 'Aux trois couleurs des bannières des Gueux');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gilde-halewyn', 3, 'direction', 1, 'Gesproken:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gilde-halewyn', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gilde-halewyn', 4, 0, 'Gris et bleu ... Bier en Geus');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('le-grand-metingue-du-metropolitain', 'LE GRAND MÉTINGUE DU MÉTROPOLITAIN', 'GRAND MÉTINGUE DU MÉTROPOLITAIN, LE', 'franstalige-liederen', 'fr', NULL, 340, 341, 'Maurice Mac Nab', 'Camille Baron', 'Maurice Mac Nab wou met dit lied spotten met de arbeiders en de opmars van de vakbonden. Maurice heeft zichzelf nooit erg serieus genomen. De arbeiders van hun kant konden de grap ervan inzien en hebben het tot een grote klassieker gemaakt. De ‘métropolitain’ waar hier wordt van gesproken, is - in tegenstelling tot wat velen denken niet de Parijse metro, maar een Rijselse vergaderzaal, waar activiteiten van de vakbonden werden georganiseerd.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-grand-metingue-du-metropolitain', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 0, 0, 'C’était hier, samedi, jour de paye,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 0, 1, 'Et le soleil se levait sur nos fronts');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 0, 2, 'J’avais déjà vidé plus d’un’ bouteille,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 0, 3, 'Si bien qu’ j’m’avais jamais trouvé si rond');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 0, 4, 'V’là la bourgeois’ qui rappliqu’ devant l’ zingue:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 0, 5, '“Feignant, qu’ell’ dit, t’as donc lâché l’ turbin?”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 0, 6, '“Oui, que j’ réponds, car je vais au métingue,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 0, 7, 'Au grand métingu’ du métropolitain!”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-grand-metingue-du-metropolitain', 0, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-grand-metingue-du-metropolitain', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 1, 0, 'Les citoyens, dans un élan sublime,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 1, 1, 'Etaient venus guidés par la raison');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 1, 2, 'A la porte, on donnait vingt-cinq centimes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 1, 3, 'Pour soutenir les grèves de Vierzon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 1, 4, 'Bref à part quatr’ municipaux qui chlinguent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 1, 5, 'Et trois sergents déguisés en pékins,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 1, 6, 'J’ai jamais vu de plus chouette métingue,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 1, 7, 'Que le métingu’ du métropolitain!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-grand-metingue-du-metropolitain', 1, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-grand-metingue-du-metropolitain', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 2, 0, 'Y avait Basly, le mineur indomptable,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 2, 1, 'Camélinat, l’orgueille du pays');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 2, 2, 'Ils sont grimpés tous deux sur une table,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 2, 3, 'Pour mettre la question sur le tapis');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 2, 4, 'Mais, tout à coup, on entend du bastringue;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 2, 5, 'C’est un mouchard qui veut fair’ le malin!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 2, 6, 'Il est venu pour troubler le métingue,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 2, 7, 'Le grand métingu’ du métropolitain!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-grand-metingue-du-metropolitain', 2, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-grand-metingue-du-metropolitain', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 3, 0, 'Moi j’ tomb’ dessus, et pendant qu’il proteste,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 3, 1, 'D’un grand coup d’ poing, j’y renfonc’ son chapeau.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 3, 2, 'Il déguerpit sans demander son reste,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 3, 3, 'En faisant signe aux quatr’ municipaux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 3, 4, 'A la faveur de c’que j’étais brind’zingue');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 3, 5, 'On m’a conduit jusqu’au poste voisin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 3, 6, 'Et c’est comm’ ça qu’a fini le métingue,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 3, 7, 'Le grand métingu’ du métropolitain!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-grand-metingue-du-metropolitain', 3, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-grand-metingue-du-metropolitain', 4, 'direction', 1, 'Moraal:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-grand-metingue-du-metropolitain', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 5, 0, 'Peuple français, la Bastille est détruite,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 5, 1, 'Et y a z’encor des cachots pour tes fils!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 5, 2, 'Souviens-toi des géants de quarante-huite');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 5, 3, 'Qu’étaient plus grands qu’ ceuss’ d’au jour d’aujourd’hui');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 5, 4, 'Car c’est toujours l’ pauvre ouverrier qui trinque,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 5, 5, 'Mêm’ qu’on le fourre au violon pour un rien,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 5, 6, 'C’était tout d’ même un bien chouette métingue,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-grand-metingue-du-metropolitain', 5, 7, 'Que le métingu’ du métropolitain!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-grand-metingue-du-metropolitain', 5, 6, 7, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('l-homme-au-puissant-braquemart', 'L’HOMME AU PUISSANT BRAQUEMART', 'HOMME AU PUISSANT BRAQUEMART, L’', 'franstalige-liederen', 'fr', NULL, 342, 343, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('l-homme-au-puissant-braquemart', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 0, 0, 'Sacrée putain tu recules');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 0, 1, 'Je n’en puis plus de bander');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 0, 2, 'Regarde mes testicules');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 0, 3, 'Ils vont bientôt éclater');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 0, 4, 'Le foutre, c’est ridicule');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 0, 5, 'Va jaillir comme un geyser');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 0, 6, 'Amèn’ ici ton derrière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 0, 7, 'Pour qu’à la fin je t’encule');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('l-homme-au-puissant-braquemart', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 1, 0, 'Je suis l’homme');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 1, 1, 'Au puissant braquemart');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 1, 2, 'Je suis l’homme');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 1, 3, 'Au gros dard');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('l-homme-au-puissant-braquemart', 1, 0, 0, 3, '(TER)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('l-homme-au-puissant-braquemart', 1, 2, 2, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('l-homme-au-puissant-braquemart', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 2, 0, 'Mais les putains me dégoûtent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 2, 1, 'Il faut toujours les payer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 2, 2, 'D’autant plus que ma bell’ zoute');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 2, 3, 'N’aime pas les enculer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 2, 4, 'Le trou du cul ell’s le planquent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 2, 5, 'Quand j’arrive dans la rue');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 2, 6, 'C’est pourquoi il faut qu’ je bande');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 2, 7, 'Pour leur démolir l’anus');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('l-homme-au-puissant-braquemart', 3, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 3, 0, 'À bas l’homme');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 3, 1, 'Au puissant braquemart');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 3, 2, 'À bas l’homme');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 3, 3, 'Au gros dard');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('l-homme-au-puissant-braquemart', 3, 0, 0, 3, '(TER)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('l-homme-au-puissant-braquemart', 3, 2, 2, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('l-homme-au-puissant-braquemart', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 4, 0, 'Je vais monter à Pigalle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 4, 1, 'Sur le trottoir du milieu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 4, 2, 'J’irai chercher les pédales');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 4, 3, 'Qui aimeront mon gros noeud');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 4, 4, 'Sans la moindre résistance');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 4, 5, 'Dans leur merde je foutr’rai');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 4, 6, 'Et puis pour leur récompense');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 4, 7, 'Sur leur cul je m’essuierai');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('l-homme-au-puissant-braquemart', 5, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 5, 0, 'Vive l’homme');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 5, 1, 'Au puissant braquemart');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 5, 2, 'Vive l’homme');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('l-homme-au-puissant-braquemart', 5, 3, 'Au gros dard');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('l-homme-au-puissant-braquemart', 5, 0, 0, 3, '(TER)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('l-homme-au-puissant-braquemart', 5, 2, 2, 3, '(TER)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('le-hussard-de-la-garde', 'LE HUSSARD DE LA GARDE', 'HUSSARD DE LA GARDE, LE', 'franstalige-liederen', 'fr', NULL, 343, 346, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-hussard-de-la-garde', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 0, 0, 'C’était un hussard de la garde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 0, 1, 'Qui revenait de garnison');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 0, 2, 'De Briançon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 0, 3, 'Portant sa pine en hallebarde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 0, 4, 'Agrémentée de deux roustons');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 0, 5, 'Pleins de morpions.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-hussard-de-la-garde', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 1, 0, 'Vivre sans souci, boire du purin, manger d’la merde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 1, 1, 'C’est le seul moyen de ne jamais crever de faim');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 1, 2, 'O merde, merde divine! Toi seule a des appas');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 1, 3, 'La rose a des épines; toi, merde, tu n’en as pas.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-hussard-de-la-garde', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 2, 0, 'En descendant de la rue Trouss’couille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 2, 1, 'Il rencontra la garc’ Manon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 2, 2, 'Qui pue du con');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 2, 3, 'Il lui dit: “Ma chaste vadrouille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 2, 4, 'Le régiment s’en va demain');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 2, 5, 'La pine en main”.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-hussard-de-la-garde', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 3, 0, 'En vain Manon se désespère');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 3, 1, 'De voir partir tous ses amis');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 3, 2, 'Avec leurs vits');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 3, 3, 'Ell’ va trouver madam’ sa mère');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 3, 4, 'Lui dit: “Je veux partir aussi');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 3, 5, 'Sacrée chipie”.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-hussard-de-la-garde', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 4, 0, '“Ma fill’, ma sacrée garc’ de fille,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 4, 1, 'N’vas pas avec ce hussard-là');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 4, 2, 'Il te perdra!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 4, 3, 'Ils t’ont fendue jusqu’au nombril(e)');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 4, 4, 'Ils te fendraient jusqu’au menton');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 4, 5, 'La peau du con”.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-hussard-de-la-garde', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 5, 0, '“Ma fill’, ma sacrée garc’ de fille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 5, 1, 'Quand s’ra parti ce hussard-là');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 5, 2, 'Tu te branl’ras');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 5, 3, 'Je t’achèt’rai une cheville');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 5, 4, 'Avec laquelle tu t’ masturb’ras');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 5, 5, 'À tour de bras.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-hussard-de-la-garde', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 6, 0, '“Ma mère, mon vieux chameau de mère');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 6, 1, 'Quand tu parles de me branler');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 6, 2, 'Tu m’fais chier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 6, 3, 'Un vit, ça sort de l’ordinaire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 6, 4, 'Ça vous laisse un doux souvenir');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 6, 5, 'Qui fait jouir”.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-hussard-de-la-garde', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 7, 0, 'La garc’ s’est quand mêm’ laissée faire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 7, 1, 'Par le hussard qui la pressait');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 7, 2, 'De se donner');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 7, 3, 'Il lui mit un’ si longue affaire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 7, 4, 'Que ça ressortait par le nez');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 7, 5, 'Ça l’a tuée.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-hussard-de-la-garde', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 8, 0, 'Manon la sacrée garce est morte');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 8, 1, 'Morte comme elle avait vécu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 8, 2, 'La pine au cul');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 8, 3, 'Le corbillard est à sa porte');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 8, 4, 'Traîné par quatr’ morpions en deuil');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 8, 5, 'La larme à l’œil.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-hussard-de-la-garde', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 9, 0, 'Ils l’ont conduite au cimetière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 9, 1, 'Et sur sa tombe ils ont gravé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 9, 2, 'Tous ces couplets');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 9, 3, 'Mais le fossoyeur par derrière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 9, 4, 'L’a déterrée et l’a violée');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 9, 5, 'Ca lui manquait.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-hussard-de-la-garde', 10, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 10, 0, 'L’auteur de cette barcarolle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 10, 1, 'Est un bon hussard à chevrons');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 10, 2, 'Foutu cochon!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 10, 3, 'Quand il mourut de la vérole');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 10, 4, 'Les asticots qui l’ont bouffé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-hussard-de-la-garde', 10, 5, 'Ont dégueulé.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('il-faut-boire', 'IL FAUT BOIRE', 'IL FAUT BOIRE', 'franstalige-liederen', 'fr', NULL, 346, 347, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('il-faut-boire', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('il-faut-boire', 0, 0, 'Quand au monde on est venu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('il-faut-boire', 0, 1, 'Braillant, suintant et tout nu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('il-faut-boire', 0, 2, 'Une voix dit, péremptoire:');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('il-faut-boire', 0, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('il-faut-boire', 0, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('il-faut-boire', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('il-faut-boire', 1, 0, 'Il faut boire,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('il-faut-boire', 1, 1, 'Boire et toujours boire.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('il-faut-boire', 1, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('il-faut-boire', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('il-faut-boire', 2, 0, 'Toute la vie durant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('il-faut-boire', 2, 1, 'A la fête au premier rang');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('il-faut-boire', 2, 2, 'Pour submerger nos déboires:');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('il-faut-boire', 2, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('il-faut-boire', 2, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('il-faut-boire', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('il-faut-boire', 3, 0, 'Dans nos goussets trop souvent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('il-faut-boire', 3, 1, 'Ne résonne que le vent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('il-faut-boire', 3, 2, 'Aux frais d’une bonne poire,');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('il-faut-boire', 3, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('il-faut-boire', 3, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('il-faut-boire', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('il-faut-boire', 4, 0, 'Sans souci du lendemain');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('il-faut-boire', 4, 1, 'En attendant l’examen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('il-faut-boire', 4, 2, 'Au diplôme aléatoire,');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('il-faut-boire', 4, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('il-faut-boire', 4, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('il-faut-boire', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('il-faut-boire', 5, 0, 'Tant que nos femmes auront');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('il-faut-boire', 5, 1, 'Seins jeunes, fermes et ronds');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('il-faut-boire', 5, 2, 'Lèvr’s en feu, prunelles noires,');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('il-faut-boire', 5, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('il-faut-boire', 5, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('il-faut-boire', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('il-faut-boire', 6, 0, 'Quand la Camarde viendra');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('il-faut-boire', 6, 1, 'Nous cueillir entre ses bras');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('il-faut-boire', 6, 2, 'Pour finir gaiement l’histoire,');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('il-faut-boire', 6, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('il-faut-boire', 6, 1, 1, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('j-ai-choppe-la-diarrhee', 'J’AI CHOPPÉ LA DIARRHÉE', 'J’AI CHOPPÉ LA DIARRHÉE', 'franstalige-liederen', 'fr', NULL, 347, 348, 'René La Taupe', '‘The Lion sleeps tonight’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('j-ai-choppe-la-diarrhee', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 0, 0, 'Dans mes fringues');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 0, 1, 'Ça pue, ça chlingue');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 0, 2, 'Mais que s’est-il passé?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 0, 3, 'J’ai la chiasse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 0, 4, 'La méga chiasse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 0, 5, 'Mon slip a dérouillé');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('j-ai-choppe-la-diarrhee', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 1, 0, 'Moi, j’ai caqué (14×)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('j-ai-choppe-la-diarrhee', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 2, 0, 'Dans mon ventre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 2, 1, 'Y a tout qui fermente');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 2, 2, 'C’est une usine à pet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 2, 3, 'Ça gargouille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 2, 4, 'Ça part en couilles');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 2, 5, 'Mon cul fait des fusées');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('j-ai-choppe-la-diarrhee', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 3, 0, 'J’ai des spasmes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 3, 1, 'C’est pas l’orgasme');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 3, 2, 'J’ai chopé la diarrhée');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 3, 3, 'C’est le stress');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 3, 4, 'Je sers les fesses');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 3, 5, 'Sinon je chie en spray');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('j-ai-choppe-la-diarrhee', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 4, 0, 'J’ai des gaz');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 4, 1, 'C’est le carnage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 4, 2, 'Mon cul va exploser');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 4, 3, 'Faut qu’ça cesse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 4, 4, 'L’odeur m’agresse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('j-ai-choppe-la-diarrhee', 4, 5, 'J’vais mourir asphyxié');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('je-baise-avec-ma-pine', 'JE BAISE AVEC MA PINE', 'JE BAISE AVEC MA PINE', 'franstalige-liederen', 'fr', NULL, 348, 349, 'Corporatio Bruxellensis!', '‘Titine’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-baise-avec-ma-pine', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 0, 0, 'Je baise avec ma pine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 0, 1, 'Ma pin’, ma grosse pine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 0, 2, 'Ma pine, elle est divine');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-baise-avec-ma-pine', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 1, 0, 'Je ne m’en lasse pas');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 1, 1, 'Tralalalala lala');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('je-baise-avec-ma-pine', 1, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-baise-avec-ma-pine', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 2, 0, 'J’aime les rastaquouères');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 2, 1, 'Dont le cul prolétaire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 2, 2, 'M’attire dans l’ornière!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-baise-avec-ma-pine', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 3, 0, 'J’aime les nymphomanes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 3, 1, 'Dont le cul mélomane');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 3, 2, 'Me fait aimer les gammes.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-baise-avec-ma-pine', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 4, 0, 'Je promène en Asie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 4, 1, 'En Perse et en Russie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 4, 2, 'Ma vieill’ blennorragie.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-baise-avec-ma-pine', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 5, 0, 'Les femmes d’Argentine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 5, 1, 'Ont un p’tit air coquine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 5, 2, 'Mon tich dans les narines.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-baise-avec-ma-pine', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 6, 0, 'Quand j’ vais aux antipodes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 6, 1, 'Je baise à tout’s les modes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 6, 2, 'Debout sur la commode.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-baise-avec-ma-pine', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 7, 0, 'J’ai enfilé des bègues');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 7, 1, 'Des longs, des minc’s, des maigres,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 7, 2, 'Des voleurs, des intègres.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-baise-avec-ma-pine', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 8, 0, 'Quand je voyage en Grèce,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 8, 1, 'Je m’y prends à mon aise');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 8, 2, 'Je baise les obèses.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-baise-avec-ma-pine', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 9, 0, 'Les femmes du Mexique');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-baise-avec-ma-pine', 9, 1, 'D’un’ façon hystérique');
