INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('je-cherche-fortune', 'JE CHERCHE FORTUNE', 'JE CHERCHE FORTUNE', 'franstalige-liederen', 'fr', NULL, 350, 352, 'Het refrein van dit lied is het refrein van ‘Le chat noir’ van Aristide Bruant, uit 1884; één van zijn vele liederen voor het gelijknamige Parijse cabaret. De herkomst van de strofen kon niet achterhaald worden, maar is studentikoos van oorsprong.', 'Occitaanse ballade, ‘Aqueros Montagneros’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-cherche-fortune', 0, 'direction', 1, 'Wordt voorgezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-cherche-fortune', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 1, 0, 'Chez l’ boulanger');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 1, 1, 'Fais-moi crédit.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 1, 2, 'J’ n’ai plus d’argent,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 1, 3, 'J’ paierai sam’di');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 1, 4, 'Si tu n’ veux pas');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 1, 5, 'M’ donner du pain');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 1, 6, 'J’ te cass’ la gueule');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 1, 7, 'Dans ton pétrin.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('je-cherche-fortune', 1, 0, 0, 2, '(BIS)');
