INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-cherche-fortune', 2, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 2, 0, 'Non, c’est pas moi, c’est ma soeur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 2, 1, 'Qui a cassé la machine à vapeur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 2, 2, 'Ta gueule! Ta gueule! Ta gueule!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 2, 3, 'Je cherche fortune, autour du “Chat Noir”,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 2, 4, 'Au clair de la lune à Montmartre, le soir.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-cherche-fortune', 3, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-cherche-fortune', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 4, 0, 'Chez l’ marchand d’ frites ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 4, 1, 'M’ donner des frites');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 4, 2, 'J’ te cass’ la gueule');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 4, 3, 'Dans tes marmites.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-cherche-fortune', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 5, 0, 'Chez l’ cabar’tier ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 5, 1, 'M’ donner à boire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 5, 2, 'J’ te cass’ la gueule');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 5, 3, 'Sur ton comptoir.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-cherche-fortune', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 6, 0, 'Marchand d’ tabac ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 6, 1, 'M’ donner des sèches');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 6, 2, 'J’fais dans ta gueule');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 6, 3, 'Un’ large brèche.');
