INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 7, 0, 'Chez la putain ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 7, 1, 'Baiser à l’œil');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 7, 2, 'J’ te cass’ la gueule');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 7, 3, 'Dans ton fauteuil.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-cherche-fortune', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 8, 0, 'Chez l’ autr’ putain ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 8, 1, 'M’ prêter ton con');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 8, 2, 'J’ te bouff’ le cul');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 8, 3, 'Et les nichons.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-cherche-fortune', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 9, 0, 'Chez l’ aubergiste ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 9, 1, 'M’ donner un’ chambre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 9, 2, 'J’ te cass’ la gueule');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 9, 3, 'Et les cinq membres.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-cherche-fortune', 10, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 10, 0, 'Chez l’ chirurgien ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 10, 1, 'Soigner mon p’tit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 10, 2, 'J’ t’enfonc’ dans l’ cul');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 10, 3, 'Ton bistouri.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-cherche-fortune', 11, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 11, 0, 'Chez l’ pharmacien ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 11, 1, 'M’ donner d’ potion');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 11, 2, 'J’ te cass’ la gueule');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 11, 3, 'Dans tes flacons.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('je-cherche-fortune', 12, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 12, 0, 'Chez M’sieur l’ curé ...');
