INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 12, 2, 'J’ te cass’ la gueule');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('je-cherche-fortune', 12, 3, 'Dans l’ bénitier.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('jeanneton', 'JEANNETON', 'JEANNETON', 'franstalige-liederen', 'fr', NULL, 352, 353, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jeanneton', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 0, 0, 'Jeanneton prend sa faucille,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 0, 1, 'Lahirette, lahirette,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 0, 2, 'Jeanneton prend sa faucille,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 0, 3, 'Pour aller couper des joncs.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('jeanneton', 0, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jeanneton', 1, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jeanneton', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 2, 0, 'En chemin, elle rencontre,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 2, 1, 'Quatre jeun’s et beaux garçons,');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jeanneton', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 3, 0, 'Le premier, un peu timide,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 3, 1, 'Lui caressa le menton,');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jeanneton', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 4, 0, 'Le second un peu moins sage,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 4, 1, 'La coucha sur le gazon,');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jeanneton', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 5, 0, 'Le troisième un intrépide,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 5, 1, 'Lui souleva le jupon,');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jeanneton', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 6, 0, 'Ce que fit le quatrième,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 6, 1, 'N’est pas dit dans la chanson,');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jeanneton', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 7, 0, 'Si vous le saviez, mesdames,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 7, 1, 'Vous iriez couper des joncs,');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jeanneton', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 8, 0, 'La moral’ de cet’histoire,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 8, 1, 'C’est que les hommes sont des cochons!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jeanneton', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 9, 0, 'La moral’ de cette morale,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 9, 1, 'C’est que les femmes aiment les cochons!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('jeanneton', 10, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 10, 0, 'La morale de ces morales,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('jeanneton', 10, 1, 'C’est qu’ils font des p’tits cochons!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-jeune-fille-du-metro', 'LA JEUNE FILLE DU MÉTRO', 'JEUNE FILLE DU MÉTRO, LA', 'franstalige-liederen', 'fr', NULL, 353, 354, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-jeune-fille-du-metro', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 0, 0, 'C’était une jeune fille chaste et bonne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 0, 1, 'Qui n’refusait rien a personne.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 0, 2, 'Un jour dans l’ métro y’avait presse,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 0, 3, 'Un jeune homme osa, je l’ confesse,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 0, 4, 'Lui passer la main dans les ... ch’veux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 0, 5, 'Comme elle avait bon coeur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 0, 6, 'Elle s’approcha un peu.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-jeune-fille-du-metro', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 1, 0, 'L’ jeune homme vit l’mouvement d’la demoiselle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 1, 1, 'Il se rapprocha de plus belle;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 1, 2, 'Mais comme en chaque homme tout de suite');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 1, 3, 'S’éveille le cochon qui l’habite,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 1, 4, 'Sans tarder il sortit sa ... carte,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 1, 5, 'Lui dit qu’il s’app’lait Jules');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 1, 6, 'Et d’meurait rue Descartes.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-jeune-fille-du-metro', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 2, 0, 'L’ métro continuait son voyage.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 2, 1, 'Elle dit: “Ce jeun’ homme n’est pas sage,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 2, 2, 'Je sens quelque chose de pointu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 2, 3, 'Qui, d’un air ferme et convaincu,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 2, 4, 'Cherch’ à pénétrer dans mon ... coeur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 2, 5, 'Ah, qu’il est doux d’aimer,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 2, 6, 'Doux frisson du bonheur!”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-jeune-fille-du-metro', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 3, 0, 'Comm’ elle avait peur pour sa robe,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 3, 1, 'À cett’ attaque elle se dérobe;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 3, 2, 'Voulant savoir c’ qui la chatouille,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 3, 3, 'Derrièr’ son dos elle tripatouille,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 3, 4, 'Et tomb’ sur une belle paire de ... gants,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 3, 5, 'Que l’ jeune homme, à la main,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 3, 6, 'Tenait négligemment.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-jeune-fille-du-metro', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 4, 0, 'Ainsi à Paris quand on s’aime,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 4, 1, 'On peut s’le dire en public même.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 4, 2, 'Les amoureux ne s’font pas d’bile,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 4, 3, 'Entre tout l’monde, ils se faufilent,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 4, 4, 'Je crois même bien qu’ils s’en ... fichent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 4, 5, 'L’amour ouvrant les yeux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-jeune-fille-du-metro', 4, 6, 'Même aux gens très godiches.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('le-joueur-de-luth', 'LE JOUEUR DE LUTH', 'JOUEUR DE LUTH, LE', 'franstalige-liederen', 'fr', NULL, 355, 356, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-joueur-de-luth', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 0, 0, 'En notre ville est venu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 0, 1, 'Un fameux joueur de luth');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 0, 2, 'Pour attirer la pratique');
