INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-joueur-de-luth', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 3, 0, 'Toutes les fill’s de Paris');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 3, 1, 'De Versailles à Saint-Denis');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 3, 2, 'Ont vendu leur chemisette');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 3, 3, 'Leurs jarr’tièr’s, leurs collerettes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 3, 4, 'Afin d’avoir un écu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 3, 5, 'Pour apprendre à jouer de l’épinette ...');
