INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-joueur-de-luth', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 4, 0, 'Un’ jeun’ fille se présenta');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 4, 1, 'Qui des leçons demanda');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 4, 2, 'Ah! Que tes leçons sont bonnes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 4, 3, 'Il faudra que tu m’en r’donnes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 4, 4, 'Tiens voilà mon jeune écu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 4, 5, 'Pour apprendre à jouer de l’épinette ...');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-joueur-de-luth', 4, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-joueur-de-luth', 4, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-joueur-de-luth', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 5, 0, 'Un’ vieille femme aux cheveux gris');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 5, 1, 'Voulut en tâter aussi');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 5, 2, 'Fais-moi passer la première');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 5, 3, 'Par la porte de derrière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 5, 4, 'Tiens voilà mon vieil écu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 5, 5, 'Pour apprendre à jouer de l’épinette ...');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-joueur-de-luth', 5, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-joueur-de-luth', 5, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-joueur-de-luth', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 6, 0, 'Vieille femme allez-vous en');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 6, 1, 'Et reprenez votr’ argent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 6, 2, 'Car ce n’est plus à votre âge');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 6, 3, 'Qu’on entre en apprentissage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 6, 4, 'Vous avez trop attendu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 6, 5, 'Pour apprendre à jouer de l’épinette ...');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-joueur-de-luth', 6, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-joueur-de-luth', 6, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-joueur-de-luth', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 7, 0, 'La viell’ femme en s’en allant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 7, 1, 'Marmonnait entre ses dents:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 7, 2, '“Ah! Vous me la baillez belle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 7, 3, 'De me croire encore pucelle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 7, 4, 'Voilà cinquante ans et plus');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 7, 5, 'Que je sais jouer de l’épinette ...”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-joueur-de-luth', 7, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-joueur-de-luth', 7, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-joueur-de-luth', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 8, 0, 'La morale de ceci');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 8, 1, 'Je vais vous la dire ici:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 8, 2, 'C’est quand on est jeune et belle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 8, 3, 'Qu’il n’faut pas rester pucelle.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 8, 4, 'Faut donner son p’tit écu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-joueur-de-luth', 8, 5, 'Pour apprendre à jouer de l’épinette ...');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-joueur-de-luth', 8, 0, 0, 2, '(BIS)');
