INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('le-kyrie-des-moines', 'LE KYRIÉ DES MOINES', 'KYRIÉ DES MOINES, LE', 'franstalige-liederen', 'fr', NULL, 357, 357, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-kyrie-des-moines', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 0, 0, 'Kyrié, kyrié, dans la chambre de nos abbés');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 0, 1, 'On n’y boit, on n’y boit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 0, 2, 'Que des vins bi-en cachetés,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 0, 3, 'Mais nous autres, pauvres apôtres,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 0, 4, 'Pauvres moines, tripaillons de moines.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 0, 5, 'Sacré nom de Dieu de religieux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 0, 6, 'Nous ne buvons que des vins frelatés, Eleison,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 0, 7, 'Kyrié Christe Dominum nostrum. Kyrié, Eleison.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-kyrie-des-moines', 1, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-kyrie-des-moines', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 2, 0, 'Kyrié, kyrié, dans la chambre de nos abbés');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 2, 1, 'On n’y mange, on n’y mange');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 2, 2, 'Que des plats bi-en préparés, ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 2, 3, '... Nous ne mangeons que des mets avariés, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-kyrie-des-moines', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 3, 0, 'Kyrié, kyrié, dans la chambre de nos abbés');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 3, 1, 'On se couche, on se couche');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 3, 2, 'Sur des matelas bien douillets, ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 3, 3, '... Nous nous couchons sur la paille de blé ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-kyrie-des-moines', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 4, 0, 'Kyrié, kyrié, dans la chambre de nos abbés');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 4, 1, 'On n’y baise, on n’y baise');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 4, 2, 'Que des femmes de qualité, ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 4, 3, '... Nous ne baisons que des cons vérolés ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-kyrie-des-moines', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 5, 0, 'Kyrié, kyrié, dans la chambre de nos abbés');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 5, 1, 'On n’encule, on n’encule');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 5, 2, 'Que des petits bien balancés, ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-kyrie-des-moines', 5, 3, '... Nous ne pouvons que nous entreculer ...');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('les-legionnaires', 'LES LÉGIONNAIRES', 'LÉGIONNAIRES, LES', 'franstalige-liederen', 'fr', NULL, 359, 360, NULL, 'De strofen worden gezongen tegen 88bpm, het aan de Afrikaanse hitte aangepaste marsritme van het Vreemdelingenlegioen.', 'Gebaseerd op het lied van ‘Les Bat’d’Afs’, de Afrika-bataljons waar de vrijwilligers voor het Vreemdelingenlegioen werden naar toegestuurd die een gevangenisstraf uitzaten.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-legionnaires', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 0, 0, 'Il est, sur la terre africaine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 0, 1, 'Un régiment dont les soldats, dont les soldats,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 0, 2, 'Sont tous des gars qui n’ont pas d’veine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 0, 3, 'C’est la légion et nous voilà, et nous voilà!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 0, 4, 'Pour ce qui est d’la discipline,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 0, 5, 'Faut être passé par Biribi, par Biribi!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 0, 6, 'Avoir goûté de la praline,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 0, 7, 'Et travaillé du bistouri, du bistouri ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-legionnaires', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 1, 0, 'Et on s’en fout, et après tout,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 1, 1, 'Qu’est-ce que ça fout?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 1, 2, 'En marchant sur la grand-route,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 1, 3, 'Souviens-toi, oui souviens-toi, ah! ah! ah!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 1, 4, 'Les anciens l’ont fait sans doute,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 1, 5, 'Avant toi, ou avant moi, ah! ah! ah!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 1, 6, 'De Gabés à Ténérive');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 1, 7, 'De Tanger à Tombouctou, ouh! ouh! ouh!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 1, 8, 'Sac au dos dans la poussière,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 1, 9, 'Marchons les légionnaires ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-legionnaires', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 2, 0, 'J’ai vu mourir un pauvre gosse,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 2, 1, 'Un pauvre gosse de 18 ans, de 18 ans');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 2, 2, 'Paumé par les balles féroces,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 2, 3, 'Il est mort en criant maman, criant maman!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 2, 4, 'Je lui ai fermé les paupières,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 2, 5, 'Recueilli son dernier soupir, dernier soupir!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 2, 6, 'J’ai écrit à sa pauvre mère,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 2, 7, 'Qu’un légionnaire, ça sait mourir, ça sait mourir ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-legionnaires', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 3, 0, 'Et puisqu’on n’a jamais eu d’ veine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 3, 1, 'Pour sûr qu’un jour, on y crèvera, on y crèvera');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 3, 2, 'Sur cette putain d’ terre africaine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 3, 3, 'Enterrés sous le sable chaud, le sable chaud!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 3, 4, 'Avec pour croix une baïonnette,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 3, 5, 'À l’endroit où l’on est tombé, on est tombé!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 3, 6, 'Qui voulez-vous qui nous regrette,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-legionnaires', 3, 7, 'Puisqu’on est tous des réprouvés, des réprouvés?');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ma-femme-est-morte', 'MA FEMME EST MORTE', 'MA FEMME EST MORTE', 'franstalige-liederen', 'fr', NULL, 360, 362, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ma-femme-est-morte', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 0, 0, 'Jean, l’autre soir, en montant l’escalier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 0, 1, 'Trouva sa femme étendu’ sur l’palier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 0, 2, 'Ohé, portier ma femme est morte!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 0, 3, 'Venez, venez vit’, pour me la chercher,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 0, 4, 'Ou bien j’la fous derrièr’ la porte.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ma-femme-est-morte', 0, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ma-femme-est-morte', 0, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ma-femme-est-morte', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 1, 0, 'Car c’était elle qui faisait le chahut à la maison');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 1, 1, 'La guenon, la poison, elle est morte!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 1, 2, 'Elle ne mettra plus de l’eau dedans mon verre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 1, 3, 'La guenon, la poison, elle est morte!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ma-femme-est-morte', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 2, 0, 'Puis il s’en fut réveiller les copains');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 2, 1, 'Fit tant d’potin, qu’il fit lever Martin:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 2, 2, 'Eh, les copains! Ma femme est morte!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 2, 3, 'C’est moi qui paie la goutt’ demain matin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 2, 4, 'Si vous venez lui faire escorte.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ma-femme-est-morte', 2, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ma-femme-est-morte', 2, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ma-femme-est-morte', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 3, 0, 'Puis il s’en vint trouver Monsieur l’curé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 3, 1, 'Qui ronflait fort sous son bonnet carré:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 3, 2, 'Ohé, curé! Ma femme est morte!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 3, 3, 'Donnez, donnez-lui tout’s vos oraisons');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 3, 4, 'Et puis que le diable l’emporte.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ma-femme-est-morte', 3, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ma-femme-est-morte', 3, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ma-femme-est-morte', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 4, 0, 'Puis il s’en fut trouver le fossoyeur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 4, 1, 'Qui dans un’ foss’ dormait à la fraîcheur:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 4, 2, 'Eh, fossoyeur! Ma femme est morte!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 4, 3, 'Faits-lui un trou si grand et si profond');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 4, 4, 'De peur que la garc’ n’en ressorte.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ma-femme-est-morte', 4, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ma-femme-est-morte', 4, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ma-femme-est-morte', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 5, 0, 'Puis moult oignons, Jean s’en fut acheter');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 5, 1, 'Pour qu’en son deuil on le vit bien pleurer:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 5, 2, 'Ohé, fruitier! Ma femme est morte!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 5, 3, 'Donnez, donnez-moi des oignons biens dorés');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 5, 4, 'Pour que je la pleure en la sorte.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ma-femme-est-morte', 5, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ma-femme-est-morte', 5, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ma-femme-est-morte', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 6, 0, 'Puis il s’en vint retrouver sa moitié');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 6, 1, 'Sa garc’ de femme avait ressuscité:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 6, 2, 'Oh Aglaé, tu n’es pas morte!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 6, 3, 'Elle lui répondit, le pot de chambre au poing:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 6, 4, '“Voici la tisan’ que j’ t’apporte.”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ma-femme-est-morte', 6, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ma-femme-est-morte', 6, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ma-femme-est-morte', 7, 'direction', 1, 'Laatste refrein:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ma-femme-est-morte', 8, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 8, 0, 'Et comm’ toujours, je ferai le chahut à la maison');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 8, 1, 'Ta guenon, ta poison, n’est pas morte!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 8, 2, 'Et je mettrai de l’eau dedans ton verre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-femme-est-morte', 8, 3, 'Ta guenon, ta poison, n’est pas morte!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ma-mere-m-a-donne-cent-sous', 'MA MÈRE M’A DONNÉ CENT SOUS', 'MA MÈRE M’A DONNÉ CENT SOUS', 'franstalige-liederen', 'fr', NULL, 362, 363, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ma-mere-m-a-donne-cent-sous', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 0, 0, 'Ma mère m’a donné cent sous,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 0, 1, 'Pour acheter des bretelles,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 0, 2, 'J’ai gardé mes cent sous,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 0, 3, 'Pour aller au bordel,');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ma-mere-m-a-donne-cent-sous', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 1, 0, 'Tra la la la la la');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 1, 1, 'Tra la la la la la la');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ma-mere-m-a-donne-cent-sous', 1, 0, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ma-mere-m-a-donne-cent-sous', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 2, 0, 'Chemin faisant,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 2, 1, 'J’ai rencontré grand-mère,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 2, 2, 'Elle m’a dit: “Où vas-tu?”,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 2, 3, '“Je m’en vais au bordel.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ma-mere-m-a-donne-cent-sous', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 3, 0, '“Espèce de petit salaud,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 3, 1, 'Ne ferais-je pas l’ affaire?”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 3, 2, 'Moi, j’ai gardé mes cent sous,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 3, 3, 'Et j’ai baisé grand-mère.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ma-mere-m-a-donne-cent-sous', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 4, 0, 'Chemin revenant,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 4, 1, 'J’ai rencontré mon père,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 4, 2, 'Qui m’a dit: “D’où viens-tu?”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 4, 3, '“Je viens d’baiser grand-mère!”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ma-mere-m-a-donne-cent-sous', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 5, 0, '“Espèce d’petit salaud,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 5, 1, 'Tu as baisé ma mère.”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 5, 2, 'Et moi je lui répond:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ma-mere-m-a-donne-cent-sous', 5, 3, '“Tu baises bien la mienne!”');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('marche-americaine', 'MARCHE AMÉRICAINE', 'MARCHE AMÉRICAINE', 'franstalige-liederen', 'fr', NULL, 363, 363, NULL, '‘Stars and stripes’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('marche-americaine', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marche-americaine', 0, 0, 'Une fois!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marche-americaine', 0, 1, 'Deux fois!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marche-americaine', 0, 2, 'Trois fois!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marche-americaine', 0, 3, 'Quatre fois!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marche-americaine', 0, 4, 'Cinq fois!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marche-americaine', 0, 5, 'Six fois!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marche-americaine', 0, 6, 'Cette fois je sens bien que çà vient! *');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marche-americaine', 0, 7, 'Ce n’est plus ton p’tit doigt qui m’chatouille,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marche-americaine', 0, 8, 'Je sens bien ton nombril contre le mien');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marche-americaine', 0, 9, 'Et la chaleur de tes deux couilles,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marche-americaine', 0, 10, 'Ton doigt n’était pas si mouillé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marche-americaine', 0, 11, 'Et ta main ne battait pas la cadence');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marche-americaine', 0, 12, 'Cette fois c’est bien plus régulier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marche-americaine', 0, 13, 'Ah nom de Dieu! Ah nom de Dieu!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marche-americaine', 0, 14, 'Quelle jouissance!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marche-americaine', 0, 15, 'Ah nom de Dieu! Ah nom de Dieu!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marche-americaine', 0, 16, 'Qu’on recommence!');
INSERT INTO footnote (song_id, position, text) VALUES ('marche-americaine', 0, '* De jongens zingen wat er staat, de meisjes: “Cette fois je sens bien que tu m’ l’as mis!”');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-marche-des-etudiants', 'LA MARCHE DES ÉTUDIANTS', 'MARCHE DES ÉTUDIANTS, LA', 'franstalige-liederen', 'fr', NULL, 365, 366, 'Paul Vanderborght, 1919', '‘Les Gueux’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-marche-des-etudiants', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 0, 0, 'Nous sommes ceux qu’anime la folie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 0, 1, 'Et qui s’en vont ivres de liberté;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 0, 2, 'Nous faisons guerr’ à la mélancolie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 0, 3, 'Ou la cachons sous des cris de gaieté.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 0, 4, 'Bourgeois sans feu, votre vie est banale:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 0, 5, 'Les préjugés guident vos fronts tremblants;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 0, 6, 'Chez nous, l’on a l’humeur paradoxale,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 0, 7, 'Le coeur léger, et le gosier brûlant.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-marche-des-etudiants', 0, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-marche-des-etudiants', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 1, 0, 'Des vieux gaulois nous gardons la mémoire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 1, 1, 'En les chantant perchés sur nos tonneaux;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 1, 2, 'Si le bourgeois veut nous payer à boire,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 1, 3, 'Nous le suivrons jusqu’au fond des caveaux.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 1, 4, 'Fraternité, tu nais entre les verres;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 1, 5, 'Ami, buvons à la Fraternité!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 1, 6, 'Haro! Haro sur les mines sévères!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 1, 7, 'Pourquoi Bacchus n’est-il pas député?');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-marche-des-etudiants', 1, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-marche-des-etudiants', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 2, 0, 'Si nous avons parfois la bourse plate,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 2, 1, 'Nous possédons bien des coeurs de trottins;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 2, 2, 'Car, en amour, nous sommes des pirates');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 2, 3, 'Braquant partout leurs regards assassins.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 2, 4, 'Souvent, pourtant, nous devons en rabattre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 2, 5, 'De nos grands airs de riche Don Juan:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 2, 6, 'Dans les bouquins nous allons nous ébattre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 2, 7, 'Pour oublier les suppôts de Satan.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-marche-des-etudiants', 2, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-marche-des-etudiants', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 3, 0, 'Quand nous serons amis de doctes sages,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 3, 1, 'Nous sourirons doucement au passé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 3, 2, 'En regrettant, malgré tout, ce bel âge');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 3, 3, 'D’enthousiasme à jamais effacé.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 3, 4, 'Alors, tirant sur nos vieilles bouffardes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 3, 5, 'Nous redirons à mi-voix nos chansons;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 3, 6, 'Elles étaient peut-être un peu gaillardes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marche-des-etudiants', 3, 7, 'Mais on hurlait si bien à l’unisson!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-marche-des-etudiants', 3, 6, 7, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-marseillaise-anticlericale', 'LA MARSEILLAISE ANTICLÉRICALE', 'MARSEILLAISE ANTICLÉRICALE, LA', 'franstalige-liederen', 'fr', NULL, 367, 368, 'Léo Taxil, 1881', '‘La Marseillaise’, Rouget de Lisle, 24 april 1792', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-marseillaise-anticlericale', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 0, 0, 'Allons! Fils de la République,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 0, 1, 'Le jour du vote est arrivé!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 0, 2, 'Contre nous de la noire clique');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 0, 3, 'L’oriflamme ignoble est levé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 0, 4, 'Entendez-vous tous ces infâmes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 0, 5, 'Croasser leurs stupides chants?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 0, 6, 'Ils voudraient encore, les brigands,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 0, 7, 'Salir nos enfants et nos femmes!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-marseillaise-anticlericale', 0, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-marseillaise-anticlericale', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 1, 0, 'Aux urnes citoyens, contre les cléricaux!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 1, 1, 'Votons, votons,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 1, 2, 'Et que nos voix dispersent les corbeaux!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-marseillaise-anticlericale', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 2, 0, 'Que veut cette maudite engeance,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 2, 1, 'Cette canaille aux jupons noirs?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 2, 2, 'Elle veut étouffer la France');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 2, 3, 'Sous la calotte et l’éteignoir');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 2, 4, 'Mais de nos bulletins de vote');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 2, 5, 'Nous accablerons ces gredins,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 2, 6, 'Et les voix de tous nos scrutins.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 2, 7, 'Leur crieront: “À bas la calotte!”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-marseillaise-anticlericale', 2, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-marseillaise-anticlericale', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 3, 0, 'Quoi! Ces curés et leurs vicaires');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 3, 1, 'Feraient la loi dans nos foyers!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 3, 2, 'Quoi! Ces assassins de nos pères');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 3, 3, 'Seraient un jour nos meurtriers!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 3, 4, 'Car ces cafards, de vile race,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 3, 5, 'Sont nés pour être inquisiteurs ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 3, 6, 'A la porte, les imposteurs!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 3, 7, 'Place à la République! Place!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-marseillaise-anticlericale', 3, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-marseillaise-anticlericale', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 4, 0, 'Tremblez, coquins! Cachez-vous, traîtres!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 4, 1, 'Disparaissez loin de nos yeux!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 4, 2, 'Le Peuple ne veut plus de prêtres;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 4, 3, 'Patrie et Loi, voilà ses Dieux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 4, 4, 'Assez de vos pratiques niaises!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 4, 5, 'Les vices sont vos qualités.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 4, 6, 'Vous réclamez des libertés?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 4, 7, 'Il n’en est pas pour les punaises!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-marseillaise-anticlericale', 4, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-marseillaise-anticlericale', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 5, 0, 'Citoyens, punissons les crimes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 5, 1, 'De ces immondes calotins;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 5, 2, 'N’ayons pitié que des victimes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 5, 3, 'Que la foi transforme en crétins');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 5, 4, 'Mais les voleurs, les hypocrites,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 5, 5, 'Mais les gros moines fainéants,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 5, 6, 'Mais les escrocs, les charlatans ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 5, 7, 'Pas de pitié pour les jésuites!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-marseillaise-anticlericale', 5, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-marseillaise-anticlericale', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 6, 0, 'Que la haine de l’imposture');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 6, 1, 'Inspire nos votes vengeurs!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 6, 2, 'Expulsons l’horrible tonsure;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 6, 3, 'Hors de France, les malfaiteurs!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 6, 4, 'Formons l’union radicale;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 6, 5, 'Allons au scrutin le front haut:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 6, 6, 'Pour sauver le pays, il faut');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-marseillaise-anticlericale', 6, 7, 'Une chambre anticléricale!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-marseillaise-anticlericale', 6, 3, 3, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('les-marteaux', 'LES MARTEAUX', 'MARTEAUX, LES', 'franstalige-liederen', 'fr', NULL, 369, 371, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-marteaux', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 0, 0, 'Nous étions six fameux bougres');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 0, 1, 'Revenant de Longjumeau,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 0, 2, 'Nous entrâm’s dans une auberge');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 0, 3, 'Pour y boir’ du vin nouveau. Oh!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-marteaux', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 1, 0, 'C’est à boire, à boire, à boire,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 1, 1, 'C’est à boire qu’il nous faut!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 1, 2, 'Oh! Oh! Oh! Oh!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-marteaux', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 2, 0, 'Nous entrâm’s dans une auberge');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 2, 1, 'Pour y boir’ du vin nouveau.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 2, 2, 'Nous vidâm’s plus d’un’ fiole');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 2, 3, 'Nous y bûmes plus d’un pot. Oh!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-marteaux', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 3, 0, 'Chacun fouilla dans sa poche');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 3, 1, 'Quand il fallut payer l’ pot,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 3, 2, 'Dans la poche du plus riche');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 3, 3, 'On n’ trouva qu’un écu faux. Oh!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-marteaux', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 4, 0, '“Sacrebleu!” dit la patronne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 4, 1, '“Qu’on leur prenne leur shako!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 4, 2, '“Nom de dieu!” dit la servante,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 4, 3, '“Leur falzar, leurs godillots.” Oh!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-marteaux', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 5, 0, 'Quand nous fûmes en liquette,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 5, 1, 'Nous montâm’s sur des tonneaux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 5, 2, 'Nos liquett’s étaient si courtes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 5, 3, 'Que l’on voyait nos marteaux. Oh!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-marteaux', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 6, 0, '“Sacrebleu!” dit la patronne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 6, 1, '“Qu’ils sont noirs et qu’ils sont beaux!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 6, 2, '“Nom de dieu!” dit la servante,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 6, 3, '“J’en voudrais bien un morceau.” Oh!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-marteaux', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 7, 0, '“Sacrebleu!” dit la patronne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 7, 1, '“Tous les six, il me les faut!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 7, 2, 'Et tous les six y passèrent,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 7, 3, 'Du plus p’tit jusqu’au plus gros. Oh!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-marteaux', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 8, 0, '“Sacrebleu!” dit la patronne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 8, 1, '“Qu’on leur rende leur shako!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 8, 2, '“Nom de dieu!” dit la servante,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 8, 3, '“Leur falzar, leurs godillots.” Oh!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-marteaux', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 9, 0, 'Et en sortant nous plaçâmes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 9, 1, 'Sur la porte un écriteau:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 9, 2, 'C’est ici qu’on boit, qu’on mange');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-marteaux', 9, 3, 'Et qu’on paye à coups d’ marteaux. Oh!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-mauvaise-reputation', 'LA MAUVAISE RÉPUTATION', 'MAUVAISE RÉPUTATION, LA', 'franstalige-liederen', 'fr', NULL, 372, 373, NULL, NULL, 'T & M: Georges Brassens');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-mauvaise-reputation', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 0, 0, 'Au village, sans prétention,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 0, 1, 'J’ai mauvaise réputation.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 0, 2, 'Qu’je m’démène ou qu’je reste coi');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 0, 3, 'Je pass’ pour un je-ne-sais-quoi!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 0, 4, 'Je ne fait pourtant de tort à personne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 0, 5, 'En suivant mon chemin de petit bonhomme.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 0, 6, 'Mais les brav’s gens n’aiment pas que');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 0, 7, 'L’on suive une autre route qu’eux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 0, 8, 'Non les brav’s gens n’aiment pas que');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 0, 9, 'L’on suive une autre route qu’eux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 0, 10, 'Tout le monde médit de moi,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 0, 11, 'Sauf les muets, ça va de soi.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-mauvaise-reputation', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 1, 0, 'Le jour du Quatorze Juillet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 1, 1, 'Je reste dans mon lit douillet.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 1, 2, 'La musique qui marche au pas,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 1, 3, 'Cela ne me regarde pas.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 1, 4, 'Je ne fais pourtant de tort à personne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 1, 5, 'En n’écoutant pas le clairon qui sonne.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 1, 6, 'Mais les brav’s gens n’aiment pas que');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 1, 7, 'L’on suive une autre route qu’eux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 1, 8, 'Non les brav’s gens n’aiment pas que');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 1, 9, 'L’on suive une autre route qu’eux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 1, 10, 'Tout le monde me montre du doigt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 1, 11, 'Sauf les manchots, ça va de soi.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-mauvaise-reputation', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 2, 0, 'Quand j’croise un voleur malchanceux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 2, 1, 'Poursuivi par un cul-terreux;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 2, 2, 'J’lance la patte et pourquoi le taire,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 2, 3, 'Le cul-terreux s’retrouv’ par terre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 2, 4, 'Je ne fait pourtant de tort à personne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 2, 5, 'En laissant courir les voleurs de pommes.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 2, 6, 'Mais les brav’s gens n’aiment pas que');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 2, 7, 'L’on suive une autre route qu’eux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 2, 8, 'Non les brav’s gens n’aiment pas que');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 2, 9, 'L’on suive une autre route qu’eux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 2, 10, 'Tout le monde se rue sur moi,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 2, 11, 'Sauf les culs-de-jatte, ça va de soi.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-mauvaise-reputation', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 3, 0, 'Pas besoin d’être Jérémie,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 3, 1, 'Pour d’viner l’sort qui m’est promis,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 3, 2, 'S’ils trouv’nt une corde à leur goût,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 3, 3, 'Ils me la passeront au cou,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 3, 4, 'Je ne fait pourtant de tort à personne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 3, 5, 'En suivant les ch’mins qui n’mènent pas à Rome,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 3, 6, 'Mais les brav’s gens n’aiment pas que');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 3, 7, 'L’on suive une autre route qu’eux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 3, 8, 'Non les brav’s gens n’aiment pas que');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 3, 9, 'L’on suive une autre route qu’eux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 3, 10, 'Tout l’mond’ viendra me voir pendu,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mauvaise-reputation', 3, 11, 'Sauf les aveugles, bien entendu.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-mere-gaspard', 'LA MÈRE GASPARD', 'MÈRE GASPARD, LA', 'franstalige-liederen', 'fr', NULL, 374, 374, NULL, NULL, 'Le père en la mère Gaspard waren de uitbaters van het Brussels studentencabaret ‘Le Diable-Au-Corps’, in de wijk waar nu de Nieuwstraat ligt. Het werd in 1928 gesloopt voor de bouw van de warenhuizen ‘Innovation’.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-mere-gaspard', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mere-gaspard', 0, 0, 'Allons la mère Gaspard');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mere-gaspard', 0, 1, 'Encor’un verre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mere-gaspard', 0, 2, 'Allons la mère Gaspard,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mere-gaspard', 0, 3, 'Encor’un verr’, il se fait tard.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mere-gaspard', 0, 4, 'Si l’ paternel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mere-gaspard', 0, 5, 'Si le paternel revient,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mere-gaspard', 0, 6, 'On lui dira qu’son fils (sa fille)');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-mere-gaspard', 0, 7, 'Est toujours plein, plein, plein ...');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-mere-gaspard', 0, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-mere-gaspard', 1, 'direction', 1, 'Tijdens het zingen van deze regels klinkt iemand met de commilito links van hem, deze op zijn beurt met die links van hem en zo heel de corona (of om het even welke groep commilitones) rond. Diegene die aangeklonken wordt bij “tard” drinkt zijn glas ad fundum, terwijl de rest het woord “plein” blijft herhalen, totdat zijn glas leeg is. De commilito die gedronken heeft zet het klinken opnieuw in gang, en trekt zich dan terug uit de corona/groep. Dit geheel wordt herhaald tot er maar twee commilitones overblijven, die dan samen een ad fundum drinken. Dit liedje wordt typisch gezongen bij het einde van een activiteit, voor iedereen huiswaarts keert.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('les-moines-de-saint-bernardin', 'LES MOINES DE SAINT-BERNARDIN', 'MOINES DE SAINT-BERNARDIN, LES', 'franstalige-liederen', 'fr', NULL, 374, 375, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-moines-de-saint-bernardin', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 0, 0, 'Nous sommes les moines de Saint-Bernardin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 0, 1, 'Qui nous couchons tard et nous levons matin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 0, 2, 'Pour aller à matines vider quelques flacons');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 0, 3, 'Voilà c’ qu’est bon, est bon, est bon ...');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-moines-de-saint-bernardin', 0, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-moines-de-saint-bernardin', 0, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-moines-de-saint-bernardin', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 1, 0, 'Et voilà la vie, la vie, la vie,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 1, 1, 'La vie chérie! Ah! Ah!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 1, 2, 'Et voilà la vie que les moines font.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-moines-de-saint-bernardin', 1, 0, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-moines-de-saint-bernardin', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 2, 0, 'Pour notre déjeuner du bon chocolat');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 2, 1, 'Et du bon café que l’on nomme moka');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 2, 2, 'Et la tarte sucrée et les marrons de Lyon,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 2, 3, 'Voilà c’ qu’est bon, est bon, est bon ...');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-moines-de-saint-bernardin', 2, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-moines-de-saint-bernardin', 2, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-moines-de-saint-bernardin', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 3, 0, 'Pour notre diner de bons petits oiseaux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 3, 1, 'Que l’on nomme caille, bécasse ou perdreau');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 3, 2, 'Et la fine andouillette et la tranche de jambon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 3, 3, 'Voilà c’ qu’est bon, est bon, est bon ...');
