INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-moines-de-saint-bernardin', 3, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-moines-de-saint-bernardin', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 4, 0, 'Pour notre coucher dans un lit au drap blancs');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 4, 1, 'Une jeune nonne de quinze à seize ans');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 4, 2, 'A la taille bien faite et aux nichons bien ronds');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 4, 3, 'Voilà c’ qu’est bon, est bon, est bon ...');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-moines-de-saint-bernardin', 4, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-moines-de-saint-bernardin', 4, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-moines-de-saint-bernardin', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 5, 0, 'La nuit, tous ensemble nous nous enculons');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 5, 1, 'Et puis jusqu’au jour ensemble nous buvons,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 5, 2, 'Après, dessous la table nous roulons et dormons');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 5, 3, 'Voilà c’ qu’est bon, est bon, est bon ...');
