INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-moines-de-saint-bernardin', 5, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-moines-de-saint-bernardin', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 6, 0, 'Si c’est ça la vie que les moines font');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-moines-de-saint-bernardin', 6, 1, 'Je me ferai moine avec ma Jeanneton');
