INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('nini-peau-d-chien', 'NINI-PEAU-D’CHIEN', 'NINI-PEAU-D’CHIEN', 'franstalige-liederen', 'fr', NULL, 376, 377, NULL, NULL, 'T & M: Aristide Bruant');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('nini-peau-d-chien', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 0, 0, 'Quand elle était petite');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 0, 1, 'Le soir elle allait');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 0, 2, 'À Sainte Marguerite');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 0, 3, 'Où est-ce qu’elle dessalait.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 0, 4, 'Maintenant qu’elle est grande');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 0, 5, 'Elle marche le soir');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 0, 6, 'Avec ceux de la bande');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 0, 7, 'De Richard Lenoir');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('nini-peau-d-chien', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 1, 0, 'À la Bastille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 1, 1, 'On l’aime bien');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 1, 2, 'Nini peau de chien');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 1, 3, 'Elle est si belle et si gentille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 1, 4, 'On l’aime bien.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 1, 5, 'Qui ça?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 1, 6, 'Nini peau de chien!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 1, 7, 'Où ça?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 1, 8, 'A la Bastille!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('nini-peau-d-chien', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 2, 0, 'Elle a la peau douce');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 2, 1, 'Aux taches de son,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 2, 2, 'Une odeur de rousse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 2, 3, 'Qui donne le frisson,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 2, 4, 'Et dans sa prunelle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 2, 5, 'Aux tons vert de gris');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 2, 6, 'L’amour étincelle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 2, 7, 'Dans ses yeux d’souris');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('nini-peau-d-chien', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 3, 0, 'Quand le soleil brille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 3, 1, 'Dans ses cheveux roux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 3, 2, 'L’ génie d’ la Bastille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 3, 3, 'Lui fait les yeux doux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 3, 4, 'Et quand elle se promène');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 3, 5, 'Du bout d’ l’Arsenal');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 3, 6, 'Tout l’quartier s’amène');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 3, 7, 'Au coin du canal');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('nini-peau-d-chien', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 4, 0, 'Mais le gars qu’elle aime');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 4, 1, 'Qu’elle a dans la peau');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 4, 2, 'C’est Bibi la Crème');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 4, 3, 'Parce qu’il est costaud,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 4, 4, 'Parce que c’est un homme');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 4, 5, 'Qui n’a pas l’foie blanc,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 4, 6, 'Aussi faut voir comme');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('nini-peau-d-chien', 4, 7, 'Nini l’a dans l’sang');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ode-a-une-feministe', 'ODE À UNE FÉMINISTE', 'ODE À UNE FÉMINISTE', 'franstalige-liederen', 'fr', NULL, 378, 380, 'Guilde Halewijn', '‘Le petit âne gris’, Hugues Aufray', 'Festival de la chanson estudiantine, 1997
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ode-a-une-feministe', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 0, 0, 'Approches-toi car ce soir');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 0, 1, 'Je m’en vais t’enculer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 0, 2, 'Vire-moi tes gros nibards');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 0, 3, 'Ton troufion va saigner');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 0, 4, 'J’vais rembourrer ta panse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 0, 5, 'Du jus de mes roustons');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 0, 6, 'Je mènerai la danse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 0, 7, 'Avec mon gros bâton');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ode-a-une-feministe', 0, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ode-a-une-feministe', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 1, 0, 'Je vais être sauvage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 1, 1, 'J’abandonnes ton vagin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 1, 2, 'Ton deuxième pucelage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 1, 3, 'Je l’aurai sans les mains');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 1, 4, 'Tu dis quand je t’enfile');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 1, 5, 'Tu te trompes de côté');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 1, 6, 'Je serai fort viril');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 1, 7, 'Je crois qu’tu vas pleurer');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ode-a-une-feministe', 1, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ode-a-une-feministe', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 2, 0, 'Quand je serai en nage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 2, 1, 'Je boufferai ton croupion');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 2, 2, 'Et pendant l’enculage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 2, 3, 'Je r’cracherai les morpions');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 2, 4, 'Dardant toujours ma pine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 2, 5, 'Aux premières lueurs');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 2, 6, 'N’ayant plus de vaseline');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 2, 7, 'J’empoigne le pot de beurre');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ode-a-une-feministe', 2, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ode-a-une-feministe', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 3, 0, 'Mais je sens que je jute');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 3, 1, 'Au fond de ton rectum');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 3, 2, 'Espèce de sale pute');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 3, 3, 'Tu vois c’que c’est un homme');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 3, 4, 'Maintenant tu vas sucer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 3, 5, 'Mon petit gland merdeux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 3, 6, 'Et puis sans te presser');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 3, 7, 'Avaler l’jus d’mon noeud');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ode-a-une-feministe', 3, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ode-a-une-feministe', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 4, 0, 'Et dans deux p’tites secondes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 4, 1, 'Je serai requinqué');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 4, 2, 'J’amènerai du monde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 4, 3, 'Pour finir de t’purger');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 4, 4, 'Image d’évangile');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 4, 5, 'Vivant d’humilité');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 4, 6, 'Tu seras plus docile');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 4, 7, 'A te faire enculer');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ode-a-une-feministe', 4, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ode-a-une-feministe', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 5, 0, 'Et demain nous irons');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 5, 1, 'Après une bonne vadrouille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 5, 2, 'Quatre à quatre au boxon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 5, 3, 'Te bourrer la cramouille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 5, 4, 'Même truffée de syphile');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 5, 5, 'Gluante d’humidité');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 5, 6, 'Tu te rendras utile');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ode-a-une-feministe', 5, 7, 'A la communauté');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ode-a-une-feministe', 5, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ode-a-une-feministe', 6, 'direction', 1, 'de laatste strofe wordt geneuried');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ode-a-une-feministe', 7, 'verse', 1, NULL);
