INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('parcours-sante', 'PARCOURS SANTÉ', 'PARCOURS SANTÉ', 'franstalige-liederen', 'fr', NULL, 380, 381, 'Guilde Polytechnique, ULB', '‘La fleur aux dents’, Joe Dassin', 'Festival de la chanson estudiantine, 1992');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('parcours-sante', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 0, 0, 'Tout frais sorti d’ l’Athénée');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 0, 1, 'A l’unif, j’ai débarqué');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 0, 2, 'J’ai vu des filles partout');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 0, 3, 'Des petits trous qui n’attendaient que moi');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 0, 4, 'Tout excité, je me suis précipité');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 0, 5, 'Mais on m’a dit: “Bleu, pas toucher!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 0, 6, 'Sinon tu s’ras rasé.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('parcours-sante', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 1, 0, 'Il y a les filles que l’on baise');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 1, 1, 'Et celles chez qui l’on s’endort');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 1, 2, 'Il y a les filles qui vous plaisent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 1, 3, 'Et celles qu’on largue sans remords');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 1, 4, 'Il y a les filles que l’on saute');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 1, 5, 'Par hygiène ou pour le sport');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 1, 6, 'Puis il y a celles qui vous passent la bague en or.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('parcours-sante', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 2, 0, 'Maintenant que je suis poil');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 2, 1, 'Sur tout’s les mott’s je m’installe');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 2, 2, 'Dans tout’s les positions');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 2, 3, 'Gueux, que c’est bon, je ne m’arrête plus');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 2, 4, 'Je me régale surtout du coït anal');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 2, 5, 'La feuill’ de rose, à forte dose,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 2, 6, 'Me guérit d’ mes névroses');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('parcours-sante', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 3, 0, 'Je suis enfin comitard');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 3, 1, 'J’atteins le sommet de l’art');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 3, 2, 'Ma toge est un appât');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 3, 3, 'Dessous, mon vit crache comme un lama');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 3, 4, 'J’ai mon gros dard dressé comm’ un étendard');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 3, 5, 'Trop à l’étroit dans mon cal’bar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 3, 6, 'Je décharg’ de tout’s parts.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('parcours-sante', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 4, 0, 'Aujourd’hui je suis bourgeois');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 4, 1, 'C’ en est fini de tout ça');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 4, 2, 'Je suis casé, marié');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 4, 3, 'Plus de pépées, fini de rigoler');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 4, 4, 'Mais quand mémé s’endort devant la télé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 4, 5, 'Moi j’ai la triqu’, je m’astiqu’');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('parcours-sante', 4, 6, 'En pensant que j’ les nique');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('le-pere-adam', 'LE PÈRE ADAM', 'PÈRE ADAM, LE', 'franstalige-liederen', 'fr', NULL, 382, 383, NULL, NULL, 'Voor uw eigen goed: een zwaar ingekorte versie ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-pere-adam', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 0, 0, 'Le père Adam, trois jours avant la faute,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 0, 1, 'Au paradis ronflait comm’ un cochon.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 0, 2, 'Pour le punir, dieu lui prit une côte,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 0, 3, 'Souffla dessus et fit le premier ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-pere-adam', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 1, 0, 'Trim, troum, tram, laridondaine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 1, 1, 'Trim, troum, tram, laridondon.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 1, 2, 'Souffla dessus et fit le premier ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 1, 3, 'Qu’on nous verse à boire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 1, 4, 'Et du bon vin!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-pere-adam', 1, 3, 3, 3, '(TER)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-pere-adam', 1, 3, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-pere-adam', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 2, 0, 'Comment Noé repeupla-t-il la Terre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 2, 1, 'Avec sa femm’ dans leur uniqu’ maison?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 2, 2, 'Chacun prétend que c’est par la prière,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 2, 3, 'Mais moi je dis que c’est à coup de ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-pere-adam', 3, 'direction', 1, 'In het refrein wordt de derde regel steeds vervangen door de laatste regel van de strofe');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-pere-adam', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 4, 0, 'Pourquoi Enée a-t-il quitté Carthage?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 4, 1, 'Pourquoi Enée a-t-il quitté Didon?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 4, 2, 'C’est qu’il voyait, debout sur le rivage,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 4, 3, 'Des femm’s Troyenn’s qui se grattaient le ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-pere-adam', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 5, 0, 'Pourquoi Priam, du haut d’une tourelle,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 5, 1, 'Se branlait-il comme un foutu cochon?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 5, 2, 'C’est que d’en haut, il vit une pucelle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 5, 3, 'Qui se foutait les dix doigts dans le ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-pere-adam', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 6, 0, 'Pourquoi Enée a-t-il quitté la Grèce,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 6, 1, 'Pourquoi César franchit le Rubicon,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 6, 2, 'C’est qu’ si les Grecqu’s avaient de jolies fesses');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 6, 3, 'Les Italienn’s ont de plus jolis ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-pere-adam', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 7, 0, 'Neuf mois avant que la Vierge n’accouche');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 7, 1, 'Le Saint Esprit la visita, dit-on,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 7, 2, 'Les uns prétend’nt qu’il entra par la bouche,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 7, 3, 'Moi, je soutiens que ce fut par le ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-pere-adam', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 8, 0, 'Pourquoi les femm’s ne vont-ell’s plus en guerre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 8, 1, 'Depuis le temps du grand Napoléon?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 8, 2, 'C’est qu’elles sav’nt que pour passer la frontière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 8, 3, 'Aux officiers, il faut montrer le ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-pere-adam', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 9, 0, 'Allons, Messieurs, encore une bouteille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 9, 1, 'De ce bon vin qui fait perdr’ la raison.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 9, 2, 'Si l’on boit peu, le soir on fait merveille;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 9, 3, 'Si l’on boit trop, on s’endort sur le ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-pere-adam', 10, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 10, 0, 'Les imbécil’s, ainsi que les vicaires,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 10, 1, 'Auraient voulu supprimer ma chanson.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 10, 2, 'Aucun d’entr’ eux ne serait sur la terre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 10, 3, 'Si leur maman n’avait prêté son ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-pere-adam', 11, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 11, 0, 'Bénissez-moi mon pèr’, je vous convie,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 11, 1, 'Donnez-moi vite votr’ absolution.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 11, 2, 'Le seul péché que j’ai fait dans ma vie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-pere-adam', 11, 3, 'C’est d’avoir trop joué avec leur ...');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('le-plaisir-des-dieux', 'LE PLAISIR DES DIEUX', 'PLAISIR DES DIEUX, LE', 'franstalige-liederen', 'fr', NULL, 384, 385, NULL, NULL, 'Ook ‘Les quatre âges du cœur’ genoemd, ca.1830');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-plaisir-des-dieux', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 0, 0, 'Du dieu Vulcain, quand l’épouse friponne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 0, 1, 'Va boxonner loin de son vieux sournois,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 0, 2, 'Le noir époux, que l’amour aiguillonne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 0, 3, 'Tranquillement se polit le chinois.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 0, 4, 'Va-t-en, dit-il à sa fichue femelle,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 0, 5, 'Je me fous bien de ton con chassieux:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 0, 6, 'De mes cinq doigts je fais une pucelle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 0, 7, 'Masturbons-nous c’est le plaisir des dieux.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-plaisir-des-dieux', 0, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-plaisir-des-dieux', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 1, 0, 'Bast! Laissons-lui ce plaisir ridicule,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 1, 1, 'Chacun, d’ailleurs, s’amuse à sa façon:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 1, 2, 'Moi, je préfèr’ la manière d’Hercule,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 1, 3, 'Jamais sa main ne lui servit de con.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 1, 4, 'Le plus sal’ trou, la plus vieille fendasse,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 1, 5, 'Rien n’échappait à son vit glorieux.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 1, 6, 'Nous serons fiers de marcher sur ses traces');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 1, 7, 'Baisons baisons c’est le plaisir des dieux.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-plaisir-des-dieux', 1, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-plaisir-des-dieux', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 2, 0, 'Du dieu Bacchus quand, accablé d’ivresse,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 2, 1, 'Le vit mollit et sur le con s’endort,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 2, 2, 'Soixante neuf et le vit se redresse;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 2, 3, 'Soixante neuf ferait bander un mort.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 2, 4, 'O clitoris, ton parfum de fromage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 2, 5, 'Fait regimber nos engins glorieux.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 2, 6, 'A ta vertu nous rendons tous hommage:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 2, 7, 'Gamahuchons c’est le plaisir des dieux.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-plaisir-des-dieux', 2, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-plaisir-des-dieux', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 3, 0, 'Pour Jupiter, façon vraiment divine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 3, 1, 'Le con lui pue, il aime le goudron;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 3, 2, 'D’un moule à merde, il fait un moule à pine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 3, 3, 'Et bat le beurre au milieu de l’étron.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 3, 4, 'Cette façon est cruellement bonne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 3, 5, 'Pour terminer un gueuleton joyeux:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 3, 6, 'Après l’ dessert on s’encule en couronne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 3, 7, 'Enculons-nous c’est le plaisir des dieux.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-plaisir-des-dieux', 3, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-plaisir-des-dieux', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 4, 0, 'Quand à Pluton, le dieu à large panse,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 4, 1, 'Le moindre effort lui semble fatigant;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 4, 2, 'Aussi, veut-il, sans craindre la dépense,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 4, 3, 'Faire sucer son pénis arrogant.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 4, 4, 'Et nous, rêvant aux extases passées,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 4, 5, 'Tout languissants, réjouissons nos yeux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 4, 6, 'En laissant faire une amante empressée,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 4, 7, 'Laissons sucer c’est le plaisir des dieux.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-plaisir-des-dieux', 4, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-plaisir-des-dieux', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 5, 0, 'Au reste, amis, qu’on en fasse à sa tête,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 5, 1, 'Main, con, cul, bouche, au plaisir tout est bon.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 5, 2, 'Sur quelqu’autel qu’on célèbre la fête,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 5, 3, 'Toujours là-haut, on est sûr du patron.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 5, 4, 'Foutre et jouir, voilà l’unique affaire,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 5, 5, 'Foutre et jouir: voilà quels sont nos voeux.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 5, 6, 'Foutons amis qu’importe la manière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-plaisir-des-dieux', 5, 7, 'Foutons foutons c’est le plaisir des dieux.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-plaisir-des-dieux', 5, 6, 7, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('quand-on-a-une-gueul-comme-ca', 'QUAND ON A UNE GUEUL’ COMME ÇA', 'QUAND ON A UNE GUEUL’ COMME ÇA', 'franstalige-liederen', 'fr', NULL, 386, 386, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('quand-on-a-une-gueul-comme-ca', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('quand-on-a-une-gueul-comme-ca', 0, 0, 'Quand on a une gueul’ comme ça,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('quand-on-a-une-gueul-comme-ca', 0, 1, 'On la ferme, on la ferme!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('quand-on-a-une-gueul-comme-ca', 0, 2, 'Quand on a une gueul’ comme ça,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('quand-on-a-une-gueul-comme-ca', 0, 3, 'On la ferme et on s’en va!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('les-quatre-vingts-chasseurs', 'LES QUATRE-VINGTS CHASSEURS', 'QUATRE-VINGTS CHASSEURS, LES', 'franstalige-liederen', 'fr', NULL, 386, 388, 'Waarschijnlijk gebaseerd op Noël de Henri Murger, 1850', 'Jacques Mendel', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-quatre-vingts-chasseurs', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 0, 0, 'A l’ouverture de la chasse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 0, 1, 'Dans un château riche en gibier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 0, 2, 'Riche en gibier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 0, 3, 'Une marquise aux fins limiers');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 0, 4, 'Invita des chasseurs en masse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 0, 5, 'Bientôt l’on vit tous les chasseurs');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 0, 6, 'Accourir sans même qu’on leur dise:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-quatre-vingts-chasseurs', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 1, 0, 'Au rendez-vous de la marquise');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 1, 1, 'Nous étions quatre-vingts chasseurs');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 1, 2, 'Quatre-vingts, Quatre-vingts');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 1, 3, 'Quatre-vingts chasseurs');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 1, 4, 'Et nous n’avions pas peur!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-quatre-vingts-chasseurs', 1, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-quatre-vingts-chasseurs', 1, 2, 2, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-quatre-vingts-chasseurs', 1, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-quatre-vingts-chasseurs', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 2, 0, 'Encouragés par notre belle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 2, 1, 'Nous abattîmes plus d’un faisan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 2, 2, 'Plus d’un faisan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 2, 3, 'Quand un sanglier menaçant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 2, 4, 'Vint à s’élancer dessus elle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 2, 5, 'Malgré sa rage et sa fureur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 2, 6, 'Nous l’obligeâmes à lâcher prise.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-quatre-vingts-chasseurs', 3, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 3, 0, 'Et pour défendre la marquise ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-quatre-vingts-chasseurs', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 4, 0, 'Après cette attaque effroyable');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 4, 1, 'Dit la marquise, il faut rentrer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 4, 2, 'Il faut rentrer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 4, 3, 'Ce n’est pas tout de s’illustrer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 4, 4, 'Il faut aussi manger et boire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 4, 5, 'En avant les vins, les liqueurs');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 4, 6, 'Et la nappe était déjà mise.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-quatre-vingts-chasseurs', 5, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 5, 0, 'À la table de la marquise ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-quatre-vingts-chasseurs', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 6, 0, 'Après qu’on eut sabré l’champagne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 6, 1, 'Nous étions tous de belle humeur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 6, 2, 'De belle humeur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 6, 3, 'Chacun voulut, chacun son tour');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 6, 4, 'Embrasser l’aimable compagne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 6, 5, 'Nous fûmes dispos à l’amour');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 6, 6, 'Et la belle était déjà grise.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-quatre-vingts-chasseurs', 7, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 7, 0, 'Et dans le lit de la marquise ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-quatre-vingts-chasseurs', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 8, 0, 'Après cette partie mémorable');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 8, 1, 'Notre marquise, neuf mois plus tard');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 8, 2, 'Neuf mois plus tard');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 8, 3, 'Nous mit au monde un beau bâtard');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 8, 4, 'Un homme aujourd’hui redoutable');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 8, 5, 'De ses jours ignorant l’auteur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 8, 6, 'Il demanda qu’on l’en instruise.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-quatre-vingts-chasseurs', 9, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 9, 0, 'Tu es, lui dit notre marquise,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 9, 1, 'Le fils de quatre-vingts chasseurs ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-quatre-vingts-chasseurs', 9, 2, '... Et qui n’ avaient pas peur!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-quille', 'LA QUILLE', 'QUILLE, LA', 'franstalige-liederen', 'fr', NULL, 388, 389, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-quille', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 0, 0, 'Il paraît qu’en Amérique,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 0, 1, 'Par un procédé nouveau,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 0, 2, 'On fait fondre les couilles des flics,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 0, 3, 'Pour en faire des chars d’assaut.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-quille', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 1, 0, 'Tiens, tiens, voilà la quille,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 1, 1, 'C’est pas pour les bleus nom de dieu,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 1, 2, 'Tiens, tiens, voilà la quille,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 1, 3, 'C’est pour les anciens nom d’un chien.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-quille', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 2, 0, 'À Paris dans les gouttières,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 2, 1, 'On entend les chats péter,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 2, 2, 'Ce qui prouve que ces sales bêtes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 2, 3, 'N’ont pas l’trou du cul bouché.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-quille', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 3, 0, 'Les chameaux dans le désert,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 3, 1, 'Ont la peau du ventre tendu,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 3, 2, 'Quand ils ferment leurs paupières,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 3, 3, 'Ca leur ouvre le trou du cul.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-quille', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 4, 0, 'Ma grand-mère et mon grand-père,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 4, 1, 'Ont l’habitude de coucher nus,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 4, 2, 'Ma grand-mère qui est carnassière,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 4, 3, 'À mordu pépé dans l’cul.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-quille', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 5, 0, 'À l’enterrement de ma grand’mère,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 5, 1, 'J’étais devant, j’étais derrière,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 5, 2, 'J’étais derrière, j’étais devant,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-quille', 5, 3, 'J’étais tout seul à l’enterrement.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('reponse-d-une-feministe', 'RÉPONSE D’UNE FÉMINISTE', 'RÉPONSE D’UNE FÉMINISTE', 'franstalige-liederen', 'fr', NULL, 389, 391, 'Cercle de Philosophie et Lettres', '‘Le petit âne gris’, Hugues Aufray', 'Festival de la chanson estudiantine, 2007
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('reponse-d-une-feministe', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 0, 0, 'Accroche-toi car ce soir');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 0, 1, 'Je m’en vais t’étonner');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 0, 2, 'Ta chanson de queutard');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 0, 3, 'Est trop édulcorée');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 0, 4, 'Tu t’prends pour un pervers');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 0, 5, 'Mais t’as encore rien vu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 0, 6, 'Je t’emmène en enfer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 0, 7, 'Au fin fond de mon cul');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('reponse-d-une-feministe', 0, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('reponse-d-une-feministe', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 1, 0, 'Tu dis être sauvage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 1, 1, 'J’ai connu plus sanglant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 1, 2, 'Mon premier pucelage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 1, 3, 'J’l’ai vendu à dix ans');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 1, 4, 'Pénétration anale');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 1, 5, 'Tout en limant ma fente');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 1, 6, 'Oh oui fais-moi bien mal');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 1, 7, 'J’aime que tu me violentes');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('reponse-d-une-feministe', 1, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('reponse-d-une-feministe', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 2, 0, 'Rends-moi tous mes morpions');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 2, 1, 'Et file m’en un des tiens');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 2, 2, 'Complète ma collection');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 2, 3, 'Je baiserai pas pour rien');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 2, 4, 'Enfonce loin ton phallus');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 2, 5, 'Dans mon tendre rectum');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 2, 6, 'De sorte que mon anus');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 2, 7, 'Devienne un trou ènorme');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('reponse-d-une-feministe', 2, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('reponse-d-une-feministe', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 3, 0, 'Mais je sens que tu jutes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 3, 1, 'Au fond de mon trou d’balle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 3, 2, 'Je suis fière d’être une pute');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 3, 3, 'Une traînée vénale');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 3, 4, 'Tu finis par cracher');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 3, 5, 'Que je te suce ou non');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 3, 6, 'Que ce soit ta purée');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 3, 7, 'Ou bien tout ton pognon');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('reponse-d-une-feministe', 3, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('reponse-d-une-feministe', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 4, 0, 'Et dans deux p’tites secondes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 4, 1, 'Je vais devenir gouine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 4, 2, 'Car ta semence immonde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 4, 3, 'Ne vaut pas la cyprine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 4, 4, 'J’vais dépuceler ta sœur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 4, 5, 'Lui enfoncer mon poing');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 4, 6, 'Jusqu’à c’qu’elle soit en pleurs');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 4, 7, 'J’en ferai une catin');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('reponse-d-une-feministe', 4, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('reponse-d-une-feministe', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 5, 0, 'Et pour te consoler');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 5, 1, 'Direction le cimetière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 5, 2, 'Tu t’en vas te vider');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 5, 3, 'Dans un corps plein de vers');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 5, 4, 'Moi j’aime la mort, le sang');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 5, 5, 'Quand c’est gore, quand c’est trash');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 5, 6, 'Ton organe turgescent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 5, 7, 'Je le taille à la hache');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('reponse-d-une-feministe', 5, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('reponse-d-une-feministe', 6, 'direction', 1, 'de laatste strofe wordt geneuried');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('reponse-d-une-feministe', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('reponse-d-une-feministe', 7, 0, '... Ton organe turgescent je le taille à la hache!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('reponse-d-une-feministe', 7, 0, 0, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-romance-du-14-juillet', 'LA ROMANCE DU 14 JUILLET', 'ROMANCE DU 14 JUILLET, LA', 'franstalige-liederen', 'fr', NULL, 391, 393, 'Léon Keimeul, 1946, Cercle Mèdecine, ULB', NULL, 'Dit lied werd geschreven ter gelegenheid van het bezoek van een delegatie Franse geneeskundestudenten aan de ULB, en werd voor het eerst gepubliceerd in de Universitaire Médical van februari 1948.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-romance-du-14-juillet', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 0, 0, 'Elle avait ses quinze ans à peine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 0, 1, 'Quand ell’sentit battr’son coeur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 0, 2, 'Un beau soir, près du mec Gégène');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 0, 3, 'Marinette a cru au bonheur.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 0, 4, 'C’était l’jour d’la fêt’ nationale');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 0, 5, 'Quand la bombe éclate en l’air');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 0, 6, 'Elle sentit comme une lame');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 0, 7, 'Qui lui pénétrait, dans la chair.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-romance-du-14-juillet', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 1, 0, 'Par devant, par derrière,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 1, 1, 'Tristement comme toujours,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 1, 2, 'Sans chichis, sans manières,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 1, 3, 'Elle a connu l’amour,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 1, 4, 'Les oiseaux dans les branches');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 1, 5, 'En les voyant s’aimer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 1, 6, 'Entonnèr’nt la romance');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 1, 7, 'Du quatorze juillet.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-romance-du-14-juillet', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 2, 0, 'Mais quand refleurit l’aubépine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 2, 1, 'Au premier souffle du printemps,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 2, 2, 'Fallait voir la pauvre gamine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 2, 3, 'Mettre au monde un petit enfant.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 2, 4, 'Mais Gégène, qui est l’mec à la coule');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 2, 5, 'Lui dit: “Ton gosse, moi j’ m’en fous!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 2, 6, 'Si tu savais comm’je m’les roule');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 2, 7, 'A ta place moi j’lui tordrais l’cou.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-romance-du-14-juillet', 3, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 3, 0, 'Par devant, par derrière,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 3, 1, 'Tristement comm’toujours,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 3, 2, 'Fallait voir la pauvr’ mère,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 3, 3, 'Avec son gosse d’huit jours,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 3, 4, 'En fermant les paupières');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 3, 5, 'Ell’ lui tordit l’ kiki');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 3, 6, 'Et dans l’ trou des ouatères');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 3, 7, 'Ell’ jeta son petit.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-romance-du-14-juillet', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 4, 0, 'Mise au banc de la cour d’assises');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 4, 1, 'Et de c’lui de la société');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 4, 2, 'Ell’ fut traitée de fill’ soumise');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 4, 3, 'A la veill’ du quatorz’ juillet.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 4, 4, 'Elle entendait son petit gosse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 4, 5, 'Qui appelait sa maman');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 4, 6, 'Tandis que le verdict atroce');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 4, 7, 'La condamne au bagn’ pour vingt ans.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-romance-du-14-juillet', 5, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 5, 0, 'Par devant, par derrière,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 5, 1, 'Tristement comme toujours,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 5, 2, 'Elle est mort’ la pauvre mère');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 5, 3, 'À Cayenne un beau jour,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 5, 4, 'Morte avec l’espérance');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 5, 5, 'De revoir son bébé');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 5, 6, 'Dans la fosse d’aisance');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 5, 7, 'Où ell’ l’avait jeté.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-romance-du-14-juillet', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 6, 0, 'Elle avait ses quinze ans à peine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 6, 1, 'Quand ell’ sentit battr’ son coeur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 6, 2, 'Un beau soir, près du mec Gégène');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-romance-du-14-juillet', 6, 3, 'Marinette a cru au bonheur.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('saint-nicolas', 'SAINT NICOLAS', 'SAINT NICOLAS', 'franstalige-liederen', 'fr', NULL, 393, 395, NULL, '‘La chanson de Cadet Roussel’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('saint-nicolas', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 0, 0, 'Saint Nicolas encor’ moutard');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 0, 1, 'Montrait ce qu’il ferait plus tard');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 0, 2, 'Encore dans le ventr’ de sa mère');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 0, 3, 'Il suçait la pine de son père.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('saint-nicolas', 0, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('saint-nicolas', 0, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('saint-nicolas', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 1, 0, 'Zut! Merde! Cré nom de nom!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 1, 1, 'Saint Nicolas est un cochon.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('saint-nicolas', 1, 0, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('saint-nicolas', 2, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('saint-nicolas', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 3, 0, 'Saint Nicolas dans son berceau');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 3, 1, 'Bandait déjà comme un taureau');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 3, 2, 'Pour satisfaire tous ses caprices');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 3, 3, 'Il enculait sa vieill’ nourrice.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('saint-nicolas', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 4, 0, 'Saint Nicolas à la cuisine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 4, 1, 'Battait les oeufs avec sa pine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 4, 2, 'Nom de Dieu dit la cuisinière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 4, 3, 'Fous-la moi donc dans le derrière.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('saint-nicolas', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 5, 0, 'Saint Nicolas monte en ballon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 5, 1, 'Mais il avait l’système trop long');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 5, 2, 'Il était dans la stratosphère');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 5, 3, 'Ses couill’s pendaient toujours par terre.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('saint-nicolas', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 6, 0, 'Saint Nicolas monte en bateau');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 6, 1, 'Et laiss’ses couill’s flotter dans l’eau');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 6, 2, 'Il y avait plus d’ dix mille grenouilles');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 6, 3, 'Qui lui suçaient la peau des couilles.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('saint-nicolas', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 7, 0, 'Saint Nicolas à l’opéra');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 7, 1, 'Avait grande envie de faire caca');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 7, 2, 'Sans s’départir d’un certain morgue');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 7, 3, 'Il pétait pendant les points d’orgue.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('saint-nicolas', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 8, 0, 'Saint Nicolas du haut d’un toit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 8, 1, 'S’foutait des touch’s à tour de bras');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 8, 2, 'La servante qui était sur le seuil');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 8, 3, 'Reçut tout’ la décharge dans l’oeil.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('saint-nicolas', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 9, 0, 'Saint Nicolas devant Carthage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 9, 1, 'Aux Romains donna l’avantage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 9, 2, 'Posant sa bit’sur un trépied');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 9, 3, 'Il s’en servait comme d’un bélier.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('saint-nicolas', 10, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 10, 0, 'Saint Nicolas à Sainte Gudule');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 10, 1, 'Se conduisait comme une crapule');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 10, 2, 'Malgré les efforts de la police');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 10, 3, 'Il y enculait le vieux suisse.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('saint-nicolas', 11, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 11, 0, 'A la bataille de Zamora');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 11, 1, 'Saint Nicolas n’y était pas');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 11, 2, 'On le retrouva dans l’désert');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 11, 3, 'Il enculait des dromadaires.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('saint-nicolas', 12, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 12, 0, 'Saint Nicolas à l’Alcazar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 12, 1, 'Voulut montrer tout son bazar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 12, 2, 'Mais soudain survint la patrouille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 12, 3, 'Qui lui fit rentrer ses grosses couilles.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('saint-nicolas', 13, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 13, 0, 'Saint Nicolas dans son cerceuil');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 13, 1, 'Bandait encore avec orgeuil');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 13, 2, 'Avec sa bite en arc de cercle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 13, 3, 'Il en soul’vait même le couvercle.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('saint-nicolas', 14, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 14, 0, 'Trois quarts de siècle après sa mort');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 14, 1, 'Saint Nicolas bandait encore');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 14, 2, 'Il n’avait plus que son squelette');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('saint-nicolas', 14, 3, 'Mais il avait toujours sa quéquette.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-salope', 'LA SALOPE', 'SALOPE, LA', 'franstalige-liederen', 'fr', NULL, 396, 396, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-salope', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-salope', 0, 0, 'Il était une fille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-salope', 0, 1, 'Qui s’appelait Suzon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-salope', 0, 2, 'Et qui aimait à rire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-salope', 0, 3, 'Avec tous les garçons!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-salope', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-salope', 1, 0, 'Ah, la salope');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-salope', 1, 1, 'Va laver ton cul malpropre,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-salope', 1, 2, 'Car il n’est pas propr’ tirelire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-salope', 1, 3, 'Car il n’est pas propr’ tirela');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-salope', 1, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-salope', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-salope', 2, 0, 'Et qui aimait à rire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-salope', 2, 1, 'Avec tous les garçons');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-salope', 2, 2, 'Mais à force de rire');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-salope', 2, 3, 'Son ventre devint rond.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-salope', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-salope', 3, 0, '... Sa mère lui demande:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-salope', 3, 1, 'Qui t’a fait ça Suzon?');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-salope', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-salope', 4, 0, '... C’est le fils du gard’champêtre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-salope', 4, 1, 'Avec son gros bâton.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-salope', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-salope', 5, 0, '... Y avait du sucre au bout');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-salope', 5, 1, 'Mon Dieu, que c’était bon!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-salope', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-salope', 6, 0, '... Si c’était à refaire,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-salope', 6, 1, 'Nous recommencerions.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('si-j-t-encule', 'SI J’ T’ENCULE', 'SI J’ T’ENCULE', 'franstalige-liederen', 'fr', NULL, 397, 398, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('si-j-t-encule', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 0, 0, 'Entrant dans une église,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 0, 1, 'On ne voit d’abord rien');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 0, 2, 'Qu’un vieux cochon de moine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 0, 3, 'Qui s’ masturb’ dans un coin.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('si-j-t-encule', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 1, 0, 'Si j’ t’encule, cule, cule,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 1, 1, 'Si j’ t’encule c’est pour ton bien!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 1, 2, 'Si j’ te baise, baise, baise,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 1, 3, 'Si j’ te baise c’est pour le mien!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('si-j-t-encule', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 2, 0, 'Qu’un vieux cochon de moine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 2, 1, 'Qui s’ masturb’ dans un coin,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 2, 2, 'Qui confesse des nonnes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 2, 3, 'Avec la pine en main.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('si-j-t-encule', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 3, 0, '... Il dit à la plus jeune:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 3, 1, 'Tu reviendras demain.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('si-j-t-encule', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 4, 0, '... Je te f’rai voir de l’herbe');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 4, 1, 'Qui pousse dans ma main.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('si-j-t-encule', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 5, 0, '... Qui fait grossir le ventre');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 5, 1, 'Et arrondir les seins.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('si-j-t-encule', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 6, 0, '... Et nous ferons ensemble');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 6, 1, 'Un petit capucin.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('si-j-t-encule', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 7, 0, '... Aux couilles tricolores');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 7, 1, 'Aux poils du cul châtains.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('si-j-t-encule', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 8, 0, '... Il ira au bordel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 8, 1, 'Confesser les putains.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('si-j-t-encule', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 9, 0, '...Il aura la vérole');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('si-j-t-encule', 9, 1, 'Son père l’avait bien!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('les-stances-a-sophie', 'LES STANCES À SOPHIE', 'STANCES À SOPHIE, LES', 'franstalige-liederen', 'fr', NULL, 399, 400, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-stances-a-sophie', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 0, 0, 'Tu m’ demand’s tes lettr’s, ta photographie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 0, 1, 'Ton épong’ à cul, ton bidet d’ métal');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 0, 2, 'Je m’en fous pas mal, ingrate Sophie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 0, 3, 'Et j’ te renvoie l’ tout par colis postal.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-stances-a-sophie', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 1, 0, 'Sophie que j’aimais tant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 1, 1, 'J’ t’emmerde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 1, 2, 'Sophie que j’aimais tant');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 1, 3, 'J’ t’emmerde à présent!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('les-stances-a-sophie', 1, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-stances-a-sophie', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 2, 0, 'Tu veux fair’ la peau, un métier d’ grenouille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 2, 1, 'Et me remplacer par d’autres amants,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 2, 2, 'Mais vois-tu, j’ m’en fous, comm’ d’la peau d’mes couilles');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 2, 3, 'Car tu pues du bec, et t’as l’ con trop grand.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-stances-a-sophie', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 3, 0, 'Je t’ai rencontrée un soir dans la rue,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 3, 1, 'Où tu dégueulais tripes et boyaux,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 3, 2, 'Ah! Si j’avais su qu’ tu n’étais qu’un’ grue,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 3, 3, 'J’ t’aurais balancée par l’ trou des gogu’nots.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-stances-a-sophie', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 4, 0, 'Mais j’ t’ai ramassée, gueux que j’étais bête!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 4, 1, 'Car le lendemain, je m’ suis aperçu,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 4, 2, 'Qu’ j’avais des morpions des pieds à la tête,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 4, 3, 'Des poils du nombril jusqu’au trou du cul!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-stances-a-sophie', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 5, 0, 'Puis il a fallu qu’avec toi je couche,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 5, 1, 'Mais de tout’ la nuit, j’ n’ai pu roupiller,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 5, 2, 'Tu n’as pas voulu ma pin’ dans ta bouche');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 5, 3, 'Et t’avais tout l’ temps l’ con sur l’oreiller.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-stances-a-sophie', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 6, 0, 'Puis le lendemain, t’avais tes affaires,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 6, 1, 'Le sang inondait la chambre à coucher,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 6, 2, 'Et j’ai consenti, pour te satisfaire,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 6, 3, 'À te sucer l’ con pour mieux le sécher.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-stances-a-sophie', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 7, 0, 'En ai-je bouffé de tes pertes blanches,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 7, 1, 'Mais quand j’ai voulu tirer un bon coup,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 7, 2, 'Tu ne gigotais pas plus qu’une planche,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 7, 3, 'Et je m’esquintais sans rien fair’ du tout!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-stances-a-sophie', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 8, 0, 'Et puis tu avais des passions honteuses,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 8, 1, 'J’en rougis encor’, rien que d’y songer.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 8, 2, 'Et pour apaiser ta chair luxurieuse,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 8, 3, 'À tous tes capric’s m’a fallu céder.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-stances-a-sophie', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 9, 0, 'N’as-tu point voulu que ma langu’ se perde,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 9, 1, 'Dans les plis profonds de ton trou du cul,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 9, 2, 'Je l’ai retirée toute plein’ de merde,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 9, 3, 'J’en ai dégueulé, tu n’en as rien su.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-stances-a-sophie', 10, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 10, 0, 'Tu peux t’en aller, va, tu me dégoûtes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 10, 1, 'De toi, je me fous, je sais me branler,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 10, 2, 'Je ferai gicler mon sperm’ goutt’ à goutte,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 10, 3, 'Plutôt qu’ revenir te caramboler.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-stances-a-sophie', 11, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 11, 0, 'Tout est bien fini, je te l’ dis sans glose');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 11, 1, 'N’ayant plus d’ putain, je n’ s’rai plus cocu,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 11, 2, 'Et si, par hasard, je te r’mets que’qu’ chose,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-stances-a-sophie', 11, 3, 'Ce n’ sera jamais que mon pied dans l’ cul!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('sur-les-bords-de-la-loire', 'SUR LES BORDS DE LA LOIRE', 'SUR LES BORDS DE LA LOIRE', 'franstalige-liederen', 'fr', NULL, 401, 401, NULL, NULL, 'Lied van de Guilde Turquoise
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sur-les-bords-de-la-loire', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-loire', 0, 0, 'La belle se promène, au fond de son jardin,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-loire', 0, 1, 'Au fond de son jardin, sur les bords de la Loire,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-loire', 0, 2, 'Au fond de son jardin, sur les bords du ruisseau');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('sur-les-bords-de-la-loire', 0, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sur-les-bords-de-la-loire', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-loire', 1, 0, 'Tout auprès du vaisseau, charmant matelot ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sur-les-bords-de-la-loire', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-loire', 2, 0, 'Sur le grand fleuve passe un brick de marinier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-loire', 2, 1, 'Un brick de marinier, sur les bords de la Loire,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-loire', 2, 2, 'Un brick de marinier, sur les bords du ruisseau');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('sur-les-bords-de-la-loire', 2, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sur-les-bords-de-la-loire', 3, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sur-les-bords-de-la-loire', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-loire', 4, 0, 'Le plus jeune des mousses chantait une chanson.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sur-les-bords-de-la-loire', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-loire', 5, 0, '“Je voudrais” dit la belle, “savoir votre chanson ...”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sur-les-bords-de-la-loire', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-loire', 6, 0, '“Montez dedans le brick(e) et je vous l’apprendrai ...”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sur-les-bords-de-la-loire', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-loire', 7, 0, 'Quand elle fut sur le brick(e), elle se mit à pleurer.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sur-les-bords-de-la-loire', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-loire', 8, 0, '“Qu’avez-vous donc, la belle, qu’avez-vous à pleurer?”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sur-les-bords-de-la-loire', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-loire', 9, 0, '“Je pleure mon pucelage qu’un gabier m’a volé ...”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sur-les-bords-de-la-loire', 10, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-loire', 10, 0, '“Ne pleurez pas la belle, je vous le retrouv’rai ...”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sur-les-bords-de-la-loire', 11, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-loire', 11, 0, '“Ça n’se rend pas” dit-elle, “comm’ de l’argent prêté ...”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sur-les-bords-de-la-loire', 12, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-loire', 12, 0, '“Sans ça, toutes les filles trouv’raient à se marier ...”');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('sur-les-bords-de-la-tamise', 'SUR LES BORDS DE LA TAMISE', 'SUR LES BORDS DE LA TAMISE', 'franstalige-liederen', 'fr', NULL, 402, 402, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sur-les-bords-de-la-tamise', 0, 'direction', 1, 'Dit lied wordt aangeheven door één commilito, die er na de eerste herhaling een tweede bijhaalt. Bij de derde herhaling halen ze elk een commilito uit de corona en zo voorts en zo verder. Men voegt vanzelfsprekenderwijs telkens het dubbel aantal Engelsen bij, tot de ganse corona rechtstaat.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sur-les-bords-de-la-tamise', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-tamise', 1, 0, 'Sur les bords de la Tamise');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-tamise', 1, 1, 'Y avait un Anglais');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-tamise', 1, 2, 'Qui était en bras d’chemise');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-tamise', 1, 3, 'Et sans cesse répétait: “Aie, Aie, Aie, ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-tamise', 1, 4, 'J’ai un morpion qui me gratte les couilles,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-tamise', 1, 5, 'J’ai un morpion, je ne peux l’attraper,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-tamise', 1, 6, 'J’ai un morpion qui me gratte les couilles,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-tamise', 1, 7, 'J’ai un morpion, je ne peux l’attraper.”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-tamise', 1, 8, 'Sur les bords de la Tamise');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-tamise', 1, 9, 'Y avait deux Anglais ... !');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sur-les-bords-de-la-tamise', 2, 'direction', 1, 'Als iedereen rechtstaat zingt men nog:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sur-les-bords-de-la-tamise', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-tamise', 3, 0, 'Sur les bords de la Tamise');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sur-les-bords-de-la-tamise', 3, 1, 'Y avait tous les anglais ...');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('la-tour-de-londres', 'LA TOUR DE LONDRES', 'TOUR DE LONDRES, LA', 'franstalige-liederen', 'fr', NULL, 403, 403, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-tour-de-londres', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-tour-de-londres', 0, 0, 'Dans une tour de Londres');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-tour-de-londres', 0, 1, 'Là-haut, là-haut,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-tour-de-londres', 0, 2, 'Dans une tour de Londres');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-tour-de-londres', 0, 3, 'Y avait un prisonnier.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('la-tour-de-londres', 0, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-tour-de-londres', 1, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-tour-de-londres', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-tour-de-londres', 2, 0, 'Il n’y voyait personne ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-tour-de-londres', 2, 1, 'Que la fille du geôlier.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-tour-de-londres', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-tour-de-londres', 3, 0, 'Un jour, il lui demande ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-tour-de-londres', 3, 1, 'La clef du cabinet.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-tour-de-londres', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-tour-de-londres', 4, 0, 'Il s’assit sur le trône ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-tour-de-londres', 4, 1, 'Et se mit à chier.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-tour-de-londres', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-tour-de-londres', 5, 0, 'En attendant que ça sèche ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-tour-de-londres', 5, 1, 'Il se mit à chanter.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-tour-de-londres', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-tour-de-londres', 6, 0, 'J’emmerde la police ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-tour-de-londres', 6, 1, 'Et la maréchaussée.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-tour-de-londres', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-tour-de-londres', 7, 0, 'Les gendarm’s l’entendirent ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-tour-de-londres', 7, 1, 'Et vinr’nt le trucider.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('la-tour-de-londres', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-tour-de-londres', 8, 0, 'La moral’ de l’histoire ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-tour-de-londres', 8, 1, 'Est qu’il n’faut pas chier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('la-tour-de-londres', 8, 2, 'Sans avoir du papier.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('le-tourdion', 'LE TOURDION', 'TOURDION, LE', 'franstalige-liederen', 'fr', NULL, 404, 404, NULL, NULL, 'Bourgondische dans uit de Renaissance, later populair geworden als drinklied');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-tourdion', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-tourdion', 0, 0, 'Quand je bois du vin clairet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-tourdion', 0, 1, 'Amis tout tourne, tourne, tourne, tourne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-tourdion', 0, 2, 'Aussi désormais je bois');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-tourdion', 0, 3, 'Anjou ou Arbois.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-tourdion', 0, 0, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-tourdion', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-tourdion', 1, 0, 'Chantons et buvons,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-tourdion', 1, 1, 'À ce flacon faisons la guerre;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-tourdion', 1, 2, 'Chantons et buvons,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-tourdion', 1, 3, 'Mes amis, buvons donc!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-tourdion', 1, 0, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-tourdion', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-tourdion', 2, 0, 'Hey, der gute, kühle Wein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-tourdion', 2, 1, 'Macht alles kunter- kunterbunt sich drehen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-tourdion', 2, 2, 'Holt die Gläser, schenket ein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-tourdion', 2, 3, 'Anjou und Arbois');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-tourdion', 2, 0, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-tourdion', 3, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-tourdion', 3, 0, 'Vivat! Singt und trinkt!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-tourdion', 3, 1, 'Und leert die Flasche bis zum Grunde;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-tourdion', 3, 2, 'Singt und trinkt mit uns,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-tourdion', 3, 3, 'Den Wein schenket ein');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('le-tourdion', 3, 0, 3, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('les-trois-orfevres', 'LES TROIS ORFÈVRES', 'TROIS ORFÈVRES, LES', 'franstalige-liederen', 'fr', NULL, 405, 406, NULL, NULL, 'T & M: Anthologie Hospitalière et Latinesque, 1911');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-trois-orfevres', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 0, 0, 'Trois orfèvres, à la Saint-Éloi,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 0, 1, 'S’en allèr’nt dîner chez un autre orfèvre.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 0, 2, 'Trois orfèvres, à la Saint-Éloi,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 0, 3, 'S’en allèr’nt dîner chez un bon bourgeois.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 0, 4, 'Ils ont baisé toute la famille:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 0, 5, 'La mèr’ aux nichons,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 0, 6, 'Le pèr’ au cul, la fill’ au con.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-trois-orfevres', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 1, 0, 'Relevez, belles, votre blanc jupon,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 1, 1, 'Qu’on vous voie le cul, qu’on vous voie les fesses,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 1, 2, 'Relevez, belles, votre blanc jupon,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 1, 3, 'Qu’on vous voie le cul, qu’on vous voie le con!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-trois-orfevres', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 2, 0, 'La servante, qui avait tout vu,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 2, 1, 'Leur dit: “Foutez-moi votre pine aux fesses!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 2, 2, 'La servante qui avait tout vu,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 2, 3, 'Leur dit: “Foutez-moi votre pine dans l’ cul!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 2, 4, 'Ils l’ont baisée, tous trois, sur un’ chaise,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 2, 5, 'La chais’ a cassé,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 2, 6, 'Ils sont tombés sans débander.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-trois-orfevres', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 3, 0, 'Les orfèvres, non contents de ça');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 3, 1, 'Montèr’nt sur le toit pour baiser Minette;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 3, 2, 'Les orfèvres non contents de ça,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 3, 3, 'Montèr’nt sur le toit, pour baiser le chat.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 3, 4, '“Chat, petit chat, chat tu m’égratignes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 3, 5, 'Petit polisson,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 3, 6, 'Tu m’égratignes les roustons!”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-trois-orfevres', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 4, 0, 'Les orfèvres chez un pâtissier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 4, 1, 'Entrèr’nt pour manger quelques friandises;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 4, 2, 'Les orfèvres, chez un pâtissier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 4, 3, 'Par les p’tits mitrons se fir’nt enculer.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 4, 4, 'Puis, voyant leurs vits pleins de merde,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 4, 5, 'Ils ont bouffé ça,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 4, 6, 'En guis’ d’éclairs au chocolat.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('les-trois-orfevres', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 5, 0, 'Les orfèvres, au son du canon,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 5, 1, 'Se retrouveront tous à la frontière;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 5, 2, 'Les orfèvres, au son du canon,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 5, 3, 'En guis’ de boulets, lanc’ront des étrons,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 5, 4, 'Bandant tous ainsi que des carmes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 5, 5, 'À grands coups de vit,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('les-trois-orfevres', 5, 6, 'Repousseront les ennemis.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('le-troubadour', 'LE TROUBADOUR', 'TROUBADOUR, LE', 'franstalige-liederen', 'fr', NULL, 407, 408, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-troubadour', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 0, 0, 'J’ai fait le tour du monde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 0, 1, 'Et partout j’ai baisé,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 0, 2, 'Les brunes et les blondes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 0, 3, 'Le soir dans les fossés,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 0, 4, 'J’ ai baisé les grenouilles,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 0, 5, 'Enculé les crapauds,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 0, 6, 'Qui me suçaient les couilles,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 0, 7, 'Le soir au bord de l’eau.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-troubadour', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 1, 0, 'C’est le trou-ba-ba-a-a');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 1, 1, 'C’est le trou-ba-dou-ou-our');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 1, 2, 'Qui baisait la nuit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 1, 3, 'Et qui baisait le jour.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 1, 4, 'C’est le trou-ba-ba-a-a');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 1, 5, 'C’est le trou-ba-dou-ou-our');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 1, 6, 'Qui baisait la nuit, le jour');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 1, 7, 'Le troubadour.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-troubadour', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 2, 0, 'C’est la reine d’Angleterre,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 2, 1, 'Qui traversa les mers,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 2, 2, 'Pour voir si les Anglais,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 2, 3, 'Baisaient mieux que les Français.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 2, 4, 'Et sacré nom de noms');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 2, 5, 'Des 36 positions,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 2, 6, 'C’est encore là le mieux');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 2, 7, 'Pour gagner le ping-pong.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-troubadour', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 3, 0, 'C’est la reine d’Espagne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 3, 1, 'Qui dit à son mari:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 3, 2, 'J’aime bien le champagne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 3, 3, 'Mais j’aime aussi le lit.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 3, 4, 'Ce soir au clair de lune,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 3, 5, 'Mon ami Alphonso,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 3, 6, 'Je te taillerai une plume,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-troubadour', 3, 7, 'Pour mettre à ton chapeau.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('vivre-pour-vivre', 'VIVRE POUR VIVRE', 'VIVRE POUR VIVRE', 'franstalige-liederen', 'fr', NULL, 408, 410, 'E. Philippon, Corporatio Brabantia Bruxellensis', 'Naar de film ‘Mon oncle Benjamin’', 'Winnend lied, Festival de la chanson estudiantine, 1999');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vivre-pour-vivre', 0, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 0, 0, 'Je veux vivre ma vie avant qu’elle ne soit vieille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 0, 1, 'Entre le cul des filles et le cul des bouteilles');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vivre-pour-vivre', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 1, 0, 'Manger pour manger que ce soit ripaille,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 1, 1, 'Cochonnets bien gras, venaison tendre et dorée');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 1, 2, 'Manger pour manger que ce soit riche tripaille,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 1, 3, 'Régaler ses yeux, l’appétit démesuré.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vivre-pour-vivre', 2, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 2, 0, 'Je veux manger ma vie avant qu’elle ne soit vieille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 2, 1, 'Entre le cul des filles et le cul des bouteilles, mais ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vivre-pour-vivre', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 3, 0, 'Baiser pour baiser, quelle que soit la femme');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 3, 1, 'Prendre du plaisir, part bonheur de faire jouir.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 3, 2, 'Baiser pour baiser, que ce soit avec flamme');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 3, 3, 'Caresser ses reins, goûter à tout ses plaisirs');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vivre-pour-vivre', 4, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 4, 0, 'Je veux baiser ma vie avant qu’elle ne soit vieille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 4, 1, 'Entre le cul des filles et le cul des bouteilles, mais ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vivre-pour-vivre', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 5, 0, 'Chanter pour chanter, que ce soit La Bière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 5, 1, 'Le Gaudeamus, Io Vivat ou Le Semeur,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 5, 2, 'Chanter pour chanter, que ce soit avec mes frères');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 5, 3, 'Et dans l’harmonie, entonner avec ardeur ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vivre-pour-vivre', 6, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 6, 0, 'Je veux chanter ma vie avant qu’elle ne soit vieille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 6, 1, 'Entre le cul des filles et le cul des bouteilles');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vivre-pour-vivre', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 7, 0, 'Mourir pour mourir, que ce soit d’ivresse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 7, 1, 'Sa vie bien remplie, l’esprit plein de souvenirs');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 7, 2, 'Mourir pour mourir, que ce soit avec noblesse,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 7, 3, 'Un dernier sourire, croir’ encore à l’avenir');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('vivre-pour-vivre', 8, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 8, 0, 'Je veux mourir ma vie avant qu’elle ne soit vieille');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('vivre-pour-vivre', 8, 1, 'Entre le cul des filles et le cul des bouteilles');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('le-zobi-d-ali-pacha', 'LE ZOBI D’ALI PACHA', 'ZOBI D’ALI PACHA, LE', 'franstalige-liederen', 'fr', NULL, 410, 412, NULL, NULL, 'T & M: Gérard Doulssane');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-zobi-d-ali-pacha', 0, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 0, 0, 'Alla, Allala! Alla, Allala!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 0, 1, 'Le zobi d’Ali Pacha');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 0, 2, 'L’est encore plus gros qu’Allah!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 0, 3, 'Le zobi d’Ali Pacha est là.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-zobi-d-ali-pacha', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 1, 0, 'Quand il entre à la mosquée');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 1, 1, 'Pour y faire son prière');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 1, 2, 'Y peut pas s’agenouiller');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 1, 3, 'Son zobi traîne par terre.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 1, 4, 'Quand y s’ promène dans la casbah');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 1, 5, 'L’odeur attire les mouches');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 1, 6, 'Ca l’ fait jouir sous son djellaba');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 1, 7, 'Et ça coule sur ses babouch’s');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-zobi-d-ali-pacha', 2, 'chorus-ref', 1, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-zobi-d-ali-pacha', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 3, 0, 'Les fatmas y s’en sont folles');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 3, 1, 'Elles le sucent elles le fignolent');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 3, 2, 'Il décharge comme un puits de pétrole');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-zobi-d-ali-pacha', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 4, 0, 'Aïcha la fille du cheik');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 4, 1, 'A chaque fois qu’il la r’nique');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 4, 2, 'Il l’encule toujours à sec');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 4, 3, 'Elle devient hystérique');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 4, 4, 'Il va, il vient, il rentre, il sort,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 4, 5, 'Il défonce la pastèque');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 4, 6, 'Elle a du mal elle crie bien fort');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 4, 7, 'On l’entend jusqu’à la Mecque');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-zobi-d-ali-pacha', 5, 'chorus-ref', 1, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-zobi-d-ali-pacha', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 6, 0, 'Quand il le glisse à la raie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 6, 1, 'On dirait un minaret');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 6, 2, 'Tell’ment qu’il est gros ça fait pas vrai.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-zobi-d-ali-pacha', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 7, 0, 'Les tantouzes du monde entier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 7, 1, 'Tous y font le voyage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 7, 2, 'Pour aller se faire pointer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 7, 3, 'Par ce zobi sauvage');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 7, 4, 'De beaux claouis tendus comme ça');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 7, 5, 'C’est meilleur qu’un couscous');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 7, 6, 'Quand ils y ont goûté un’ fois');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('le-zobi-d-ali-pacha', 7, 7, 'Les pédés y s’en veulent tous.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('le-zobi-d-ali-pacha', 8, 'chorus-ref', 1, NULL);
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('alle-fische-schwimmen', 'ALLE FISCHE SCHWIMMEN', 'ALLE FISCHE SCHWIMMEN', 'duitstalige-liederen', 'de', NULL, 415, 415, NULL, NULL, NULL);
