INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alle-fische-schwimmen', 1, 0, 'O Susanna! Wie ist das Leben wunderschön');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alle-fische-schwimmen', 1, 1, 'O Susanna! Wie ist das Leben schön');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('alle-fische-schwimmen', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alle-fische-schwimmen', 2, 0, 'Alle Möpse rollen, alle Möpse rollen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alle-fische-schwimmen', 2, 1, 'Nur der kleine Rollmops nicht!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('alle-fische-schwimmen', 2, 0, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('alle-fische-schwimmen', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alle-fische-schwimmen', 3, 0, 'Alle Böcke springen, alle Böcke springen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alle-fische-schwimmen', 3, 1, 'Nur der kleine Holzbock nicht!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('alle-fische-schwimmen', 3, 0, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('alle-fische-schwimmen', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alle-fische-schwimmen', 4, 0, 'Trinke noch ein Tröpfchen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alle-fische-schwimmen', 4, 1, 'Aus dem kleinen Henkeltöpfchen!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('alle-fische-schwimmen', 4, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('alle-fische-schwimmen', 4, 0, 1, 2, '(BIS)');
