INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alle-fische-schwimmen', 5, 0, 'Alle Belle bellen, alle Belle bellen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alle-fische-schwimmen', 5, 1, 'Nur die kleine Schnotbel nicht!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('alle-fische-schwimmen', 5, 0, 1, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('alt-heidelberg', 'ALT HEIDELBERG', 'ALT HEIDELBERG', 'duitstalige-liederen', 'de', NULL, 415, 416, 'Joseph Viktor von Scheffel, Heidelberger und Berliner Burschenschaft, 1852', 'Anton Zimmermann, 1861', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('alt-heidelberg', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 0, 0, 'Alt Heidelberg, du feine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 0, 1, 'Du Stadt an Ehren reich,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 0, 2, 'Am Neckar und am Rheine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 0, 3, 'Kein’ andre kommt dir gleich.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 0, 4, 'Stadt fröhlicher Gesellen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 0, 5, 'An Weisheit schwer und Wein,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 0, 6, 'Klar zieh’n des Stromes Wellen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 0, 7, 'Blau äuglein blitzen drein.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('alt-heidelberg', 0, 7, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('alt-heidelberg', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 1, 0, 'Und kommt aus Winden Süden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 1, 1, 'Der Frühling über’s Land,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 1, 2, 'So webt er dir aus Blüten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 1, 3, 'Ein schimmernd Brautgewand.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 1, 4, 'Auch mir stehst du geschrieben,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 1, 5, 'Im Herz gleich einer Braut.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 1, 6, 'Es klingt wie junges Lieben,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 1, 7, 'Dein Name mir, so traut!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('alt-heidelberg', 1, 7, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('alt-heidelberg', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 2, 0, 'Alt Heidelberg du feine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 2, 1, 'Du Stadt an Ehren reich,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 2, 2, 'Am Neckar und am Rheine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 2, 3, 'Kein andre kommt dir gleich.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 2, 4, 'Und stechen mich die Dornen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 2, 5, 'Und wird mir’s da zu kalt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 2, 6, 'Geb ich dem Roß die Sporen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('alt-heidelberg', 2, 7, 'Und treib’s ins Neckartal.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('alt-heidelberg', 2, 7, 7, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('bier-her', 'BIER HER!', 'BIER HER!', 'duitstalige-liederen', 'de', NULL, 416, 417, NULL, '‘Lebe strebe’, G.W. Baumann, 1855, Heidelberg', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bier-her', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 0, 0, 'Bier her! Bier her!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 0, 1, 'Oder ich fall’um, juchei!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 0, 2, 'Bier her! Bier her!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 0, 3, 'Oder ich fall’um!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 0, 4, 'Soll das Bier im Keller liegen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 0, 5, 'Und ich hier die Ohnmacht kriegen?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 0, 6, 'Bier her! Bier her!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 0, 7, 'Oder ich fall’um!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bier-her', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 1, 0, 'Bier her! Bier her!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 1, 1, 'Oder ich fall’um, juchei!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 1, 2, 'Bier her! Bier her!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 1, 3, 'Oder ich fall’um!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 1, 4, 'Wenn ich nicht gleich Bier bekumm’');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 1, 5, 'Schmeiss’ ich die ganze Kneipe um');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 1, 6, 'Bier her! Bier her!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 1, 7, 'Oder ich fall’um!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bier-her', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 2, 0, 'Frau her! Frau her!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 2, 1, 'Oder ich spiel ab, juchei!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 2, 2, 'Frau her! Frau her!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 2, 3, 'Oder ich spiel ab!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 2, 4, 'Soll die Frau im Bette liegen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 2, 5, 'Und ich hier ein Slapfe kriegen?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 2, 6, 'Frau her! Frau her!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bier-her', 2, 7, 'Oder ich spiel ab!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('bums-valdera', 'BUMS VALDERA', 'BUMS VALDERA', 'duitstalige-liederen', 'de', NULL, 417, 418, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bums-valdera', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bums-valdera', 0, 0, 'Wir machen durch bis morgen früh,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bums-valdera', 0, 1, 'Und singen: bums valdera,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bums-valdera', 0, 2, 'Bums valdera, bums valdera.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bums-valdera', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bums-valdera', 1, 0, 'Wir trinken heut’ so viel wie nie,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bums-valdera', 1, 1, 'Und singen: bums valdera,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bums-valdera', 1, 2, 'Bums valdera, so viel wie nie.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bums-valdera', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bums-valdera', 2, 0, 'Herr Wirt, komm her,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bums-valdera', 2, 1, 'Das Glass ist leer,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bums-valdera', 2, 2, 'Wir möchten jetzt erst recht noch mehr!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bums-valdera', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bums-valdera', 3, 0, 'Wir machen durch bis morgen früh,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bums-valdera', 3, 1, 'Und singen: bums valdera,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bums-valdera', 3, 2, 'Bums valdera, bis morgen früh.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('burschen-heraus', 'BURSCHEN, HERAUS', 'BURSCHEN, HERAUS', 'duitstalige-liederen', 'de', NULL, 419, 419, 'Franz von Kobell 1844, Corps Isaria München', NULL, 'Opgetekend Deutches Lieder- und Kommersbuch, Karl Göpel, 1847');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('burschen-heraus', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('burschen-heraus', 0, 0, 'Burschen, heraus!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('burschen-heraus', 0, 1, 'Lasset es schallen von Haus zu Haus!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('burschen-heraus', 0, 2, 'Wenn der Lerche Silberschlag');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('burschen-heraus', 0, 3, 'Grüßt des Maien ersten Tag');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('burschen-heraus', 0, 4, 'Dann heraus und fragt nicht viel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('burschen-heraus', 0, 5, 'Frisch mit Lied und Lautenspiel!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('burschen-heraus', 0, 6, 'Burschen, heraus!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('burschen-heraus', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('burschen-heraus', 1, 0, 'Burschen, heraus!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('burschen-heraus', 1, 1, 'Lasset es schallen von Haus zu Haus!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('burschen-heraus', 1, 2, 'Ruft um Hilf die Poesei');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('burschen-heraus', 1, 3, 'Gegen Zopf und Philisterei,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('burschen-heraus', 1, 4, 'Dann heraus bei Tag und Nacht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('burschen-heraus', 1, 5, 'Bis sie wieder frei gemacht!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('burschen-heraus', 1, 6, 'Burschen, heraus!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('burschen-heraus', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('burschen-heraus', 2, 0, 'Burschen, heraus!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('burschen-heraus', 2, 1, 'Lasset es schallen von Haus zu Haus!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('burschen-heraus', 2, 2, 'Wenn es gilt fürs Vaterland,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('burschen-heraus', 2, 3, 'Treu die Klingen dann zur Hand,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('burschen-heraus', 2, 4, 'Und heraus mit mut’gem Sang,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('burschen-heraus', 2, 5, 'Wär es auch zum letzten Gang!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('burschen-heraus', 2, 6, 'Burschen, heraus!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ca-ca-geschmauset', 'ÇA, ÇA GESCHMAUSET', 'ÇA, ÇA GESCHMAUSET', 'duitstalige-liederen', 'de', NULL, 420, 421, 'Christian Wilhelm Kindleben, 1781', NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ca-ca-geschmauset', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 0, 0, 'Ça, ça geschmauset,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 0, 1, 'Lasst uns nicht rappelköpfisch sein!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 0, 2, 'Wer nicht mithauset, der bleibt daheim.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ca-ca-geschmauset', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 1, 0, 'Edite, bibite, collegiales!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 1, 1, 'Post multa saecula, pocula nulla!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ca-ca-geschmauset', 1, 1, 1, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ca-ca-geschmauset', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 2, 0, 'Der Herr Professor');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 2, 1, 'Liest heut’ kein Kollegium:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 2, 2, 'Darum ist es besser, man trinkt eins ’rum.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ca-ca-geschmauset', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 3, 0, 'Trinkt nach Gefallen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 3, 1, 'Bis ihr die Finger darnach leckt;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 3, 2, 'Dann hat’s uns allen recht wohl geschmeckt.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ca-ca-geschmauset', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 4, 0, 'Auf, auf, ihr Brüder!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 4, 1, 'Erhebt den Bacchus auf den Thron');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 4, 2, 'Und setzt euch nieder, wir trinken schon.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ca-ca-geschmauset', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 5, 0, 'So lebt man immer,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 5, 1, 'So lang der junge Lenz uns blinkt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 5, 2, 'Und Jugendschimmer die Wangen schminkt.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ca-ca-geschmauset', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 6, 0, 'Knaster, den gelben,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 6, 1, 'Uns Apolda präpariert');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 6, 2, 'Und uns denselben rekommandiert.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ca-ca-geschmauset', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 7, 0, 'Hat dann ein jeder');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 7, 1, 'Sein Pfeifchen Knaster angebrannt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 7, 2, 'So nimmt er wieder sein Glas zur Hand!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ca-ca-geschmauset', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 8, 0, 'So lebt man lustig,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 8, 1, 'Weil es noch flotter Bursche heißt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 8, 2, 'Bis dass man rüstig ad patres reist.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ca-ca-geschmauset', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 9, 0, 'Bis dass mein Hieber');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 9, 1, 'Vom Corpus juris wird besiegt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 9, 2, 'So lang, ihr Brüder, leb ich vergnügt!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ca-ca-geschmauset', 10, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 10, 0, 'Denkt oft, ihr Brüder,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 10, 1, 'An uns’re Jugendfröhlichkeit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ca-ca-geschmauset', 10, 2, 'Sie kehrt nicht wieder, die goldne Zeit!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('donaustrudel', 'DONAUSTRUDEL', 'DONAUSTRUDEL', 'duitstalige-liederen', 'de', NULL, 421, 422, NULL, NULL, 'Uit Beieren, omgevormd door opeenvolgende studentengeneraties.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('donaustrudel', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 0, 0, 'Als wir jüngst in Regensburg waren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 0, 1, 'Sind wir über den Strudel gefahren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 0, 2, 'Da war’n viele Holden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 0, 3, 'die mitfahren wollten.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('donaustrudel', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 1, 0, 'Schwäbische; Bayrische Dirndel; juchei-sa-sa!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 1, 1, 'Muß der Schiffsmann fahren.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('donaustrudel', 1, 0, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('donaustrudel', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 2, 0, 'Und ein Mädel von zwölf Jahren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 2, 1, 'Ist mit über den Strudel gefahren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 2, 2, 'Weil sie noch nicht lieben kunnt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 2, 3, 'Kamm sie sicher übers Strudels Grund.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('donaustrudel', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 3, 0, 'Und vom hohen Bergesschloße');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 3, 1, 'Kam auf stolzem schwarzem Rosse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 3, 2, 'Adlig Fräulein Kunigund,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 3, 3, 'Wollt mit fahren übers Strudels Grund!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('donaustrudel', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 4, 0, '“Schiffsmann, lieber Schiffsmann mein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 4, 1, 'Soll’s denn so gefährlich sein?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 4, 2, 'Schiffsmann, sag’s mir ehrlich,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 4, 3, 'Ist’s denn so gefährlich?”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('donaustrudel', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 5, 0, 'Wem der Myrtenkranz geblieben,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 5, 1, 'Landet froh und sicher drüben,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 5, 2, 'Wer ihn hat verloren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 5, 3, 'Ist dem Tod erkoren!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('donaustrudel', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 6, 0, 'Als sie auf die Mitt gekommen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 6, 1, 'Kam ein grosser Nix geschwommen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 6, 2, 'Nahm das Fräulein Kunigund,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donaustrudel', 6, 3, 'Fuhr mit ihr in des Strudels Grund!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('erika', 'ERIKA', 'ERIKA', 'duitstalige-liederen', 'de', NULL, 422, 423, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('erika', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 0, 0, 'Auf der Heide blüht ein kleines Blümelein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 0, 1, 'Und das heißt ... Erika.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 0, 2, 'Heiß von hunderttausend kleinen Bienelein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 0, 3, 'Wird umschwärmt ... Erika.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 0, 4, 'Denn ihr Herz ist voller Süßigkeit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 0, 5, 'Zarter Duft entströmt dem Blütenkleid.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 0, 6, 'Auf der Heide blüht ein kleines Blümelein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 0, 7, 'Und das heißt ... Erika.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('erika', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 1, 0, 'In der Heimat wohnt ein kleines Mägdelein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 1, 1, 'Und das heißt ... Erika.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 1, 2, 'Dieses Mädel ist mein treues Schätzelein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 1, 3, 'Und mein Glück, ... Erika.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 1, 4, 'Wenn das Heidekraut da rötlich blüht');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 1, 5, 'Singe ich zum Gruß ihr dieses Lied:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 1, 6, 'In der Heimat wohnt ein kleines Mägdelein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 1, 7, 'Und das heißt ... Erika.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('erika', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 2, 0, 'In mein Kämmerlein blüht auch ein Blümelein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 2, 1, 'Und das heißt ... Erika.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 2, 2, 'Schon bei’m Morgengrau’n so wie bei Dämmerschein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 2, 3, 'Schaut’s mich an, ... Erika.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 2, 4, 'Und dann ist es mir, als spräch es laut:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 2, 5, '“Denkst du noch an deine kleine Braut?”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 2, 6, 'In der Heimat weint um dich ein Mägdelein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('erika', 2, 7, 'Und das heißt ... Erika.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', '’S GIBT KEIN SCHÖNER LEBEN ALS STUDENTENLEBEN', '’S GIBT KEIN SCHÖNER LEBEN ALS STUDENTENLEBEN', 'duitstalige-liederen', 'de', NULL, 425, 426, 'Braun’s Liederbuch für Studenten, 1845', 'Karl Gottlieb Reißiger, 1822', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 0, 0, '’s gibt kein schöner Leben als Studentenleben,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 0, 1, 'Wie es Bacchus und Gambrinus schuf;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 0, 2, 'In die Kneipen laufen und sein Geld versaufen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 0, 3, 'Ist ein hoher; herrlicher Beruf.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 0, 4, 'Ist das Moos entschwunden, wird ein Bär gebunden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 0, 5, 'Immer geht ’s in dulci jubilo;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 0, 6, 'Ist kein Geld in Bänken, ist doch Pump in Schenken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 0, 7, 'Für den kreuzfidelen Studio.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 1, 0, 'Auch von Lieb umgeben ist’s Studentenleben,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 1, 1, 'Uns beschützet Venus Cypria.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 1, 2, 'Mädchen, die da lieben und das Küssen üben,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 1, 3, 'Waren stets in schwerer Menge da.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 1, 4, 'Aber die da schmachten und platonisch trachten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 1, 5, 'Ach, die liebe Unschuld tut nur so;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 1, 6, 'Denn so recht inwendig brennt es ganz unbändig');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 1, 7, 'Für den kreuzfidelen Studio.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 2, 0, 'Will zum Kontrahieren einer mich touchieren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 2, 1, 'Gleich gefordert wird er augenblicks:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 2, 2, '“Bist ein dummer Junge!” Und mit raschem Sprunge');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 2, 3, 'Auf Mensur geht’s im Paukantenwichs.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 2, 4, 'Schleppfuchs muß die Waffen auf den Paukplatz schaffen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 2, 5, 'Quarten pfeifen, Terzen schwirren froh.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 2, 6, 'Hat ein Schmiss gesessen, ist der Tusch vergessen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 2, 7, 'Von dem kreuzfidelen Studio.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 3, 0, 'Vater spricht: “Das Raufen und das Kneipenlaufen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 3, 1, 'Nutzt dir zum Examen keinen Deut!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 3, 2, 'Doch dabei vergisst er, dass er ein Philister;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 3, 3, 'Und dass jedes Ding hat seine Zeit.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 3, 4, 'Traun! Das hieße lästern, schon nach sechs Semestern');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 3, 5, 'Ein Examen! Nein, das geht nicht so!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 3, 6, 'Möcht nie auf Erden et was anders werden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('s-gibt-kein-schoner-leben-als-studentenleben', 3, 7, 'Als ein kreuzfideler Studio.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('es-leben-die-studenten', 'ES LEBEN DIE STUDENTEN', 'ES LEBEN DIE STUDENTEN', 'duitstalige-liederen', 'de', NULL, 426, 427, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('es-leben-die-studenten', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 0, 0, 'Es leben die Studenten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 0, 1, 'Stets in den Tag hinein,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 0, 2, 'Wärn wir der Welt Regenten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 0, 3, 'Sollt immer Festtag sein;');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('es-leben-die-studenten', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 1, 0, 'Fürwahr, fürwahr, das ist doch sonderbar!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 1, 1, 'Jup jup jup jup tralalala!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 1, 2, 'Fürwahr, fürwahr, das ist doch sonderbar!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('es-leben-die-studenten', 1, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('es-leben-die-studenten', 1, 1, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('es-leben-die-studenten', 1, 2, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('es-leben-die-studenten', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 2, 0, 'Wir jubeln, singen, trinken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 2, 1, 'Wohl durch die ganze Nacht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 2, 2, 'So lang die Sterne blinken,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 2, 3, 'Wird an kein Rast gedacht;');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('es-leben-die-studenten', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 3, 0, 'Doch sind geleert die Taschen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 3, 1, 'Dann ziehen wir nach Haus,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 3, 2, 'Man lebt bei leeren Flaschen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 3, 3, 'Nicht gut in Saus und Braus;');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('es-leben-die-studenten', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 4, 0, 'Nun, aber sagt, ihr Leute,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 4, 1, 'Wie mag es wohl geschehen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 4, 2, 'Daß gestern, morgen, heute');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 4, 3, 'Wir stets zum Trinken gehen?');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('es-leben-die-studenten', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 5, 0, 'Das kommt, ich will’s euch sagen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 5, 1, 'Nur vom Studieren her.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 5, 2, 'Wer will sich damit plagen!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 5, 3, 'Das Bier behagt uns mehr!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('es-leben-die-studenten', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 6, 0, 'Drum leben wir Studenten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 6, 1, 'Stets in den Tag hinein,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 6, 2, 'Wärn wir der Welt Regenten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('es-leben-die-studenten', 6, 3, 'Sollt immer Festtag sein.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('die-gedanken-sind-frei', 'DIE GEDANKEN SIND FREI', 'GEDANKEN SIND FREI, DIE', 'duitstalige-liederen', 'de', NULL, 429, 429, NULL, NULL, 'Tekst van Zuid-Duitse oorsprong, verschenen op pamfletten tussen 1780 en 1800. De basisgedachte is echter reeds uitgedrukt geweest in een middelhoogduitse vrijdenkerszegswijze ‘Bescheidenheit’, uit het jaar 1229. Deze luidt: ‘Diu bant mac nieman vinden, diu mine gedanken binden’. Walther von der Vogelweide (ergens tussen 1170 en 1230) zong: ‘Sind doch Gedanken frei’, terwijl de Oostenrijkse minnezanger Dietmar von Aist in de 12e eeuw ‘Die Gedanken, die sind ledig frei’ schreef.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-gedanken-sind-frei', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-gedanken-sind-frei', 0, 0, 'Die Gedanken sind frei, wer kann sie erraten?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-gedanken-sind-frei', 0, 1, 'Sie fliehen vorbei, wie nächtliche Schatten.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-gedanken-sind-frei', 0, 2, 'Kein Mensch kann sie wissen, kein Jäger sie ’rschießen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-gedanken-sind-frei', 0, 3, 'Mit Pulver und Blei: Die Gedanken sind frei!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-gedanken-sind-frei', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-gedanken-sind-frei', 1, 0, 'Ich denke, was ich will und was mich beglücket,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-gedanken-sind-frei', 1, 1, 'Doch alles in der Still’ und wie es sich schicket.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-gedanken-sind-frei', 1, 2, 'Mein Wunsch und Begehren kann niemand verwehren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-gedanken-sind-frei', 1, 3, 'Es bleibet dabei: Die Gedanken sind frei!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-gedanken-sind-frei', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-gedanken-sind-frei', 2, 0, 'Und sperrt man mich ein im finsteren Kerker,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-gedanken-sind-frei', 2, 1, 'Das alles sind rein vergebliche Werke!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-gedanken-sind-frei', 2, 2, 'Denn meine Gedanken zerreißen die Schranken');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-gedanken-sind-frei', 2, 3, 'Und Mauern entzwei: Die Gedanken sind frei.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-gedanken-sind-frei', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-gedanken-sind-frei', 3, 0, 'D’rum will ich auf immer den Sorgen entsagen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-gedanken-sind-frei', 3, 1, 'Und will mich auch nimmer mit Grillen mehr plagen.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-gedanken-sind-frei', 3, 2, 'Man kann ja im Herzen stets lachen und scherzen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-gedanken-sind-frei', 3, 3, 'Und denken dabei: Die Gedanken sind frei!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('gold-und-silber', 'GOLD UND SILBER', 'GOLD UND SILBER', 'duitstalige-liederen', 'de', NULL, 430, 431, 'August Schnezler, 1828, opgetekend door Franz Behr', 'F.H. Truhn, 1843', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gold-und-silber', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 0, 0, 'Gold und Silber lieb’ ich sehr,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 0, 1, 'Kann’s auch sehr gebrauchen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 0, 2, 'Hätt’ich nur ein ganzes Meer,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 0, 3, 'Mich hinein zu tauchen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 0, 4, '’s Braucht nicht grad geprägt zu sein,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 0, 5, 'Hab’s auch so ganz gerne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 0, 6, 'Sei’s des Mondes Silberschein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 0, 7, 'Sei’s das Gold der Sterne.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('gold-und-silber', 0, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gold-und-silber', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 1, 0, 'Seht, wie blinkt der goldne Wein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 1, 1, 'Hier in meinem Becher,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 1, 2, 'Horcht, wie klingt so silberrein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 1, 3, 'Froher Sang der Zecher,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 1, 4, 'Daß die Zeit einst golden war,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 1, 5, 'Will ich nicht bestreiten!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 1, 6, 'Denk’ ich doch im Silberhaar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 1, 7, 'Gern vergangner Zeiten.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('gold-und-silber', 1, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gold-und-silber', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 2, 0, 'Doch viel schöner ist das Gold,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 2, 1, 'Das vom Lockenköpfchen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 2, 2, 'Meines Liebchens niederrollet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 2, 3, 'In zwei blonden Zöpfchen.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 2, 4, 'Darum du, mein liebes Kind,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 2, 5, 'Laß uns herzen, küssen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 2, 6, 'Bis die Locken silbern sind');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 2, 7, 'Und wir scheiden müssen.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('gold-und-silber', 2, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gold-und-silber', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 3, 0, 'Liebes Mädchen, trag nicht Leid,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 3, 1, 'Blicke nicht so trübe,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 3, 2, 'Weil du nicht die einz’ge Maid');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 3, 3, 'Die ich herzlich liebe,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 3, 4, 'Schau, Studenten machen’s so:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 3, 5, 'Lieben mehr als eine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 3, 6, 'Bin ich nicht mehr studio');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 3, 7, 'Lieb’ich dich alleine.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('gold-und-silber', 3, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gold-und-silber', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 4, 0, 'Wer nur eine einz’ge küsst');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 4, 1, 'Bis zur Jahresende,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 4, 2, 'Und die andern schüchtern grüßt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 4, 3, 'Der ist kein Studente!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 4, 4, 'Wer noch nie bezechet war,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 4, 5, 'Der hat nie studieret,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 4, 6, 'Wär’ er auch so manches Jahr,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 4, 7, 'Ins Kolleg marschieret.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('gold-und-silber', 4, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gold-und-silber', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 5, 0, 'Deine Mutter hat’s gesagt:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 5, 1, '“Einen Kuss in Ehren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 5, 2, 'Soll man einem Studio');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 5, 3, 'Nimmermehr verwehren.”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 5, 4, 'Und was deine Mutter sagt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 5, 5, 'Sollst du treulich halten:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 5, 6, 'Küssen ist für junge Leut’');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gold-und-silber', 5, 7, 'Zuschauen für die Alten.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('gold-und-silber', 5, 6, 7, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('der-gute-kamerad', 'DER GUTE KAMERAD', 'GUTE KAMERAD, DER', 'duitstalige-liederen', 'de', NULL, 432, 432, 'L. Uhland, 1809', 'F. Silcher, 1825', '“Der gute Kamerad” wordt alleen gezongen om aan te leren of om de dood van een commilito te gedenken.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('der-gute-kamerad', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-gute-kamerad', 0, 0, 'Ich hatt’ einen Kameraden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-gute-kamerad', 0, 1, 'Einen besser’n find’st du ni’t');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-gute-kamerad', 0, 2, 'Die Trommel schlug zum Streite,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-gute-kamerad', 0, 3, 'Er ging an meiner Seite');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-gute-kamerad', 0, 4, 'In gleichem Schritt und Tritt.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('der-gute-kamerad', 0, 4, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('der-gute-kamerad', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-gute-kamerad', 1, 0, 'Eine Kugel kam geflogen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-gute-kamerad', 1, 1, 'Gilt’s mir oder gilt es dir?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-gute-kamerad', 1, 2, 'Ihn hat es weggerissen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-gute-kamerad', 1, 3, 'Er liegt mir vor den Füßen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-gute-kamerad', 1, 4, 'Als wär’s ein Stück von mir.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('der-gute-kamerad', 1, 4, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('der-gute-kamerad', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-gute-kamerad', 2, 0, 'Will mir die Hand noch reichen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-gute-kamerad', 2, 1, 'Derweil ich eben lad’:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-gute-kamerad', 2, 2, '“Kann dir die Hand nicht geben,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-gute-kamerad', 2, 3, 'Bleib’ du im ew’gen Leben,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-gute-kamerad', 2, 4, 'Mein guter Kamerad!”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('der-gute-kamerad', 2, 4, 4, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('de-hamborger-veermaster', 'DE HAMBORGER VEERMASTER', 'HAMBORGER VEERMASTER, DE', 'duitstalige-liederen', 'de', NULL, 433, 433, NULL, NULL, 'Traditional, circa 1850
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-hamborger-veermaster', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-hamborger-veermaster', 0, 0, 'Ick heff mol en Hamborger Veermaster sehn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-hamborger-veermaster', 0, 1, 'To my hooda, to my hooda!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-hamborger-veermaster', 0, 2, 'De Masten so scheef as den Schipper sien Been,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-hamborger-veermaster', 0, 3, 'To my hoo da hoo da ho!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-hamborger-veermaster', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-hamborger-veermaster', 1, 0, 'Blow, boys, blow for Californio,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-hamborger-veermaster', 1, 1, 'There is plenty of Gold');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-hamborger-veermaster', 1, 2, 'So I’ve been told');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-hamborger-veermaster', 1, 3, 'On the banks of Sacramento.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('de-hamborger-veermaster', 1, 0, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-hamborger-veermaster', 2, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-hamborger-veermaster', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-hamborger-veermaster', 3, 0, 'Dat Deck weur vun Isen, vull Schiet uns vull Schmeer.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-hamborger-veermaster', 3, 1, 'Dat weer de Schietgäng eer schönstes Pläseer.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-hamborger-veermaster', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-hamborger-veermaster', 4, 0, 'Dat Logis weur vull Wanzen, de Kombüs weur vull Dreck.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-hamborger-veermaster', 4, 1, 'De Beschüten, de leupen von sülben all weg.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-hamborger-veermaster', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-hamborger-veermaster', 5, 0, 'Dat Soltfleesch weur gröön un de Speck weur vull Moden.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-hamborger-veermaster', 5, 1, 'Kööm gev dat bloß an Wiehnachtsobend.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-hamborger-veermaster', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-hamborger-veermaster', 6, 0, 'Un wull’n wi mol seil’n, ick segg dat ja nur,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-hamborger-veermaster', 6, 1, 'Denn lööp he dree vörut und veer wedder retur.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('de-hamborger-veermaster', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-hamborger-veermaster', 7, 0, 'As dat Schipp, so weer ok de Kaptein,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('de-hamborger-veermaster', 7, 1, 'De Lüüd für dat Schipp weern ok bloß schangheit.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('heute-ist-heut', 'HEUTE IST HEUT', 'HEUTE IST HEUT', 'duitstalige-liederen', 'de', NULL, 434, 435, 'Rudolf Baumbach, 1882', 'V.E. Becker, 1885', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('heute-ist-heut', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 0, 0, 'Was die Welt morgen bringt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 0, 1, 'Ob sie mir Sorgen bringt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 0, 2, 'Leid oder Freud?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 0, 3, 'Komme was kommen mag,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 0, 4, 'Sonnenschein, Wetterschlag,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 0, 5, 'Morgen ist auch ein Tag');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 0, 6, 'Heute ist heut!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('heute-ist-heut', 0, 5, 6, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('heute-ist-heut', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 1, 0, 'Wenn’s dem Geschick gefällt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 1, 1, 'Sind wir in alle Welt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 1, 2, 'Morgen zerstreut!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 1, 3, 'D’rum lasst uns lustig sein!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 1, 4, 'Wirt, roll das Fass herein!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 1, 5, 'Mädel; schenk ein; schenk ein!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 1, 6, 'Heute ist heut!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('heute-ist-heut', 1, 5, 6, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('heute-ist-heut', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 2, 0, 'Ob ihren Rosenmund');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 2, 1, 'Morgen schön Hildegund');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 2, 2, 'Anderen beut');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 2, 3, 'Danach ich nimmer frag,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 2, 4, 'Das schafft mir keine Plag,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 2, 5, 'Wenn sie mich heut nur mag');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 2, 6, 'Heute ist heut!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('heute-ist-heut', 2, 5, 6, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('heute-ist-heut', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 3, 0, 'Klingklang, stoßt an und singt!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 3, 1, 'Morgen vielleicht erklingt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 3, 2, 'Sterbegeläut!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 3, 3, 'Wer weiß, ob nicht die Welt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 3, 4, 'Morgen in Schutt zerfällt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 3, 5, 'Wenn sie nur heut noch hält');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('heute-ist-heut', 3, 6, 'Heute ist heut!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('heute-ist-heut', 3, 5, 6, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 'ICH HAB’ MEIN HERZ IN HEIDELBERG VERLOREN', 'ICH HAB’ MEIN HERZ IN HEIDELBERG VERLOREN', 'duitstalige-liederen', 'de', NULL, 435, 436, 'Beda, Ernst Neubach, M: Fred Raymond, 1925', NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 0, 0, 'Es war an einem Abend, da ich kaum zwanzig Jahr’');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 0, 1, 'Da küsst’ ich rote Lippen und gold’nes, blondes Haar,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 0, 2, 'Die Nacht war blau und selig, der Neckar silberklar.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 0, 3, 'Ja, da wußte ich,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 0, 4, 'Woran, woran ich war');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 0, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 1, 0, 'Ich hab’ mein Herz in Heidelberg verloren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 1, 1, 'In einer lauen Sommernacht;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 1, 2, 'Ich war verliebt bis über beide Ohren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 1, 3, 'Und wie ein Röslein hat ihr Mund gelacht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 1, 4, 'Und als wir Abschied nahmen vor den Toren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 1, 5, 'Beim letzten Kuss da hab’ich’s klar erkannt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 1, 6, 'Dass ich mein Herz in Heidelberg verloren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 1, 7, 'Mein Herz das schlägt am Neckarstrand.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 1, 7, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 2, 0, 'Und wieder blüht wie damals am Neckarstrand der Wein;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 2, 1, 'Die Jahre sind vergangen und ich bin ganz allein.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 2, 2, 'Und fragt ihr mir Gesellen, warum er keine nahm,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 2, 3, 'Ja dann sag’ ich euch');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 2, 4, 'Ihr Freunde wie es kam');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 2, 3, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 3, 0, 'Was ist aus dir geworden seitdem ich dich verließ,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 3, 1, 'Alt-Heidelberg, du feine, du Deutsches Paradies?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 3, 2, 'Ich bin von dir gezogen, ließ Leichtsinn, Wein und Glück.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 3, 3, 'Und ich sehne mich');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 3, 4, 'Mein Leben lang zurück');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ich-hab-mein-herz-in-heidelberg-verloren', 3, 3, 3, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('im-tiefen-keller', 'IM TIEFEN KELLER', 'IM TIEFEN KELLER', 'duitstalige-liederen', 'de', NULL, 437, 437, 'Karl Müchler, 1802', 'Ludwig Fischer, 1802', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('im-tiefen-keller', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 0, 0, 'Im tiefen Keller sitz’ ich hier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 0, 1, 'Bei einem Fass voll Reben');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 0, 2, 'Bin frohen Muts und lasse mir');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 0, 3, 'Vom allerbesten geben,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 0, 4, 'Der Küfer zieht den Heber vor,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 0, 5, 'Gehorsam meinem Winke,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 0, 6, 'Reicht mir das Glas, ich halt’s empor');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 0, 7, 'Und trinke, trinke, trinke, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('im-tiefen-keller', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 1, 0, 'Mich plagt ein Dämon, Durst genannt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 1, 1, 'Doch um ihn zu verscheuchen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 1, 2, 'Nehm’ ich mein Deckelglas zur Hand,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 1, 3, 'Und lass mir Rheinwein reichen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 1, 4, 'Die ganze Welt erscheint mir nun');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 1, 5, 'Im rosenroter Schminke,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 1, 6, 'Ich könnte niemand Leides tun,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 1, 7, 'Und trinke, trinke, trinke, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('im-tiefen-keller', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 2, 0, 'Allein mein Durst vermehrt sich nur,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 2, 1, 'Bei jedem vollen Becher,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 2, 2, 'Das ist die leidige Natur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 2, 3, 'Der echten Rheinweinzecher!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 2, 4, 'Doch tröst’ ich mich, wenn ich zuletzt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 2, 5, 'Vom Fass zu Boden sinke,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 2, 6, 'Ich hab’ keine Pflicht verletzt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('im-tiefen-keller', 2, 7, 'Ich trinke, trinke, trinke, ...');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('in-munchen-steht-ein-hofbrauhaus', 'IN MÜNCHEN STEHT EIN HOFBRÄUHAUS', 'IN MÜNCHEN STEHT EIN HOFBRÄUHAUS', 'duitstalige-liederen', 'de', NULL, 438, 438, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('in-munchen-steht-ein-hofbrauhaus', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 0, 0, 'Da wo die grüne Isar fließt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 0, 1, 'Wo man mit ”Grüß Gott” dich grüßt;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 0, 2, 'Liegt meine schöne Münchnerstadt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 0, 3, 'Die ihres gleichen nicht hat.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 0, 4, 'Wasser ist billig, rein und gut,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 0, 5, 'Nur verdünnt es unsres Blut!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 0, 6, 'Schöner sind Tropfen goldnen Wein’s!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 0, 7, 'Aber am schönsten ist eins!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('in-munchen-steht-ein-hofbrauhaus', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 1, 0, 'In München steht ein Hofbräuhaus');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 1, 1, 'Eins, zwei, suffa;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 1, 2, 'Da läuft so manches Fässchen aus');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 1, 3, 'Eins, zwei, suffa;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 1, 4, 'Da hat so mancher brave Mann');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 1, 5, 'Eins, zwei, suffa;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 1, 6, 'Gezeigt was er schon vertragen kann.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 1, 7, 'Schon früh am Morgen fing er an,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 1, 8, 'Und spät am Abend kam er heraus');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 1, 9, 'So schön ist’s im Hofbräuhaus.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('in-munchen-steht-ein-hofbrauhaus', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 2, 0, 'Da trinkt man Bier nicht aus dem Glas');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 2, 1, 'Da gibt’s nur die große Maß');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 2, 2, 'Und wenn die erste Maß ist leer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 2, 3, 'Dann bringt dir die Resl bald mehr,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 2, 4, 'Dann kriegt zu Haus die Frau’en Schreck,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 2, 5, 'Bleibt der Mann noch lange weg');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 2, 6, 'Aber die braven Nachbarleut’,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('in-munchen-steht-ein-hofbrauhaus', 2, 7, 'Die wissen besser Bescheid.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('kurfurst-friedrich-von-der-pfalz', 'KURFÜRST FRIEDRICH VON DER PFALZ', 'KURFÜRST FRIEDRICH VON DER PFALZ', 'duitstalige-liederen', 'de', NULL, 439, 440, 'August Schuster, 1887', 'Karl Friedrich August Hering, 1887', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('kurfurst-friedrich-von-der-pfalz', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 0, 0, 'Wütend wälzt sich einst im Bette');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 0, 1, 'Kurfürst Friedrich von der Pfalz;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 0, 2, 'Gegen alle Etikette');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 0, 3, 'Brüllte er aus vollem Hals:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 0, 4, '“Wie kam gestern ich ins Nest?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 0, 5, 'Bin scheint’s wieder voll gewest!”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('kurfurst-friedrich-von-der-pfalz', 0, 4, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('kurfurst-friedrich-von-der-pfalz', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 1, 0, 'Na, ein wenig schief geladen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 1, 1, 'Grinste d’rauf der Kammermohr,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 1, 2, 'Selbst von Mainz des Bischofs G’naden');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 1, 3, 'Kamen mir benebelt vor,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 1, 4, 'War halt doch ein schönes Fest,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 1, 5, 'Alles wieder voll gewest!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('kurfurst-friedrich-von-der-pfalz', 1, 4, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('kurfurst-friedrich-von-der-pfalz', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 2, 0, 'So? Du findest das zum Lachen?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 2, 1, 'Sklavenseele, lache nur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 2, 2, 'Künftig werd ich’s anders machen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 2, 3, 'Hassan, höre meine Schwur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 2, 4, '’s Letzte Mal, bei Tod und Pest,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 2, 5, 'War es, dass ich voll gewest!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('kurfurst-friedrich-von-der-pfalz', 2, 4, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('kurfurst-friedrich-von-der-pfalz', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 3, 0, 'Will ein sportlich’ Leben führen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 3, 1, 'Ganz mich der Gesundheit weihn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 3, 2, 'Um mein Tun zu kontrollieren');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 3, 3, 'Trag’ich’s in ein Tagebuch ein,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 3, 4, 'Und ich hoff, dass ihr nicht lest,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 3, 5, 'Dass ich wieder voll gewest!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('kurfurst-friedrich-von-der-pfalz', 3, 4, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('kurfurst-friedrich-von-der-pfalz', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 4, 0, 'Als der Kurfürst kam zu sterben,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 4, 1, 'Machte er sein Testament,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 4, 2, 'Und es fanden seine Erben');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 4, 3, 'Auch ein Buch in Pergament,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 4, 4, 'Drinnen stand auf jeder Seit:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 4, 5, '“Seid vernünftig, liebe Leut,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 4, 6, 'Dieses geb ich zu Attest:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 4, 7, 'Heute wieder voll gewest!”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('kurfurst-friedrich-von-der-pfalz', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 5, 0, 'Hieraus mag nun jeder sehen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 5, 1, 'Was ein guter Vorsatz nützt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 5, 2, 'Und wozu auch widerstehen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 5, 3, 'Wenn der volle Becher blitzt?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 5, 4, 'Drum stoßt an! Probatum est:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kurfurst-friedrich-von-der-pfalz', 5, 5, 'Heute wieder voll gewest!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('kurfurst-friedrich-von-der-pfalz', 5, 4, 5, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('lili-marleen', 'LILI MARLEEN', 'LILI MARLEEN', 'duitstalige-liederen', 'de', NULL, 440, 441, 'Hans Leip, 1915', 'Norbert Schultze, 1937', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lili-marleen', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 0, 0, 'Vor der Kaserne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 0, 1, 'Vor dem großen Tor,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 0, 2, 'Stand eine Laterne,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 0, 3, 'Und steht sie noch davor,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 0, 4, 'So woll’n wir uns wiederseh’n,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 0, 5, 'Bei der Laterne woll’n wir steh’n');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 0, 6, 'Wie einst Lili Marleen.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('lili-marleen', 0, 6, 6, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lili-marleen', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 1, 0, 'Uns’re beiden Schatten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 1, 1, 'Seh’n wie einer aus.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 1, 2, 'Dass wir so lieb uns hatten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 1, 3, 'Das sah man gleich daraus.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 1, 4, 'Und alle Leute soll’n es seh’n,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 1, 5, 'Wenn wir bei der Laterne steh’n');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 1, 6, 'Wie einst Lili Marleen.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('lili-marleen', 1, 6, 6, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lili-marleen', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 2, 0, 'Schon rief der Posten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 2, 1, 'Sie blasen Zapfenstreich,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 2, 2, 'Es kann drei Tage kosten.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 2, 3, 'Kam’rad ich komm’ sogleich!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 2, 4, 'Da sagten wir auf Wiedersehn.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 2, 5, 'Wie gerne wollt’ich mit dir geh’n,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 2, 6, 'Mit dir, Lili Marleen.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('lili-marleen', 2, 6, 6, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lili-marleen', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 3, 0, 'Deine Schritte kennt sie,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 3, 1, 'Deinen zarten Gang,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 3, 2, 'Alle Abend brennt sie,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 3, 3, 'Doch mich vergaß sie lang.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 3, 4, 'Und sollte mir ein Leid gescheh’n,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 3, 5, 'Wer wird bei der Laterne steh’n,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 3, 6, 'Mit dir, Lili Marleen?');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('lili-marleen', 3, 6, 6, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lili-marleen', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 4, 0, 'Aus dem stillen Raume,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 4, 1, 'Aus der Erde Grund');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 4, 2, 'Hebt mich wie im Traume');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 4, 3, 'Dein verliebter Mund.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 4, 4, 'Wenn sich die späten Nebel dreh’n');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 4, 5, 'Werd’ ich bei der Laterne steh’n');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lili-marleen', 4, 6, 'Wie einst Lili Marleen.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('lili-marleen', 4, 6, 6, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('die-lore', 'DIE LORE', 'LORE, DIE', 'duitstalige-liederen', 'de', NULL, 442, 442, 'Heinrich C. Boie, 1797', 'rond 1840', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-lore', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 0, 0, 'Im Wald; im grünen Walde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 0, 1, 'Da steht ein Försterhaus');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 0, 2, 'Da schauet jeden Morgen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 0, 3, 'So frisch und frei von Sorgen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 0, 4, 'Des Försters Töchterlein hinaus');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('die-lore', 0, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('die-lore', 0, 4, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-lore', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 1, 0, 'Tiralala, tiralala,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 1, 1, 'Tira, tira, tiralala lala');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 1, 2, 'Lore, Lore, Lore, Lore,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 1, 3, 'Schön sind die Mädchen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 1, 4, 'Von siebzehn, achtzehn Jahr,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 1, 5, 'Lore, Lore, Lore, Lore,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 1, 6, 'Schöne Mädel gibt es überall');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 1, 7, 'Und kommt der Frühling in das Tal;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 1, 8, 'Grüßt mir die Lore noch einmal.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 1, 9, 'Ade; ade; ade.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 1, 10, 'Ade; ade; ade.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('die-lore', 1, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('die-lore', 1, 7, 9, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-lore', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 2, 0, 'Der Förster und die Tochter;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 2, 1, 'Die schossen beide gut;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 2, 2, 'Der Förster schoss ein Hirschelein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 2, 3, 'Die Tochter traf ein Bürschelein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 2, 4, 'Tief in das junge Herz hinein.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('die-lore', 2, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('die-lore', 2, 4, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-lore', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 3, 0, 'Steh’ich auf Bergeshöhen;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 3, 1, 'Schau in die Täler hin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 3, 2, 'Dann sehe ich so gerne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 3, 3, 'Aus weiter, weiter Ferne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-lore', 3, 4, 'Das Haus der jungen Försterin.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('die-lore', 3, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('die-lore', 3, 4, 4, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('lustig-ist-das-zigeunerleben', 'LUSTIG IST DAS ZIGEUNERLEBEN', 'LUSTIG IST DAS ZIGEUNERLEBEN', 'duitstalige-liederen', 'de', NULL, 443, 443, NULL, NULL, 'Volkslied uit Niederschlesien, 1842');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lustig-ist-das-zigeunerleben', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lustig-ist-das-zigeunerleben', 0, 0, 'Lustig ist das Zigeunerleben,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lustig-ist-das-zigeunerleben', 0, 1, 'Faria, faria');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lustig-ist-das-zigeunerleben', 0, 2, 'Brauch’n dem Kaiser kein’n Zins zu geben');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lustig-ist-das-zigeunerleben', 0, 3, 'Faria, faria');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lustig-ist-das-zigeunerleben', 0, 4, 'Lustig ist es im grünen Wald');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lustig-ist-das-zigeunerleben', 0, 5, 'Wo des Zigeuners Aufenthalt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lustig-ist-das-zigeunerleben', 0, 6, 'Faria, faria, faria, faria, faria, faria');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lustig-ist-das-zigeunerleben', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lustig-ist-das-zigeunerleben', 1, 0, 'Sollt’ uns einmal der Hunger plagen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lustig-ist-das-zigeunerleben', 1, 1, 'Faria, faria');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lustig-ist-das-zigeunerleben', 1, 2, 'Geh’n wir uns ein Häschen jagen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lustig-ist-das-zigeunerleben', 1, 3, 'Faria, faria');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lustig-ist-das-zigeunerleben', 1, 4, 'Häschen, nimm dich wohl in Acht');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lustig-ist-das-zigeunerleben', 1, 5, 'Wenn des Jägers Büchse kracht');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lustig-ist-das-zigeunerleben', 1, 6, 'Faria, faria, faria, faria, faria, faria');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('lustig-ist-das-zigeunerleben', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lustig-ist-das-zigeunerleben', 2, 0, 'Sollt’ uns einmal der Durst sehr quälen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lustig-ist-das-zigeunerleben', 2, 1, 'Faria, faria');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lustig-ist-das-zigeunerleben', 2, 2, 'Geh’n wir hin zu Wasserquellen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lustig-ist-das-zigeunerleben', 2, 3, 'Faria, faria');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lustig-ist-das-zigeunerleben', 2, 4, 'Trinken Wasser wie kühlen Wein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lustig-ist-das-zigeunerleben', 2, 5, 'Denken, es wäre Champagnerwein,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('lustig-ist-das-zigeunerleben', 2, 6, 'Faria, faria, faria, faria, faria, faria');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('die-moorsoldaten', 'DIE MOORSOLDATEN', 'MOORSOLDATEN, DIE', 'duitstalige-liederen', 'de', NULL, 444, 445, 'Johann Esser, Wolfgang Langhoff', 'Rudi Goguel', 'Uit het concentratiekamp Papenburg te Börgermoor, 1933');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-moorsoldaten', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 0, 0, 'Wohin auch das Auge blicket');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 0, 1, 'Moor und Heide nur ringsum');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 0, 2, 'Vogelsang uns nicht erquicket');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 0, 3, 'Eichen stehn kahl und krumm');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-moorsoldaten', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 1, 0, 'Wir sind die Moorsoldaten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 1, 1, 'Und ziehen mit dem Spaten ins Moor!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('die-moorsoldaten', 1, 0, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-moorsoldaten', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 2, 0, 'Hier in dieser öden Heide');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 2, 1, 'Ist das Lager aufgebaut');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 2, 2, 'Wo wir fern von jeder Freude');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 2, 3, 'hinter Stacheldraht verstaut');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-moorsoldaten', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 3, 0, 'Morgens ziehen die Kolonnen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 3, 1, 'In das Moor zur Arbeit hin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 3, 2, 'Graben bei dem Brand der Sonne');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 3, 3, 'Doch zur Heimat steht der Sinn');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-moorsoldaten', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 4, 0, 'Heimwärts, heimwärts! Jeder sehnet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 4, 1, 'Sich nach Eltern, Weib und Kind');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 4, 2, 'Manche Brust ein Seufzer dehnet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 4, 3, 'Weil wir hier gefangen sind');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-moorsoldaten', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 5, 0, 'Auf und nieder geh’n die Posten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 5, 1, 'Keiner, keiner kann hindurch');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 5, 2, 'Flucht wird nur das Leben kosten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 5, 3, 'Vierfach ist umzäunt die Burg');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-moorsoldaten', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 6, 0, 'Doch für uns gibt es kein Klagen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 6, 1, 'Ewig kann’s nicht Winter sein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 6, 2, 'Einmal werden froh wir sagen:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 6, 3, 'Heimat, Du bist wieder mein!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-moorsoldaten', 7, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 7, 0, 'Dann ziehn die Moorsoldaten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-moorsoldaten', 7, 1, 'Nicht mehr mit dem Spaten in’s Moor!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('die-moorsoldaten', 7, 0, 1, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('o-alte-burschenherlichkeit', 'O ALTE BURSCHENHERLICHKEIT', 'O ALTE BURSCHENHERLICHKEIT', 'duitstalige-liederen', 'de', NULL, 446, 447, 'Eugen Höfling, Berlijn, 9 augustus 1825', 'Uit het studentenlied: ‘Was fang ich armer Teufel an’, in G. Brauns ‘Liederbuch für Studenten’ uit 1843', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('o-alte-burschenherlichkeit', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 0, 0, 'O alte Burschenherlichkeit!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 0, 1, 'Wohin bist du verschwinden?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 0, 2, 'Nie kehrst du wieder, gold’ne Zeit,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 0, 3, 'So froh und ungebunden!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 0, 4, 'Vergebens spähe ich umher,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 0, 5, 'Ich finde deine Spur nicht mehr.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 0, 6, 'O jerum, jerum, jerum, o quae mutatio rerum!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('o-alte-burschenherlichkeit', 0, 6, 6, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('o-alte-burschenherlichkeit', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 1, 0, 'Den Burschenhut bedeckt der Staub,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 1, 1, 'Es sank der Flaus in Trümmer.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 1, 2, 'Der Schläger war des Rostes Raub,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 1, 3, 'Erblichen ist sein Schimmer.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 1, 4, 'Verklungen der Kommersgesang,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 1, 5, 'Verhallt Rapier- und Sporenklang.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 1, 6, 'O jerum, jerum, jerum, o quae mutatio rerum!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('o-alte-burschenherlichkeit', 1, 6, 6, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('o-alte-burschenherlichkeit', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 2, 0, 'Wo sind sie, die vom breiten Stein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 2, 1, 'Nicht wankten und nicht wichen?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 2, 2, 'Die ohne Spieß bei Scherz und Wein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 2, 3, 'Den Herrn der Erde glichen.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 2, 4, 'Sie zogen mit gesenktem Blick');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 2, 5, 'In das Philisterland zurück');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 2, 6, 'O jerum, jerum, jerum, o quae mutatio rerum!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('o-alte-burschenherlichkeit', 2, 6, 6, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('o-alte-burschenherlichkeit', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 3, 0, 'Da schreibt mit finsterm Amtsgesicht');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 3, 1, 'Der eine Relationen.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 3, 2, 'Der and’re seufzt beim Unterricht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 3, 3, 'Und der macht Rezensionen.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 3, 4, 'Der schilt die sünd’ge Seele aus,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 3, 5, 'Und der flickt ihr verfall’nes Haus.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 3, 6, 'O jerum, jerum, jerum, o quae mutatio rerum!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('o-alte-burschenherlichkeit', 3, 6, 6, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('o-alte-burschenherlichkeit', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 4, 0, 'Allein, das rechte Burschenherz');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 4, 1, 'Kann nimmermehr erkalten.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 4, 2, 'Im Ernste wird wie hier im Scherz,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 4, 3, 'Der rechte Sinn stets walten.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 4, 4, 'Die alte Schale nur ist fern,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 4, 5, 'Geblieben ist uns doch der Kern.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 4, 6, 'Und den lasst fest uns halten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 4, 7, 'wir bleiben stets die Alten!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('o-alte-burschenherlichkeit', 4, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('o-alte-burschenherlichkeit', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 5, 0, 'Drum, Freunde! Reichet euch die Hand,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 5, 1, 'Damit es sich erneue,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 5, 2, 'Der alten Freundschaft heilges Band,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 5, 3, 'Das alte Band der Treue.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 5, 4, 'Klingt an und hebt die Gläser hoch,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 5, 5, 'Die alten Burschen leben noch!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('o-alte-burschenherlichkeit', 5, 6, 'Es lebt die alte Treue! Es lebt die alte Treue!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('o-alte-burschenherlichkeit', 5, 6, 6, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('der-pappenheimer', 'DER PAPPENHEIMER', 'PAPPENHEIMER, DER', 'duitstalige-liederen', 'de', NULL, 448, 448, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('der-pappenheimer', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-pappenheimer', 0, 0, 'Wir trinken einen Halben, einen Halben in der Welt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-pappenheimer', 0, 1, 'Warum sollten wir nicht trinken einen Halben');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-pappenheimer', 0, 2, 'Einen Halben in der Welt?');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('der-pappenheimer', 0, 0, 0, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('der-pappenheimer', 0, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('der-pappenheimer', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-pappenheimer', 1, 0, 'General Pappenheimer der soll leben');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-pappenheimer', 1, 1, 'General Pappenheimer der lebe hoch');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-pappenheimer', 1, 2, 'Bei Wein und bei Bier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-pappenheimer', 1, 3, 'Lustige Pappenheimer sind wir hier;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-pappenheimer', 1, 4, 'Bei Bier und bei Wein,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-pappenheimer', 1, 5, 'Lustige Pappenheimer wollen wir sein.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('der-pappenheimer', 1, 0, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('der-pappenheimer', 2, 'direction', 1, 'Bij “General Pappenheimer ... Der lebe hoch” groeten de leden van de corona links en rechts op militaire wijze. Volgende strofen van dit lied worden gemaakt door:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('der-pappenheimer', 3, 'direction', 1, '“... in der Welt” te vervangen door:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('der-pappenheimer', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-pappenheimer', 4, 0, '“... auf dem Stuhl”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-pappenheimer', 4, 1, '“... auf dem Tisch”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('der-pappenheimer', 4, 2, '“... unterm Tisch”');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('das-polenkind', 'DAS POLENKIND', 'POLENKIND, DAS', 'duitstalige-liederen', 'de', NULL, 449, 449, NULL, NULL, 'Volkslied uit Pommern');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('das-polenkind', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 0, 0, 'In einem Polenstädtchen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 0, 1, 'Da wohnte einst ein Mädchen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 0, 2, 'Sie war so schön!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 0, 3, 'Sie war das allerschönste Kind,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 0, 4, 'Das man in Polen find’t.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('das-polenkind', 0, 2, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('das-polenkind', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 1, 0, 'Aber nein, aber nein sprach sie,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 1, 1, 'Ich küsse nie!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('das-polenkind', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 2, 0, 'Ich führte sie zum Tanze,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 2, 1, 'Da fiel aus ihrem Kranze,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 2, 2, 'Ein Röslein rot,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 2, 3, 'Ich hob es auf von Ihrem Fuß');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 2, 4, 'Und bat um einen Kuss.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('das-polenkind', 2, 2, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('das-polenkind', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 3, 0, 'Und war der Tanz zu Ende,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 3, 1, 'Wir reichten uns die Hände,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 3, 2, 'Zum letzten Mal.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 3, 3, 'Sie lag in meinem, meinem Arm');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 3, 4, 'Mir schlug das Herz so warm.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('das-polenkind', 3, 2, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('das-polenkind', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 4, 0, 'Doch in den Abschiedsstunden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 4, 1, 'Da fiel aus Ihrem Munde,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 4, 2, 'Ein einziges Wort:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 4, 3, '”So nimmst du, Dussel-Dusseltier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 4, 4, 'Den ersten Kuss von mir,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('das-polenkind', 4, 5, 'Vergiss Maruschka nicht, das Polenkind”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('das-polenkind', 4, 2, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('das-polenkind', 5, 'direction', 1, 'Na de laatste strofe geen refrein meer!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ein-prosit', 'EIN PROSIT', 'PROSIT, EIN', 'duitstalige-liederen', 'de', NULL, 450, 450, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ein-prosit', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-prosit', 0, 0, 'Ein Prosit, ein Prosit,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-prosit', 0, 1, 'Der Gemütlichkeit!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-prosit', 0, 2, 'Ein Prosit, ein Prosit,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-prosit', 0, 3, 'Der Gemütlichkeit!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-prosit', 0, 4, 'Eins, Zwei, Saufen!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('roslein-auf-der-heiden', 'RÖSLEIN AUF DER HEIDEN', 'RÖSLEIN AUF DER HEIDEN', 'duitstalige-liederen', 'de', NULL, 450, 450, 'Johann Wolfgang Goethe, 1771', 'H.Werner, 1829', 'Uit “36 ausgewählte Lieder”, B. Schotts Söhne, Mainz');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('roslein-auf-der-heiden', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roslein-auf-der-heiden', 0, 0, 'Sah ein Knab ein Röslein steh’n,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roslein-auf-der-heiden', 0, 1, 'Röslein auf der Heiden:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roslein-auf-der-heiden', 0, 2, 'War so jung und morgenschön,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roslein-auf-der-heiden', 0, 3, 'Lief er schnell, es nah zu seh’n,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roslein-auf-der-heiden', 0, 4, 'Sah’s mit vielen Freuden.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('roslein-auf-der-heiden', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roslein-auf-der-heiden', 1, 0, 'Röslein, Röslein, Röslein rot,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roslein-auf-der-heiden', 1, 1, 'Röslein auf der Heiden.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('roslein-auf-der-heiden', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roslein-auf-der-heiden', 2, 0, 'Knabe sprach: “Ich breche dich,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roslein-auf-der-heiden', 2, 1, 'Röslein auf der Heiden!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roslein-auf-der-heiden', 2, 2, 'Röslein sprach: “Ich steche dich,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roslein-auf-der-heiden', 2, 3, 'Dass du ewig denkst an mich,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roslein-auf-der-heiden', 2, 4, 'Und ich will’s nicht leiden.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('roslein-auf-der-heiden', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roslein-auf-der-heiden', 3, 0, 'Und der wilde Knabe brach');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roslein-auf-der-heiden', 3, 1, '’s Röslein auf der Heiden!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roslein-auf-der-heiden', 3, 2, 'Röslein wehrte sich und stach,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roslein-auf-der-heiden', 3, 3, 'Half ihr doch kein Weh und Ach,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roslein-auf-der-heiden', 3, 4, 'Musst’es eben leiden.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('rote-husaren', 'ROTE HUSAREN', 'ROTE HUSAREN', 'duitstalige-liederen', 'de', NULL, 451, 451, 'Hermann Löns, 1924', 'Otto Koch', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('rote-husaren', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rote-husaren', 0, 0, 'Heiß ist die Liebe,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rote-husaren', 0, 1, 'Kalt ist der Schnee, ja Schnee,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rote-husaren', 0, 2, 'Scheiden und meiden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rote-husaren', 0, 3, 'Ja das tut weh.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('rote-husaren', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rote-husaren', 1, 0, 'Rote Husaren, die reiten,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rote-husaren', 1, 1, 'Reiten, reiten niemals Schritt.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rote-husaren', 1, 2, 'Herzliebstes Mädel, und du,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rote-husaren', 1, 3, 'Du kannst nicht mit.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('rote-husaren', 1, 0, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('rote-husaren', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rote-husaren', 2, 0, 'Weiß ist die Feder,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rote-husaren', 2, 1, 'An meinem Hut, ja Hut');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rote-husaren', 2, 2, 'Schwarz ist das Pulver,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rote-husaren', 2, 3, 'Und rot das Blut.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('rote-husaren', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rote-husaren', 3, 0, 'Das grüne Gräslein,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rote-husaren', 3, 1, 'Zersprang in meiner Hand,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rote-husaren', 3, 2, 'Brüder, ich sterbe,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rote-husaren', 3, 3, 'Fürs Vaterland.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('rote-husaren', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rote-husaren', 4, 0, 'Auf meinem Grabe,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rote-husaren', 4, 1, 'Sollen rote Rosen steh’n,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rote-husaren', 4, 2, 'Die rote Rosen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('rote-husaren', 4, 3, 'Ja die sind schön.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('ein-schifflein-sah-ich-fahren', 'EIN SCHIFFLEIN SAH ICH FAHREN', 'SCHIFFLEIN SAH ICH FAHREN, EIN', 'duitstalige-liederen', 'de', NULL, 452, 453, NULL, NULL, 'Duitse Volkswijze, 1781');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ein-schifflein-sah-ich-fahren', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 0, 0, 'Ein Schifflein sah ich fahren,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 0, 1, 'Kapitän und Leutenant;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 0, 2, 'Darinnen waren geladen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 0, 3, 'Zwei brave Kompanien Soldaten.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ein-schifflein-sah-ich-fahren', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 1, 0, 'Kapitän, Leutenant, Fähndrich, Sergeant,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 1, 1, 'Nimm das Mädel, nimm das Mädel bei der Hand,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 1, 2, 'Soldaten, Kameraden, nimm das Mädel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 1, 3, 'Nimm das Mädel bei der Hand.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('ein-schifflein-sah-ich-fahren', 1, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ein-schifflein-sah-ich-fahren', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 2, 0, 'Was sollen die Soldaten essen?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 2, 1, 'Kapitän und Leutenant;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 2, 2, 'Gebratene Fisch mit Kressen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 2, 3, 'Das sollen die Soldaten essen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ein-schifflein-sah-ich-fahren', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 3, 0, 'Was sollen die Soldaten trinken?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 3, 1, 'Kapitän und Leutenant;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 3, 2, 'Den besten Wein, der zu finden,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 3, 3, 'Den sollen die Soldaten trinken.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ein-schifflein-sah-ich-fahren', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 4, 0, 'Wo sollen die Soldaten schlafen?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 4, 1, 'Kapitän und Leutenant;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 4, 2, 'Bei ihren Gewehr’ und Waffen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 4, 3, 'Da müssen die Soldaten schlafen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ein-schifflein-sah-ich-fahren', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 5, 0, 'Wo sollen die Soldaten tanzen?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 5, 1, 'Kapitän und Leutenant;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 5, 2, 'Vor Harburg auf der Schanzen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 5, 3, 'Da müssen die Soldaten tanzen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ein-schifflein-sah-ich-fahren', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 6, 0, 'Wie kommen die Soldaten in den Himmel?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 6, 1, 'Kapitän und Leutenant;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 6, 2, 'Auf einem weißen Schimmel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 6, 3, 'Da reiten die Soldaten in den Himmel.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('ein-schifflein-sah-ich-fahren', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 7, 0, 'Wie komm’n die Offiziers in die Höllen?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 7, 1, 'Kapitän und Leutenant;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 7, 2, 'Auf einem schwarzen Fohlen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('ein-schifflein-sah-ich-fahren', 7, 3, 'Da wird sie der Teufel schon holen.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('schwarzbraun-ist-die-haselnuss', 'SCHWARZBRAUN IST DIE HASELNUSS', 'SCHWARZBRAUN IST DIE HASELNUSS', 'duitstalige-liederen', 'de', NULL, 453, 454, NULL, NULL, 'Uit Salzburg');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('schwarzbraun-ist-die-haselnuss', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schwarzbraun-ist-die-haselnuss', 0, 0, 'Schwarzbraun ist die Haselnuss,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schwarzbraun-ist-die-haselnuss', 0, 1, 'Schwarzbraun bin auch ich, ja ich.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schwarzbraun-ist-die-haselnuss', 0, 2, 'Schwarzbraun muss mein Mädel sein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schwarzbraun-ist-die-haselnuss', 0, 3, 'Gerade so wie ich.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('schwarzbraun-ist-die-haselnuss', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schwarzbraun-ist-die-haselnuss', 1, 0, 'Holdrio juvivalle ra, hahaha!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schwarzbraun-ist-die-haselnuss', 1, 1, 'Holdrio juvivalle ra!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('schwarzbraun-ist-die-haselnuss', 1, 0, 0, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('schwarzbraun-ist-die-haselnuss', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schwarzbraun-ist-die-haselnuss', 2, 0, 'Mädel, hat mir Busserl’ geb’n,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schwarzbraun-ist-die-haselnuss', 2, 1, 'Hat mir schwer gekränkt, ja kränkt.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schwarzbraun-ist-die-haselnuss', 2, 2, 'Hab ich ’s ihr gleich wiedergeb’n');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schwarzbraun-ist-die-haselnuss', 2, 3, 'Ich nehm ja nichts geschenkt.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('schwarzbraun-ist-die-haselnuss', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schwarzbraun-ist-die-haselnuss', 3, 0, 'Mädel hat nicht Hof noch Haus,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schwarzbraun-ist-die-haselnuss', 3, 1, 'Mädel hat kein Geld, ja Geld.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schwarzbraun-ist-die-haselnuss', 3, 2, 'Doch ich geb es nicht heraus');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schwarzbraun-ist-die-haselnuss', 3, 3, 'Für alles in der Welt.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('schwarzbraun-ist-die-haselnuss', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schwarzbraun-ist-die-haselnuss', 4, 0, 'Schwarzbraun ist die Haselnuss,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schwarzbraun-ist-die-haselnuss', 4, 1, 'Schwarzbraun bin auch ich, ja ich.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schwarzbraun-ist-die-haselnuss', 4, 2, 'Wenn ich eine heiraten tu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('schwarzbraun-ist-die-haselnuss', 4, 3, 'So muss sie sein wie ich.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('eine-seefahrt', 'EINE SEEFAHRT', 'SEEFAHRT, EINE', 'duitstalige-liederen', 'de', NULL, 454, 455, NULL, NULL, 'Duits studentenlied');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('eine-seefahrt', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 0, 0, 'Eine Seefahrt die ist lustig');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 0, 1, 'Eine Seefahrt die ist schön,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 0, 2, 'Ja, da kann man was erleben');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 0, 3, 'Ja, da kann man etwas sehen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('eine-seefahrt', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 1, 0, 'Hollahi ... hollaho');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 1, 1, 'Hollahia hia hia, hollahia hia ho');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 1, 2, 'Hollahi ... hollaho');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 1, 3, 'Hollahia hia hia, hollaho!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('eine-seefahrt', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 2, 0, 'Einen schrecklich langen Bartsack');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 2, 1, 'Den hat unser Kapitän');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 2, 2, 'Raucht davor auch starken Tabak');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 2, 3, 'Das man gar nichts mehr kann seh’n.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('eine-seefahrt', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 3, 0, 'Und der erste Offizier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 3, 1, 'Ist besoffen wie ein Stier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 3, 2, 'Und der zweite Offizier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 3, 3, 'Trinkt noch immer so viel Bier.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('eine-seefahrt', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 4, 0, 'Und der Koch in der Kambüse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 4, 1, 'Diese gottverdammte Sau,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 4, 2, 'Dauernd spuckt er ins Gemüse');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 4, 3, 'Manchmal auch in den Kakau.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('eine-seefahrt', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 5, 0, 'Eine Tonne Öl genommen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 5, 1, 'Drin ein kleiner Pinsel ist,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 5, 2, 'Und ’ne riesengroße Schnauze');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 5, 3, 'Fertig ist der Maschinist.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('eine-seefahrt', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 6, 0, 'Steh nur auf, du faules Luder,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 6, 1, 'Steh nur auf, du faules Schwein,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 6, 2, 'Kohlen willst du kleine trimmen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 6, 3, 'Aber Heizer willst du sein.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('eine-seefahrt', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 7, 0, 'Und er haut ihn vor den Dassel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 7, 1, 'Dass er an die Reling fällt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 7, 2, 'Und die heil’gen zwölf Apostel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 7, 3, 'Für ’ne Rauberbande hält.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('eine-seefahrt', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 8, 0, 'Und die schönen weißen Möwen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 8, 1, 'Sie erfüllen ihren Zweck,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 8, 2, 'Und sie scheißen, scheißen, scheißen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 8, 3, 'Auf das frischgewasch’ne Deck.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('eine-seefahrt', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 9, 0, 'In der Heimat angekommen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 9, 1, 'Fängt ein neues Leben an,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 9, 2, 'Eine Frau wird sich genommen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('eine-seefahrt', 9, 3, 'Kinder bringt der Weihnachtsmann.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('studio-auf-einer-reis', 'STUDIO AUF EINER REIS’', 'STUDIO AUF EINER REIS’', 'duitstalige-liederen', 'de', NULL, 456, 457, NULL, NULL, 'Carl Maria Weber, Richard Schäffer, 1845');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('studio-auf-einer-reis', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 0, 0, 'Studio auf einer Reis’,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 0, 1, 'Juchheidi, juchheida,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 0, 2, 'Ganz famos zu leben weiß,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 0, 3, 'Juchheidi, heida!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 0, 4, 'Immerfort durch Dick und Dünn');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 0, 5, 'Schlendert er durch’s Dasein hin.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('studio-auf-einer-reis', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 1, 0, 'Juchheidi, heidi, heida, juchheidi, juchheida!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 1, 1, 'Juchheidi, heidi, heida, juchheidi, heida!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('studio-auf-einer-reis', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 2, 0, 'Hat der Studio auch kein Geld,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 2, 1, 'Juchheidi, juchheida,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 2, 2, 'Ist er drum nicht schlecht bestellt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 2, 3, 'Juchheidi, heida!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 2, 4, 'Manches feiste Pfäffelein,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 2, 5, 'Ladet ihn zum Frühstück ein');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('studio-auf-einer-reis', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 3, 0, 'Kehren wir in ’s Wirtshaus ein,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 3, 1, 'Juchheidi, juchheida,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 3, 2, 'Trinken wir stets Bier und Wein.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 3, 3, 'Juchheidi, heida!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 3, 4, 'Alle Mädel für uns glühn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 3, 5, 'Denn wir tragen schwartz-gold-grün');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('studio-auf-einer-reis', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 4, 0, 'Bayrisch Bier und Leberwurst,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 4, 1, 'Juchheidi, juchheida,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 4, 2, 'Und ein Kind mit runder Brust,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 4, 3, 'Juchheidi, heida!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 4, 4, 'Und ein Glas Krambambuli,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 4, 5, 'Donnerwetter Paraplui!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('studio-auf-einer-reis', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 5, 0, 'Und so geht es lustig fort,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 5, 1, 'Juchheidi, juchheida,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 5, 2, 'Lustig hier und lustig dort.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 5, 3, 'Juchheidi, juchheida!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 5, 4, 'Manches Mädel sieht uns nach,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studio-auf-einer-reis', 5, 5, 'Seufzt dabei ein stilles “Ach!”');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('trink-trink-bruderlein-trink', 'TRINK, TRINK, BRÜDERLEIN, TRINK', 'TRINK, TRINK, BRÜDERLEIN, TRINK', 'duitstalige-liederen', 'de', NULL, 457, 458, 'P. Raasch & C. Franck', 'Wilhelm Lindemann, 1927', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('trink-trink-bruderlein-trink', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 0, 0, 'Das Trinken das soll man nicht lassen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 0, 1, 'Das Trinken regiert doch die Welt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 0, 2, 'Man soll auch den Menschen nicht hassen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 0, 3, 'Der stets eine Lage bestellt,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 0, 4, 'Ob Bier oder Wein, ob Champagner,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 0, 5, 'Nur lasst uns beim Trinken nicht prahlen;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 0, 6, 'Es trank den Champagner schon mancher,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 0, 7, 'Und konnt ihn nachher nicht bezahlen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('trink-trink-bruderlein-trink', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 1, 0, 'Trink, trink, Brüderlein, trink!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 1, 1, 'Lass doch die Sorgen zu Haus!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 1, 2, 'Trink, trink, Brüderlein, trink!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 1, 3, 'Zieh doch die Stirn nicht zu graus.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 1, 4, 'Meide den Kummer und meide den Schmerz,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 1, 5, 'Dann ist das Leben ein Scherz.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('trink-trink-bruderlein-trink', 1, 4, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('trink-trink-bruderlein-trink', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 2, 0, 'Das Lieben, das Trinken, das Singen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 2, 1, 'Schafft Freude und fröhlichen Mut,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 2, 2, 'Den Frauen, den musst du eins bringen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 2, 3, 'Sie sind doch so lieb und so gut,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 2, 4, 'Verlieb dich so lange du jung bist,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 2, 5, 'Die Hauptsach’, du bist noch nicht blau,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 2, 6, 'Denn wenn man beim schönsten Trunk ist,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 2, 7, 'Bekommt man sehr leicht eine Frau.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('trink-trink-bruderlein-trink', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 3, 0, 'Der Moses, der hat, gar nicht übel,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 3, 1, 'Ein elftes Gebot noch erdacht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 3, 2, 'Das steht nicht in der Bibel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 3, 3, 'Und hat so viel Freude gemacht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 3, 4, 'Man hatte es uns unterschlagen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 3, 5, 'Weil Trinken und Saufen es preist;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 3, 6, 'Ich aber, ich darf es euch sagen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('trink-trink-bruderlein-trink', 3, 7, 'Ja wisst ihr denn auch wie es heißt?');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('tunke', 'TUNKE', 'TUNKE', 'duitstalige-liederen', 'de', NULL, 458, 459, NULL, NULL, 'Liederbuch für Studenten, Gustav Braun, 1843');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('tunke', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 0, 0, 'Die Stimme unsres Küsters');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 0, 1, 'Ist nur ein leis’ Geflüster');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 0, 2, 'Vor dem Trompetenschall');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 0, 3, 'Ja vor dem Schall (7×)');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 0, 4, 'Vor dem Trompeten ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 0, 5, 'Tunke, tunke, tunke, tunk, vivallalera');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 0, 6, 'Vor dem Trompetenschall, ja vor dem Schall!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('tunke', 0, 5, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('tunke', 1, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('tunke', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 2, 0, 'Viola, Bass und Geige');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 2, 1, 'Die müssen alle schweigen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 2, 2, 'Vor dem Trompetenschall!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('tunke', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 3, 0, 'Die Vöglein in dem Walde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 3, 1, 'Die schweigen also balde');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 3, 2, 'Vor dem Trompetenschall!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('tunke', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 4, 0, 'Leb’ wohl, mein kleines Städtchen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 4, 1, 'Leb’ wohl, schwarzbraunes Mädchen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 4, 2, 'Leb’ wohl und denk’ an mich,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 4, 3, 'Und denk’ an mich (7×)');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 4, 4, 'Leb’ wohl und denk’ an ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 4, 5, 'Tunke, tunke, tunke, tunk, vivallalera');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 4, 6, 'Leb’ wohl und denk’ an mich, ja denk’ an mich!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('tunke', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 5, 0, 'Mein Brüssel, du sollst leben,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 5, 1, 'Sollst reichen Stoff mir geben,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 5, 2, 'Du bist ein Bierkanal');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 5, 3, 'Ja Bierkanal (7×)');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 5, 4, 'Du bist ein Bierka- ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 5, 5, 'Tunke, tunke, tunke, tunk, vivallalera');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tunke', 5, 6, 'Du bist ein Bierkanal, ja Bierkanal!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('wenn-alle-untreu-werden', 'WENN ALLE UNTREU WERDEN', 'WENN ALLE UNTREU WERDEN', 'duitstalige-liederen', 'de', NULL, 460, 460, 'Max von Schenkendorf, 1814', 'gebaseerd op ‘Pour aller à la chasse faut être matineux’, 1724', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wenn-alle-untreu-werden', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wenn-alle-untreu-werden', 0, 0, 'Wenn alle untreu werden, so bleiben wir doch treu,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wenn-alle-untreu-werden', 0, 1, 'Daß immer noch auf Erden für euch ein Fähnlein sei.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wenn-alle-untreu-werden', 0, 2, 'Gefährten unsrer Jugend, ihr Bilder bess’rer Zeit,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wenn-alle-untreu-werden', 0, 3, 'Die uns zu Männertugend und Liebestod geweiht.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wenn-alle-untreu-werden', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wenn-alle-untreu-werden', 1, 0, 'Wollt nimmer von uns weichen, uns immer nahe sein,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wenn-alle-untreu-werden', 1, 1, 'treu wie die deutschen Eichen, wie Mond und Sonnenschein.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wenn-alle-untreu-werden', 1, 2, 'Einst wird es wieder helle, in aller Brüder Sinn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wenn-alle-untreu-werden', 1, 3, 'sie kehren zu der Quelle in Lieb und Freude hin.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wenn-alle-untreu-werden', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wenn-alle-untreu-werden', 2, 0, 'Es haben wohl gerungen die Helden dieser Frist,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wenn-alle-untreu-werden', 2, 1, 'Und nun der Sieg gelungen, übt Satan neue List.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wenn-alle-untreu-werden', 2, 2, 'Doch wie sich auch gestalten im Leben mag die Zeit,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wenn-alle-untreu-werden', 2, 3, 'Du sollst uns nicht veralten, o Traum der Herrlichkeit.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wenn-alle-untreu-werden', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wenn-alle-untreu-werden', 3, 0, 'Ihr Sterne seid uns Zeugen, die ruhig nieder schau’n,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wenn-alle-untreu-werden', 3, 1, 'wenn alle Brüder schweigen und falschen Götzen trau’n.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wenn-alle-untreu-werden', 3, 2, 'Wir woll’n das Wort nicht brechen und Buben werden gleich,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wenn-alle-untreu-werden', 3, 3, 'woll’n predigen und sprechen vom heil’gen Deutschen Reich.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('westerwaldlied', 'WESTERWALDLIED', 'WESTERWALDLIED', 'duitstalige-liederen', 'de', NULL, 460, 461, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('westerwaldlied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('westerwaldlied', 0, 0, 'Heute wollen wir marschier’n');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('westerwaldlied', 0, 1, 'Einen neuen Marsch probier’n');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('westerwaldlied', 0, 2, 'In dem schönen Westerwald');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('westerwaldlied', 0, 3, 'Ja, da pfeift der Wind so kalt.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('westerwaldlied', 0, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('westerwaldlied', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('westerwaldlied', 1, 0, 'Oh, du schöner Westerwald!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('westerwaldlied', 1, 1, 'Über deine Höhen pfeift der Wind so kalt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('westerwaldlied', 1, 2, 'Jadoch der kleinste Sonnenschein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('westerwaldlied', 1, 3, 'Dringt tief ins Herz hinein.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('westerwaldlied', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('westerwaldlied', 2, 0, 'Und die Gretel und der Hans');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('westerwaldlied', 2, 1, 'Gehen des Sonntags gern zum Tanz');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('westerwaldlied', 2, 2, 'Weil das Tanzen Freude macht');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('westerwaldlied', 2, 3, 'Und das Herz im Leibe lacht.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('westerwaldlied', 2, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('westerwaldlied', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('westerwaldlied', 3, 0, 'Ist das Tanzen dann vorbei');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('westerwaldlied', 3, 1, 'Gibt’s gewöhnlich Keilerei,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('westerwaldlied', 3, 2, 'Und den Bursch, den das nicht freut,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('westerwaldlied', 3, 3, 'Ja man sagt, der hat kein Schneid.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('westerwaldlied', 3, 2, 3, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('wunderbares-madelein', 'WUNDERBARES MÄDELEIN', 'WUNDERBARES MÄDELEIN', 'duitstalige-liederen', 'de', NULL, 462, 462, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wunderbares-madelein', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wunderbares-madelein', 0, 0, 'O! Du wunder, wunderbares Mädelein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wunderbares-madelein', 0, 1, 'Mit deinem wunder, wunderbaren Äugelein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wunderbares-madelein', 0, 2, 'Ja das Äugelein das ist das deine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wunderbares-madelein', 0, 3, 'Aber gucken drein das ist das meine.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('wunderbares-madelein', 0, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wunderbares-madelein', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wunderbares-madelein', 1, 0, 'Und dann gucken, gucken wir die ganze Nacht');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wunderbares-madelein', 1, 1, 'Weil das Gucken, gucken uns viel Freude bracht');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wunderbares-madelein', 1, 2, 'Ja das Äugelein das ist das deine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wunderbares-madelein', 1, 3, 'Aber gucken drein das ist das meine.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('wunderbares-madelein', 1, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wunderbares-madelein', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wunderbares-madelein', 2, 0, 'O! Du wunder, wunderbares Mädelein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wunderbares-madelein', 2, 1, 'Mit deinem wunder, wunderbaren Mündelein');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wunderbares-madelein', 2, 2, 'Ja das Mündelein das ist das deine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wunderbares-madelein', 2, 3, 'Aber küssen drauf das ist das meine.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('wunderbares-madelein', 2, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wunderbares-madelein', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wunderbares-madelein', 3, 0, 'Und dann küssten, küssten wir die ganze Nacht,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wunderbares-madelein', 3, 1, 'Weil das küssen, küssen uns viel Freude bracht');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wunderbares-madelein', 3, 2, 'Ja das Mündelein das ist das deine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('wunderbares-madelein', 3, 3, 'Aber küssen drauf das ist das meine.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('wunderbares-madelein', 3, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('wunderbares-madelein', 4, 'direction', 1, 'Naargelang de inspiratie van de corona worden er vrije versies gezongen!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('all-around-my-hat', 'ALL AROUND MY HAT', 'ALL AROUND MY HAT', 'engelstalige-liederen', 'en', NULL, 465, 465, NULL, NULL, 'T & M: Steeleye Span, traditional');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('all-around-my-hat', 0, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('all-around-my-hat', 0, 0, 'All around my hat, I will wear the green willow');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('all-around-my-hat', 0, 1, 'All around my hat, for a twelve-month and a day');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('all-around-my-hat', 0, 2, 'And if anyone should ask me the reason why I’m wearing it');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('all-around-my-hat', 0, 3, 'It’s all for my true love who’s far, far away');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('all-around-my-hat', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('all-around-my-hat', 1, 0, 'Fare thee well cold winter and fare thee well cold frost');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('all-around-my-hat', 1, 1, 'Nothing have I gained but my own true love I’ve lost');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('all-around-my-hat', 1, 2, 'I’ll sing and I’ll be merry when occasion I do see');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('all-around-my-hat', 1, 3, 'He’s a false deluding young man, let him go farewell he');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('all-around-my-hat', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('all-around-my-hat', 2, 0, 'The other night he brought me a fine diamond ring');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('all-around-my-hat', 2, 1, 'But he thought to have deprived me of a far better thing');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('all-around-my-hat', 2, 2, 'But I being careful like lovers ought to be');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('all-around-my-hat', 2, 3, 'He’s a false deluding young man, let him go farewell he');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('all-around-my-hat', 3, 'chorus-ref', 1, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('all-around-my-hat', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('all-around-my-hat', 4, 0, 'Here’s a half a pound of reasons, and a quarter pound of sense');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('all-around-my-hat', 4, 1, 'A small sprig of time and as much of prudence');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('all-around-my-hat', 4, 2, 'You mix them all together and you will plainly see');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('all-around-my-hat', 4, 3, 'He’s a false deluding young man, let him go farewell he');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('all-around-my-hat', 5, 'chorus-ref', 1, NULL);
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('another-irish-drinking-song', 'ANOTHER IRISH DRINKING SONG', 'ANOTHER IRISH DRINKING SONG', 'engelstalige-liederen', 'en', NULL, 466, 467, NULL, NULL, 'T & M: Da Vinci’s Notebook');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('another-irish-drinking-song', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 0, 0, 'Gather ’round, ye lads and lasses, set ye for a while');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 0, 1, 'And hearken to me mournful tale about the Emerald Isle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 0, 2, 'Let’s all raise our glasses high to friends and family gone');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 0, 3, 'And lift our voices in another Irish drinking song');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 0, 4, 'Consumption took me mother and me father got the pox');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 0, 5, 'Me brother drank the whiskey ’til he wound up in a box');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 0, 6, 'My other brother in the Troubles met with his demise');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 0, 7, 'My sister has forever closed her smiling Irish eyes');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('another-irish-drinking-song', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 1, 0, 'Now everybody’s died');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 1, 1, 'So until our tears are dried');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 1, 2, 'We’ll drink and drink and drink and drink,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 1, 3, 'And then we’ll drink some more');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 1, 4, 'We’ll dance and sing and fight');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 1, 5, 'Until the early morning light');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 1, 6, 'Then we’ll throw up, pass out, wake up,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 1, 7, 'And then go drinking once again');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('another-irish-drinking-song', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 2, 0, 'Kenny was killed in Kilkenny and Claire, she died in Clare');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 2, 1, 'Tip from Tipperary died out in the Derry air');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 2, 2, 'Shannon jumped into the River Shannon back in June');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 2, 3, 'Ernie fell into the Erne, and Tom is in the Toome');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 2, 4, '“Cleanliness is godliness” me Uncle Pat would sing');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 2, 5, 'He broke his neck a’slippin’ on a bar of Irish Spring');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 2, 6, 'O’Grady, he was 80 though his bride was just a pup');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 2, 7, 'He died upon the honeymoon when she got his Irish up');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('another-irish-drinking-song', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 3, 0, 'Me drunken Uncle Brendan tried to drive home from the bar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 3, 1, 'The road rose up to meet him when he fell out of his car');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 3, 2, 'Irony was what befell my great-grand Uncle Sam');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 3, 3, 'He choked upon the very last potato in the land');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 3, 4, 'Conor lived in Ulster town, he used to smuggle arms');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 3, 5, 'Until the British killed him and cut off his lucky charms');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 3, 6, 'And dear old Father Flanagan, who left the lord’s employ');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 3, 7, 'Drunk on sacramental wine, beneath the altar boy');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('another-irish-drinking-song', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 4, 0, 'Someday soon I’ll leave this world of pain and toil and sin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 4, 1, 'The Lord will take me by the hand to join all of me kin');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 4, 2, 'Me only wish is when the Savior comes for me and you ...');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('another-irish-drinking-song', 4, 3, 'He kills the cast of Riverdance, and Michael Flatley too!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('the-ball-of-kerrymuir', 'THE BALL OF KERRYMUIR', 'BALL OF KERRYMUIR, THE', 'engelstalige-liederen', 'en', NULL, 468, 469, NULL, NULL, 'Vermoedelijk bestaan op dit moment 273 strofen, waarvan hier een kleine selectie:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-ball-of-kerrymuir', 0, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-ball-of-kerrymuir', 0, 0, 'Balls to your partner,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-ball-of-kerrymuir', 0, 1, 'Arse against the wall');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-ball-of-kerrymuir', 0, 2, 'If you’ve never been fucked on a Saturday night');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-ball-of-kerrymuir', 0, 3, 'you’ll never be fucked at all');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-ball-of-kerrymuir', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-ball-of-kerrymuir', 1, 0, '’t Was the gathering of the clans');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-ball-of-kerrymuir', 1, 1, 'And all the Scots were there');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-ball-of-kerrymuir', 1, 2, 'A-feeling up the lassies');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-ball-of-kerrymuir', 1, 3, 'Among the pubic hair');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-ball-of-kerrymuir', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-ball-of-kerrymuir', 2, 0, 'Four and twenty virgins');
