INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('the-bricklayer-s-lament', 'THE BRICKLAYER’S LAMENT', 'BRICKLAYER’S LAMENT, THE', 'engelstalige-liederen', 'en', NULL, 474, 476, 'Pat Cooksey', 'Traditional Iers, ‘In the Garden Where the Praties Grow’', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-bricklayer-s-lament', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 0, 0, 'Dear sir I write this note to you');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 0, 1, 'To tell you of my plight');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 0, 2, 'For at the time of writing it,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 0, 3, 'I am not a pretty sight');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 0, 4, 'Me body is all black and blue,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 0, 5, 'Me face a deadly gray');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 0, 6, 'And I write this note to say');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 0, 7, 'Why I am not at work today');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-bricklayer-s-lament', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 1, 0, 'While working on the fourteenth floor,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 1, 1, 'Some bricks I had to clear');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 1, 2, 'But tossing them down from such a height');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 1, 3, 'Was not a good idea');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 1, 4, 'The foreman wasn’t very pleased,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 1, 5, 'He is an awkward sod');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 1, 6, 'He said I’d have to cart em');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 1, 7, 'Down the ladder in me hod');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-bricklayer-s-lament', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 2, 0, 'Well clearing all these bricks by hand');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 2, 1, 'It seemed so very slow');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 2, 2, 'So I hoisted up a barrel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 2, 3, 'And secured a rope below');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 2, 4, 'But in my haste to do the job,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 2, 5, 'I was too blind to see');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 2, 6, 'That a barrel full of building bricks');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 2, 7, 'Was heavier than me');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-bricklayer-s-lament', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 3, 0, 'And so when I untied the rope,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 3, 1, 'The barrel fell like lead');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 3, 2, 'And clinging tightly to the rope,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 3, 3, 'I started up instead');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 3, 4, 'I shot up like a rocket');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 3, 5, 'And to my dismay I found');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 3, 6, 'that halfway up I met the bloody');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 3, 7, 'Barrel coming down');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-bricklayer-s-lament', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 4, 0, 'Now the barrel broke me shoulder');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 4, 1, 'As to the ground it sped');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 4, 2, 'And when I reached the top');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 4, 3, 'I banged the pulley with my head');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 4, 4, 'But I clung on tightly, numb with shock');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 4, 5, 'From this almighty blow');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 4, 6, 'While the barrel spilled out half its bricks,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 4, 7, 'Some fourteen floors below');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-bricklayer-s-lament', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 5, 0, 'Now when these bricks had fallen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 5, 1, 'From the barrel to the floor');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 5, 2, 'I then outweighed the barrel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 5, 3, 'And I started down once more');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 5, 4, 'Still clinging tightly to the rope,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 5, 5, 'Me body wracked with pain');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 5, 6, 'And halfway down I met');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 5, 7, 'The bloody barrel once again');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-bricklayer-s-lament', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 6, 0, 'The force of this collision');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 6, 1, 'Halfway down the office block');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 6, 2, 'Caused multiple abrasions');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 6, 3, 'And a nasty case of shock');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 6, 4, 'But I clung on tightly to the rope');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 6, 5, 'As I fell towards the ground');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 6, 6, 'And I landed on the broken bricks');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 6, 7, 'The barrel ’d scattered ’round');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-bricklayer-s-lament', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 7, 0, 'As I lay there moaning on the floor,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 7, 1, 'I thought I’d passed the worst');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 7, 2, 'But the barrel hit the pulley wheel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 7, 3, 'And then the bottom burst');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 7, 4, 'A shower of bricks rained down on me,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 7, 5, 'I didn’t have a hope');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 7, 6, 'As I lay there bleeding on the ground');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 7, 7, 'I let go the bloody rope');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-bricklayer-s-lament', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 8, 0, 'The barrel now being heavier,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 8, 1, 'It started down once more');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 8, 2, 'It landed right across me');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 8, 3, 'As I lay there on the floor');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 8, 4, 'It broke three ribs and my left arm,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 8, 5, 'And I can only say');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 8, 6, 'I hope you’ll understand');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-bricklayer-s-lament', 8, 7, 'Why I am not at work today');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('the-british-grenadiers', 'THE BRITISH GRENADIERS', 'BRITISH GRENADIERS, THE', 'engelstalige-liederen', 'en', NULL, 477, 478, NULL, NULL, 'Oorspronkelijk 17e eeuwse Britse mars, dit lied wordt nog steeds gebruikt in het Britse leger');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-british-grenadiers', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 0, 0, 'Some talk of Alexander');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 0, 1, 'And some of Hercules,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 0, 2, 'Of Hector and Lysander');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 0, 3, 'And such great names as these.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 0, 4, 'But of all the world’s great heroes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 0, 5, 'There’s none that can compare.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 0, 6, 'With a tow, row, row, row, row, row,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 0, 7, 'To the British Grenadiers.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-british-grenadiers', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 1, 0, 'Those heroes of antiquity');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 1, 1, 'Ne’er saw a cannon ball');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 1, 2, 'Or knew the force of powder');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 1, 3, 'To slay their foes withal.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 1, 4, 'But our brave boys do know it');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 1, 5, 'And banish all their fears.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 1, 6, 'Sing tow, row, row, row, row, row,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 1, 7, 'For the British Grenadiers.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-british-grenadiers', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 2, 0, 'Whene’er we are commanded');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 2, 1, 'To storm the palisades,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 2, 2, 'Our leaders march with fusees,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 2, 3, 'And we with hand grenades.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 2, 4, 'We throw them from the glacis,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 2, 5, 'About the enemies’ ears.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 2, 6, 'Sing tow, row, row, row, row, row,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 2, 7, 'The British Grenadiers.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-british-grenadiers', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 3, 0, 'And when the siege is over,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 3, 1, 'We to the town repair.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 3, 2, 'The townsmen cry, “Hurrah, boys,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 3, 3, 'Here comes a Grenadier!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 3, 4, 'Here come the Grenadiers, my boys,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 3, 5, 'Who know no doubts or fears!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 3, 6, 'Then sing tow, row, row, row, row, row,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 3, 7, 'The British Grenadiers.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-british-grenadiers', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 4, 0, 'Then let us fill a bumper,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 4, 1, 'And drink a health to those');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 4, 2, 'Who carry caps and pouches,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 4, 3, 'And wear the loupèd clothes.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 4, 4, 'May they and their commanders');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 4, 5, 'Live happy all their years.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 4, 6, 'With a tow, row, row, row, row, row,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-british-grenadiers', 4, 7, 'For the British Grenadiers.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('clementine', 'CLEMENTINE', 'CLEMENTINE', 'engelstalige-liederen', 'en', NULL, 479, 480, NULL, NULL, 'P. Montrose');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('clementine', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 0, 0, 'In a cavern, in a canyon,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 0, 1, 'Excavating for a mine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 0, 2, 'Dwelt a miner, forty-niner,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 0, 3, 'And his daughter Clementine.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('clementine', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 1, 0, 'Oh my darling, oh my darling');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 1, 1, 'Oh my darling Clementine!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 1, 2, 'Thou are lost and gone for ever,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 1, 3, 'Dreadful sorry, Clementine.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('clementine', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 2, 0, 'Light she was and like a fairy,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 2, 1, 'And her shoes were number nine;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 2, 2, 'Herring boxes, without topses,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 2, 3, 'Sandals were for Clementine.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('clementine', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 3, 0, 'Drove her ducklings, to the water,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 3, 1, 'Ev’ry morning, just at nine;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 3, 2, 'Hit her foot against a splinter,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 3, 3, 'Fell into the foaming brine.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('clementine', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 4, 0, 'Saw her lips above the water,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 4, 1, 'Blowing bubbles mighty fine');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 4, 2, 'But alas I was no swimmer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 4, 3, 'So I lost my Clementine.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('clementine', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 5, 0, 'In a corner of the churchyard,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 5, 1, 'Where the myrtle boughs entwine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 5, 2, 'Grow the roses in their posies,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 5, 3, 'Fertilized by Clementine.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('clementine', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 6, 0, 'Then the miner, forty-niner,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 6, 1, 'Soon began to peak and pine;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 6, 2, 'Thought he “oughter join” his daughter,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 6, 3, 'Now he’s with his Clementine.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('clementine', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 7, 0, 'In my dreams she still doth haunt me');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 7, 1, 'Robed in garments, soaked in brine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 7, 2, 'Though in life I used to hug her,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 7, 3, 'Now she’s dead I draw the line.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('clementine', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 8, 0, 'How I missed her, how I missed her.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 8, 1, 'How I missed my Clementine!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 8, 2, 'But I kissed her little sister,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('clementine', 8, 3, 'And forgot my Clementine.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('cockles-and-mussels', 'COCKLES AND MUSSELS', 'COCKLES AND MUSSELS', 'engelstalige-liederen', 'en', NULL, 480, 481, NULL, NULL, 'Uit Dublin');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('cockles-and-mussels', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cockles-and-mussels', 0, 0, 'In Dublin’s fair city,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cockles-and-mussels', 0, 1, 'Where the girls are so pretty');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cockles-and-mussels', 0, 2, 'I first set my eyes on sweet Molly Malone,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cockles-and-mussels', 0, 3, 'As she wheeled her wheelbarrow');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cockles-and-mussels', 0, 4, 'Thro’ streets broad and narrow');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('cockles-and-mussels', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cockles-and-mussels', 1, 0, 'Crying: “Cockles and Mussels, alive, alive oh!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cockles-and-mussels', 1, 1, 'Alive, alive oh! Alive, alive oh!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cockles-and-mussels', 1, 2, 'Crying: “Cockles and Mussels, alive, alive oh!”');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('cockles-and-mussels', 1, 1, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('cockles-and-mussels', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cockles-and-mussels', 2, 0, 'She was a fishmonger,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cockles-and-mussels', 2, 1, 'And sure ’t was no wonder');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cockles-and-mussels', 2, 2, 'For so were her father and mother before;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cockles-and-mussels', 2, 3, 'And they each wheeled their barrow');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cockles-and-mussels', 2, 4, 'Through streets broad and narrow');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('cockles-and-mussels', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cockles-and-mussels', 3, 0, 'She died of a fever');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cockles-and-mussels', 3, 1, 'And no one could save her');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cockles-and-mussels', 3, 2, 'And that was the end of sweet Molly Malone;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cockles-and-mussels', 3, 3, 'Her ghost wheels her barrow');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cockles-and-mussels', 3, 4, 'Through streets broad and narrow');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('cotton-fields', 'COTTON FIELDS', 'COTTON FIELDS', 'engelstalige-liederen', 'en', NULL, 481, 481, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('cotton-fields', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cotton-fields', 0, 0, 'When I was a little bitty baby;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cotton-fields', 0, 1, 'My mammy would rock me in the cradle');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cotton-fields', 0, 2, 'In them old cotton fields back home.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('cotton-fields', 0, 0, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('cotton-fields', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cotton-fields', 1, 0, 'Oh when them cotton balls get rotten');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cotton-fields', 1, 1, 'You can’t pick very much cotton.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cotton-fields', 1, 2, 'In them old cotton fields back home.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cotton-fields', 1, 3, 'It was down in Louisiana,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cotton-fields', 1, 4, 'Just about a mile from Texarkana,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cotton-fields', 1, 5, 'In them old cotton fields back home.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('cotton-fields', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cotton-fields', 2, 0, 'It may sound a little funny,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cotton-fields', 2, 1, 'But you didn’t make very much money');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('cotton-fields', 2, 2, 'In them old cotton fields back home.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('cotton-fields', 2, 0, 2, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('donna-donna', 'DONNA DONNA', 'DONNA DONNA', 'engelstalige-liederen', 'en', NULL, 481, 482, NULL, NULL, 'Originele Yiddische tekst: A. Zeitlin, S. Secunda
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('donna-donna', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donna-donna', 0, 0, 'On a wagon bound for market');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donna-donna', 0, 1, 'There’s a calf with a mornful eye');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donna-donna', 0, 2, 'High above him, there’s a swallow');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donna-donna', 0, 3, 'Winging swiftly through the sky.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('donna-donna', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donna-donna', 1, 0, 'How the winds are laughing');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donna-donna', 1, 1, 'They laugh with all their might');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donna-donna', 1, 2, 'Love and laugh the whole day through');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donna-donna', 1, 3, 'And half the summer night.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donna-donna', 1, 4, 'Donna donna donna donna');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donna-donna', 1, 5, 'Donna donna donna don');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('donna-donna', 1, 4, 5, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('donna-donna', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donna-donna', 2, 0, 'Stop complaining said the farmer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donna-donna', 2, 1, 'Who told you it had to be');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donna-donna', 2, 2, 'Why can’t you have wings to fly with');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donna-donna', 2, 3, 'Like the swallow so proud and free');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('donna-donna', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donna-donna', 3, 0, 'Calves are easily bound and slaughtered');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donna-donna', 3, 1, 'Never knowin’ the reason why');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donna-donna', 3, 2, 'But whoever treasures freedom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('donna-donna', 3, 3, 'Like the swallow you’ve learned to fly.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('the-drunk-scotsman', 'THE DRUNK SCOTSMAN', 'DRUNK SCOTSMAN, THE', 'engelstalige-liederen', 'en', NULL, 483, 484, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-drunk-scotsman', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 0, 0, 'Well a Scotsman clad in kilt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 0, 1, 'Left a bar one evening fair');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 0, 2, 'And one could tell by how he walked');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 0, 3, 'That he’d drunk more than his share');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 0, 4, 'He fumbled ’round until he could');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 0, 5, 'No longer keep his feet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 0, 6, 'Then he stumbled off into the grass');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 0, 7, 'To sleep beside the street');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-drunk-scotsman', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 1, 0, 'Ring ding diddle diddle I de oh ring di diddly I oh');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 1, 1, 'He stumbled off into the grass');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 1, 2, 'To sleep beside the street');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-drunk-scotsman', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 2, 0, 'About that time two young and');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 2, 1, 'Lovely girls just happend by');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 2, 2, 'And one says to the other');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 2, 3, 'with a twinkle in her eye');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 2, 4, '“See yon sleeping Scotsman');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 2, 5, 'So strong and handsome built');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 2, 6, 'I wonder if it’s true what');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 2, 7, 'They don’t wear beneath the kilt”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-drunk-scotsman', 3, 'direction', 1, 'Bij de volgende refreinen worden de laatste twee zinnen vervangen door de laatste twee van de voorgaande strofe.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-drunk-scotsman', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 4, 0, 'They crept up on that sleeping');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 4, 1, 'Scotsman quiet as could be');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 4, 2, 'Lifted up his kilt about');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 4, 3, 'An inch so they could see');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 4, 4, 'And there, behold, for them to view,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 4, 5, 'Beneath his Scottish skirt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 4, 6, 'Was nothing more than God had graced');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 4, 7, 'Him with upon his birth');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-drunk-scotsman', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 5, 0, 'They marveled for a moment,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 5, 1, 'Then one said “we must be gone');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 5, 2, 'Let’s leave a present for our friend,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 5, 3, 'Before we move along”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 5, 4, 'As a gift they left a blue');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 5, 5, 'silk ribbon, tied into a bow');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 5, 6, 'Around the bonnie star,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 5, 7, 'the Scots kilt did lift and show');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-drunk-scotsman', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 6, 0, 'Now the Scotsman woke to nature’s call');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 6, 1, 'And stumbled towards a tree');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 6, 2, 'Behind a bush, he lift his kilt');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 6, 3, 'And gawks at what he sees');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 6, 4, 'And in a startled voice he says');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 6, 5, 'To what’s before his eyes.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 6, 6, '“O lad I don’t know where you’ve been');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-drunk-scotsman', 6, 7, 'But I see you won first prize”');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('the-flower-of-scotland', 'THE FLOWER OF SCOTLAND', 'FLOWER OF SCOTLAND, THE', 'engelstalige-liederen', 'en', NULL, 485, 485, NULL, NULL, 'T & M: Roy Williamson, The Corries, jaren ’60
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-flower-of-scotland', 0, 'verse', 1, NULL);
