INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-flower-of-scotland', 0, 2, 'That fought and died for');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-flower-of-scotland', 0, 3, 'Yer wee bit Hill and Glen');
