INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-flower-of-scotland', 1, 0, 'And stood against him');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-flower-of-scotland', 1, 1, '“Who’s that!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-flower-of-scotland', 1, 2, 'Proud Edward’s army');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-flower-of-scotland', 1, 3, 'And sent him homeward');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-flower-of-scotland', 1, 4, 'To think again.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-flower-of-scotland', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-flower-of-scotland', 2, 0, 'The hills are bare now');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-flower-of-scotland', 2, 1, 'And autumn leaves lie thick and still');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-flower-of-scotland', 2, 2, 'Our land is lost now');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-flower-of-scotland', 2, 3, 'That those so dearly held');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-flower-of-scotland', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-flower-of-scotland', 3, 0, 'Those days are passed now');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-flower-of-scotland', 3, 1, 'And in the past they must remain');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-flower-of-scotland', 3, 2, 'But we can still rise now');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-flower-of-scotland', 3, 3, 'And be the nation again');
