INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-flower-of-scotland', 4, 0, 'O’ flower of Scotland');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-flower-of-scotland', 4, 1, 'When will we see yer likes again');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-flower-of-scotland', 4, 2, 'That fought and died for');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-flower-of-scotland', 4, 3, 'Yer wee bit hill and glen');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('home-on-the-range', 'HOME ON THE RANGE', 'HOME ON THE RANGE', 'engelstalige-liederen', 'en', NULL, 486, 486, 'Dr. Brewster M. Higley', 'Daniel E. Kelley', 'Volkslied van Kansas (U.S.A.)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('home-on-the-range', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('home-on-the-range', 0, 0, 'Oh, give me a home, where the buffalo roam');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('home-on-the-range', 0, 1, 'Where the deer and the antelope play');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('home-on-the-range', 0, 2, 'Where seldom is heard a discouraging word');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('home-on-the-range', 0, 3, 'And the skies are not cloudy all day.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('home-on-the-range', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('home-on-the-range', 1, 0, 'Home, home on the range');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('home-on-the-range', 1, 1, 'Where the deer and the antelope play');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('home-on-the-range', 1, 2, 'Where seldom is heard a discouraging word');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('home-on-the-range', 1, 3, 'And the skies are not cloudy all day.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('home-on-the-range', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('home-on-the-range', 2, 0, 'How often at night where the heavens are bright');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('home-on-the-range', 2, 1, 'With the light from the glittering stars');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('home-on-the-range', 2, 2, 'Have I stood there amazed and I asked as I gazed');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('home-on-the-range', 2, 3, 'If their glory exceeds that of ours.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('home-on-the-range', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('home-on-the-range', 3, 0, 'Oh, give me a land where the bright diamond sand');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('home-on-the-range', 3, 1, 'Flows leisurely down the stream');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('home-on-the-range', 3, 2, 'Where the graceful, white swan goes gliding along');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('home-on-the-range', 3, 3, 'Like a maid in a heavenly dream.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('home-on-the-range', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('home-on-the-range', 4, 0, 'Where the air is so pure, the zephyrs so free,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('home-on-the-range', 4, 1, 'The breezes so balmy and light,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('home-on-the-range', 4, 2, 'That I would not exchange my home on the range');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('home-on-the-range', 4, 3, 'For all of the cities so bright.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('it-s-a-long-way-to-tipperary', 'IT’S A LONG WAY TO TIPPERARY', 'IT’S A LONG WAY TO TIPPERARY', 'engelstalige-liederen', 'en', NULL, 487, 487, NULL, NULL, 'T & M: Jack Judge en Harry Williams, 1912');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('it-s-a-long-way-to-tipperary', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 0, 0, 'Up to mighty London came an Irishman one day,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 0, 1, 'As the streets were paved with gold,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 0, 2, 'Sure everyone was gay,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 0, 3, 'Singing songs of Piccadilly,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 0, 4, 'Strand and Leicester Square,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 0, 5, 'Till Paddy got excited,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 0, 6, 'Then he shouted to them there:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('it-s-a-long-way-to-tipperary', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 1, 0, 'It’s a long way to Tipperary,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 1, 1, 'It’s a long way to go,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 1, 2, 'It’s a long way to Tipperary,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 1, 3, 'To the sweetest girl I know!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 1, 4, 'Goodbye Piccadilly! Farewell Leicester Square!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 1, 5, 'It’s a long, long way to Tipperary,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 1, 6, 'But my heart’s right there!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('it-s-a-long-way-to-tipperary', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 2, 0, 'Paddy wrote a letter to his Irish Molly O’,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 2, 1, 'Saying: “Should you not receive it,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 2, 2, 'Write and let me know!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 2, 3, 'If I make mistakes in spelling,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 2, 4, 'Molly dear”, said he,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 2, 5, '“Remember it’s the pen that’s bad,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 2, 6, 'Don’t lay the blame on me”.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('it-s-a-long-way-to-tipperary', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 3, 0, 'Molly wrote a neat reply to Irish Paddy O’,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 3, 1, 'Saying: “Mike Maloney wants to');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 3, 2, 'Marry me, and so,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 3, 3, 'Leave the Strand and Piccadilly,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 3, 4, 'Or you’ll be to blame,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 3, 5, 'For love has fairly drove me silly,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('it-s-a-long-way-to-tipperary', 3, 6, 'Hoping you’re the same!”');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('kingstontown', 'KINGSTONTOWN', 'KINGSTONTOWN', 'engelstalige-liederen', 'en', NULL, 488, 488, NULL, NULL, 'T & M: Harry Belafonte
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('kingstontown', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kingstontown', 0, 0, 'Down the way where the nights are gay');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kingstontown', 0, 1, 'And the sun shines daily on the mountaintop');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kingstontown', 0, 2, 'I took a trip on a sailing ship');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kingstontown', 0, 3, 'And when I reached Jamaica I made a stop.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('kingstontown', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kingstontown', 1, 0, 'But I’m sad to say I’m on my way');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kingstontown', 1, 1, 'Won’t be back for many a day');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kingstontown', 1, 2, 'My heart is down my head is turning around');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kingstontown', 1, 3, 'I have to leave a little girl in Kingstontown.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('kingstontown', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kingstontown', 2, 0, 'Sounds of laughter everywhere');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kingstontown', 2, 1, 'And the dancing girls swing to and fro');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kingstontown', 2, 2, 'I must declare that my heart is there');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kingstontown', 2, 3, 'Though I’ve been from Maine to Mexico.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('kingstontown', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kingstontown', 3, 0, 'Down at the market you can hear');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kingstontown', 3, 1, 'Ladies cry out while on their heads they bear');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kingstontown', 3, 2, 'Baskets rice, all fish are nice');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('kingstontown', 3, 3, 'And the rum is fine any time I hear.');
