INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('leave-her-johnny', 'LEAVE HER, JOHNNY', 'LEAVE HER, JOHNNY', 'engelstalige-liederen', 'en', NULL, 489, 489, NULL, NULL, 'Zeemanslied');
