INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('loch-lomon', 'LOCH LOMON’', 'LOCH LOMON’', 'engelstalige-liederen', 'en', NULL, 490, 491, 'Lady John Scott, Poets and Poetry of Scotland, 1876', 'Naar ‘Robin Cushie’, McGibbons Scots Tunes Book, 1742 De legende vertelt dat in 1745 twee Jacobijnse soldaten gevangen werden genomen in Carlisle Castle. De een schreef dit lied voor hij werd geëxecuteerd (the low road, voor de moeilijke verstaander), de ander bleef leven om het verder te vertellen.', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('loch-lomon', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('loch-lomon', 0, 0, 'By yon bonnie banks and by yon bonnie braes,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('loch-lomon', 0, 1, 'Where the sun shines bright on Loch Lomon’,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('loch-lomon', 0, 2, 'Where me and my true love will ever want to be');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('loch-lomon', 0, 3, 'On the bonnie, bonnie banks of Loch Lomon’.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('loch-lomon', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('loch-lomon', 1, 0, 'Oh you’ll take the high road,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('loch-lomon', 1, 1, 'And I’ll take the low road.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('loch-lomon', 1, 2, 'And I’ll be in Scotland before you,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('loch-lomon', 1, 3, 'But me and my true love will never meet again,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('loch-lomon', 1, 4, 'On the bonnie, bonnie banks of Loch Lomon’.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('loch-lomon', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('loch-lomon', 2, 0, 'I mind where we parted in yon shady glen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('loch-lomon', 2, 1, 'On the steep, steep side of Ben Lomon’');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('loch-lomon', 2, 2, 'Where in deep purple hue, the Highland hills we view.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('loch-lomon', 2, 3, 'And the moon coming out in the gloaming.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('loch-lomon', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('loch-lomon', 3, 0, 'The wee birdies sing and the wild flowers spring');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('loch-lomon', 3, 1, 'And in sunshine the waters are sleeping;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('loch-lomon', 3, 2, 'But the broken heart will ken no second spring again,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('loch-lomon', 3, 3, 'And the world doesn’t know how we’re greeting.');
