INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('oh-susanna', 'OH SUSANNA', 'OH SUSANNA', 'engelstalige-liederen', 'en', NULL, 493, 494, NULL, NULL, 'Stephen Foster, 1847');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oh-susanna', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 0, 0, 'I come from Alabama');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 0, 1, 'With my banjo on my knee,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 0, 2, 'I’m going to Louisiana,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 0, 3, 'My true love for to see,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 0, 4, 'It rained all night the day I left,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 0, 5, 'The weather, it was dry,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 0, 6, 'The sun so hot I froze to death,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 0, 7, 'Susanna, don’t you cry');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oh-susanna', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 1, 0, 'Oh! Susanna,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 1, 1, 'Oh! Don’t you cry for me;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 1, 2, 'For I come from Alabama');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 1, 3, 'With my banjo on my knee');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('oh-susanna', 1, 0, 3, 2, '(BIS)');
