INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 2, 0, 'I had a dream the other night,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 2, 1, 'When everything was still,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 2, 2, 'I thought I saw Susanna there,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 2, 3, 'Acoming down the hill,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 2, 4, 'The buckwheat cake was in her mouth,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 2, 5, 'The tear was in her eye');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 2, 6, 'Says I: “I’m coming from the South.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 2, 7, 'Susanna don’t you cry.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('oh-susanna', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 3, 0, 'I soon will be in New Orleans');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 3, 1, 'And then I’ll look all ’round');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 3, 2, 'And when I find Susanna,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 3, 3, 'I’ll fall upon the ground');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 3, 4, 'But if I do not find her,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 3, 5, 'This darkie’ll surely die');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 3, 6, 'And when I’m dead and buried');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('oh-susanna', 3, 7, 'Susanna, don’t you cry');
