INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('randy-dandy-oh', 'RANDY DANDY-OH', 'RANDY DANDY-OH', 'engelstalige-liederen', 'en', NULL, 495, 496, NULL, NULL, 'Traditional sea shanty
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('randy-dandy-oh', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('randy-dandy-oh', 0, 0, 'Now we are ready to head for the Horn');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('randy-dandy-oh', 0, 1, 'Way, ay, roll an’ go!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('randy-dandy-oh', 0, 2, 'Our boots an’ our clothes boys are all in the pawn,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('randy-dandy-oh', 0, 3, 'Timme rollickin’ randy dandy O!');
