INSERT INTO line (song_id, stanza_position, position, text) VALUES ('randy-dandy-oh', 1, 0, 'Heave a pawl, oh, heave away,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('randy-dandy-oh', 1, 1, 'Way, ay, roll an’ go!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('randy-dandy-oh', 1, 2, 'The anchor’s on board an’ the cable’s all stored,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('randy-dandy-oh', 1, 3, 'Timme rollickin’ randy dandy O!');
