INSERT INTO line (song_id, stanza_position, position, text) VALUES ('randy-dandy-oh', 2, 2, 'Where the pretty young gals all come down in their flocks,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('randy-dandy-oh', 2, 3, 'Timme rollickin’ randy dandy O!');
