INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('randy-dandy-oh', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('randy-dandy-oh', 6, 0, 'Oh, man the stout caps’n an’ heave with a will,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('randy-dandy-oh', 6, 1, 'Soon we’ll be drivin’ her ’way down the hill.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('randy-dandy-oh', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('randy-dandy-oh', 7, 0, 'Heave away, bullies, ye parish-rigged bums,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('randy-dandy-oh', 7, 1, 'Take yer hands from yet pockets and don’t suck yer thumbs.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('randy-dandy-oh', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('randy-dandy-oh', 8, 0, 'Roust ’er up, bullies, the wind’s drawin’ free');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('randy-dandy-oh', 8, 1, 'Let’s get the glad-rags up an’ drive ’er to sea.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('randy-dandy-oh', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('randy-dandy-oh', 9, 0, 'We’re outward bound for Vallipo Bay,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('randy-dandy-oh', 9, 1, 'Get crackin’ m’lads, ’tis a hell o’ a way.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('red-river-valley', 'RED RIVER VALLEY', 'RED RIVER VALLEY', 'engelstalige-liederen', 'en', NULL, 496, 496, NULL, NULL, 'Traditional, oorspronkelijke titel ‘In the bright Mohawk Valley’, 1896 De ‘Red River’ ontspringt in North Dakota, USA en mondt uit in Lake Winnipeg, Manitoba, Canada');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('red-river-valley', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('red-river-valley', 0, 0, 'From this valley they say you are going;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('red-river-valley', 0, 1, 'We will miss your bright eyes and sweet smile;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('red-river-valley', 0, 2, 'For they say, you are taking the sunshine,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('red-river-valley', 0, 3, 'That brightens our pathway the while.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('red-river-valley', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('red-river-valley', 1, 0, 'Come and sit by my side if you love me;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('red-river-valley', 1, 1, 'Do not hasten to bid me adieu;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('red-river-valley', 1, 2, 'But remember the Red River Valley');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('red-river-valley', 1, 3, 'And the one that has loved you so true.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('red-river-valley', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('red-river-valley', 2, 0, 'Won’t you think of the valley you’re leaving;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('red-river-valley', 2, 1, 'Oh, how lonely, how sad it will be;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('red-river-valley', 2, 2, 'Oh, think of the fond heart you’re breaking');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('red-river-valley', 2, 3, 'And the grief you are coming me to see.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('red-river-valley', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('red-river-valley', 3, 0, 'As you go to your home by the ocean;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('red-river-valley', 3, 1, 'May you never forget those sweet hours;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('red-river-valley', 3, 2, 'That we spent in the Red River Valley');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('red-river-valley', 3, 3, 'And the love we exchanged ’mid the flowers.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('the-rocky-road-to-dublin', 'THE ROCKY ROAD TO DUBLIN', 'ROCKY ROAD TO DUBLIN, THE', 'engelstalige-liederen', 'en', NULL, 497, 498, NULL, NULL, 'D. K. Gavan, 19e eeuw');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-rocky-road-to-dublin', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 0, 0, 'In the merry month of June from me home I started');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 0, 1, 'Left the girls of Tuam nearly broken hearted');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 0, 2, 'Saluted Father dear, kissed me darling mother');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 0, 3, 'Drank a pint of beer, me grief and tears to smother');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 0, 4, 'Then off to reap the corn, leave where I was born');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 0, 5, 'Cut a stout blackthorn to banish ghosts and goblins');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 0, 6, 'A brand new pair of brogues, rattlin’ o’er the bogs');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 0, 7, 'Frightenin’ all the dogs on the rocky road to Dublin');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-rocky-road-to-dublin', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 1, 0, 'One two three four five');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 1, 1, 'Hunt the Hare and turn her down the rocky road');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 1, 2, 'And all the way to Dublin, Whack fol lol le rah!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-rocky-road-to-dublin', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 2, 0, 'In Mullingar that night I rested limbs so weary');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 2, 1, 'Started by daylight me spirits bright and airy');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 2, 2, 'Took a drop of the pure, keep me heart from sinking');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 2, 3, 'That’s the Paddy’s cure whenever he’s on drinking');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 2, 4, 'To see the lassies smile, laughing all the while');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 2, 5, 'At me curious style, ’twould set your heart a bubblin’');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 2, 6, 'An’ asked if I was hired, wages I required');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 2, 7, '’Till I was nearly tired of the rocky road to Dublin');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-rocky-road-to-dublin', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 3, 0, 'In Dublin next arrived, I thought it such a pity');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 3, 1, 'To be soon deprived a view of that fine city');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 3, 2, 'Well then I took a stroll, all among the quality');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 3, 3, 'Bundle it was stole, all in a neat locality');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 3, 4, 'Something crossed me mind, when I looked behind');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 3, 5, 'No bundle could I find upon me stick a wobblin’');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 3, 6, 'Enquiring for the rogue, said me Connaught brogue');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 3, 7, 'Wasn’t much in vogue on the rocky road to Dublin');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-rocky-road-to-dublin', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 4, 0, 'From there I got away, me spirits never falling');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 4, 1, 'Landed on the quay, just as the ship was sailing');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 4, 2, 'The Captain at me roared, said that no room had he');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 4, 3, 'When I jumped aboard, a cabin found for Paddy');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 4, 4, 'Down among the pigs, played some funny rigs');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 4, 5, 'Danced some hearty jigs, the water round me bubbling');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 4, 6, 'When off Holyhead wished meself was dead');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 4, 7, 'Or better far instead on the rocky road to Dublin');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-rocky-road-to-dublin', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 5, 0, 'The boys of Liverpool, when we safely landed');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 5, 1, 'Called meself a fool, I could no longer stand it');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 5, 2, 'Blood began to boil, temper I was losing');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 5, 3, 'Poor old Erin’s isle they began abusing');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 5, 4, '‘Hurrah me soul!’ says I, me shillelagh I let fly');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 5, 5, 'Some Galway boys were nigh and saw I was a hobble in');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 5, 6, 'With a loud ‘Hurray!’ joined in the affray');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 5, 7, 'We quickly cleared the way for the rocky road to Dublin');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-rocky-road-to-dublin', 6, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 6, 0, 'One two three four five');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 6, 1, 'Hunt the Hare and turn her down the rocky road');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 6, 2, 'And all the way to Dublin, Whack fol lol le rah!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-rocky-road-to-dublin', 6, 3, 'Whack fol lol le rah!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('the-rocky-road-to-dublin', 6, 1, 2, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('the-rocky-road-to-dublin', 6, 3, 3, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('roll-the-old-chariot-along', 'ROLL THE OLD CHARIOT ALONG', 'ROLL THE OLD CHARIOT ALONG', 'engelstalige-liederen', 'en', NULL, 499, 499, NULL, NULL, 'Traditional sea shanty');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('roll-the-old-chariot-along', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roll-the-old-chariot-along', 0, 0, 'Well a night on shore');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roll-the-old-chariot-along', 0, 1, 'Wouldn’t do us any harm');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roll-the-old-chariot-along', 0, 2, 'And we’ll all hang on behind');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('roll-the-old-chariot-along', 0, 0, 1, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('roll-the-old-chariot-along', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roll-the-old-chariot-along', 1, 0, 'And we’ll roll the old');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roll-the-old-chariot-along', 1, 1, 'chariot along');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roll-the-old-chariot-along', 1, 2, 'And we’ll all hang on behind');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('roll-the-old-chariot-along', 1, 0, 1, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('roll-the-old-chariot-along', 2, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('roll-the-old-chariot-along', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roll-the-old-chariot-along', 3, 0, 'Well a nice watch below');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('roll-the-old-chariot-along', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roll-the-old-chariot-along', 4, 0, 'Well a nice glass of beer');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('roll-the-old-chariot-along', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roll-the-old-chariot-along', 5, 0, 'Well a night with the girls');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('roll-the-old-chariot-along', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('roll-the-old-chariot-along', 6, 0, 'Well a big pot of gold');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('roll-the-old-chariot-along', 7, 'direction', 1, 'Naargelang de inspiratie van de corona worden er vrije versies gezongen!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('scotland-the-brave', 'SCOTLAND THE BRAVE', 'SCOTLAND THE BRAVE', 'engelstalige-liederen', 'en', NULL, 500, 500, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('scotland-the-brave', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('scotland-the-brave', 0, 0, 'Hark when the night is falling.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('scotland-the-brave', 0, 1, 'Hear! Hear the pipes are calling,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('scotland-the-brave', 0, 2, 'Loudly and proudly calling down through the glenn.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('scotland-the-brave', 0, 3, 'There where the hills are sleeping,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('scotland-the-brave', 0, 4, 'Now feel the blood a-leaping,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('scotland-the-brave', 0, 5, 'High as the spirit');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('scotland-the-brave', 0, 6, 'Of the old Highland men.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('scotland-the-brave', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('scotland-the-brave', 1, 0, 'Towering in gallant fame');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('scotland-the-brave', 1, 1, 'Scotland my mountain home');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('scotland-the-brave', 1, 2, 'High may your proud standards gloriously wave.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('scotland-the-brave', 1, 3, 'Land of my high endeavour,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('scotland-the-brave', 1, 4, 'Land of the shining river,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('scotland-the-brave', 1, 5, 'Land of my heart for ever,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('scotland-the-brave', 1, 6, 'Scotland the Brave.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('scotland-the-brave', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('scotland-the-brave', 2, 0, 'High in the misty Highlands,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('scotland-the-brave', 2, 1, 'Out by the purple islands.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('scotland-the-brave', 2, 2, 'Brave are the hearts that beat beneath Scottish skies.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('scotland-the-brave', 2, 3, 'Wild are the winds to meet you,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('scotland-the-brave', 2, 4, 'Staunch are the friends that greet you,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('scotland-the-brave', 2, 5, 'Kind as the love that shines');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('scotland-the-brave', 2, 6, 'From fair maiden’s eyes.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('scotland-the-brave', 3, 'chorus-ref', 1, 'wordt tweemaal gezongen.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('song-for-ye-jacobites', 'SONG FOR YE JACOBITES', 'SONG FOR YE JACOBITES', 'engelstalige-liederen', 'en', NULL, 502, 503, NULL, NULL, 'De originele tekst van dit lied, geschreven in de periode van de Jacobijnse oorlogen (1689–1692) in Schotland, was zeer anti-Jacobijns van opvatting. Robert Burns had veel sympathie voor hun zaak en herschreef het lied naar zijn huidige vorm rond 1791.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('song-for-ye-jacobites', 0, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 0, 0, 'Ye Jacobites by name lend an ear, lend an ear.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 0, 1, 'Ye Jacobites by name lend an ear.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 0, 2, 'Ye Jacobites by name,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 0, 3, 'Your faults I will proclaim');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 0, 4, 'Your doctrines I must blame');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 0, 5, 'You shall hear, you shall hear.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 0, 6, 'Your doctrines I must blame, you shall hear.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('song-for-ye-jacobites', 1, 'direction', 1, 'Het refrein wordt enkel herhaald na de laatste strofe.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('song-for-ye-jacobites', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 2, 0, 'What’s right and what is wrong, by the law, by the law?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 2, 1, 'What’s right and what is wrong, by the law?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 2, 2, 'What’s right and what is wrong,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 2, 3, 'By short sword or by long?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 2, 4, 'A weak arm or a strong');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 2, 5, 'For to draw, for to draw?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 2, 6, 'A weak arm or a strong for to draw?');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('song-for-ye-jacobites', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 3, 0, 'What makes heroic strife, famed afar, famed afar.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 3, 1, 'What makes heroic strife, famed afar.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 3, 2, 'What makes heroic strife,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 3, 3, 'To whet th’ assassin’s knife');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 3, 4, 'Or hunt a parents life');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 3, 5, 'With bloody war, with bloody war.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 3, 6, 'Or hunt a parents life with bloody war.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('song-for-ye-jacobites', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 4, 0, 'So leave your schemes alone in the state, in the state.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 4, 1, 'So leave your schemes alone in the state.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 4, 2, 'So leave your schemes alone,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 4, 3, 'Adore the rising sun,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 4, 4, 'And leave a man undone');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 4, 5, 'To his fate, to his fate.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('song-for-ye-jacobites', 4, 6, 'And leave a man undone to his fate.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('the-stonecutters-song', 'THE STONECUTTERS SONG', 'STONECUTTERS SONG, THE', 'engelstalige-liederen', 'en', NULL, 503, 503, 'John Swartzwelder, The Simpsons', 'Alf Clausen', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-stonecutters-song', 0, 'direction', 1, 'Gesproken:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-stonecutters-song', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-stonecutters-song', 1, 0, 'You have joined the sacred order of the Stonecutters, who,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-stonecutters-song', 1, 1, 'since ancient times, have split the rocks of ignorance that');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-stonecutters-song', 1, 2, 'obscure the light of knowledge and truth.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-stonecutters-song', 1, 3, 'Now let’s all get drunk and play ping-pong!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-stonecutters-song', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-stonecutters-song', 2, 0, 'Who controls the British crown?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-stonecutters-song', 2, 1, 'Who keeps the metric system down?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-stonecutters-song', 2, 2, 'We do! We do!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-stonecutters-song', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-stonecutters-song', 3, 0, 'Who leaves Atlantis off the maps?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-stonecutters-song', 3, 1, 'Who keeps the Martians under wraps?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-stonecutters-song', 3, 2, 'We do! We do!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-stonecutters-song', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-stonecutters-song', 4, 0, 'Who holds back the electric car?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-stonecutters-song', 4, 1, 'Who makes Steve Guttenberg a star?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-stonecutters-song', 4, 2, 'We do! We do!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-stonecutters-song', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-stonecutters-song', 5, 0, 'Who robs cave fish of their sight?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-stonecutters-song', 5, 1, 'Who rigs every Oscar night?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-stonecutters-song', 5, 2, 'We do! We do!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('a-tavern-in-the-town', 'A TAVERN IN THE TOWN', 'TAVERN IN THE TOWN, A', 'engelstalige-liederen', 'en', NULL, 504, 504, NULL, NULL, 'Amerikaans volkswijsje');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-tavern-in-the-town', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-tavern-in-the-town', 0, 0, 'There is a tavern in the town, in the town');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-tavern-in-the-town', 0, 1, 'And there my true love sits him down, sits him down');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-tavern-in-the-town', 0, 2, 'And drinks his wine ’mid laughter free');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-tavern-in-the-town', 0, 3, 'And never, never thinks of me.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-tavern-in-the-town', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-tavern-in-the-town', 1, 0, 'Fare thee well for I must leave thee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-tavern-in-the-town', 1, 1, 'Do not let the parting grieve thee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-tavern-in-the-town', 1, 2, 'And remember that the best of friends');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-tavern-in-the-town', 1, 3, 'must part, must part');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-tavern-in-the-town', 1, 4, 'Adieu, adieu kind friends,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-tavern-in-the-town', 1, 5, 'adieu, adieu, adieu');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-tavern-in-the-town', 1, 6, 'I can no longer stay with you, stay with you.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-tavern-in-the-town', 1, 7, 'I’ll hang my harp on a weeping willow tree');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-tavern-in-the-town', 1, 8, 'And may the world go well with thee.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-tavern-in-the-town', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-tavern-in-the-town', 2, 0, 'He left me for a damsel dark, damsel dark');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-tavern-in-the-town', 2, 1, 'Each Friday night they used to spark, used to spark');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-tavern-in-the-town', 2, 2, 'And now my love, once true to me');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-tavern-in-the-town', 2, 3, 'Takes that dark damsel on his knee.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-tavern-in-the-town', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-tavern-in-the-town', 3, 0, 'O, dig my grave both wide and deep, wide and deep');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-tavern-in-the-town', 3, 1, 'Put tombstones on my head and feet, head and feet');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-tavern-in-the-town', 3, 2, 'And on my breast carve a turtle dove');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-tavern-in-the-town', 3, 3, 'To signify I died of love.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('tom-dooley', 'TOM DOOLEY', 'TOM DOOLEY', 'engelstalige-liederen', 'en', NULL, 505, 505, NULL, NULL, 'In 1866 werd Tom Dooley, een veteraan van de Amerikaanse burgeroorlog, ten onrechte opgehangen voor de moord op Laura Foster. De driehoeksverhouding in het lied, was in feite een vierhoeksverhouding. Het was de vierde persoon, Annie Melton, die uiteindelijk met sheriff Greeson huwde en later bekende de moordenaar te zijn. Het oorspronkelijke lied telt 14 strofen en werd in 1958 bekend door ‘The Kingston Trio’.
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('tom-dooley', 0, 'direction', 1, 'Gesproken:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('tom-dooley', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tom-dooley', 1, 0, 'Throughout history there have been stories and many songs,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tom-dooley', 1, 1, 'written about the trouble triangle. This next one tells the');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tom-dooley', 1, 2, 'story of a Mr. Greeson, a beautiful woman and a condemned');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tom-dooley', 1, 3, 'man, named Tom Dooley. When the sun rises tomorrow, Tom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tom-dooley', 1, 4, 'Dooley must hang ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('tom-dooley', 2, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tom-dooley', 2, 0, 'Hang down your head, Tom Dooley,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tom-dooley', 2, 1, 'Hang down your head and cry,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tom-dooley', 2, 2, 'Hang down your head, Tom Dooley,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tom-dooley', 2, 3, 'Poor boy, you’re bound to die.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('tom-dooley', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tom-dooley', 3, 0, 'I met her on the mountain,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tom-dooley', 3, 1, 'There I took her life,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tom-dooley', 3, 2, 'I met her on the mountain,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tom-dooley', 3, 3, 'And stabbed her with my knife.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('tom-dooley', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tom-dooley', 4, 0, 'By this time tomorrow,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tom-dooley', 4, 1, 'Reckon where I’ll be,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tom-dooley', 4, 2, 'Hadn’t it been for Greeson,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tom-dooley', 4, 3, 'I had been in Tennessee.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('tom-dooley', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tom-dooley', 5, 0, 'By this time tomorrow,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tom-dooley', 5, 1, 'Reckon where I’ll be,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tom-dooley', 5, 2, 'In some lonesome valley,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tom-dooley', 5, 3, 'A-hanging from a white oak tree.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('tonight', 'TONIGHT', 'TONIGHT', 'engelstalige-liederen', 'en', NULL, 506, 506, NULL, '‘Fumiento Funicula’, Luigi Denza, 1880', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('tonight', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tonight', 0, 0, 'Tonight; I feel the need of masturbation');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tonight', 0, 1, 'And I feel fine; so really fine;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tonight', 0, 2, 'Tonight; I feel the need of masturbation');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tonight', 0, 3, 'And I feel good; so really good.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('tonight', 0, 0, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('tonight', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tonight', 1, 0, 'Ease it, squeeze it, jump it to the floor,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tonight', 1, 1, 'Work it, jerk it, jump it to the door.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tonight', 1, 2, 'Some people say that in a bed');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tonight', 1, 3, 'A woman’s love is really great.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tonight', 1, 4, 'But for personal enjoyment');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('tonight', 1, 5, 'I prefer to use my hand.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('tonight', 1, 0, 5, 2, '(BIS)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('waltzing-matilda', 'WALTZING MATILDA', 'WALTZING MATILDA', 'engelstalige-liederen', 'en', NULL, 506, 507, NULL, NULL, 'A.B. ‘Banjo’ Paterson
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('waltzing-matilda', 0, 'direction', 1, 'Vervang bij elk refrein de derde en vierde lijn door de drie laatste lijnen van de voorafgaande strofe.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('waltzing-matilda', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 1, 0, 'Once a jolly swagman camped beside a billabong,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 1, 1, 'Under the shade of a coolibah tree,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 1, 2, 'And he sang as he watched');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 1, 3, 'And waited till his billy boiled,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 1, 4, '“Who’ll come a-waltzing Matilda with me?');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('waltzing-matilda', 2, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 2, 0, 'Waltzing Matilda, Waltzing Matilda,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 2, 1, 'Who’ll come a-waltzing Matilda with me?”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 2, 2, 'And he sang as he watched and waited till his billy boiled,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 2, 3, '“Who’ll come a-waltzing Matilda with me?”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('waltzing-matilda', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 3, 0, 'Down came a jumbuck to drink at the billabong:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 3, 1, 'Up jumped the swagman and grabbed him with glee.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 3, 2, 'And he sang as he stowed');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 3, 3, 'That jumbuck in his tucker-bag,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 3, 4, '“You’ll come a-waltzing Matilda with me.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('waltzing-matilda', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 4, 0, 'Up rode a squatter, mounted on his thoroughbred;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 4, 1, 'Down came the troopers, one, two, three:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 4, 2, '“Whose that jolly jumbuck');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 4, 3, 'You’ve got in your tucker-bag?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 4, 4, 'You’ll come a-waltzing Matilda with me!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('waltzing-matilda', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 5, 0, 'Up jumped the swagman and sprang into the billabong;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 5, 1, '“You’ll never catch me alive!” said he;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 5, 2, 'And his ghost may be heard');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 5, 3, 'As you pass by that billabong,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('waltzing-matilda', 5, 4, '“You’ll come a-waltzing Matilda with me!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('the-wellerman', 'THE WELLERMAN', 'WELLERMAN, THE', 'engelstalige-liederen', 'en', NULL, 507, 508, NULL, NULL, 'Traditioneel zeemanslied uit Nieuw-Zeeland');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-wellerman', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 0, 0, 'There was a ship that put to sea,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 0, 1, 'The name of the ship was the Billy of Tea.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 0, 2, 'The wind blew up, her bow dipped down,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 0, 3, 'O blow, my bully boys, blow.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-wellerman', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 1, 0, 'Soon may the Wellerman come,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 1, 1, 'And bring us sugar, tea and rum');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 1, 2, 'One day, when the tonguin’ is done,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 1, 3, 'We’ll take our leave and go.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-wellerman', 2, 'direction', 1, 'Na de laatste strofe wordt het refrein twee maal gezongen.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-wellerman', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 3, 0, 'She had not been two weeks from shore');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 3, 1, 'When down on her a right whale bore.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 3, 2, 'The captain called all hands and swore');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 3, 3, 'He’d take that whale in tow.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-wellerman', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 4, 0, 'Before the boat had hit the water,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 4, 1, 'The whale’s tail came up and caught her.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 4, 2, 'All hands to the side, harpooned and fought her');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 4, 3, 'When she dived down below.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-wellerman', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 5, 0, 'No line was cut, no whale was freed;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 5, 1, 'The captain’s mind was not of greed,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 5, 2, 'But he belonged to the Whaleman’s creed');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 5, 3, 'She took that ship in tow.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-wellerman', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 6, 0, 'For forty days, or even more,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 6, 1, 'The line went slack, then tight once more.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 6, 2, 'All boats were lost, there were only four,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 6, 3, 'But still that whale did go.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-wellerman', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 7, 0, 'As far as I’ve heard, the fight’s still on;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 7, 1, 'The line’s not cut and the whale’s not gone.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 7, 2, 'The Wellerman makes his regular call');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wellerman', 7, 3, 'To encourage the captain, crew and all.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('what-shall-we-do-with-the-drunken-sailor', 'WHAT SHALL WE DO WITH THE DRUNKEN SAILOR', 'WHAT SHALL WE DO WITH THE DRUNKEN SAILOR', 'engelstalige-liederen', 'en', NULL, 509, 509, NULL, NULL, 'Uit ‘Incidents of a whaling voyage’, Olmstead, 1839');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('what-shall-we-do-with-the-drunken-sailor', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('what-shall-we-do-with-the-drunken-sailor', 0, 0, 'What shall we do with the drunken sailor');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('what-shall-we-do-with-the-drunken-sailor', 0, 0, 0, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('what-shall-we-do-with-the-drunken-sailor', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('what-shall-we-do-with-the-drunken-sailor', 1, 0, 'Early in the morning');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('what-shall-we-do-with-the-drunken-sailor', 1, 1, 'Hooray and up she rises');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('what-shall-we-do-with-the-drunken-sailor', 1, 2, 'Early in the morning');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('what-shall-we-do-with-the-drunken-sailor', 1, 1, 1, 3, '(TER)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('what-shall-we-do-with-the-drunken-sailor', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('what-shall-we-do-with-the-drunken-sailor', 2, 0, 'Put him in the long-boat until he’s sober.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('what-shall-we-do-with-the-drunken-sailor', 2, 1, 'Pull out the plug and wet him all over.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('what-shall-we-do-with-the-drunken-sailor', 2, 2, 'Put him in the scuppers with a hosepipe on him.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('what-shall-we-do-with-the-drunken-sailor', 2, 3, 'Heave him by the leg in a running bowlin’.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('what-shall-we-do-with-the-drunken-sailor', 2, 4, 'Give ’em a taste of the Captain’s Daughter');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('what-shall-we-do-with-the-drunken-sailor', 2, 5, 'That’s what we’ll do with the drunken sailor.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('what-shall-we-do-with-the-drunken-sailor', 2, 0, 0, 3, '(TER)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('what-shall-we-do-with-the-drunken-sailor', 2, 1, 1, 3, '(TER)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('what-shall-we-do-with-the-drunken-sailor', 2, 2, 2, 3, '(TER)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('what-shall-we-do-with-the-drunken-sailor', 2, 3, 3, 3, '(TER)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('what-shall-we-do-with-the-drunken-sailor', 2, 4, 4, 3, '(TER)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('what-shall-we-do-with-the-drunken-sailor', 2, 5, 5, 3, '(TER)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('when-johnny-comes-marching-home', 'WHEN JOHNNY COMES MARCHING HOME', 'WHEN JOHNNY COMES MARCHING HOME', 'engelstalige-liederen', 'en', NULL, 509, 511, NULL, NULL, 'Lied uit de Amerikaanse burgeroorlog, circa 1860');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('when-johnny-comes-marching-home', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 0, 0, 'When Johnny comes marching home again');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 0, 1, 'Hurrah! Hurrah!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 0, 2, 'We’ll give him a hearty welcome then');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 0, 3, 'Hurrah! Hurrah!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 0, 4, 'The men will cheer, the boys will shout,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 0, 5, 'The ladies they will all turn out');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 0, 6, 'And we’ll all feel gay when Johnny comes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 0, 7, 'marching home, home.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('when-johnny-comes-marching-home', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 1, 0, 'The old churchbells will peal with joy');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 1, 1, 'Hurrah! Hurrah!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 1, 2, 'To welcome home our darling boy');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 1, 3, 'Hurrah! Hurrah!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 1, 4, 'The village lads and lasses say,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 1, 5, 'With roses they will strew the way');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 1, 6, 'And we’ll all feel gay when Johnny comes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 1, 7, 'marching home, home.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('when-johnny-comes-marching-home', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 2, 0, 'Get ready for the jubilee');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 2, 1, 'Hurrah! Hurrah!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 2, 2, 'We’ll give the hero three times three');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 2, 3, 'Hurrah! Hurrah!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 2, 4, 'The laurel wreath is ready now,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 2, 5, 'To place upon his royal brow');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 2, 6, 'And we’ll all feel gay when Johnny comes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 2, 7, 'marching home, home.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('when-johnny-comes-marching-home', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 3, 0, 'Let love and friendship on that day');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 3, 1, 'Hurrah! Hurrah!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 3, 2, 'Their choicest treasures then display');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 3, 3, 'Hurrah! Hurrah!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 3, 4, 'And let each one perform some part,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 3, 5, 'To fill with joy the warrior’s heart');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 3, 6, 'And we’ll all feel gay when Johnny comes');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('when-johnny-comes-marching-home', 3, 7, 'marching home, home.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('whiskey-in-the-jar', 'WHISKEY IN THE JAR', 'WHISKEY IN THE JAR', 'engelstalige-liederen', 'en', NULL, 511, 513, NULL, NULL, 'Traditional');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('whiskey-in-the-jar', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 0, 0, 'As I was going over');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 0, 1, 'The far famed Kerry Mountains,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 0, 2, 'I met with Captain Farrell');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 0, 3, 'And his money he was counting,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 0, 4, 'I first produced me pistol');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 0, 5, 'And I then produced me rapier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 0, 6, 'Saying: “Stand and deliver');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 0, 7, 'For you are the bold deceiver.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('whiskey-in-the-jar', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 1, 0, 'Musha ring durram do durram dah,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 1, 1, 'Whack fol the daddy o,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 1, 2, 'There’s whiskey in the jar.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('whiskey-in-the-jar', 1, 1, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('whiskey-in-the-jar', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 2, 0, 'I counted out his money');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 2, 1, 'And it made a pretty penny');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 2, 2, 'I put it in me pocket');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 2, 3, 'And I took it home to Jenny');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 2, 4, 'She sighed, and she swore');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 2, 5, 'That she never would deceive me');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 2, 6, 'But the devil take the women,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 2, 7, '’Cause they never can be easy');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('whiskey-in-the-jar', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 3, 0, 'I went into my chamber,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 3, 1, 'All for to take a slumber');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 3, 2, 'I dreamt of gold and jewels');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 3, 3, 'And for sure it was no wonder');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 3, 4, 'But Jenny drew me charges');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 3, 5, 'And she filled them up with water');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 3, 6, 'Then sent for Captain Farrell');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 3, 7, 'To be ready for the slaughter');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('whiskey-in-the-jar', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 4, 0, 'It was early in the morning,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 4, 1, 'Just before I rose to travel');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 4, 2, 'Up comes a band of footmen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 4, 3, 'And likewise Captain Farrell');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 4, 4, 'I first produced my pistol,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 4, 5, 'For she’d stolen away my rapier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 4, 6, 'I couldn’t shoot the water,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 4, 7, 'So a prisoner I was taken');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('whiskey-in-the-jar', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 5, 0, 'And if anyone can aid me,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 5, 1, '’t Is my brother in the army');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 5, 2, 'If I can find his station');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 5, 3, 'In Cork or in Killarney');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 5, 4, 'And if he’ll go with me,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 5, 5, 'We’ll go roving in Kilkenny');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 5, 6, 'And I’m sure he’ll treat me better,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 5, 7, 'Than my only sporting Jenny');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('whiskey-in-the-jar', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 6, 0, 'Now there’s some who take delight');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 6, 1, 'In the carriages a-rolling');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 6, 2, 'And others take delight');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 6, 3, 'In the hurley and the bowling');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 6, 4, 'But I take delight');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 6, 5, 'In the juice of the barley');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 6, 6, 'And courting pretty fair maids');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('whiskey-in-the-jar', 6, 7, 'In the morning bright and early');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('the-wild-rover', 'THE WILD ROVER', 'WILD ROVER, THE', 'engelstalige-liederen', 'en', NULL, 513, 514, NULL, NULL, 'Iers volksliedje');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-wild-rover', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wild-rover', 0, 0, 'I’ve been a wild rover for many’s a year');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wild-rover', 0, 1, 'I’ve spent all my money on whiskey and beer.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wild-rover', 0, 2, 'But now I’m returning with gold in great store.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wild-rover', 0, 3, 'And I never will play the wild rover no more.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-wild-rover', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wild-rover', 1, 0, 'And it’s no nay never, no nay never no more,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wild-rover', 1, 1, 'Will I play the wild rover, no never no more.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-wild-rover', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wild-rover', 2, 0, 'I went into an alehouse, I used to frequent.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wild-rover', 2, 1, 'I told the landlady my money was spent.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wild-rover', 2, 2, 'I asked her for credit, she answered me nay,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wild-rover', 2, 3, 'Such custom as yours I can have every day.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-wild-rover', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wild-rover', 3, 0, 'I then took from my pocket, ten sovereigns bright,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wild-rover', 3, 1, 'And the landlady’s eyes opened wide with delight');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wild-rover', 3, 2, 'She says I have whiskeys and wines of the best,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wild-rover', 3, 3, 'And the words that you told me were only in jest.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('the-wild-rover', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wild-rover', 4, 0, 'I’ll go home to my parents, confess what I’ve done,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wild-rover', 4, 1, 'And I’ll ask them to pardon their prodigal son.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wild-rover', 4, 2, 'And when they’ve caressed me as oft times before,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('the-wild-rover', 4, 3, 'Then I never will play the wild rover no more.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('yankee-doodle', 'YANKEE DOODLE', 'YANKEE DOODLE', 'engelstalige-liederen', 'en', NULL, 514, 516, 'Richard Shuckburgh', NULL, 'Oud Engels wiegelied en volkslied van de staat Connecticut');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('yankee-doodle', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 0, 0, 'Yankee Doodle came to town,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 0, 1, 'Upon a little pony,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 0, 2, 'He stuck a feather on his cap');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 0, 3, 'And called it Macaroni.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('yankee-doodle', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 1, 0, 'Yankee Doodle keep it up,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 1, 1, 'Yankee Doodle dandy,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 1, 2, 'Mind the music and the step,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 1, 3, 'And with the girls be handy');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('yankee-doodle', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 2, 0, 'There was Captain Washington');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 2, 1, 'Upon a slapping stallion,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 2, 2, 'A-giving orders to his men,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 2, 3, 'I guess there was a million.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('yankee-doodle', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 3, 0, 'And then the feathers on his hat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 3, 1, 'They looked so’ tarnal fin-a,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 3, 2, 'I wanted pockily to get');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 3, 3, 'To give to my Jemima.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('yankee-doodle', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 4, 0, 'And then we saw a swamping gun,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 4, 1, 'Large as a log of maple;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 4, 2, 'Upon a deuced little cart,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 4, 3, 'A load for father’s cattle.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('yankee-doodle', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 5, 0, 'And every time they shoot it off,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 5, 1, 'It takes a horn of powder;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 5, 2, 'It makes a noise like father’s gun,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 5, 3, 'Only a nation louder.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('yankee-doodle', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 6, 0, 'I went as nigh to one myself,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 6, 1, 'As’ Siah’s underpinning;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 6, 2, 'And father went as nigh agin,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 6, 3, 'I thought the deuce was in him.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('yankee-doodle', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 7, 0, 'We saw a little barrel, too,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 7, 1, 'The heads were made of leather;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 7, 2, 'They knocked upon it with little clubs,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 7, 3, 'And called the folks together.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('yankee-doodle', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 8, 0, 'And there they’d fife away like fun,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 8, 1, 'And play on cornstalk fiddles,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 8, 2, 'And some had ribbons red as blood,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 8, 3, 'All bound around their middles.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('yankee-doodle', 9, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 9, 0, 'The troopers, too, would gallop up');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 9, 1, 'And fire right in our faces;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 9, 2, 'It scared me almost to death');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 9, 3, 'To see them run such races.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('yankee-doodle', 10, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 10, 0, 'Uncle Sam came there to change');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 10, 1, 'Some pancakes and some onions,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 10, 2, 'For’ lasses cake to carry home');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 10, 3, 'To give his wife and young ones.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('yankee-doodle', 11, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 11, 0, 'But I can’t tell half I see');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 11, 1, 'They kept up such a smother;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 11, 2, 'So I took my hat off, made a bow,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 11, 3, 'And scampered home to mother.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('yankee-doodle', 12, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 12, 0, 'Cousin Simon grew so bold,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 12, 1, 'I thought he would have cocked it;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 12, 2, 'It scared me so I streaked it off,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 12, 3, 'And hung by father’s pocket.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('yankee-doodle', 13, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 13, 0, 'And there I saw a pumpkin shell,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 13, 1, 'As big as mother’s basin;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 13, 2, 'And every time they touched it off,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('yankee-doodle', 13, 3, 'They scampered like the nation.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('a-a-a-valete-studia', 'A, A, A, VALETE STUDIA', 'A, A, A, VALETE STUDIA', 'anderstalige-liederen', 'la', NULL, 519, 519, NULL, NULL, '16e eeuws Leuvens vakantielied');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-a-a-valete-studia', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-a-a-valete-studia', 0, 0, 'A, a, a, valete studia! Valete studia!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-a-a-valete-studia', 0, 1, 'Studia relinquimus, patriam repetimus,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-a-a-valete-studia', 0, 2, 'A, a, a, valete studia! Valete studia.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-a-a-valete-studia', 0, 3, 'Valete studia!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-a-a-valete-studia', 1, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-a-a-valete-studia', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-a-a-valete-studia', 2, 0, 'E, e, e, ite miseriae!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-a-a-valete-studia', 2, 1, 'Instant nobis feriae,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-a-a-valete-studia', 2, 2, 'Quo fruamur hodie, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-a-a-valete-studia', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-a-a-valete-studia', 3, 0, 'I, i, i, bibunt philosophi!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-a-a-valete-studia', 3, 1, 'Studiosi parvuli,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-a-a-valete-studia', 3, 2, 'Etiam sunt bibuli, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-a-a-valete-studia', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-a-a-valete-studia', 4, 0, 'O, o, o, nil est in poculo:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-a-a-valete-studia', 4, 1, 'Repleatur denuo!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-a-a-valete-studia', 4, 2, 'Nummi sunt in sacculo, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-a-a-valete-studia', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-a-a-valete-studia', 5, 0, 'U, u, u, ingenti spiritu!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-a-a-valete-studia', 5, 1, 'Celebramus epulas,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-a-a-valete-studia', 5, 2, 'Cras Habemus ferias, ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('a-a-a-valete-studia', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-a-a-valete-studia', 6, 0, 'IJ, ij, ij, kom schenk en drink met mij;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-a-a-valete-studia', 6, 1, 'Want wij zijn hier niet gekomen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('a-a-a-valete-studia', 6, 2, 'Om te slapen of te dromen, ...');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('bella-ciao', 'BELLA CIAO', 'BELLA CIAO', 'anderstalige-liederen', 'it', NULL, 520, 521, NULL, NULL, 'Italiaans verzetslied');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bella-ciao', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 0, 0, 'Una mattina mi son svegliato,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 0, 1, 'o bella, ciao! bella, ciao! bella, ciao, ciao, ciao!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 0, 2, 'Una mattina mi son svegliato,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 0, 3, 'e ho trovato l’invasor.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bella-ciao', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 1, 0, 'O partigiano, portami via,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 1, 1, 'o bella, ciao! bella, ciao! bella, ciao, ciao, ciao!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 1, 2, 'O partigiano, portami via,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 1, 3, 'ché mi sento di morir.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bella-ciao', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 2, 0, 'E se io muoio da partigiano,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 2, 1, 'o bella, ciao! bella, ciao! bella, ciao, ciao, ciao!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 2, 2, 'E se io muoio da partigiano,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 2, 3, 'tu mi devi seppellir.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bella-ciao', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 3, 0, 'E seppellire lassù in montagna,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 3, 1, 'o bella, ciao! bella, ciao! bella, ciao, ciao, ciao!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 3, 2, 'E seppellire lassù in montagna,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 3, 3, 'sotto l’ombra di un bel fior.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bella-ciao', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 4, 0, 'Tutte le genti che passeranno,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 4, 1, 'o bella, ciao! bella, ciao! bella, ciao, ciao, ciao!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 4, 2, 'Tutte le genti che passeranno,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 4, 3, 'Ti diranno “Che bel fior!”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('bella-ciao', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 5, 0, '“È questo il fiore del partigiano”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 5, 1, 'o bella, ciao! bella, ciao! bella, ciao, ciao, ciao!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 5, 2, '“È questo il fiore del partigiano,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('bella-ciao', 5, 3, 'morto per la libertà!”');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('filia-pastoris', 'FILIA PASTORIS', 'FILIA PASTORIS', 'anderstalige-liederen', 'la', NULL, 521, 522, NULL, NULL, 'De strofen zijn respectievelijk in het Latijn, klassiek Grieks, Duits, Pools en Nederlands.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('filia-pastoris', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 0, 0, 'Quae voluptas quae voluptas');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 0, 1, 'Est amare');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 0, 2, 'Pulchram filiam pastoris!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 0, 3, 'O admiranda, o admiranda,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 0, 4, 'O admiranda filia pastoris!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('filia-pastoris', 0, 0, 2, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('filia-pastoris', 0, 3, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('filia-pastoris', 1, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('filia-pastoris', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 2, 0, 'Hedonè oiè, hedonè oiè');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 2, 1, 'Estin Agapain');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 2, 2, 'Kalèn paida poimenos!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 2, 3, 'O thaumasia, o thaumasia,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 2, 4, 'O thaumasia paida poimenos!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('filia-pastoris', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 3, 0, 'Welch Vergnügen welch Vergnügen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 3, 1, 'Ist’s zu lieben');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 3, 2, 'Des Hirten schönstes Töchterlein!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 3, 3, 'O wunderbares, o wunderbares,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 3, 4, 'O wunderbares Hirten Töchterlein!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('filia-pastoris', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 4, 0, 'Co za radosc, co zo radosc');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 4, 1, 'Jest kochanie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 4, 2, 'Piekna corke pastora!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 4, 3, 'O nadzwyczajna, o nadzwyczajna');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 4, 4, 'O nadzwyczajna corko pastora!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('filia-pastoris', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 5, 0, 'Welk genoegen welk genoegen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 5, 1, 'Is’t te minnen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 5, 2, '’t Mooiste meisje van de stad!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 5, 3, 'O wonderbaarste, o wonderbaarste,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('filia-pastoris', 5, 4, 'O wonderbaarste meisje van de stad!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('gertjie', 'GERTJIE', 'GERTJIE', 'anderstalige-liederen', 'af', NULL, 522, 523, NULL, NULL, 'Transvaals volksliedje');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gertjie', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 0, 0, 'Wanneer kom ons troudag, Gertjie, Gertjie?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 0, 1, 'Hoe’s dit dan so stil met jou?');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 0, 2, 'Ons is so lank verloof al Gertjie, Gertjie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 0, 3, 'Dit is de tyd dat ons ga trou.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gertjie', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 1, 0, 'Glo tog Gertjie, ek sal nooit nie, nooit nie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 1, 1, 'Nog langer an jou sleeptou bly nie, bly nie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 1, 2, 'Jy dink miskien: ek kan nie dood nie, dood nie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 1, 3, 'Maar my jare gaan verby.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gertjie', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 2, 0, '’k Hoor jy is verliefd op Sarie, Sarie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 2, 1, 'Maar die pret moet jy laat staan.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 2, 2, 'Pas maar op vir Pieter en Danie, Danie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 2, 3, 'Hul is kerls, wat somaer slaan.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gertjie', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 3, 0, 'Jy weet, as ons Sondags kuier, kuier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 3, 1, 'Agter om die kop verby');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 3, 2, 'Dan seg ek: “Nonnie, lig jou sluier, sluier');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 3, 3, 'Kom en gee een soen vir my.”');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gertjie', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 4, 0, 'Jannie, al die soentjes help nie, help nie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 4, 1, 'Kyk vir Pieter en vir Griet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 4, 2, 'Vandag wil hul mekaar nie hé nie, hé nie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 4, 3, 'Al die soentjes is verniet.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('gertjie', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 5, 0, 'Ons moet dan die pret maar staan laat, staan laat');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 5, 1, 'Ons moet maar die soen laat bly,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 5, 2, 'Ek sal myn eie pad dan kry maar, kry maar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('gertjie', 5, 3, 'En jy kan na Sarie vry, vry, vry.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('hava-nagiela', 'HAVA NAGIELA', 'HAVA NAGIELA', 'anderstalige-liederen', 'he', NULL, 523, 523, NULL, NULL, '‘Laat ons vrolijk zijn’: Israëlische hups (parendans).');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('hava-nagiela', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('hava-nagiela', 0, 0, 'Hava nagiela, hava nagiela, hava nagiela,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('hava-nagiela', 0, 1, 'Venismecha');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('hava-nagiela', 0, 2, 'Hava neranena, hava neranena,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('hava-nagiela', 0, 3, 'Hava neranena venismecha');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('hava-nagiela', 0, 4, 'Oeroe oeroe achiem');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('hava-nagiela', 0, 5, 'Oeroe achiem belev sameag');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('hava-nagiela', 0, 6, 'Oeroe achiem, oeroe achiem');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('hava-nagiela', 0, 7, 'Belev sameag');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('hava-nagiela', 0, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('hava-nagiela', 0, 2, 3, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('hava-nagiela', 0, 5, 5, 4, '(QUATER)');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('die-kat-kwam-weer', 'DIE KAT KWAM WEER', 'KAT KWAM WEER, DIE', 'anderstalige-liederen', 'af', NULL, 524, 526, NULL, NULL, NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-kat-kwam-weer', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 0, 0, 'De boer, die zwoer hem blou:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 0, 1, 'Hij zou die kat doodskiet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 0, 2, 'Hij had zijn hoos gelaan.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 0, 3, 'Met kruit en dynamiet,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 0, 4, 'Hij lei die kat hem voor');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 0, 5, 'Den weg die hij moest kom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 0, 6, 'En de volgende morgen: velletjes en beentjes, maar ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-kat-kwam-weer', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 1, 0, 'Die kat kwam weer,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 1, 1, 'Die kon nie langer wach,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 1, 2, 'Die kat kwam weer de volgende dag');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 1, 3, 'Die kat kwam weer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 1, 4, 'Geloof me het is waar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 1, 5, 'De volgende dag was die kat weer daar!');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-kat-kwam-weer', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 2, 0, 'Hij zet hem op een skip');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 2, 1, 'Dat zeilde naar Ceylon');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 2, 2, 'Die skip die was gelaan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 2, 3, 'Met twaalf duizend ton,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 2, 4, 'Maar verre van dit land');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 2, 5, 'Daar is die skip gestrand');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 2, 6, 'En alle matrozen verdronk, maar ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-kat-kwam-weer', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 3, 0, 'De boer, die zet die kat');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 3, 1, 'Toen in een aeroplaan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 3, 2, 'Die derailleerde toen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 3, 3, 'Tegen een wollekie aan');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 3, 4, 'De boel die viel omlaag');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 3, 5, 'Bleef steken in een haag');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 3, 6, 'Brak armen, nek en beene, maar ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-kat-kwam-weer', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 4, 0, 'De boer, die zet die kat');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 4, 1, 'Toen op de schoorsteen neer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 4, 2, 'Die kat, die viel omlaag');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 4, 3, 'En deed zich vreselijk zeer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 4, 4, 'De kat, die viel in ’t vuur');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 4, 5, 'Verbrandde binnen ’t uur.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 4, 6, 'En de volgende morgen as en botjes, maar ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-kat-kwam-weer', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 5, 0, 'Die boer die draag die kat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 5, 1, 'Toen op een hoog gebouw,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 5, 2, 'En gooi hem naar beneen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 5, 3, 'Met een ferme dou,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 5, 4, 'De man die’m op hem krijg,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 5, 5, 'Wor plat gelijk een vijg,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 5, 6, 'Twaalf vaderloze kindertjes, maar ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-kat-kwam-weer', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 6, 0, 'Die boer die bond die kat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 6, 1, 'Die pootjes net tesaam,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 6, 2, 'En lei het beestje toen,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 6, 3, 'Op de railtjes van den tram,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 6, 4, 'Het trampje liep van spoor,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 6, 5, 'En brak te midden door,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 6, 6, 'Stukkies glas en hout en ijzer, maar ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-kat-kwam-weer', 7, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 7, 0, 'Toen stak die boer die kat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 7, 1, 'In een heel groot kanon,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 7, 2, 'Die schot die werd gelaan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 7, 3, 'Met zesenvijftig ton,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 7, 4, 'Die schot viel ver van huis,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 7, 5, 'En sloeg de stad in gruis,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 7, 6, 'Kerken, scholen, huizen en hopies puin, maar ...');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-kat-kwam-weer', 8, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 8, 0, 'Toen het die boer die kat,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 8, 1, 'In duizend stuk gekap,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 8, 2, 'En steek dan ieder stuk,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 8, 3, 'Apartjes in een graf,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 8, 4, 'Hij stamp die boel goed aan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 8, 5, 'Maar als hij slaap dan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-kat-kwam-weer', 8, 6, 'Droom hij altijd weer van ...');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('marcha-de-la-unidad-popular', 'MARCHA DE LA UNIDAD POPULAR', 'MARCHA DE LA UNIDAD POPULAR', 'anderstalige-liederen', 'es', NULL, 526, 527, 'Quilapayún', 'Sergio Ortega, 1973', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('marcha-de-la-unidad-popular', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 0, 0, 'De pie, cantar que vamos a triunfar.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 0, 1, 'Avanzan ya banderas de unidad.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 0, 2, 'Y tú vendrás marchando junto a mi,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 0, 3, 'y así verás tu canto y tu bandera florecer.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 0, 4, 'La luz, de un rojo amanecer');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 0, 5, 'anuncia ya, la vida que vendrá.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('marcha-de-la-unidad-popular', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 1, 0, 'De pie, luchar, el pueblo va a triunfar.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 1, 1, 'Será mejor la vida que vendrá');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 1, 2, 'a conquistar nuestra felicidad');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 1, 3, 'y en un clamor mil voces de combate se alzarán,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 1, 4, 'dirán canción de libertad,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 1, 5, 'con decisión la patria vencerá.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('marcha-de-la-unidad-popular', 2, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 2, 0, 'Y ahora el pueblo que se alza en la lucha');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 2, 1, 'con voz de gigante gritando: “Adelante!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 2, 2, 'El pueblo unido, jamás será vencido!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('marcha-de-la-unidad-popular', 2, 2, 2, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('marcha-de-la-unidad-popular', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 3, 0, 'La patria está forjando la unidad.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 3, 1, 'De norte a sur se movilizará');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 3, 2, 'desde el salar ardiente y mineral');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 3, 3, 'al bosque austral unidos en la lucha y al trabajo');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 3, 4, 'irán, la patria cubrirán.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 3, 5, 'Su paso ya anuncia el porvenir.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('marcha-de-la-unidad-popular', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 4, 0, 'De pie, cantar el pueblo va a triunfar.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 4, 1, 'Millones ya imponen la verdad,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 4, 2, 'de acero son ardiente batallón,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 4, 3, 'sus manos van Ilevando la justicia y a la razón.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 4, 4, 'Mujer, con fuego y con valor,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 4, 5, 'ya estás aquí junto al trabajador.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('marcha-de-la-unidad-popular', 5, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 5, 0, 'Y ahora el pueblo que se alza en la lucha');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 5, 1, 'con voz de gigante gritando: “Adelante!”');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('marcha-de-la-unidad-popular', 5, 2, 'El pueblo unido, jamás será vencido!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('marcha-de-la-unidad-popular', 5, 2, 2, 2, '(BIS)');
