INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('el-paso-del-ebro', 'EL PASO DEL EBRO', 'PASO DEL EBRO, EL', 'anderstalige-liederen', 'es', NULL, 528, 529, NULL, NULL, 'Republikeins lied uit de Spaanse burgeroorlog');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('el-paso-del-ebro', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('el-paso-del-ebro', 0, 0, 'El ejército del Ebro');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('el-paso-del-ebro', 0, 1, 'Rumba la rumba la rumbumbum');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('el-paso-del-ebro', 0, 2, 'Una noche el río pasó');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('el-paso-del-ebro', 0, 3, 'Ay Carmela, ay Carmela');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('el-paso-del-ebro', 0, 0, 1, 2, '(BIS)');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('el-paso-del-ebro', 0, 2, 3, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('el-paso-del-ebro', 1, 'direction', 1, 'Volgende strofen worden op dezelfde manier gezongen');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('el-paso-del-ebro', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('el-paso-del-ebro', 2, 0, 'Y las tropas invasoras');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('el-paso-del-ebro', 2, 1, 'Buena paliza les dió');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('el-paso-del-ebro', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('el-paso-del-ebro', 3, 0, 'El furor de los traidores');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('el-paso-del-ebro', 3, 1, 'Lo descarga su aviación');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('el-paso-del-ebro', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('el-paso-del-ebro', 4, 0, 'Pero nada pueden bombas');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('el-paso-del-ebro', 4, 1, 'Donde sobra corazón');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('el-paso-del-ebro', 5, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('el-paso-del-ebro', 5, 0, 'Contrataques muy rabiosos');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('el-paso-del-ebro', 5, 1, 'Deberemos resistir');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('el-paso-del-ebro', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('el-paso-del-ebro', 6, 0, 'Pero igual que combatimos');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('el-paso-del-ebro', 6, 1, 'Prometemos resistir');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('sarie-marais', 'SARIE MARAIS', 'SARIE MARAIS', 'anderstalige-liederen', 'af', NULL, 529, 530, NULL, NULL, 'Joan Van Niekerk');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sarie-marais', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 0, 0, 'My Sarie Marais is so ver van my hart,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 0, 1, 'Maar ’k hoop om haar weer te sien,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 0, 2, 'Sy het in die wyk van die Mooirivier gewoon,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 0, 3, 'Nog voor die oorlog het begin.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sarie-marais', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 1, 0, 'O bring my terug na die ou Transvaal,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 1, 1, 'Daar waar my Sarie woon:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 1, 2, 'Daar onder in die mielis');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 1, 3, 'By die groene doringboom');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 1, 4, 'Daar woon my Sarie Marais.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('sarie-marais', 1, 2, 4, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sarie-marais', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 2, 0, 'Ek was so bang, dat die kakies my sou vang');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 2, 1, 'En ver oor die see wegstuur,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 2, 2, 'Toe vlug ek na die kant van die Upington se sand');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 2, 3, 'Daar onder langs die Grootrivier.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sarie-marais', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 3, 0, 'Die kakies is mos net soos ’n krokodillepees');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 3, 1, 'Hul sleep jou altyd watertoe,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 3, 2, 'Hulle gooi jou op ’n skip vir ’n lange, lange trip');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 3, 3, 'Die Josie weet waarna toe.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sarie-marais', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 4, 0, 'Verlossing het gekom, en die huistoe gaan was daar');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 4, 1, 'Trug naar die ou Transvaal,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 4, 2, 'My liewelingspersoon sal seker ook daar wees');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 4, 3, 'Om my met ’n kus te beloon.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sarie-marais', 5, 'direction', 1, 'Vrijblijvende, apocriefe appendix:');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sarie-marais', 6, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 6, 0, 'Van Sarie Marijs wisten w’enkel dees,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 6, 1, 'Dat kind woonde in Transvaal.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 6, 2, 'Nu zijn we der geweest en nu weten we de rest,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 6, 3, 'Dus hier is ’t vervolg van ’t verhaal.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('sarie-marais', 7, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 7, 0, 'Van als ze maar amper veertien was');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 7, 1, 'Is ze hare gang gegaan,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 7, 2, 'Daar onder in die milies, bij die doringboom in ’t gras');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 7, 3, 'Lag zij met Bobbejaan.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 7, 4, 'Daar kwamen nooit geen vodden van,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 7, 5, 'Dus houden we’t maar stil');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('sarie-marais', 7, 6, 'Want Sarie Marijs pakt de pil.');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('die-stellenbosche-kerls', 'DIE STELLENBOSCHE KERLS', 'STELLENBOSCHE KERLS, DIE', 'anderstalige-liederen', 'af', NULL, 530, 531, 'P. Mc Clachlan', 'Traditioneel Zuid-Afrikaans', NULL);
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-stellenbosche-kerls', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-stellenbosche-kerls', 0, 0, 'Bobbejaan klim die berg, so haastig en so lustig,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-stellenbosche-kerls', 0, 1, 'Bobbejaan klim die berg om die boere te vererg:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-stellenbosche-kerls', 0, 2, 'Hoera! Vir die jollie Bobbejaan!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('die-stellenbosche-kerls', 0, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-stellenbosche-kerls', 1, 'chorus', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-stellenbosche-kerls', 1, 0, 'O moe nie huil nie o moe nie treur nie');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-stellenbosche-kerls', 1, 1, 'Die Stellenbosche kerls kom weer');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('die-stellenbosche-kerls', 1, 0, 1, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-stellenbosche-kerls', 2, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-stellenbosche-kerls', 2, 0, 'Bobbejaan sluip die dal, so haastig en zo lustig,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-stellenbosche-kerls', 2, 1, 'Bobbejaan sluip die dal om die rooinek t’overval:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-stellenbosche-kerls', 2, 2, 'Hoera vir die boer, hoera!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('die-stellenbosche-kerls', 2, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-stellenbosche-kerls', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-stellenbosche-kerls', 3, 0, 'Bobbejaan kruip die haag, so haastig en zo lustig,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-stellenbosche-kerls', 3, 1, 'Bobbejaan kruip die haag om die rooinek te verjaag');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-stellenbosche-kerls', 3, 2, 'Hoera vir die boer, hoera!');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('die-stellenbosche-kerls', 3, 0, 0, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('die-stellenbosche-kerls', 4, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-stellenbosche-kerls', 4, 0, 'Bobbejaan kom ook weer, parmantig, nou astrantig');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-stellenbosche-kerls', 4, 1, 'Nou kom kijk nog’n keer wat hij kan brou, wat hij kan brou');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-stellenbosche-kerls', 4, 2, 'Adoons kry die skoot en hy skiet hom hallef dood,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('die-stellenbosche-kerls', 4, 3, 'Hoera! Vir die jollie Bobbejaan!');
INSERT INTO song (id, title, sort_title, section_id, language, club_id, page_start, page_end, lyricist, melody, notes) VALUES ('studentelied', 'STUDENTELIED', 'STUDENTELIED', 'anderstalige-liederen', 'af', NULL, 532, 532, NULL, NULL, 'C.F. Visser, E. Hullebroeck');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('studentelied', 0, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 0, 0, 'Die studentejare gaan verby,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 0, 1, 'Verby studenteweelde;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 0, 2, 'Nooit keer hul ooit terug vir my:');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 0, 3, 'Die tyd, die lieflingsbeelde,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 0, 4, 'Die koringmeul wil nie meer maal,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 0, 5, 'My skulde moet ek self betaal!');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 0, 6, 'O treurigheid op note');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 0, 7, 'Ek staan op eie pote.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('studentelied', 0, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('studentelied', 1, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 1, 0, 'Soos mieliepitte spat uiteen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 1, 1, 'Die oue troue vrinde;');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 1, 2, 'Ek staan nou moedersiel alleen');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 1, 3, 'En is maar net bediende');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 1, 4, 'Ek is nie meer myn eie baas,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 1, 5, 'Ek werk met Paul en Piet en Klaas.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 1, 6, 'O treurigheid op note');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 1, 7, 'Ek staan op eie pote.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('studentelied', 1, 6, 7, 2, '(BIS)');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('studentelied', 2, 'direction', 1, 'De oudstudenten staan recht.');
INSERT INTO stanza (song_id, position, kind, repeat, instruction) VALUES ('studentelied', 3, 'verse', 1, NULL);
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 3, 0, 'Maar moe nie glô, al word ons oud,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 3, 1, 'Ons hart kan ooit verander,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 3, 2, 'Ons liefde is nog lang nie koud,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 3, 3, 'Ons sta nog by mekander.');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 3, 4, 'Dus vriende reik mekaar die hand,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 3, 5, 'Hernuw die heil’ge vriendskapsband,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 3, 6, 'Gaan dit met stamp’ en stote,');
INSERT INTO line (song_id, stanza_position, position, text) VALUES ('studentelied', 3, 7, 'Nog bly ons op ons pote.');
INSERT INTO repeat_span (song_id, stanza_position, from_line, to_line, times, marker) VALUES ('studentelied', 3, 6, 7, 2, '(BIS)');
